static void mothershipCliLog(const char *text)
{
  if (text != nullptr)
  {
    std::fputs(text, stdout);
  }

  std::fflush(stdout);
}

template <typename... Args>
static void mothershipCliLog(const char *format, Args&&...args)
{
  std::fprintf(stdout, format, std::forward<Args>(args)...);
  std::fflush(stdout);
}

#define basics_log mothershipCliLog

static bool parseU32Arg(const char *text, uint32_t& value)
{
  if (text == nullptr || text[0] == '\0')
  {
    return false;
  }

  char *end = nullptr;
  unsigned long parsed = std::strtoul(text, &end, 10);
  if (end == text || *end != '\0')
  {
    return false;
  }

  value = static_cast<uint32_t>(parsed);
  return true;
}

static bool mothershipValidateDiscombobulatorContainerBlobContract(
    const String& containerPath,
    String *failureReport = nullptr)
{
  return prodigyValidateDiscombobulatorContainerBlobHeader(containerPath, failureReport);
}

static bool parseBoolArg(const char *text, bool& value)
{
  if (text == nullptr)
  {
    return false;
  }

  if ((std::strcmp(text, "1") == 0) || (std::strcmp(text, "true") == 0) || (std::strcmp(text, "TRUE") == 0))
  {
    value = true;
    return true;
  }

  if ((std::strcmp(text, "0") == 0) || (std::strcmp(text, "false") == 0) || (std::strcmp(text, "FALSE") == 0))
  {
    value = false;
    return true;
  }

  return false;
}

static bool parseDoubleArg(const char *text, double& value)
{
  if (text == nullptr || text[0] == '\0')
  {
    return false;
  }

  char *end = nullptr;
  errno = 0;
  double parsed = std::strtod(text, &end);
  if (end == text || *end != '\0' || errno != 0 || std::isfinite(parsed) == false)
  {
    return false;
  }

  value = parsed;
  return true;
}

static bool parseCIDRPrefix(const char *text, IPPrefix& prefix)
{
  if (text == nullptr || text[0] == '\0')
  {
    return false;
  }

  const char *slash = std::strrchr(text, '/');
  if (slash == nullptr || slash == text || slash[1] == '\0')
  {
    return false;
  }

  char addressText[INET6_ADDRSTRLEN + 1] = {0};
  size_t addressLength = size_t(slash - text);
  if (addressLength == 0 || addressLength >= sizeof(addressText))
  {
    return false;
  }

  std::memcpy(addressText, text, addressLength);

  char *end = nullptr;
  unsigned long cidr = std::strtoul(slash + 1, &end, 10);
  if (end == slash + 1 || *end != '\0')
  {
    return false;
  }

  IPPrefix parsed = {};
  if (inet_pton(AF_INET, addressText, parsed.network.v6) == 1)
  {
    if (cidr > 32)
    {
      return false;
    }

    parsed.network.is6 = false;
    parsed.cidr = static_cast<uint8_t>(cidr);
    parsed.canonicalize();
    prefix = parsed;
    return true;
  }

  if (inet_pton(AF_INET6, addressText, parsed.network.v6) == 1)
  {
    if (cidr > 128)
    {
      return false;
    }

    parsed.network.is6 = true;
    parsed.cidr = static_cast<uint8_t>(cidr);
    parsed.canonicalize();
    prefix = parsed;
    return true;
  }

  return false;
}

static bool mothershipParseEndpointHostPort(const String& endpoint, String& host, uint16_t& port, String *failure = nullptr)
{
  host.clear();
  port = 0;

  auto fail = [&](auto&& text) -> bool {
    if (failure)
    {
      failure->assign(text);
    }
    return false;
  };

  String endpointText = {};
  endpointText.assign(endpoint);
  const char *text = endpointText.c_str();
  const char *colon = std::strrchr(text, ':');
  if (colon == nullptr || colon == text || colon[1] == '\0' || std::strchr(text, ':') != colon)
  {
    return fail("endpoint must be host:port"_ctv);
  }
  host.append(text, uint32_t(colon - text));

  char *endPort = nullptr;
  errno = 0;
  unsigned long parsedPort = std::strtoul(colon + 1, &endPort, 10);
  if (endPort == colon + 1 || *endPort != '\0' || errno != 0 || parsedPort == 0 || parsedPort > UINT16_MAX)
  {
    host.clear();
    return fail("endpoint port invalid"_ctv);
  }

  port = uint16_t(parsedPort);
  if (failure)
  {
    failure->clear();
  }
  return true;
}

