static bool formatCIDRPrefix(const IPPrefix& prefix, char *buffer, size_t bufferSize)
{
  if (buffer == nullptr || bufferSize == 0)
  {
    return false;
  }

  char addressBuffer[INET6_ADDRSTRLEN] = {0};
  if (inet_ntop(prefix.network.is6 ? AF_INET6 : AF_INET, prefix.network.v6, addressBuffer, sizeof(addressBuffer)) == nullptr)
  {
    return false;
  }

  int written = std::snprintf(buffer, bufferSize, "%s/%u", addressBuffer, unsigned(prefix.cidr));
  return written > 0 && size_t(written) < bufferSize;
}

static void renderMothershipClusterMachineIdentity(const MothershipProdigyClusterMachine& machine, String& label)
{
  label.clear();

  if (machine.cloudPresent() && machine.cloud.cloudID.size() > 0)
  {
    label.assign(machine.cloud.cloudID);
    return;
  }

  for (const ClusterMachineAddress& candidate : machine.addresses.privateAddresses)
  {
    if (candidate.address.size() > 0)
    {
      label.assign(candidate.address);
      return;
    }
  }

  if (machine.ssh.address.size() > 0)
  {
    label.assign(machine.ssh.address);
    return;
  }

  for (const ClusterMachineAddress& candidate : machine.addresses.publicAddresses)
  {
    if (candidate.address.size() > 0)
    {
      label.assign(candidate.address);
      return;
    }
  }

  label.assign("unknown-machine"_ctv);
}

static void mothershipHydrateTopologyRemoteCandidateSSH(const MothershipProdigyCluster& cluster, MothershipProdigyClusterMachine& candidate)
{
  if (candidate.ssh.address.size() == 0)
  {
    // Managed remote topology machines often do not carry an explicit SSH
    // address; prefer public reachability for Mothership-originated control.
    if (const ClusterMachineAddress *publicAddress = prodigyFirstClusterMachineAddress(candidate.addresses.publicAddresses); publicAddress != nullptr)
    {
      candidate.ssh.address = publicAddress->address;
    }
    else if (const ClusterMachineAddress *privateAddress = prodigyFirstClusterMachineAddress(candidate.addresses.privateAddresses); privateAddress != nullptr)
    {
      candidate.ssh.address = privateAddress->address;
    }
  }

  if (candidate.ssh.port == 0)
  {
    candidate.ssh.port = 22;
  }

  if (candidate.ssh.user.size() == 0)
  {
    if (cluster.bootstrapSshUser.size() > 0)
    {
      candidate.ssh.user = cluster.bootstrapSshUser;
    }
    else
    {
      candidate.ssh.user.assign(defaultMothershipClusterSSHUser());
    }
  }

  if (candidate.ssh.privateKeyPath.size() == 0)
  {
    candidate.ssh.privateKeyPath = cluster.bootstrapSshPrivateKeyPath;
  }

  if (candidate.ssh.hostPublicKeyOpenSSH.size() == 0)
  {
    candidate.ssh.hostPublicKeyOpenSSH = cluster.bootstrapSshHostKeyPackage.publicKeyOpenSSH;
  }
}

static void printManagedCluster(const MothershipProdigyCluster& cluster)
{
  String name = cluster.name;
  String clusterUUIDHex = {};
  clusterUUIDHex.assignItoh(cluster.clusterUUID);
  String lastRefreshFailure = cluster.lastRefreshFailure;
  String providerScope = cluster.providerScope;
  String providerCredentialName = cluster.providerCredentialName;

  basics_log("  name=%s clusterUUID=%s deploymentMode=%s provider=%s datacenterFragment=%u autoscaleIntervalSeconds=%u nBrains=%u desiredEnvironment=%s environmentConfigured=%d lastRefreshMs=%lld lastRefreshFailure=%s\n",
             name.c_str(),
             clusterUUIDHex.c_str(),
             mothershipClusterDeploymentModeName(cluster.deploymentMode),
             mothershipClusterProviderName(cluster.provider),
             unsigned(cluster.datacenterFragment),
             unsigned(cluster.autoscaleIntervalSeconds),
             unsigned(cluster.nBrains),
             prodigyEnvironmentKindName(cluster.desiredEnvironment),
             int(cluster.environmentConfigured),
             (long long)cluster.lastRefreshMs,
             (lastRefreshFailure.size() ? lastRefreshFailure.c_str() : ""));
  basics_log("    architecture=%s\n", machineCpuArchitectureName(cluster.architecture));

  if (cluster.deploymentMode == MothershipClusterDeploymentMode::local)
  {
    basics_log("    includeLocalMachine=%d\n", int(cluster.includeLocalMachine));
  }

  if (cluster.provider != MothershipClusterProvider::unknown || providerScope.size() > 0)
  {
    basics_log("    providerScope=%s providerCredentialName=%s propagateProviderCredentialToProdigy=%d\n",
               providerScope.size() ? providerScope.c_str() : "",
               providerCredentialName.c_str(),
               int(cluster.propagateProviderCredentialToProdigy));

    if (cluster.provider == MothershipClusterProvider::gcp || cluster.gcp.configured())
    {
      String serviceAccountEmail = cluster.gcp.serviceAccountEmail;
      String network = cluster.gcp.network;
      String subnetwork = cluster.gcp.subnetwork;
      basics_log("    gcp.serviceAccountEmail=%s gcp.network=%s gcp.subnetwork=%s\n",
                 serviceAccountEmail.c_str(),
                 network.c_str(),
                 subnetwork.c_str());
    }

    if (cluster.provider == MothershipClusterProvider::aws || cluster.aws.configured())
    {
      String instanceProfileName = cluster.aws.instanceProfileName;
      String instanceProfileArn = cluster.aws.instanceProfileArn;
      basics_log("    aws.instanceProfileName=%s aws.instanceProfileArn=%s\n",
                 instanceProfileName.c_str(),
                 instanceProfileArn.c_str());
    }

    if (cluster.provider == MothershipClusterProvider::azure || cluster.azure.configured())
    {
      String managedIdentityName = cluster.azure.managedIdentityName;
      String managedIdentityResourceID = cluster.azure.managedIdentityResourceID;
      basics_log("    azure.managedIdentityName=%s azure.managedIdentityResourceID=%s\n",
                 managedIdentityName.c_str(),
                 managedIdentityResourceID.c_str());
    }
  }

  if (cluster.dnsProvider != MothershipClusterProvider::unknown)
  {
    String dnsCredentialName = cluster.dnsProviderCredentialName;
    basics_log("    dnsProvider=%s dnsProviderCredentialName=%s\n",
               mothershipClusterProviderName(cluster.dnsProvider),
               dnsCredentialName.c_str());
  }
  if (cluster.acme.configured())
  {
    String accountEmail = cluster.acme.accountEmail;
    basics_log("    acme.accountEmail=%s acme.termsAgreed=%d\n",
               accountEmail.c_str(),
               int(cluster.acme.termsAgreed));
  }
  basics_log("    resourceReservation=%s reserved=%u/%u/%u\n",
             prodigyMachineReservedResourcesProfileName(cluster.machineReservedResources),
             unsigned(cluster.machineReservedResources.logicalCores),
             unsigned(cluster.machineReservedResources.memoryMB),
             unsigned(cluster.machineReservedResources.storageMB));

  for (const MothershipProdigyClusterControl& control : cluster.controls)
  {
    String path = control.path;

    basics_log("    control kind=%s path=%s\n",
               mothershipClusterControlKindName(control.kind),
               path.c_str());
  }

  basics_log("    mothershipConnectivity kind=%s\n", mothershipConnectivityKindName(cluster.mothershipConnectivity.kind));
  if (cluster.mothershipConnectivity.kind == MothershipConnectivityKind::tunnelProvider)
  {
    const MothershipTunnelProviderSpec& spec = cluster.mothershipConnectivity.tunnelProvider;
    String endpoint = spec.dialEndpoint;
    String egressHost = {};
    (void)prodigySystemEgressIPv4Text(spec.egress.address4, egressHost);
    String artifactSha256 = spec.artifactSha256;
    basics_log("    tunnelProvider endpoint=%s egress=%s:%u artifactSha256=%s artifactBytes=%llu\n",
               endpoint.c_str(),
               egressHost.c_str(),
               unsigned(spec.egress.port),
               artifactSha256.c_str(),
               (unsigned long long)spec.artifactBytes);
  }

  if ((cluster.deploymentMode == MothershipClusterDeploymentMode::remote) || (cluster.deploymentMode == MothershipClusterDeploymentMode::local && cluster.machines.empty() == false))
  {
    String bootstrapSshUser = cluster.bootstrapSshUser;
    String bootstrapSshPrivateKeyPath = cluster.bootstrapSshPrivateKeyPath;
    String remoteProdigyPath = cluster.remoteProdigyPath;

    basics_log("    bootstrapSshUser=%s bootstrapSshPrivateKeyPath=%s remoteProdigyPath=%s\n",
               bootstrapSshUser.c_str(),
               bootstrapSshPrivateKeyPath.c_str(),
               remoteProdigyPath.c_str());
  }

  if (cluster.deploymentMode == MothershipClusterDeploymentMode::test && cluster.test.specified)
  {
    String workspaceRoot = cluster.test.workspaceRoot;
    basics_log("    test workspaceRoot=%s machineCount=%u spareMachineCount=%u machineLogicalCores=%u machineMemoryMB=%u machineStorageMB=%u storageDeviceCount=%u storageDeviceMB=%u brainBootstrapFamily=%s enableFakeIpv4Boundary=%d interContainerMTU=%u\n",
               workspaceRoot.c_str(),
               unsigned(cluster.test.machineCount),
               unsigned(cluster.test.spareMachineCount),
               unsigned(cluster.test.machineLogicalCores),
               unsigned(cluster.test.machineMemoryMB),
               unsigned(cluster.test.machineStorageMB),
               unsigned(cluster.test.storageDeviceCount),
               unsigned(cluster.test.storageDeviceMB),
               mothershipClusterTestBootstrapFamilyName(cluster.test.brainBootstrapFamily),
               int(cluster.test.enableFakeIpv4Boundary),
               unsigned(cluster.test.interContainerMTU));
  }

  for (const MothershipProdigyClusterMachineSchema& managedSchema : cluster.machineSchemas)
  {
    String schema = managedSchema.schema;
    String ipxeScriptURL = managedSchema.ipxeScriptURL;
    String vmImageURI = managedSchema.vmImageURI;
    String gcpInstanceTemplate = managedSchema.gcpInstanceTemplate;
    String gcpInstanceTemplateSpot = managedSchema.gcpInstanceTemplateSpot;
    String providerMachineType = managedSchema.providerMachineType;
    String providerReservationID = managedSchema.providerReservationID;
    String region = managedSchema.region;
    String zone = managedSchema.zone;
    String cpuPlatform = managedSchema.cpu.cpuPlatform;
    basics_log("    schema=%s kind=%s lifetime=%s ipxeScriptURL=%s vmImageURI=%s gcpInstanceTemplate=%s gcpInstanceTemplateSpot=%s providerMachineType=%s providerReservationID=%s region=%s zone=%s cpuArchitecture=%s cpuPlatform=%s budget=%u\n",
               schema.c_str(),
               machineKindName(managedSchema.kind),
               machineLifetimeName(managedSchema.lifetime),
               ipxeScriptURL.c_str(),
               vmImageURI.c_str(),
               gcpInstanceTemplate.c_str(),
               gcpInstanceTemplateSpot.c_str(),
               providerMachineType.c_str(),
               providerReservationID.c_str(),
               region.c_str(),
               zone.c_str(),
               machineCpuArchitectureName(managedSchema.cpu.architecture),
               cpuPlatform.c_str(),
               unsigned(managedSchema.budget));
  }

  for (const MothershipProdigyClusterMachine& machine : cluster.machines)
  {
    String machineIdentity = {};
    renderMothershipClusterMachineIdentity(machine, machineIdentity);
    String sshAddress = machine.ssh.address;
    String sshUser = machine.ssh.user;
    String sshPrivateKeyPath = machine.ssh.privateKeyPath;
    String privateAddresses = {};
    String publicAddresses = {};
    prodigyAppendCommaSeparatedClusterMachineAddressList(machine.addresses.privateAddresses, privateAddresses);
    prodigyAppendCommaSeparatedClusterMachineAddressList(machine.addresses.publicAddresses, publicAddresses);
    if (machine.cloudPresent())
    {
      String schema = machine.cloud.schema;
      String providerMachineType = machine.cloud.providerMachineType;
      String cloudID = machine.cloud.cloudID;
      basics_log("    machine identity=%s schema=%s source=%s backing=%s kind=%s lifetime=%s isBrain=%d providerMachineType=%s cloudID=%s sshAddress=%s sshPort=%u sshUser=%s sshPrivateKeyPath=%s publicAddresses=%s privateAddresses=%s ",
                 machineIdentity.c_str(),
                 schema.c_str(),
                 mothershipClusterMachineSourceName(machine.source),
                 clusterMachineBackingName(machine.backing),
                 machineKindName(machine.kind),
                 machineLifetimeName(machine.lifetime),
                 int(machine.isBrain),
                 providerMachineType.c_str(),
                 cloudID.c_str(),
                 sshAddress.c_str(),
                 unsigned(machine.ssh.port),
                 sshUser.c_str(),
                 sshPrivateKeyPath.c_str(),
                 publicAddresses.c_str(),
                 privateAddresses.c_str());
    }
    else
    {
      basics_log("    machine identity=%s source=%s backing=%s kind=%s lifetime=%s isBrain=%d sshAddress=%s sshPort=%u sshUser=%s sshPrivateKeyPath=%s publicAddresses=%s privateAddresses=%s ",
                 machineIdentity.c_str(),
                 mothershipClusterMachineSourceName(machine.source),
                 clusterMachineBackingName(machine.backing),
                 machineKindName(machine.kind),
                 machineLifetimeName(machine.lifetime),
                 int(machine.isBrain),
                 sshAddress.c_str(),
                 unsigned(machine.ssh.port),
                 sshUser.c_str(),
                 sshPrivateKeyPath.c_str(),
                 publicAddresses.c_str(),
                 privateAddresses.c_str());
    }
    printClusterMachineOwnership(machine.ownership);
    basics_log("\n");
  }

  if (cluster.topology.machines.empty() == false)
  {
    basics_log("    topology version=%llu machines=%u\n",
               (unsigned long long)cluster.topology.version,
               unsigned(cluster.topology.machines.size()));

    for (const ClusterMachine& machine : cluster.topology.machines)
    {
      String machineIdentity = {};
      machine.renderIdentityLabel(machineIdentity);
      String sshAddress = machine.ssh.address;
      String sshUser = machine.ssh.user;
      String sshPrivateKeyPath = machine.ssh.privateKeyPath;
      String privateAddresses = {};
      String publicAddresses = {};
      prodigyAppendCommaSeparatedClusterMachineAddressList(machine.addresses.privateAddresses, privateAddresses);
      prodigyAppendCommaSeparatedClusterMachineAddressList(machine.addresses.publicAddresses, publicAddresses);
      if (machine.cloudPresent())
      {
        String schema = machine.cloud.schema;
        String providerMachineType = machine.cloud.providerMachineType;
        String cloudID = machine.cloud.cloudID;
        basics_log("      topologyMachine identity=%s schema=%s source=%u backing=%s kind=%s lifetime=%s isBrain=%d providerMachineType=%s cloudID=%s sshAddress=%s sshPort=%u sshUser=%s sshPrivateKeyPath=%s publicAddresses=%s privateAddresses=%s creationTimeMs=%lld ",
                   machineIdentity.c_str(),
                   schema.c_str(),
                   unsigned(machine.source),
                   clusterMachineBackingName(machine.backing),
                   machineKindName(machine.kind),
                   machineLifetimeName(machine.lifetime),
                   int(machine.isBrain),
                   providerMachineType.c_str(),
                   cloudID.c_str(),
                   sshAddress.c_str(),
                   unsigned(machine.ssh.port),
                   sshUser.c_str(),
                   sshPrivateKeyPath.c_str(),
                   publicAddresses.c_str(),
                   privateAddresses.c_str(),
                   (long long)machine.creationTimeMs);
      }
      else
      {
        basics_log("      topologyMachine identity=%s source=%u backing=%s kind=%s lifetime=%s isBrain=%d sshAddress=%s sshPort=%u sshUser=%s sshPrivateKeyPath=%s publicAddresses=%s privateAddresses=%s creationTimeMs=%lld ",
                   machineIdentity.c_str(),
                   unsigned(machine.source),
                   clusterMachineBackingName(machine.backing),
                   machineKindName(machine.kind),
                   machineLifetimeName(machine.lifetime),
                   int(machine.isBrain),
                   sshAddress.c_str(),
                   unsigned(machine.ssh.port),
                   sshUser.c_str(),
                   sshPrivateKeyPath.c_str(),
                   publicAddresses.c_str(),
                   privateAddresses.c_str(),
                   (long long)machine.creationTimeMs);
      }
      printClusterMachineOwnership(machine.ownership);
      basics_log(" owned=%u/%u/%u uuidSet=%d\n",
                 unsigned(machine.ownedLogicalCores),
                 unsigned(machine.ownedMemoryMB),
                 unsigned(machine.ownedStorageMB),
                 int(machine.uuid != 0));
      if (!machine.ssh.hostPublicKeyOpenSSH.empty())
      {
        String hostPublicKey = machine.ssh.hostPublicKeyOpenSSH;
        basics_log("      topologyMachineHostPublicKey identity=%s hostPublicKeyOpenSSH=%s\n",
                   machineIdentity.c_str(), hostPublicKey.c_str());
      }
    }
  }
}

static void printProviderCredential(const MothershipProviderCredential& credential)
{
  String name = credential.name;
  String scope = credential.scope;
  String impersonateServiceAccount = credential.impersonateServiceAccount;
  String credentialPath = credential.credentialPath;

  basics_log("  name=%s provider=%s mode=%s scope=%s allowPropagateToProdigy=%d materialPresent=%d materialBytes=%u metadata=%u impersonateServiceAccount=%s credentialPath=%s createdAtMs=%lld updatedAtMs=%lld\n",
             name.c_str(),
             mothershipClusterProviderName(credential.provider),
             mothershipProviderCredentialModeName(credential.mode),
             scope.c_str(),
             int(credential.allowPropagateToProdigy),
             int(credential.material.size() > 0),
             unsigned(credential.material.size()),
             unsigned(credential.metadata.size()),
             impersonateServiceAccount.c_str(),
             credentialPath.c_str(),
             (long long)credential.createdAtMs,
             (long long)credential.updatedAtMs);
  for (const auto& [key, value] : credential.metadata)
  {
    String renderedKey = key;
    String renderedValue = value;
    basics_log("    metadata %s=%s\n", renderedKey.c_str(), renderedValue.c_str());
  }
}

static bool resolveServiceName(String serviceName, uint64_t& service)
{
  if (auto it = MeshRegistry::serviceMappings.find(serviceName); it != MeshRegistry::serviceMappings.end())
  {
    service = it->second;
    return true;
  }

  int64_t dot = serviceName.rfindChar('.');
  if (dot <= 0 || dot >= int64_t(serviceName.size() - 1))
  {
    return false;
  }

  String suffix = serviceName.substr(uint64_t(dot + 1), serviceName.size() - uint64_t(dot + 1), Copy::no);
  if (suffix.size() <= 5 || memcmp(suffix.data(), "group", 5) != 0)
  {
    return false;
  }

  uint32_t group = 0;
  for (uint64_t i = 5; i < suffix.size(); i++)
  {
    uint8_t c = suffix.data()[i];
    if (c < '0' || c > '9')
    {
      return false;
    }

    group = (group * 10) + uint32_t(c - '0');
    if (group >= (1u << 10))
    {
      return false;
    }
  }

  String baseService = serviceName.substr(0, uint64_t(dot), Copy::yes);
  if (auto it = MeshRegistry::serviceMappings.find(baseService); it != MeshRegistry::serviceMappings.end())
  {
    if (MeshServices::isPrefix(it->second) == false)
    {
      return false;
    }

    service = MeshServices::constrainPrefixToGroup(it->second, uint16_t(group));
    return true;
  }

  return false;
}

static bool parseSymbolReference(const String& value, const char *kind, String& body)
{
  uint64_t kindSize = std::strlen(kind);
  uint64_t expectedSize = 2 + kindSize + 1;
  if (value.size() <= expectedSize)
  {
    return false;
  }

  if (value.data()[0] != '$' || value.data()[1] != '{' || value.data()[value.size() - 1] != '}')
  {
    return false;
  }

  if (std::memcmp(value.data() + 2, kind, kindSize) != 0)
  {
    return false;
  }

  if (value.data()[2 + kindSize] != ':')
  {
    return false;
  }

  body.assign(value.substr(3 + kindSize, value.size() - (3 + kindSize) - 1, Copy::no));
  return body.size() > 0;
}

static bool parseApplicationReferenceSymbol(const String& value, String& applicationName)
{
  if (parseSymbolReference(value, "application", applicationName))
  {
    return true;
  }

  return parseSymbolReference(value, "app", applicationName);
}

static bool parseServiceReferenceSymbol(const String& value, String& applicationName, String& serviceName, bool& hasGroup, uint16_t& group)
{
  String body;
  if (parseSymbolReference(value, "service", body) == false && parseSymbolReference(value, "svc", body) == false)
  {
    return false;
  }

  int64_t slash = body.findChar('/');
  if (slash <= 0 || slash >= int64_t(body.size() - 1))
  {
    return false;
  }

  applicationName.assign(body.substr(0, uint64_t(slash), Copy::no));

  String serviceSpec;
  serviceSpec.assign(body.substr(uint64_t(slash + 1), body.size() - uint64_t(slash + 1), Copy::no));
  if (serviceSpec.size() == 0)
  {
    return false;
  }

  hasGroup = false;
  group = 0;
  serviceName = serviceSpec;

  int64_t dot = serviceSpec.rfindChar('.');
  if (dot <= 0 || dot >= int64_t(serviceSpec.size() - 1))
  {
    return true;
  }

  String suffix = serviceSpec.substr(uint64_t(dot + 1), serviceSpec.size() - uint64_t(dot + 1), Copy::no);
  if (suffix.size() <= 5 || std::memcmp(suffix.data(), "group", 5) != 0)
  {
    return true;
  }

  uint32_t parsedGroup = 0;
  for (uint64_t i = 5; i < suffix.size(); i += 1)
  {
    uint8_t c = suffix.data()[i];
    if (c < '0' || c > '9')
    {
      return false;
    }

    parsedGroup = (parsedGroup * 10) + uint32_t(c - '0');
    if (parsedGroup >= (1u << 10))
    {
      return false;
    }
  }

  hasGroup = true;
  group = uint16_t(parsedGroup);
  serviceName.assign(serviceSpec.substr(0, uint64_t(dot), Copy::no));
  return serviceName.size() > 0;
}

static bool parseScalingDimensionAlias(const String& value, ScalingDimension& dimension)
{
  if (value.equal("ScalingDimension::cpu"_ctv) || value.equal("ResourceType::cpu"_ctv))
  {
    dimension = ScalingDimension::cpu;
    return true;
  }
  else if (value.equal("ScalingDimension::memory"_ctv) || value.equal("ResourceType::memory"_ctv))
  {
    dimension = ScalingDimension::memory;
    return true;
  }
  else if (value.equal("ScalingDimension::storage"_ctv) || value.equal("ResourceType::storage"_ctv))
  {
    dimension = ScalingDimension::storage;
    return true;
  }
  else if (value.equal("ScalingDimension::runtimeIngressQueueWaitComposite"_ctv) || value.equal("ResourceType::runtimeIngressQueueWaitComposite"_ctv))
  {
    dimension = ScalingDimension::runtimeIngressQueueWaitComposite;
    return true;
  }
  else if (value.equal("ScalingDimension::runtimeIngressHandlerComposite"_ctv) || value.equal("ResourceType::runtimeIngressHandlerComposite"_ctv))
  {
    dimension = ScalingDimension::runtimeIngressHandlerComposite;
    return true;
  }

  return false;
}

static bool resolveScalerMetricNameFromAlias(const String& value, String& metricName)
{
  ScalingDimension dimension = ScalingDimension::cpu;
  if (parseScalingDimensionAlias(value, dimension) == false)
  {
    return false;
  }

  const char *builtinName = ProdigyMetrics::nameForScalingDimension(dimension);
  if (builtinName == nullptr)
  {
    return false;
  }

  metricName.assign(builtinName);
  return true;
}

constexpr static uint32_t radarMinimumLogicalCores = 3;

static void printConnectFailure(void)
{
  basics_log("failed to connect to mothership: %s\n", std::strerror(errno));
}

static void mothershipAppendSSHSessionLastError(LIBSSH2_SESSION *session, String& failure)
{
  if (session == nullptr)
  {
    return;
  }

  char *errmsg = nullptr;
  int len = 0;
  if (libssh2_session_last_error(session, &errmsg, &len, 0) == 0 && errmsg != nullptr && len > 0)
  {
    failure.append(reinterpret_cast<const uint8_t *>(errmsg), uint64_t(len));
  }
}

static bool mothershipWaitForSSHSessionIO(LIBSSH2_SESSION *session, int fd, int timeoutMs)
{
  if (session == nullptr || fd < 0)
  {
    return false;
  }

  struct pollfd descriptor = {};
  descriptor.fd = fd;
  descriptor.events = POLLHUP | POLLERR;

  int directions = libssh2_session_block_directions(session);
  if (directions & LIBSSH2_SESSION_BLOCK_INBOUND)
  {
    descriptor.events |= POLLIN;
  }

  if (directions & LIBSSH2_SESSION_BLOCK_OUTBOUND)
  {
    descriptor.events |= POLLOUT;
  }

  if (descriptor.events == 0)
  {
    descriptor.events = POLLHUP | POLLERR | POLLIN | POLLOUT;
  }

  int rc = ::poll(&descriptor, 1, timeoutMs);
  if (rc <= 0)
  {
    basics_log("mothership control ssh-wait rc=%d fd=%d timeoutMs=%d directions=%d events=%hd revents=%hd errno=%d(%s)\n",
               rc,
               fd,
               timeoutMs,
               directions,
               descriptor.events,
               descriptor.revents,
               errno,
               std::strerror(errno));
    return false;
  }

  if (descriptor.revents & (POLLHUP | POLLERR | POLLNVAL))
  {
    basics_log("mothership control ssh-wait-event fd=%d timeoutMs=%d directions=%d events=%hd revents=%hd\n",
               fd,
               timeoutMs,
               directions,
               descriptor.events,
               descriptor.revents);
  }

  return true;
}

static bool mothershipRunSSHCommandCaptureOutput(LIBSSH2_SESSION *session, int fd, const String& command, String& output, String *failure = nullptr, int timeoutMs = 25'000)
{
  output.clear();

  String commandText = {};
  commandText.assign(command);
  LIBSSH2_CHANNEL *channel = libssh2_channel_open_session(session);
  if (channel == nullptr)
  {
    if (failure)
    {
      failure->assign("failed to open ssh exec channel");
    }
    return false;
  }

  if (libssh2_channel_exec(channel, commandText.c_str()) != 0)
  {
    if (failure)
    {
      failure->snprintf<"failed to execute remote command {}"_ctv>(command);
    }
    libssh2_channel_free(channel);
    return false;
  }

  libssh2_session_set_blocking(session, 0);

  char scratch[2048];
  int64_t deadlineMs = Time::now<TimeResolution::ms>() + int64_t(timeoutMs);
  for (;;)
  {
    bool progressed = false;

    for (;;)
    {
      ssize_t rc = libssh2_channel_read(channel, scratch, sizeof(scratch));
      if (rc > 0)
      {
        output.append(reinterpret_cast<uint8_t *>(scratch), uint64_t(rc));
        progressed = true;
        continue;
      }

      if (rc == LIBSSH2_ERROR_EAGAIN)
      {
        break;
      }

      if (rc < 0)
      {
        if (failure)
        {
          failure->assign("failed to read remote command stdout: "_ctv);
          mothershipAppendSSHSessionLastError(session, *failure);
        }

        libssh2_session_set_blocking(session, 1);
        (void)libssh2_channel_close(channel);
        libssh2_channel_free(channel);
        return false;
      }

      break;
    }

    for (;;)
    {
      ssize_t rc = libssh2_channel_read_stderr(channel, scratch, sizeof(scratch));
      if (rc > 0)
      {
        output.append(reinterpret_cast<uint8_t *>(scratch), uint64_t(rc));
        progressed = true;
        continue;
      }

      if (rc == LIBSSH2_ERROR_EAGAIN)
      {
        break;
      }

      if (rc < 0)
      {
        if (failure)
        {
          failure->assign("failed to read remote command stderr: "_ctv);
          mothershipAppendSSHSessionLastError(session, *failure);
        }

        libssh2_session_set_blocking(session, 1);
        (void)libssh2_channel_close(channel);
        libssh2_channel_free(channel);
        return false;
      }

      break;
    }

    if (libssh2_channel_eof(channel))
    {
      break;
    }

    if (progressed)
    {
      continue;
    }

    int64_t nowMs = Time::now<TimeResolution::ms>();
    if (nowMs >= deadlineMs)
    {
      if (failure)
      {
        failure->snprintf<"remote command timed out after {itoa}ms: {}"_ctv>(uint64_t(timeoutMs), command);
      }
      libssh2_session_set_blocking(session, 1);
      (void)libssh2_channel_close(channel);
      libssh2_channel_free(channel);
      return false;
    }

    int remainingMs = int(deadlineMs - nowMs);
    if (mothershipWaitForSSHSessionIO(session, fd, remainingMs) == false)
    {
      if (failure)
      {
        failure->snprintf<"remote command timed out after {itoa}ms waiting for ssh io: {}"_ctv>(uint64_t(timeoutMs), command);
      }
      libssh2_session_set_blocking(session, 1);
      (void)libssh2_channel_close(channel);
      libssh2_channel_free(channel);
      return false;
    }
  }

  libssh2_session_set_blocking(session, 1);
  (void)libssh2_channel_send_eof(channel);
  (void)libssh2_channel_wait_eof(channel);
  (void)libssh2_channel_close(channel);

  int exitStatus = libssh2_channel_get_exit_status(channel);
  libssh2_channel_free(channel);
  if (exitStatus != 0)
  {
    if (failure)
    {
      failure->snprintf<"remote command failed: {}"_ctv>(command);
    }
    return false;
  }

  if (failure)
  {
    failure->clear();
  }
  return true;
}

static bool mothershipReadProcFile(const String& path, String& output)
{
  output.clear();

  String ownedPath = {};
  ownedPath.assign(path);
  int fd = ::open(ownedPath.c_str(), O_RDONLY | O_CLOEXEC);
  if (fd < 0)
  {
    return false;
  }

  char scratch[4096];
  for (;;)
  {
    ssize_t bytes = ::read(fd, scratch, sizeof(scratch));
    if (bytes == 0)
    {
      break;
    }

    if (bytes < 0)
    {
      if (errno == EINTR)
      {
        continue;
      }

      output.clear();
      ::close(fd);
      return false;
    }

    output.append(reinterpret_cast<uint8_t *>(scratch), uint64_t(bytes));
  }

  ::close(fd);
  return output.size() > 0;
}

static bool mothershipReadProcEnvironmentValue(uint32_t pid, const char *name, String& value)
{
  value.clear();
  if (name == nullptr || name[0] == '\0')
  {
    return false;
  }

  String path = {};
  path.snprintf<"/proc/{itoa}/environ"_ctv>(uint64_t(pid));

  String environment = {};
  if (mothershipReadProcFile(path, environment) == false)
  {
    return false;
  }

  const uint64_t nameLength = uint64_t(std::strlen(name));
  uint64_t offset = 0;
  while (offset < environment.size())
  {
    uint64_t end = offset;
    while (end < environment.size() && environment[end] != '\0')
    {
      end += 1;
    }

    if (end > offset + nameLength && std::memcmp(environment.data() + offset, name, nameLength) == 0 && environment[offset + nameLength] == '=')
    {
      value.assign(environment.substr(offset + nameLength + 1, end - offset - nameLength - 1, Copy::yes));
      return value.size() > 0;
    }

    offset = end + 1;
  }

  return false;
}

static bool mothershipReadProcCommandLineValue(uint32_t pid, const char *name, String& value)
{
  value.clear();
  if (name == nullptr || name[0] == '\0')
  {
    return false;
  }

  String path = {};
  path.snprintf<"/proc/{itoa}/cmdline"_ctv>(uint64_t(pid));

  String commandLine = {};
  if (mothershipReadProcFile(path, commandLine) == false)
  {
    return false;
  }

  const uint64_t nameLength = uint64_t(std::strlen(name));
  uint64_t offset = 0;
  while (offset < commandLine.size())
  {
    uint64_t end = offset;
    while (end < commandLine.size() && commandLine[end] != '\0')
    {
      end += 1;
    }

    if (end > offset + nameLength && std::memcmp(commandLine.data() + offset, name, nameLength) == 0 && commandLine[offset + nameLength] == '=')
    {
      value.assign(commandLine.substr(offset + nameLength + 1, end - offset - nameLength - 1, Copy::yes));
      return value.size() > 0;
    }

    if (end == offset + nameLength && std::memcmp(commandLine.data() + offset, name, nameLength) == 0)
    {
      offset = end + 1;
      if (offset >= commandLine.size())
      {
        return false;
      }

      uint64_t nextEnd = offset;
      while (nextEnd < commandLine.size() && commandLine[nextEnd] != '\0')
      {
        nextEnd += 1;
      }

      value.assign(commandLine.substr(offset, nextEnd - offset, Copy::yes));
      return value.size() > 0;
    }

    offset = end + 1;
  }

  return false;
}

static bool mothershipReadProcBootJSONControlSocketPath(uint32_t pid, String& controlSocketPath)
{
  controlSocketPath.clear();

  String bootJSON = {};
  if (mothershipReadProcCommandLineValue(pid, "--boot-json", bootJSON) == false)
  {
    return false;
  }

  ProdigyPersistentBootState bootState = {};
  if (parseProdigyPersistentBootStateJSON(bootJSON, bootState) == false)
  {
    return false;
  }

  if (bootState.bootstrapConfig.controlSocketPath.size() == 0)
  {
    return false;
  }

  controlSocketPath = bootState.bootstrapConfig.controlSocketPath;
  return true;
}

static bool mothershipPathIsUnixSocket(const String& path)
{
  String ownedPath = {};
  ownedPath.assign(path);
  struct stat st = {};
  if (::stat(ownedPath.c_str(), &st) != 0)
  {
    return false;
  }

  return S_ISSOCK(st.st_mode);
}

static bool mothershipIsProdigyProcess(uint32_t pid)
{
  String path = {};
  path.snprintf<"/proc/{itoa}/comm"_ctv>(uint64_t(pid));

  String processName = {};
  if (mothershipReadProcFile(path, processName) == false)
  {
    return false;
  }

  uint64_t trimmedLength = processName.size();
  while (trimmedLength > 0 && std::isspace(static_cast<unsigned char>(processName[trimmedLength - 1])))
  {
    trimmedLength -= 1;
  }

  if (trimmedLength != processName.size())
  {
    processName.assign(processName.substr(0, trimmedLength, Copy::yes));
  }

  return processName.equal("prodigy"_ctv);
}

static bool resolveLiveLocalProdigyControlSocketPath(String& controlSocketPath, String *failure = nullptr)
{
  controlSocketPath.clear();

  String expectedStateDBPath = {};
  resolveProdigyPersistentStateDBPath(expectedStateDBPath);

  DIR *proc = ::opendir("/proc");
  if (proc == nullptr)
  {
    if (failure)
    {
      failure->snprintf<"failed to open /proc: {}"_ctv>(String(std::strerror(errno)));
    }
    return false;
  }

  String singleCandidateSocketPath = {};
  uint32_t candidateCount = 0;

  while (dirent *entry = ::readdir(proc))
  {
    char *end = nullptr;
    unsigned long pidValue = std::strtoul(entry->d_name, &end, 10);
    if (end == entry->d_name || *end != '\0' || pidValue == 0 || pidValue > std::numeric_limits<uint32_t>::max())
    {
      continue;
    }

    uint32_t pid = uint32_t(pidValue);
    if (mothershipIsProdigyProcess(pid) == false)
    {
      continue;
    }

    String socketPath = {};
    if (mothershipReadProcBootJSONControlSocketPath(pid, socketPath) == false && mothershipReadProcEnvironmentValue(pid, "PRODIGY_MOTHERSHIP_SOCKET", socketPath) == false)
    {
      continue;
    }

    String stateDBPath = {};
    if (mothershipReadProcEnvironmentValue(pid, "PRODIGY_STATE_DB", stateDBPath) && stateDBPath.equals(expectedStateDBPath))
    {
      ::closedir(proc);
      controlSocketPath = socketPath;
      if (failure)
      {
        failure->clear();
      }
      return true;
    }

    candidateCount += 1;
    if (candidateCount == 1)
    {
      singleCandidateSocketPath = socketPath;
    }
  }

  ::closedir(proc);

  if (candidateCount == 1)
  {
    controlSocketPath = singleCandidateSocketPath;
    if (failure)
    {
      failure->clear();
    }
    return true;
  }

  if (candidateCount > 1)
  {
    if (failure)
    {
      failure->snprintf<"found {itoa} live local prodigy processes but none matched PRODIGY_STATE_DB={}"_ctv>(
          uint64_t(candidateCount),
          expectedStateDBPath);
    }

    return false;
  }

  if (failure)
  {
    failure->assign("no live local prodigy process found"_ctv);
  }
  return false;
}

static bool loadLocalProdigyClusterUUID(uint128_t& clusterUUID, String *failure = nullptr)
{
  clusterUUID = 0;
  ProdigyPersistentStateStore stateStore;
  return stateStore.readStoredClusterUUID(clusterUUID, failure);
}

static bool loadLocalProdigyControlSocketPath(String& controlSocketPath, String *failure = nullptr)
{
  if (const char *explicitSocketPath = getenv("PRODIGY_MOTHERSHIP_SOCKET"))
  {
    if (explicitSocketPath[0] == '\0')
    {
      if (failure)
      {
        failure->assign("PRODIGY_MOTHERSHIP_SOCKET is empty"_ctv);
      }
      return false;
    }

    controlSocketPath.assign(explicitSocketPath);
    if (mothershipPathIsUnixSocket(controlSocketPath))
    {
      if (failure)
      {
        failure->clear();
      }
      return true;
    }

    if (failure)
    {
      failure->snprintf<"PRODIGY_MOTHERSHIP_SOCKET is not a live unix socket: {}"_ctv>(controlSocketPath);
    }
    return false;
  }

  String liveProcessFailure = {};
  if (resolveLiveLocalProdigyControlSocketPath(controlSocketPath, &liveProcessFailure))
  {
    if (failure)
    {
      failure->clear();
    }
    return true;
  }

  ProdigyPersistentStateStore stateStore;
  ProdigyPersistentBootState bootState = {};
  String loadFailure;
  if (stateStore.loadBootState(bootState, &loadFailure) == false)
  {
    if (failure)
    {
      if (liveProcessFailure.size() > 0 && liveProcessFailure.equal("no live local prodigy process found"_ctv) == false)
      {
        failure->assign(liveProcessFailure);
        failure->append("; boot state fallback failed: "_ctv);
        if (loadFailure.equal("record not found"_ctv))
        {
          failure->append("local prodigy boot state not found"_ctv);
        }
        else
        {
          failure->append(loadFailure);
        }

        return false;
      }

      if (loadFailure.equal("record not found"_ctv))
      {
        failure->assign("local prodigy boot state not found"_ctv);
      }
      else
      {
        *failure = loadFailure;
      }
    }

    return false;
  }

  if (bootState.bootstrapConfig.controlSocketPath.size() == 0)
  {
    if (failure)
    {
      failure->assign("local prodigy control socket path missing from boot state"_ctv);
    }
    return false;
  }

  controlSocketPath = bootState.bootstrapConfig.controlSocketPath;
  if (failure)
  {
    failure->clear();
  }
  return true;
}

static bool resolveLocalProdigyExecutablePath(String& localProdigyPath, String *failure = nullptr)
{
  localProdigyPath.clear();

  String selfPath;
  if (prodigyResolveCurrentExecutablePath(selfPath))
  {
    String selfDirectory;
    prodigyDirname(selfPath, selfDirectory);

    localProdigyPath.assign(selfDirectory);
    if (localProdigyPath.size() > 0 && localProdigyPath[localProdigyPath.size() - 1] != '/')
    {
      localProdigyPath.append('/');
    }
    localProdigyPath.append("prodigy"_ctv);

    String localProdigyText = localProdigyPath;
    if (::access(localProdigyText.c_str(), X_OK) == 0)
    {
      if (failure)
      {
        failure->clear();
      }
      return true;
    }
  }

  localProdigyPath.assign("/root/prodigy/prodigy"_ctv);
  String installedBundleText = localProdigyPath;
  if (::access(installedBundleText.c_str(), X_OK) == 0)
  {
    if (failure)
    {
      failure->clear();
    }
    return true;
  }

  localProdigyPath.assign("/usr/local/bin/prodigy"_ctv);
  String fallbackText = localProdigyPath;
  if (::access(fallbackText.c_str(), X_OK) == 0)
  {
    if (failure)
    {
      failure->clear();
    }
    return true;
  }

  localProdigyPath.clear();
  if (failure)
  {
    failure->assign("failed to locate local prodigy executable"_ctv);
  }
  return false;
}

static bool mothershipCreateSealedProviderFD(const char *name, const uint8_t *source,
                                             uint64_t sourceBytes, int& providerFD,
                                             String *failure = nullptr)
{
  providerFD = ::memfd_create(name, MFD_ALLOW_SEALING);
  if (providerFD < 0)
  {
    if (failure)
    {
      failure->snprintf<"failed to create sealed provider image: {}"_ctv>(String(std::strerror(errno)));
    }
    return false;
  }

  uint64_t offset = 0;
  while (offset < sourceBytes)
  {
    ssize_t written = ::write(providerFD,
                              source + offset,
                              sourceBytes - offset);
    if (written < 0 && errno == EINTR)
    {
      continue;
    }
    if (written <= 0)
    {
      int saved = errno;
      ::close(providerFD);
      providerFD = -1;
      if (failure)
      {
        failure->snprintf<"failed to write sealed provider image: {}"_ctv>(String(std::strerror(saved)));
      }
      return false;
    }
    offset += uint64_t(written);
  }

  if (::fcntl(providerFD, F_ADD_SEALS, F_SEAL_SEAL | F_SEAL_SHRINK | F_SEAL_GROW | F_SEAL_WRITE) != 0 ||
      ::lseek(providerFD, 0, SEEK_SET) != 0)
  {
    int saved = errno;
    ::close(providerFD);
    providerFD = -1;
    if (failure)
    {
      failure->snprintf<"failed to seal provider image: {}"_ctv>(String(std::strerror(saved)));
    }
    return false;
  }
  if (failure)
  {
    failure->clear();
  }
  return true;
}

static bool mothershipCreateVirtualDatacenterProviderFD(int& providerFD, String *failure = nullptr)
{
  return mothershipCreateSealedProviderFD("mothership-vdc-provider",
      mothershipVirtualDatacenterProviderSource,
      sizeof(mothershipVirtualDatacenterProviderSource), providerFD, failure);
}

static bool mothershipAppendVirtualDatacenterProviderOutput(
    String& output, const uint8_t *bytes, uint64_t count, uint64_t maximumOutputBytes)
{
  const uint64_t available = output.size() < maximumOutputBytes ? maximumOutputBytes - output.size() : 0;
  const uint64_t retained = std::min(count, available);
  if (retained) output.append(bytes, retained);
  return retained == count;
}

static bool mothershipCaptureVirtualDatacenterProviderOutput(
    int outputFD, pid_t pid, String& output, String *failure,
    uint64_t maximumOutputBytes, uint64_t timeoutMilliseconds,
    bool killProcessGroup, int& status)
{
  bool outputClosed = false, failedCapture = false, childKilled = false, exited = false;
  const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeoutMilliseconds);
  auto closeOutput = [&]() { if (!outputClosed) { ::close(outputFD); outputClosed = true; } };
  // The child establishes its own group before exec. We deliberately do not race
  // a parent setpgid against a fast child exit; kill(-pid) safely becomes ESRCH.
  auto stopChild = [&]() {
    if (!childKilled && (!exited || killProcessGroup))
    {
      (void)::kill(killProcessGroup ? -pid : pid, SIGKILL);
      childKilled = true;
    }
  };
  const int flags = ::fcntl(outputFD, F_GETFL, 0);
  if (flags < 0 || ::fcntl(outputFD, F_SETFL, flags | O_NONBLOCK) != 0)
  {
    failedCapture = true; closeOutput(); stopChild();
  }
  while (!exited)
  {
    if (!failedCapture && !outputClosed)
    {
      uint8_t buffer[4096];
      for (;;)
      {
        const ssize_t count = ::read(outputFD, buffer, sizeof(buffer));
        if (count > 0)
        {
          if (!mothershipAppendVirtualDatacenterProviderOutput(output, buffer, uint64_t(count), maximumOutputBytes))
          { failedCapture = true; closeOutput(); stopChild(); break; }
          continue;
        }
        if (count == 0) { closeOutput(); break; }
        if (errno == EINTR) continue;
        if (errno == EAGAIN || errno == EWOULDBLOCK) break;
        failedCapture = true; closeOutput(); stopChild(); break;
      }
    }
    const pid_t waited = ::waitpid(pid, &status, WNOHANG);
    if (waited == pid) { exited = true; break; }
    if (waited < 0 && errno != EINTR) { failedCapture = true; closeOutput(); stopChild(); break; }
    if (std::chrono::steady_clock::now() >= deadline)
    {
      failedCapture = true; closeOutput(); stopChild();
      while (::waitpid(pid, &status, 0) < 0 && errno == EINTR) { }
      exited = true;
      break;
    }
    if (!failedCapture && !outputClosed)
    {
      pollfd descriptor = {outputFD, POLLIN | POLLHUP | POLLERR, 0};
      (void)::poll(&descriptor, 1, 50);
    }
    else ::usleep(1000);
  }
  if (!outputClosed && !failedCapture)
  {
    while (!outputClosed && std::chrono::steady_clock::now() < deadline)
    {
      uint8_t buffer[4096]; const ssize_t count = ::read(outputFD, buffer, sizeof(buffer));
      if (count > 0)
      {
        if (!mothershipAppendVirtualDatacenterProviderOutput(output, buffer, uint64_t(count), maximumOutputBytes))
        { failedCapture = true; closeOutput(); stopChild(); break; }
        continue;
      }
      if (count == 0) { closeOutput(); break; }
      if (errno != EINTR && errno != EAGAIN && errno != EWOULDBLOCK)
      { failedCapture = true; closeOutput(); stopChild(); break; }
      pollfd descriptor = {outputFD, POLLIN | POLLHUP | POLLERR, 0}; (void)::poll(&descriptor, 1, 50);
    }
    if (!outputClosed) { failedCapture = true; closeOutput(); stopChild(); }
  }
  if (failedCapture)
  {
    if (failure) failure->assign("virtual datacenter provider capture failed; retained output prefix is bounded"_ctv);
    return false;
  }
  return true;
}

static bool mothershipRunVirtualDatacenterProvider(Vector<String> arguments, String *output, String *failure,
                                                    uint64_t maximumOutputBytes = 64 * 1024, uint64_t timeoutMilliseconds = 30'000,
                                                    bool killProcessGroup = false)
{
  int providerFD = -1;
  if (output) output->clear();
  if (mothershipCreateVirtualDatacenterProviderFD(providerFD, failure) == false) return false;

  String providerPath = {};
  providerPath.snprintf<"/proc/self/fd/{itoa}"_ctv>(uint64_t(providerFD));
  Vector<char *> argv = {};
  argv.reserve(arguments.size() + 3);
  argv.push_back(const_cast<char *>("/bin/bash"));
  argv.push_back(const_cast<char *>(providerPath.c_str()));
  for (String& argument : arguments) argv.push_back(const_cast<char *>(argument.c_str()));
  argv.push_back(nullptr);

  int stdoutPipe[2] = {-1, -1};
  if (output && ::pipe2(stdoutPipe, O_CLOEXEC) != 0)
  {
    ::close(providerFD);
    if (failure) failure->snprintf<"failed to create virtual datacenter provider output pipe: {}"_ctv>(String(std::strerror(errno)));
    return false;
  }
  pid_t pid = ::fork();
  if (pid == 0)
  {
    if (killProcessGroup && ::setpgid(0, 0) != 0) _exit(127);
    if (output && (::dup2(stdoutPipe[1], STDOUT_FILENO) < 0)) _exit(127);
    if (output) { ::close(stdoutPipe[0]); ::close(stdoutPipe[1]); }
    ::execv("/bin/bash", argv.data());
    _exit(127);
  }
  ::close(providerFD);
  if (output) ::close(stdoutPipe[1]);
  if (pid < 0)
  {
    if (output) ::close(stdoutPipe[0]);
    if (failure) failure->snprintf<"failed to launch virtual datacenter provider: {}"_ctv>(String(std::strerror(errno)));
    return false;
  }

  int status = 0;
  if (output == nullptr)
  {
    while (::waitpid(pid, &status, 0) < 0)
    {
      if (errno == EINTR) continue;
      if (failure) failure->snprintf<"failed to wait for virtual datacenter provider: {}"_ctv>(String(std::strerror(errno)));
      return false;
    }
  }
  else
  {
    if (!mothershipCaptureVirtualDatacenterProviderOutput(
            stdoutPipe[0], pid, *output, failure, maximumOutputBytes,
            timeoutMilliseconds, killProcessGroup, status)) return false;
  }

  if (WIFEXITED(status) == false || WEXITSTATUS(status) != 0)
  {
    if (failure)
    {
      if (WIFSIGNALED(status)) failure->snprintf<"virtual datacenter provider terminated by signal={itoa}"_ctv>(uint64_t(WTERMSIG(status)));
      else failure->snprintf<"virtual datacenter provider failed status={itoa}"_ctv>(uint64_t(WEXITSTATUS(status)));
    }
    return false;
  }
  if (failure) failure->clear();
  return true;
}

static bool mothershipRunSealedPythonProvider(const char *imageName,
                                              const uint8_t *source, uint64_t sourceBytes,
                                              Vector<String> arguments, String& output,
                                              String& failure,
                                              uint64_t timeoutMilliseconds = 30'000)
{
  output.clear(); failure.clear();
  int providerFD = -1;
  if (!mothershipCreateSealedProviderFD(imageName, source, sourceBytes, providerFD, &failure)) return false;

  String providerPath = {};
  providerPath.snprintf<"/proc/self/fd/{itoa}"_ctv>(uint64_t(providerFD));
  Vector<char *> argv = {};
  argv.reserve(arguments.size() + 3);
  argv.push_back(const_cast<char *>("/usr/bin/python3"));
  argv.push_back(const_cast<char *>(providerPath.c_str()));
  for (String& argument : arguments) argv.push_back(const_cast<char *>(argument.c_str()));
  argv.push_back(nullptr);

  int outputPipe[2] = {-1, -1};
  if (::pipe2(outputPipe, O_CLOEXEC) != 0)
  {
    ::close(providerFD);
    failure.snprintf<"failed to create sealed provider output pipe: {}"_ctv>(String(std::strerror(errno)));
    return false;
  }
  const pid_t pid = ::fork();
  if (pid == 0)
  {
    if (::dup2(outputPipe[1], STDOUT_FILENO) < 0 || ::dup2(outputPipe[1], STDERR_FILENO) < 0) _exit(127);
    ::close(outputPipe[0]); ::close(outputPipe[1]);
    ::execv("/usr/bin/python3", argv.data());
    _exit(127);
  }
  ::close(providerFD); ::close(outputPipe[1]);
  if (pid < 0)
  {
    ::close(outputPipe[0]);
    failure.snprintf<"failed to launch sealed provider: {}"_ctv>(String(std::strerror(errno)));
    return false;
  }
  int status = 0;
  if (!mothershipCaptureVirtualDatacenterProviderOutput(
          outputPipe[0], pid, output, &failure, 64_KB, timeoutMilliseconds, false, status)) return false;
  if (!WIFEXITED(status) || WEXITSTATUS(status) != 0)
  {
    if (failure.empty())
    {
      if (WIFSIGNALED(status)) failure.snprintf<"sealed provider terminated by signal={itoa}"_ctv>(uint64_t(WTERMSIG(status)));
      else failure.snprintf<"sealed provider failed status={itoa} output={}"_ctv>(uint64_t(WEXITSTATUS(status)), output);
    }
    return false;
  }
  return true;
}

static bool mothershipRunVirtualDatacenterProvider(Vector<String> arguments, String *failure = nullptr)
{
  return mothershipRunVirtualDatacenterProvider(std::move(arguments), nullptr, failure);
}

class MothershipVDCApplicationIdentity {
public:
  String name;
  MothershipVDCProcessIdentity process;
  uint64_t storageDevice = 0, storageInode = 0;
};

static bool mothershipVDCReadApplicationIdentities(const MothershipVDCProcessIdentity& runtime,
    Vector<MothershipVDCApplicationIdentity>& applications, String *failure)
{
  applications.clear();
  String root = {};
  root.snprintf<"/proc/{itoa}/root/sys/fs/cgroup/containers.slice"_ctv>(runtime.pid);
  DIR *directory = ::opendir(root.c_str());
  if (directory == nullptr)
  {
    // A machine that has never hosted an application has no containers.slice.
    // Require the retained cgroup filesystem itself before accepting zero apps.
    if (errno == ENOENT)
    {
      String cgroupRoot = {};
      cgroupRoot.snprintf<"/proc/{itoa}/root/sys/fs/cgroup"_ctv>(runtime.pid);
      struct stat metadata = {};
      if (::stat(cgroupRoot.c_str(), &metadata) == 0 && S_ISDIR(metadata.st_mode) && mothershipVDCProcessMatches(runtime)) return true;
    }
    if (failure) failure->assign("local application cgroup inventory unavailable"_ctv);
    return false;
  }
  bool okay = true;
  while (dirent *entry = ::readdir(directory))
  {
    const size_t length = std::strlen(entry->d_name);
    if (length <= 6 || std::strcmp(entry->d_name + length - 6, ".slice") != 0) continue;
    MothershipVDCApplicationIdentity application = {};
    application.name.assign(entry->d_name, length - 6);
    String pidsPath = {}, pids = {};
    pidsPath.snprintf<"{}/{}.slice/leaf/cgroup.procs"_ctv>(root, application.name);
    if (mothershipVDCRead(pidsPath, pids, 4096) == false) { okay = false; break; }
    if (pids.empty()) continue;
    uint64_t pid = 0;
    if (pids[pids.size() - 1] == '\n') pids.resize(pids.size() - 1);
    if (mothershipVDCParseUnsigned(pids.c_str(), pids.c_str() + pids.size(), pid) == false ||
        mothershipVDCReadProcess(pid, application.process) == false) { okay = false; break; }
    String storagePath = {};
    storagePath.snprintf<"/proc/{itoa}/root/storage"_ctv>(pid);
    struct stat storage = {};
    if (::stat(storagePath.c_str(), &storage) == 0)
    {
      application.storageDevice = uint64_t(storage.st_dev);
      application.storageInode = uint64_t(storage.st_ino);
    }
    else if (errno != ENOENT) { okay = false; break; }
    applications.push_back(std::move(application));
  }
  ::closedir(directory);
  if (okay == false && failure) failure->assign("local application process or storage identity is ambiguous"_ctv);
  return okay && mothershipVDCProcessMatches(runtime);
}

static bool mothershipVDCWaitStopped(const MothershipVDCProcessIdentity& process)
{
  for (unsigned attempt = 0; attempt < 100; ++attempt)
  {
    char state = 0;
    if (mothershipVDCProcessMatches(process, &state) == false) return false;
    if (state == 'T' || state == 't') return true;
    ::usleep(10000);
  }
  return false;
}

class MothershipVDCCheckpointContext {
public:
  MothershipVDCProcessIdentity runtime;
  uint8_t datacenterFragment = 0;
  Vector<MothershipVDCApplicationIdentity> applications;
};

static bool mothershipVDCFreezeCheckpoint(void *opaque, ProdigyLocalContainerCheckpoint& checkpoint, String *failure)
{
  auto& context = *static_cast<MothershipVDCCheckpointContext *>(opaque);
  if (checkpoint.datacenterFragment != context.datacenterFragment ||
      checkpoint.machineFragment == 0 || checkpoint.machineFragment > 0xffffff ||
      mothershipVDCSignal(context.runtime, SIGSTOP) == false || mothershipVDCWaitStopped(context.runtime) == false)
  {
    if (failure) failure->assign("cannot fence the exact local checkpoint runtime"_ctv);
    return false;
  }
  Vector<MothershipVDCApplicationIdentity> observed = {};
  if (mothershipVDCReadApplicationIdentities(context.runtime, observed, failure) == false ||
      observed.size() != context.applications.size() || observed.size() != checkpoint.plans.size())
  {
    if (failure) failure->assign("local checkpoint does not cover the full retained application inventory"_ctv);
    return false;
  }
  bytell_hash_set<String> checkpointNames = {};
  for (const ContainerPlan& plan : checkpoint.plans)
  {
    String name = {}; name.assignItoa(plan.uuid);
    if (plan.uuid == 0 || checkpointNames.insert(name).second == false) return false;
  }
  for (const auto& before : context.applications)
  {
    bool found = false;
    for (const auto& after : observed)
    {
      if (before.name != after.name) continue;
      found = checkpointNames.contains(after.name) &&
              before.process.pid == after.process.pid && before.process.startTime == after.process.startTime &&
              before.process.mountNamespace == after.process.mountNamespace &&
              before.process.networkNamespace == after.process.networkNamespace &&
              before.process.cgroupNamespace == after.process.cgroupNamespace &&
              before.storageDevice == after.storageDevice && before.storageInode == after.storageInode;
      break;
    }
    if (found == false)
    {
      if (failure) failure->assign("local checkpoint application identity changed during capture"_ctv);
      return false;
    }
  }
  return true;
}

// Run only under the existing provider-recovery lock and frozen provider.
// The temporary state copy is opened through the canonical persistence owner;
// the live databases are never opened or modified by the recovery client.
static bool mothershipVDCCaptureLocalCheckpoint(MothershipVDCBundleRecovery& operation,
    const String& directory, String *failure)
{
  auto reject = [&](const char *message) { if (failure) failure->assign(message); return false; };
  if (std::getenv("PRODIGY_STATE_SECRETS_DB") != nullptr)
    return reject("explicit secrets DB override is incompatible with isolated recovery state capture");
  MothershipVDCProcessResumeGuard resume(operation.worker);
  if (!resume.freeze(failure)) return false;
  MothershipVDCCheckpointContext context = {};
  context.runtime = operation.worker;
  if (mothershipVDCReadApplicationIdentities(operation.worker, context.applications, failure) == false) return false;
  String source = {}, copy = {}, copySecrets = {};
  source.snprintf<"/proc/{itoa}/root/containers/prodigy.state"_ctv>(operation.worker.pid);
  uint64_t nonce = Random::generateNumberWithNBits<64, uint64_t>();
  copy.snprintf<"{}/checkpoint-state-{itoa}"_ctv>(directory, nonce);
  copySecrets = copy; copySecrets.append(".secrets"_ctv);
  struct RemoveCopies {
    String primary, secrets;
    ~RemoveCopies() {
      std::error_code error;
      std::filesystem::remove_all(primary.c_str(), error);
      std::filesystem::remove_all(secrets.c_str(), error);
    }
  } cleanup {copy, copySecrets};
  String sourceSecrets = source; sourceSecrets.append(".secrets"_ctv);
  if (!mothershipVDCCopyPrivateStateTree(source, copy, failure) ||
      !mothershipVDCCopyPrivateStateTree(sourceSecrets, copySecrets, failure))
    return reject("private crash-consistent Brain state capture failed");
  if (!resume.resume(failure)) return false;

  String checkpointPath = {}, failurePath = {};
  mothershipVirtualDatacenterPath(directory, "local-checkpoint.bin", checkpointPath);
  mothershipVirtualDatacenterPath(directory, "checkpoint-failure", failurePath);
  pid_t child = ::fork();
  if (child == 0)
  {
    String childFailure = {};
    bool okay = false;
    {
      ProdigyPersistentStateStore state(copy);
      ProdigyPersistentLocalBrainState local = {};
      ProdigyPersistentBrainSnapshot snapshot = {};
      bool stateMatches = state.loadLocalBrainState(local, &childFailure) && state.loadBrainSnapshot(snapshot, &childFailure);
      if (stateMatches)
      {
        if (local.ownerClusterUUID != operation.clusterUUID)
          childFailure.assign("checkpoint local state owner cluster mismatch"_ctv);
        else if (local.uuid == 0)
          childFailure.assign("checkpoint local state has no machine identity"_ctv);
        else if (snapshot.brainConfig.clusterUUID != operation.clusterUUID)
          childFailure.assign("checkpoint snapshot cluster mismatch"_ctv);
        else if (snapshot.masterAuthority.runtimeState.updateSelf.workerExpectedBundleSHA256 != operation.expectedIncompleteWorkerBundle)
          childFailure.assign("checkpoint pending worker bundle mismatch"_ctv);
        else if (snapshot.masterAuthority.runtimeState.updateSelf.workerMachineUUIDs.empty())
          childFailure.assign("checkpoint has no pending worker cohort"_ctv);
        stateMatches = childFailure.empty();
      }
      if (stateMatches)
      {
        context.datacenterFragment = snapshot.brainConfig.datacenterFragment;
        String netPath = {};
        netPath.snprintf<"/proc/{itoa}/ns/net"_ctv>(operation.worker.pid);
        int network = ::open(netPath.c_str(), O_RDONLY | O_CLOEXEC);
        if (network >= 0 && mothershipVDCProcessMatches(operation.worker) && ::setns(network, CLONE_NEWNET) == 0)
        {
          ProdigyLocalContainerCheckpoint checkpoint = {};
          if (mothershipCaptureNeuronCheckpoint(local, "::1"_ctv, operation.expectedOldBundle,
                                               checkpoint, mothershipVDCFreezeCheckpoint, &context, &childFailure))
          {
            String serialized = {};
            BitseryEngine::serialize(serialized, checkpoint);
            okay = mothershipVDCDurableWrite(directory, "local-checkpoint.bin", serialized, &childFailure);
          }
        }
        if (network >= 0) ::close(network);
      }
      state.close();
      if (okay == false && childFailure.empty()) childFailure.assign("checkpoint exact runtime network namespace is unavailable"_ctv);
    }
    if (okay == false) (void)mothershipVDCDurableWrite(directory, "checkpoint-failure", childFailure, nullptr);
    _exit(okay ? 0 : 1);
  }
  if (child < 0) return reject("cannot launch isolated checkpoint client");
  bool finished = false;
  int status = 0;
  for (unsigned attempt = 0; attempt < 300; ++attempt)
  {
    if (::waitpid(child, &status, WNOHANG) == child) { finished = true; break; }
    ::usleep(100000);
  }
  if (finished == false)
  {
    (void)::kill(child, SIGKILL);
    while (::waitpid(child, &status, 0) < 0 && errno == EINTR) {}
    return reject("authenticated local checkpoint capture timed out");
  }
  if (WIFEXITED(status) == false || WEXITSTATUS(status) != 0)
  {
    String detail = {};
    if (mothershipVDCRead(failurePath, detail) && failure) *failure = detail;
    else if (failure) failure->assign("authenticated local checkpoint capture failed"_ctv);
    return false;
  }
  if (mothershipVDCWaitStopped(operation.worker) == false) return reject("checkpoint runtime fence was lost");
  String originalPath = {}, original = {}, checkpoint = {}, successorBoot = {};
  mothershipVirtualDatacenterPath(directory, "previous-boot.json", originalPath);
  if (mothershipVDCRead(originalPath, original, 32 * 1024 * 1024) == false ||
      mothershipVDCRead(checkpointPath, checkpoint, 32 * 1024 * 1024) == false ||
      mothershipVDCPrepareSupersessionBoot(original, operation, successorBoot, failure, &checkpoint) == false ||
      prodigyComputeSHA256Hex(successorBoot, operation.successorBootSHA256, failure) == false ||
      mothershipVDCDurableWrite(directory, "successor-boot.json", successorBoot, failure) == false)
    return false;
  return true;
}

// Capture-only entry point used by the remote coordinator below.  It is
// intentionally local to one already-selected Brain and cannot choose a host,
// application, deployment, or recovery operation.  Both state trees are copied
// while the exact process is stopped; the copied owner is opened only after the
// guard has verified that process resumed.
static bool mothershipVDCCaptureBrainStateLocal(
    uint128_t expectedClusterUUID, uint128_t expectedMachineUUID,
    uint64_t expectedPID, const String& directory, String *failure)
{
  auto reject = [&](const char *message) {
    if (failure && failure->empty()) failure->assign(message);
    return false;
  };
  if (expectedClusterUUID == 0 || expectedMachineUUID == 0 || expectedPID < 2 ||
      !mothershipVDCPrivateDirectory(directory) ||
      std::getenv("PRODIGY_STATE_DB") != nullptr ||
      std::getenv("PRODIGY_STATE_SECRETS_DB") != nullptr)
    return reject("invalid isolated Brain state capture input");

  MothershipVDCBrainStateCaptureReceipt receipt = {};
  receipt.clusterUUID = expectedClusterUUID;
  receipt.machineUUID = expectedMachineUUID;
  if (!mothershipVDCReadProcess(expectedPID, receipt.process) ||
      !mothershipVDCWriteBrainStateCaptureReceipt(directory, receipt, failure))
    return reject("exact Brain process identity is unavailable");

  String source = {}, sourceSecrets = {}, copy = {}, copySecrets = {}, processRoot = {};
  processRoot.snprintf<"/proc/{itoa}/root"_ctv>(expectedPID);
  mothershipVirtualDatacenterPath(directory, "state", copy);
  mothershipVirtualDatacenterPath(directory, "state.secrets", copySecrets);
  struct RemoveIncompleteCopy {
    String primary, secrets;
    bool committed = false;
    ~RemoveIncompleteCopy() {
      if (committed) return;
      std::error_code error = {};
      std::filesystem::remove_all(primary.c_str(), error);
      error.clear();
      std::filesystem::remove_all(secrets.c_str(), error);
    }
  } cleanup {copy, copySecrets};

  MothershipVDCProcessResumeGuard resume(receipt.process);
  if (!resume.freeze(failure)) return false;
  if (!mothershipVDCBrainCaptureStatePaths(processRoot, source, sourceSecrets, failure)) return false;
  if (!mothershipVDCCopyPrivateStateTree(source, copy, failure) ||
      !mothershipVDCCopyPrivateStateTree(sourceSecrets, copySecrets, failure))
    return reject("private crash-consistent Brain state capture failed");
  if (!resume.resume(failure)) return false;
  receipt.resumed = true;
  if (!mothershipVDCWriteBrainStateCaptureReceipt(directory, receipt, failure)) return false;

  // Preserve the frozen bytes even if recovery/identity validation fails.
  // Opening TidesDB may perform recovery writes, so validate a disposable clone.
  // The existing captureComplete bit remains the recovery admission boundary.
  cleanup.committed = true;
  String validation = {}, validationSecrets = {};
  mothershipVirtualDatacenterPath(directory, "validation", validation);
  validationSecrets = validation; validationSecrets.append(".secrets"_ctv);
  RemoveIncompleteCopy validationCleanup {validation, validationSecrets};
  if (!mothershipVDCCopyPrivateStateTree(copy, validation, failure) ||
      !mothershipVDCCopyPrivateStateTree(copySecrets, validationSecrets, failure))
    return reject("captured Brain state validation clone failed");
  ProdigyPersistentStateStore state(validation);
  ProdigyPersistentLocalBrainState local = {};
  ProdigyPersistentBrainSnapshot snapshot = {};
  const bool valid = state.loadLocalBrainState(local, failure) &&
      state.loadBrainSnapshot(snapshot, failure) &&
      local.ownerClusterUUID == expectedClusterUUID && local.uuid == expectedMachineUUID &&
      snapshot.brainConfig.clusterUUID == expectedClusterUUID;
  state.close();
  if (!valid) {
    reject("copied Brain state does not match the selected cluster and machine");
    String detail = failure && !failure->empty() ? *failure : String("Brain capture validation failed");
    (void)mothershipVDCDurableWrite(directory, "brain-capture.incomplete", detail, nullptr);
    return false;
  }
  receipt.captureComplete = true;
  if (!mothershipVDCWriteBrainStateCaptureReceipt(directory, receipt, failure)) return false;
  cleanup.committed = true;
  return true;
}

// Reconciliation command for an interrupted SSH/controller result.  It never
// stops a process.  It resumes only the exact persisted process identity and
// rewrites the receipt only after observing that identity outside T/t state.
static bool mothershipVDCResumeBrainStateCaptureLocal(
    uint64_t expectedPID, const String& directory, String *failure)
{
  MothershipVDCBrainStateCaptureReceipt receipt = {};
  if (expectedPID < 2 || !mothershipVDCReadBrainStateCaptureReceipt(directory, receipt) ||
      receipt.process.pid != expectedPID || !mothershipVDCProcessMatches(receipt.process))
  {
    if (failure) failure->assign("Brain capture resume identity is absent or changed"_ctv);
    return false;
  }
  char state = 0;
  if (!mothershipVDCProcessMatches(receipt.process, &state)) return false;
  if ((state == 'T' || state == 't') && !mothershipVDCSignal(receipt.process, SIGCONT))
  {
    if (failure) failure->assign("cannot resume exact Brain capture identity"_ctv);
    return false;
  }
  if (!mothershipVDCWaitForStoppedState(receipt.process, false))
  {
    if (failure) failure->assign("exact Brain capture identity did not resume"_ctv);
    return false;
  }
  receipt.resumed = true;
  return mothershipVDCWriteBrainStateCaptureReceipt(directory, receipt, failure);
}

// The lifecycle owner asks Switchboard to retain its existing resources. It
// neither attaches a program nor writes a routing map. Namespace entry stays in
// this bounded child, and the durable recovery record owns the exact identities.
static bool mothershipVDCRetainFollowerNetworking(MothershipVDCBundleRecovery& operation,
                                                 bool capture, String *failure)
{
  auto reject = [&](const char *message) { if (failure) failure->assign(message); return false; };
  if (!operation.testOnlyFollowerReplacement || operation.machineIndex == 0 || operation.machineIndex > 3)
    return reject("host routing retention requires the admitted test follower");
  const auto& owner = capture ? operation.worker : operation.adopter;
  char state = 0;
  if (!mothershipVDCProcessMatches(owner, &state) || (capture && state != 'T' && state != 't'))
    return reject("host routing retention namespace owner changed or worker is not stopped");
  struct CloseFD { int fd = -1; ~CloseFD() { if (fd >= 0) ::close(fd); } } mount, network, input, output;
  String path = {};
  path.snprintf<"/proc/{itoa}/ns/mnt"_ctv>(owner.pid);
  mount.fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
  if (capture) path.snprintf<"/proc/{itoa}/ns/net"_ctv>(owner.pid);
  else path.snprintf<"/proc/{itoa}/root/run/netns/pvd-m{itoa}-{itoa}"_ctv>(owner.pid, uint64_t(operation.machineIndex), operation.runtimeIdentity);
  network.fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
  struct stat mountInfo = {}, networkInfo = {};
  if (mount.fd < 0 || network.fd < 0 || ::fstat(mount.fd, &mountInfo) != 0 || ::fstat(network.fd, &networkInfo) != 0 ||
      uint64_t(mountInfo.st_ino) != owner.mountNamespace || uint64_t(networkInfo.st_ino) != operation.worker.networkNamespace ||
      !mothershipVDCProcessMatches(owner))
    return reject("host routing retention namespace identity mismatch");
  int descriptors[2];
  if (::pipe2(descriptors, O_CLOEXEC) != 0) return reject("cannot open host routing retention receipt channel");
  input.fd = descriptors[0]; output.fd = descriptors[1];
  struct Receipt { MothershipVDCRetainedTCX links[2]; int result = 1; } receipt = {};
  pid_t child = ::fork();
  if (child == 0)
  {
    ::close(input.fd);
    ::signal(SIGALRM, SIG_DFL);
    ::alarm(10);
    if (::setns(mount.fd, CLONE_NEWNS) != 0 || ::setns(network.fd, CLONE_NEWNET) != 0) _exit(125);
    const uint32_t ifindex = ::if_nametoindex("bond0"); // the admitted VDC machine interface
    String bpffsRoot = {};
    if (capture) bpffsRoot.assign("/sys/fs/bpf"_ctv);
    else bpffsRoot.snprintf<"/mnt/prodigy-vdc-{itoa}/machine-bpffs/machine{itoa}"_ctv>(operation.runtimeIdentity, uint64_t(operation.machineIndex));
    SwitchboardHostTCXRetentionPair pair = {};
    auto importIdentity = [](const MothershipVDCRetainedTCX& source, SwitchboardHostTCXRetentionIdentity& target) {
      target.interfaceIndex = source.ifindex;
      target.direction = source.attachType == uint32_t(BPF_TCX_INGRESS) ? SwitchboardHostTCXDirection::ingress : SwitchboardHostTCXDirection::egress;
      target.programID = source.programID; target.linkID = source.linkID;
      target.wormholeFlowMapID = source.wormholeFlowMapID; target.wormholePendingFlowMapID = source.wormholePendingFlowMapID;
      std::memcpy(target.programTag, source.programTag, sizeof(target.programTag));
    };
    auto exportIdentity = [](const SwitchboardHostTCXRetentionIdentity& source, MothershipVDCRetainedTCX& target) {
      target.ifindex = source.interfaceIndex;
      target.attachType = uint32_t(switchboardHostTCXAttachType(source.direction));
      target.programID = source.programID; target.linkID = source.linkID;
      target.wormholeFlowMapID = source.wormholeFlowMapID; target.wormholePendingFlowMapID = source.wormholePendingFlowMapID;
      std::memcpy(target.programTag, source.programTag, sizeof(target.programTag));
    };
    bool okay = false;
    if (capture)
      okay = switchboardHostTCXRetainCurrentPair(ifindex, bpffsRoot, pair);
    else if (operation.version == 4 && operation.retainedTCX[0].attachType == uint32_t(BPF_TCX_INGRESS) &&
             operation.retainedTCX[1].attachType == uint32_t(BPF_TCX_EGRESS))
    {
      importIdentity(operation.retainedTCX[0], pair.ingress);
      importIdentity(operation.retainedTCX[1], pair.egress);
      okay = switchboardHostTCXVerifyRetainedPair(ifindex, bpffsRoot, pair);
    }
    if (okay)
    {
      exportIdentity(pair.ingress, receipt.links[0]);
      exportIdentity(pair.egress, receipt.links[1]);
      receipt.result = 0;
    }
    ssize_t bytes;
    do { bytes = ::write(output.fd, &receipt, sizeof(receipt)); } while (bytes < 0 && errno == EINTR);
    _exit(bytes == sizeof(receipt) && okay ? 0 : 1);
  }
  if (child < 0) return reject("cannot launch bounded host routing retention request");
  ::close(output.fd); output.fd = -1;
  size_t received = 0;
  while (received < sizeof(receipt))
  {
    ssize_t bytes = ::read(input.fd, reinterpret_cast<char *>(&receipt) + received, sizeof(receipt) - received);
    if (bytes < 0 && errno == EINTR) continue;
    if (bytes <= 0) break;
    received += size_t(bytes);
  }
  int status = 0;
  pid_t waited;
  do { waited = ::waitpid(child, &status, 0); } while (waited < 0 && errno == EINTR);
  if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 || received != sizeof(receipt) || receipt.result != 0)
    return reject("exact host routing link retention failed; follower recovery remains held");
  if (capture)
  {
    operation.version = 4;
    for (unsigned index = 0; index < 2; ++index) operation.retainedTCX[index] = receipt.links[index];
  }
  basics_log("retainedFollowerNetworking verified=1 machineIndex=%u capture=%u ingressLink=%u egressLink=%u flowMap=%u pendingMap=%u\n",
             operation.machineIndex, unsigned(capture), receipt.links[0].linkID, receipt.links[1].linkID,
             receipt.links[0].wormholeFlowMapID, receipt.links[0].wormholePendingFlowMapID);
  return true;
}

static void mothershipVDCTestFaultAfterRecoveryTransition(MothershipVDCTestRecoveryFaultPhase requested,
    MothershipVDCTestRecoveryFaultPhase transition, const MothershipVDCBundleRecovery& operation)
{
  if (requested != transition) return;
  String operationText = {}; operationText.assignItoh(operation.operationID);
  const char *phase = transition == MothershipVDCTestRecoveryFaultPhase::frozen ? "frozen" :
                      transition == MothershipVDCTestRecoveryFaultPhase::rootInstalled ? "rootInstalled" : "workerReplaced";
  basics_log("recoverTestClusterFollowerBrain testFault=1 phase=%s operationID=%s machineIndex=%u before_exit=86\n",
             phase, operationText.c_str(), unsigned(operation.machineIndex));
  std::fflush(stdout);
  std::fflush(stderr);
  _exit(86);
}

static bool mothershipRecoverVirtualDatacenterBundle(const MothershipProdigyCluster& cluster,
    const String& bundlePath, const String& successorSHA, uint32_t machineIndex,
    const String& expectedOldSHA, const String& expectedIncompleteWorkerSHA,
    const MothershipVDCBundleRecovery *followerPreflight, MothershipVDCTestRecoveryFaultPhase testFaultAfterPhase,
    uint128_t *completedOperationID, String *failure)
{
  auto reject = [&](const char *message) { if (failure) failure->assign(message); return false; };
  if (cluster.test.spareMachineCount != 0)
    return reject("retained-provider bundle recovery does not support SSH spare machines");
  const bool followerReplacement = followerPreflight != nullptr;
  // A follower retains its unchanged boot record and restarts under the old
  // master, which remains the plan owner.  Bootstrap supersession/checkpoint
  // is reserved for the existing sole-Brain path.
  if (mothershipVDCRecoveryTargetIsSupported(machineIndex, cluster.nBrains, expectedIncompleteWorkerSHA.empty() == false,
                                              followerReplacement) == false)
    return reject("Brain replacement is unsupported without an authoritative local-container checkpoint");
  if (followerReplacement && expectedIncompleteWorkerSHA.empty() == false)
    return reject("test follower replacement must retain its original boot without an incomplete-update receipt");
  if (testFaultAfterPhase != MothershipVDCTestRecoveryFaultPhase::none && followerReplacement == false)
    return reject("test recovery fault injection requires the test-only follower operation");
  if (expectedIncompleteWorkerSHA.empty() == false && ((!followerReplacement && (machineIndex != 1 || cluster.nBrains != 1)) ||
      prodigyIsSHA256HexDigest(expectedIncompleteWorkerSHA) == false || expectedIncompleteWorkerSHA.equals(successorSHA)))
    return reject("incomplete bundle supersession requires the sole Brain and a distinct expected pending digest");
  if (followerReplacement && (cluster.nBrains != 3 || machineIndex > 3 || machineIndex == 0 ||
      mothershipVDCTestFollowerRecoveryMatches(*followerPreflight, cluster.clusterUUID, machineIndex,
                                               expectedOldSHA, successorSHA) == false))
    return reject("test follower replacement preflight is incomplete or differs from retained recovery request");
  String lockPath = {};
  mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "virtual-datacenter.recovery.lock", lockPath);
  struct CloseFD { int fd = -1; ~CloseFD() { if (fd >= 0) ::close(fd); } } lock;
  lock.fd = ::open(lockPath.c_str(), O_RDWR | O_CREAT | O_CLOEXEC | O_NOFOLLOW, 0600);
  if (lock.fd < 0 || ::flock(lock.fd, LOCK_EX | LOCK_NB) != 0) return reject("another provider recovery owns the workspace");

  String recoveryRoot = {}, directory = {}, directoryName = {};
  mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "virtual-datacenter.recovery", recoveryRoot);
  if (::mkdir(recoveryRoot.c_str(), 0700) != 0 && errno != EEXIST) return reject("cannot create provider recovery owner");
  String recoveryPrefix = {};
  if (followerReplacement) recoveryPrefix.assign("follower-"_ctv);
  directoryName.snprintf<"{}machine{itoa}-{}-{}"_ctv>(recoveryPrefix, uint64_t(machineIndex), expectedOldSHA, successorSHA);
  mothershipVirtualDatacenterPath(recoveryRoot, directoryName.c_str(), directory);
  String activePath = {}, active = {};
  MothershipVDCProcessIdentity refusedWorker = {}, refusedSupervisor = {};
  mothershipVirtualDatacenterPath(recoveryRoot, "active", activePath);
  if (::access(activePath.c_str(), F_OK) == 0)
  {
    if (mothershipVDCRead(activePath, active) == false) return reject("unreadable provider recovery intent");
    if (active.equals(directoryName) == false)
    {
      if (active.empty() || std::strchr(active.c_str(), '/') != nullptr) return reject("invalid provider recovery intent path");
      String priorDirectory = {};
      mothershipVirtualDatacenterPath(recoveryRoot, active.c_str(), priorDirectory);
      MothershipVDCBundleRecovery prior = {};
      if (mothershipVDCReadRecovery(priorDirectory, prior) == false) return reject("another provider recovery is incomplete");
      if (prior.phase != MothershipVDCRecoveryPhase::complete)
      {
        // A refused precommit sole-Brain replacement leaves its journal for
        // diagnosis. A corrected artifact may replace that pointer only while
        // the recorded original owners and boot bytes are still intact.
        char supervisorState = 0, workerState = 0;
        uint64_t supervisorPID = 0, runtimeIdentity = 0;
        String pidPath = {}, runtimeIdentityPath = {}, installedRoot = {}, installedBundlePath = {}, bootDirectory = {}, bootName = {}, bootPath = {};
        mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, mothershipVirtualDatacenterPIDFilename, pidPath);
        mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "virtual-datacenter.identity", runtimeIdentityPath);
        installedRoot.snprintf<"{}/machines/{itoa}/root/prodigy"_ctv>(cluster.test.workspaceRoot, uint64_t(machineIndex));
        mothershipVirtualDatacenterPath(installedRoot, "prodigy.bundle.tar.zst", installedBundlePath);
        mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "boot", bootDirectory);
        bootName.snprintf<"{itoa}.json"_ctv>(uint64_t(machineIndex));
        mothershipVirtualDatacenterPath(bootDirectory, bootName.c_str(), bootPath);
        bool retryableRefusal = expectedIncompleteWorkerSHA.empty() == false &&
            (prior.phase == MothershipVDCRecoveryPhase::accepted || prior.phase == MothershipVDCRecoveryPhase::frozen) &&
            prior.clusterUUID == cluster.clusterUUID && prior.machineIndex == machineIndex &&
            prior.expectedOldBundle.equals(expectedOldSHA) &&
            prior.expectedIncompleteWorkerBundle.equals(expectedIncompleteWorkerSHA) &&
            prior.successorBundle.equals(successorSHA) == false && prior.adopter.pid <= 1 && prior.replacement.pid <= 1 &&
            mothershipVDCReadNumber(pidPath, supervisorPID) && supervisorPID == prior.supervisor.pid &&
            mothershipVDCProcessMatches(prior.supervisor, &supervisorState) && supervisorState != 'T' && supervisorState != 't' &&
            mothershipVDCProcessMatches(prior.worker, &workerState) && workerState != 'T' && workerState != 't';
        if (retryableRefusal)
        {
          runtimeIdentity = supervisorPID;
          if (::access(runtimeIdentityPath.c_str(), F_OK) == 0 && mothershipVDCReadNumber(runtimeIdentityPath, runtimeIdentity) == false)
            retryableRefusal = false;
          String installedDigest = {}, executablePath = {}, executableDigest = {}, bootDigest = {};
          executablePath.snprintf<"/proc/{itoa}/exe"_ctv>(prior.worker.pid);
          retryableRefusal = retryableRefusal && runtimeIdentity == prior.runtimeIdentity &&
              prodigyIsSHA256HexDigest(prior.previousBootSHA256) && prodigyIsSHA256HexDigest(prior.oldExecutable) &&
              prodigyComputeFileSHA256Hex(installedBundlePath, installedDigest, failure) && installedDigest.equals(expectedOldSHA) &&
              prodigyComputeFileSHA256Hex(executablePath, executableDigest, failure) && executableDigest.equals(prior.oldExecutable) &&
              prodigyComputeFileSHA256Hex(bootPath, bootDigest, failure) && bootDigest.equals(prior.previousBootSHA256);
        }
        if (retryableRefusal == false)
          return reject("another provider recovery is incomplete");
        refusedWorker = prior.worker;
        refusedSupervisor = prior.supervisor;
      }
    }
  }
  if (::mkdir(directory.c_str(), 0700) != 0 && errno != EEXIST) return reject("cannot create provider recovery operation");
  String operationPath = {}, stagedRoot = {}, installedRoot = {}, previousRoot = {}, runtimePath = {}, pidPath = {};
  mothershipVirtualDatacenterPath(directory, "operation", operationPath);
  mothershipVirtualDatacenterPath(directory, "staged-root", stagedRoot);
  mothershipVirtualDatacenterPath(directory, "previous-root", previousRoot);
  installedRoot.snprintf<"{}/machines/{itoa}/root/prodigy"_ctv>(cluster.test.workspaceRoot, uint64_t(machineIndex));
  mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, mothershipVirtualDatacenterRuntimeFilename, runtimePath);
  mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, mothershipVirtualDatacenterPIDFilename, pidPath);
  MothershipVDCBundleRecovery operation = {};
  String bootDirectory = {}, bootPath = {};
  mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "boot", bootDirectory);
  String bootName = {}; bootName.snprintf<"{itoa}.json"_ctv>(uint64_t(machineIndex));
  mothershipVirtualDatacenterPath(bootDirectory, bootName.c_str(), bootPath);
  auto fileDigest = [&](const String& root, const char *filename, String& digest) {
    String path = {}; mothershipVirtualDatacenterPath(root, filename, path);
    return prodigyComputeFileSHA256Hex(path, digest, failure);
  };
  auto executableMatches = [&](const MothershipVDCProcessIdentity& process, const String& digest) {
    String path = {}, observed = {};
    path.snprintf<"/proc/{itoa}/exe"_ctv>(process.pid);
    return mothershipVDCProcessMatches(process) && prodigyComputeFileSHA256Hex(path, observed, failure) && observed.equals(digest);
  };
  auto save = [&]() { return mothershipVDCWriteRecovery(directory, operation, failure); };
  if (::access(operationPath.c_str(), F_OK) == 0)
  {
    if (mothershipVDCReadRecovery(directory, operation) == false || operation.clusterUUID != cluster.clusterUUID ||
        operation.machineIndex != machineIndex || operation.testOnlyFollowerReplacement != followerReplacement ||
        operation.expectedOldBundle.equals(expectedOldSHA) == false ||
        operation.expectedIncompleteWorkerBundle.equals(expectedIncompleteWorkerSHA) == false ||
        operation.successorBundle.equals(successorSHA) == false ||
        (followerReplacement && (operation.selectedMachineUUID != followerPreflight->selectedMachineUUID ||
                                 operation.masterMachineUUID != followerPreflight->masterMachineUUID ||
                                 operation.witnessMachineUUID != followerPreflight->witnessMachineUUID ||
                                 operation.preflightReportSHA256 != followerPreflight->preflightReportSHA256)))
      return reject("provider recovery operation identity mismatch");
    if (followerReplacement && operation.version < 4 && operation.phase >= MothershipVDCRecoveryPhase::workerKilled)
      return reject("legacy follower recovery journal has no retained routing identities; cannot attest this retry");
  }
  else
  {
    operation.clusterUUID = cluster.clusterUUID;
    do { operation.operationID = Random::generateNumberWithNBits<128, uint128_t>(); } while (operation.operationID == 0);
    operation.machineIndex = machineIndex;
    operation.expectedOldBundle = expectedOldSHA;
    operation.successorBundle = successorSHA;
    operation.expectedIncompleteWorkerBundle = expectedIncompleteWorkerSHA;
    if (followerReplacement)
    {
      operation.version = 3;
      operation.testOnlyFollowerReplacement = true;
      operation.selectedMachineUUID = followerPreflight->selectedMachineUUID;
      operation.masterMachineUUID = followerPreflight->masterMachineUUID;
      operation.witnessMachineUUID = followerPreflight->witnessMachineUUID;
      operation.preflightReportSHA256 = followerPreflight->preflightReportSHA256;
    }
    uint64_t supervisorPID = 0;
    if (mothershipVDCReadNumber(pidPath, supervisorPID) == false || mothershipVDCReadProcess(supervisorPID, operation.supervisor) == false)
      return reject("retained provider process identity unavailable");
    String identityPath = {};
    mothershipVirtualDatacenterPath(cluster.test.workspaceRoot, "virtual-datacenter.identity", identityPath);
    operation.runtimeIdentity = supervisorPID;
    if (::access(identityPath.c_str(), F_OK) == 0 && mothershipVDCReadNumber(identityPath, operation.runtimeIdentity) == false)
      return reject("retained provider runtime identity is invalid");
    Vector<String> arguments = {};
    if (mothershipVDCReadArguments(supervisorPID, arguments) == false ||
        mothershipVDCProviderArguments(arguments, cluster.test.workspaceRoot, operation.runtimeIdentity, operation.providerArguments) == false)
      return reject("retained provider command does not own this workspace");
    uint64_t count = 0, brains = 0;
    if (mothershipVDCParseUnsigned(operation.providerArguments[1].c_str(), operation.providerArguments[1].c_str() + operation.providerArguments[1].size(), count) == false ||
        mothershipVDCParseUnsigned(operation.providerArguments[2].c_str(), operation.providerArguments[2].c_str() + operation.providerArguments[2].size(), brains) == false ||
        count != cluster.test.machineCount || brains != cluster.nBrains) return reject("retained provider topology differs from Mothership");
    String runtime = {};
    if (mothershipVDCRead(runtimePath, runtime) == false) return reject("retained worker inventory unavailable");
    const char *cursor = runtime.c_str(), *terminal = cursor + runtime.size();
    for (uint32_t index = 1; index <= count; ++index)
    {
      const char *end = cursor;
      while (end != terminal && *end != '\n') ++end;
      uint64_t worker = 0;
      if (end == terminal || mothershipVDCParseUnsigned(cursor, end, worker) == false || worker < 2) return reject("retained worker inventory is malformed");
      if (followerReplacement && index <= 3 &&
          mothershipVDCReadProcess(worker, operation.commissionedBrains[index - 1]) == false)
        return reject("commissioned Brain process identity unavailable");
      if (index == machineIndex)
      {
        if (followerReplacement) operation.worker = operation.commissionedBrains[index - 1];
        else if (mothershipVDCReadProcess(worker, operation.worker) == false) return reject("selected worker identity unavailable");
      }
      cursor = end + 1;
    }
    if (cursor != terminal) return reject("retained worker inventory has unexpected entries");
    String installedDigest = {}, expectedCgroupSuffix = {};
    expectedCgroupSuffix.snprintf<"/prodigy-vdc-{itoa}/provider\n"_ctv>(operation.runtimeIdentity);
    if (mothershipVDCReadProcessFile(supervisorPID, "cgroup", operation.providerCgroup) == false ||
        operation.providerCgroup.size() < expectedCgroupSuffix.size() ||
        std::memcmp(operation.providerCgroup.data() + operation.providerCgroup.size() - expectedCgroupSuffix.size(),
                    expectedCgroupSuffix.data(), expectedCgroupSuffix.size()) != 0 ||
        mothershipVDCReadProcessFile(operation.worker.pid, "cgroup", operation.workerCgroup) == false)
      return reject("retained provider cgroup identity mismatch");
    String expectedWorker = {};
    expectedWorker.assign(operation.providerCgroup.data(), operation.providerCgroup.size() - 9); // provider\n
    String leaf = {}; leaf.snprintf<"machine{itoa}/prodigy-runtime\n"_ctv>(uint64_t(machineIndex));
    expectedWorker.append(leaf);
    if (operation.workerCgroup.equals(expectedWorker) == false || operation.worker.networkNamespace == operation.supervisor.networkNamespace)
      return reject("selected worker does not own the expected isolated machine cgroup");
    if (followerReplacement)
    {
      for (uint32_t index = 1; index <= 3; ++index)
      {
        String brainRoot = {}, observedBundle = {};
        brainRoot.snprintf<"{}/machines/{itoa}/root/prodigy"_ctv>(cluster.test.workspaceRoot, uint64_t(index));
        if (mothershipVDCProcessMatches(operation.commissionedBrains[index - 1]) == false ||
            fileDigest(brainRoot, "prodigy.bundle.tar.zst", observedBundle) == false ||
            observedBundle.equals(expectedOldSHA) == false)
          return reject("commissioned Brain source artifact or process identity differs from exact legacy fixture");
      }
    }
    if (fileDigest(installedRoot, "prodigy.bundle.tar.zst", installedDigest) == false || installedDigest.equals(expectedOldSHA) == false ||
        fileDigest(installedRoot, "prodigy", operation.oldExecutable) == false || executableMatches(operation.worker, operation.oldExecutable) == false)
      return reject("selected worker installed bundle or executable differs from expected old artifact");
    // The existing installer validates/extracts the approved Discombobulator
    // artifact into this operation's private staging root before any signal.
    if (prodigyInstallBundleToRoot(bundlePath, stagedRoot, failure) == false ||
        fileDigest(stagedRoot, "prodigy", operation.successorExecutable) == false) return false;
    if (expectedIncompleteWorkerSHA.empty() == false)
    {
      String originalBoot = {}, successorBoot = {};
      if (mothershipVDCRead(bootPath, originalBoot) == false ||
          mothershipVDCPrepareSupersessionBoot(originalBoot, operation, successorBoot, failure) == false ||
          prodigyComputeSHA256Hex(originalBoot, operation.previousBootSHA256, failure) == false ||
          prodigyComputeSHA256Hex(successorBoot, operation.successorBootSHA256, failure) == false ||
          mothershipVDCDurableWrite(directory, "previous-boot.json", originalBoot, failure) == false ||
          mothershipVDCDurableWrite(directory, "successor-boot.json", successorBoot, failure) == false) return false;
    }
    else if (followerReplacement &&
             prodigyComputeFileSHA256Hex(bootPath, operation.previousBootSHA256, failure) == false)
    {
      return false;
    }
    if (save() == false) return false;
  }
  // Before this test-only transaction takes the irreversible provider handoff,
  // all three identities captured from the initial authenticated 19b fixture
  // must still be live.  A completed retry is handled by the command's durable
  // query path and never reaches this admission check.
  if (followerReplacement && operation.phase < MothershipVDCRecoveryPhase::committed)
  {
    for (uint32_t member = 1; member <= 3; ++member)
    {
      String root = {}, observedBundle = {};
      root.snprintf<"{}/machines/{itoa}/root/prodigy"_ctv>(cluster.test.workspaceRoot, uint64_t(member));
      if (mothershipVDCProcessMatches(operation.commissionedBrains[member - 1]) == false ||
          fileDigest(root, "prodigy.bundle.tar.zst", observedBundle) == false ||
          observedBundle.equals(operation.expectedOldBundle) == false)
        return reject("commissioned Brain identity changed before retained follower handoff");
    }
  }
  if (refusedWorker.pid > 1 &&
      (operation.phase != MothershipVDCRecoveryPhase::accepted ||
       mothershipVDCSameProcess(operation.worker, refusedWorker) == false ||
       mothershipVDCSameProcess(operation.supervisor, refusedSupervisor) == false))
    return reject("corrected recovery artifact no longer targets the refused original owners");
  if (mothershipVDCDurableWrite(recoveryRoot, "active", directoryName, failure) == false) return false;
  String selected = {}; selected.assignItoa(machineIndex);
  if (mothershipVDCDurableWrite(directory, "selected-machine", selected, failure) == false) return false;

  // Ordinary errors before the irreversible handoff leave the original owner
  // running. A process crash keeps its durable phase for an explicit retry.
  struct PrecommitRollback {
    MothershipVDCBundleRecovery& operation;
    ~PrecommitRollback() {
      if (operation.phase < MothershipVDCRecoveryPhase::committed) {
        if (operation.adopter.pid > 1) (void)mothershipVDCSignal(operation.adopter, SIGKILL);
        char state = 0;
        if (mothershipVDCProcessMatches(operation.worker, &state) && (state == 'T' || state == 't'))
          (void)mothershipVDCSignal(operation.worker, SIGCONT);
        if (mothershipVDCProcessMatches(operation.supervisor, &state) && (state == 'T' || state == 't'))
          (void)mothershipVDCSignal(operation.supervisor, SIGCONT);
      }
    }
  } rollback {operation};
  auto waitStopped = [&](const MothershipVDCProcessIdentity& process) {
    for (unsigned i = 0; i < 100; ++i) {
      char state = 0;
      if (mothershipVDCProcessMatches(process, &state) == false) return false;
      if (state == 'T' || state == 't') return true;
      ::usleep(10000);
    }
    return false;
  };
  if (operation.phase < MothershipVDCRecoveryPhase::committed)
  {
    const bool transitionsFromAccepted = operation.phase == MothershipVDCRecoveryPhase::accepted;
    if (mothershipVDCSignal(operation.supervisor, SIGSTOP) == false || waitStopped(operation.supervisor) == false)
      return reject("cannot freeze the exact retained provider");
    operation.phase = MothershipVDCRecoveryPhase::frozen;
    if (save() == false) return false;
    if (transitionsFromAccepted)
      mothershipVDCTestFaultAfterRecoveryTransition(testFaultAfterPhase, MothershipVDCTestRecoveryFaultPhase::frozen, operation);
    String currentCgroup = {};
    if (mothershipVDCReadProcessFile(operation.supervisor.pid, "cgroup", currentCgroup) == false || currentCgroup.equals(operation.providerCgroup) == false ||
        executableMatches(operation.worker, operation.oldExecutable) == false)
      return reject("retained process identity changed before provider handoff");
    if (expectedIncompleteWorkerSHA.empty() == false || followerReplacement)
    {
      String observedBootSHA = {};
      if (prodigyComputeFileSHA256Hex(bootPath, observedBootSHA, failure) == false || observedBootSHA.equals(operation.previousBootSHA256) == false)
        return reject("retained Brain boot identity changed before provider handoff");
    }
    if (expectedIncompleteWorkerSHA.empty() == false)
    {
      if (mothershipVDCCaptureLocalCheckpoint(operation, directory, failure) == false || save() == false) return false;
    }
    String readyPath = {}; mothershipVirtualDatacenterPath(directory, "ready", readyPath);
    auto readReady = [&]() {
      String receipt = {};
      if (mothershipVDCRead(readyPath, receipt, 256) == false) return false;
      unsigned long long pid = 0, start = 0, mount = 0, runtime = 0; char extra = 0;
      if (std::sscanf(receipt.c_str(), "%llu %llu %llu %llu %c", &pid, &start, &mount, &runtime, &extra) != 4 || runtime != operation.runtimeIdentity ||
          mount != operation.supervisor.mountNamespace) return false;
      MothershipVDCProcessIdentity observed = {};
      Vector<String> args = {};
      if (mothershipVDCReadProcess(pid, observed) == false || observed.startTime != start || observed.mountNamespace != mount ||
          observed.networkNamespace != operation.supervisor.networkNamespace || mothershipVDCReadArguments(pid, args) == false ||
          args.size() != 17 || args[2].equals("--serve-adopt"_ctv) == false || args[4].equals(directory) == false) return false;
      operation.adopter = observed;
      return true;
    };
    if (readReady() == false)
    {
      int providerFD = -1;
      if (mothershipCreateVirtualDatacenterProviderFD(providerFD, failure) == false) return false;
      CloseFD image {providerFD}, mount, retainedCgroup;
      String mountPath = {}; mountPath.snprintf<"/proc/{itoa}/ns/mnt"_ctv>(operation.supervisor.pid);
      mount.fd = ::open(mountPath.c_str(), O_RDONLY | O_CLOEXEC);
      if (mount.fd < 0 || mothershipVDCProcessMatches(operation.supervisor) == false) return reject("retained provider mount namespace unavailable");
      String cgroupNamespacePath = {};
      cgroupNamespacePath.snprintf<"/proc/{itoa}/ns/cgroup"_ctv>(operation.worker.pid);
      // Preserve the original cgroup namespace root while the new process joins
      // the existing runtime leaf. Creating a namespace from that leaf would
      // hide sibling container cgroups; joining the internal parent is EBUSY.
      retainedCgroup.fd = ::open(cgroupNamespacePath.c_str(), O_RDONLY);
      struct stat cgroupNamespace = {};
      if (retainedCgroup.fd < 0 || ::fstat(retainedCgroup.fd, &cgroupNamespace) != 0 ||
          uint64_t(cgroupNamespace.st_ino) != operation.worker.cgroupNamespace || mothershipVDCProcessMatches(operation.worker) == false)
        return reject("selected worker cgroup namespace identity changed");
      String retainedCgroupFD = {}; retainedCgroupFD.assignItoa(retainedCgroup.fd);
      String providerPath = {}, runtime = {}, logPath = {};
      providerPath.snprintf<"/proc/self/fd/{itoa}"_ctv>(uint64_t(providerFD));
      runtime.assignItoa(operation.runtimeIdentity);
      mothershipVirtualDatacenterPath(directory, "provider.log", logPath);
      Vector<char *> argv = {};
      argv.push_back(const_cast<char *>("/bin/bash")); argv.push_back(const_cast<char *>(providerPath.c_str()));
      argv.push_back(const_cast<char *>("--serve-adopt")); argv.push_back(const_cast<char *>(runtime.c_str())); argv.push_back(const_cast<char *>(directory.c_str()));
      for (String& argument : operation.providerArguments) argv.push_back(const_cast<char *>(argument.c_str()));
      argv.push_back(nullptr);
      pid_t child = ::fork();
      if (child == 0)
      {
        if (::setsid() < 0 || ::setns(mount.fd, CLONE_NEWNS) != 0 ||
            ::setenv("PRODIGY_VDC_RECOVERY_CGROUP_FD", retainedCgroupFD.c_str(), 1) != 0) _exit(125);
        int log = ::open(logPath.c_str(), O_WRONLY | O_CREAT | O_APPEND, 0600);
        int input = ::open("/dev/null", O_RDONLY);
        if (log < 0 || input < 0 || ::dup2(log, STDOUT_FILENO) < 0 || ::dup2(log, STDERR_FILENO) < 0 || ::dup2(input, STDIN_FILENO) < 0) _exit(125);
        ::execv("/bin/bash", argv.data()); _exit(127);
      }
      if (child < 0) return reject("cannot launch retained provider adopter");
      bool ready = false;
      for (unsigned attempt = 0; attempt < 200; ++attempt) {
        if (readReady()) { ready = true; break; }
        int status = 0; if (::waitpid(child, &status, WNOHANG) == child) break;
        ::usleep(50000);
      }
      if (ready == false) {
        MothershipVDCProcessIdentity pending = {};
        if (mothershipVDCReadProcess(child, pending)) (void)mothershipVDCSignal(pending, SIGKILL);
        return reject("retained provider adopter did not become ready");
      }
    }
    operation.phase = MothershipVDCRecoveryPhase::ready;
    if (save() == false || mothershipVDCProcessMatches(operation.supervisor) == false || mothershipVDCProcessMatches(operation.adopter) == false) return false;
    operation.phase = MothershipVDCRecoveryPhase::committed;
    if (save() == false) { operation.phase = MothershipVDCRecoveryPhase::ready; return false; }
  }
  if (mothershipVDCProcessMatches(operation.adopter) == false) return reject("committed provider owner is unavailable; retained resources remain held");
  if (mothershipVDCProcessMatches(operation.supervisor) && mothershipVDCSignal(operation.supervisor, SIGKILL) == false)
    return reject("cannot retire the exact frozen provider");
  if (mothershipVDCDurableWrite(directory, "commit", directoryName, failure) == false) return false;
  bool owns = false;
  for (unsigned i = 0; i < 100; ++i) {
    uint64_t pid = 0;
    if (mothershipVDCReadNumber(pidPath, pid) && pid == operation.adopter.pid) { owns = true; break; }
    ::usleep(50000);
  }
  if (owns == false) return reject("committed provider has not published ownership");

  if (operation.phase == MothershipVDCRecoveryPhase::committed)
  {
    if (mothershipVDCSignal(operation.worker, SIGSTOP) == false || waitStopped(operation.worker) == false ||
        executableMatches(operation.worker, operation.oldExecutable) == false) return reject("selected worker changed before replacement; recovery remains held");
    operation.phase = MothershipVDCRecoveryPhase::workerStopped;
    if (save() == false) return false;
  }
  if (operation.phase == MothershipVDCRecoveryPhase::workerStopped)
  {
    if (followerReplacement)
    {
      // Partial pinning before a coordinator crash is safely repeatable while
      // the exact original worker is stopped. Never kill it until both kernel
      // references and their durable identity have been established.
      const bool capture = operation.retainedTCX[0].linkID == 0 && operation.retainedTCX[1].linkID == 0;
      if (mothershipVDCRetainFollowerNetworking(operation, capture, failure) == false || save() == false) return false;
    }
    if (mothershipVDCProcessMatches(operation.worker) && mothershipVDCSignal(operation.worker, SIGKILL) == false)
      return reject("cannot stop exact selected worker; recovery remains held");
    for (unsigned i = 0; i < 100 && mothershipVDCProcessMatches(operation.worker); ++i) ::usleep(10000);
    if (mothershipVDCProcessMatches(operation.worker)) return reject("selected worker has not exited");
    operation.phase = MothershipVDCRecoveryPhase::workerKilled;
    if (save() == false) return false;
  }
  if (followerReplacement && operation.phase >= MothershipVDCRecoveryPhase::workerKilled &&
      mothershipVDCRetainFollowerNetworking(operation, false, failure) == false) return false;
  if (operation.phase == MothershipVDCRecoveryPhase::workerKilled)
  {
    String installed = {}, previous = {}, staged = {};
    bool rootExists = ::access(installedRoot.c_str(), F_OK) == 0;
    bool previousExists = ::access(previousRoot.c_str(), F_OK) == 0;
    if (rootExists && fileDigest(installedRoot, "prodigy.bundle.tar.zst", installed) == false) return false;
    if (previousExists && (fileDigest(previousRoot, "prodigy.bundle.tar.zst", previous) == false || previous.equals(expectedOldSHA) == false))
      return reject("recovery previous runtime identity mismatch");
    if (installed.equals(successorSHA) == false)
    {
      if (fileDigest(stagedRoot, "prodigy.bundle.tar.zst", staged) == false || staged.equals(successorSHA) == false ||
          (rootExists && (installed.equals(expectedOldSHA) == false || previousExists))) return reject("recovery runtime swap identity mismatch");
      if (rootExists && ::rename(installedRoot.c_str(), previousRoot.c_str()) != 0) return reject("cannot retain previous runtime root");
      if (::rename(stagedRoot.c_str(), installedRoot.c_str()) != 0) return reject("cannot install approved recovery runtime root");
    }
    else if (previousExists == false) return reject("successor runtime has no retained predecessor root");
    // Both source and target rename directories must be durable before launch.
    String machineRoot = {}; machineRoot.snprintf<"{}/machines/{itoa}/root"_ctv>(cluster.test.workspaceRoot, uint64_t(machineIndex));
    if (mothershipVDCDurableWrite(machineRoot, ".recovery-owner", directoryName, failure) == false ||
        mothershipVDCDurableWrite(directory, "root-installed", directoryName, failure) == false) return false;
    operation.phase = MothershipVDCRecoveryPhase::rootInstalled;
    if (save() == false) return false;
    mothershipVDCTestFaultAfterRecoveryTransition(testFaultAfterPhase, MothershipVDCTestRecoveryFaultPhase::rootInstalled, operation);
  }
  if (operation.phase == MothershipVDCRecoveryPhase::rootInstalled)
  {
    if (expectedIncompleteWorkerSHA.empty() == false)
    {
      String currentSHA = {}, stagedBoot = {}, stagedSHA = {}, stagedPath = {};
      mothershipVirtualDatacenterPath(directory, "successor-boot.json", stagedPath);
      if (prodigyComputeFileSHA256Hex(bootPath, currentSHA, failure) == false ||
          mothershipVDCRead(stagedPath, stagedBoot, 32 * 1024 * 1024) == false ||
          prodigyComputeSHA256Hex(stagedBoot, stagedSHA, failure) == false || stagedSHA.equals(operation.successorBootSHA256) == false)
        return reject("prepared Brain bootstrap receipt identity mismatch");
      if (currentSHA.equals(operation.successorBootSHA256) == false)
      {
        if (currentSHA.equals(operation.previousBootSHA256) == false)
          return reject("retained Brain boot changed while recovery was held");
        if (mothershipVDCDurableWrite(bootDirectory, bootName.c_str(), stagedBoot, failure) == false) return false;
      }
    }
    operation.phase = MothershipVDCRecoveryPhase::launchRequested;
    if (save() == false) return false;
  }
  if (operation.phase == MothershipVDCRecoveryPhase::launchRequested)
  {
    if (expectedIncompleteWorkerSHA.empty() == false)
    {
      String observedBootSHA = {};
      if (prodigyComputeFileSHA256Hex(bootPath, observedBootSHA, failure) == false || observedBootSHA.equals(operation.successorBootSHA256) == false)
        return reject("prepared Brain bootstrap receipt changed before launch");
    }
    if (mothershipVDCDurableWrite(directory, "launch", directoryName, failure) == false) return false;
    String replacedPath = {}; mothershipVirtualDatacenterPath(directory, "replaced", replacedPath);
    bool replaced = false;
    for (unsigned attempt = 0; attempt < 300; ++attempt)
    {
      String receipt = {}, cgroup = {};
      unsigned long long pid = 0, start = 0, net = 0; char extra = 0;
      MothershipVDCProcessIdentity observed = {};
      if (mothershipVDCRead(replacedPath, receipt, 256) &&
          std::sscanf(receipt.c_str(), "%llu %llu %llu %c", &pid, &start, &net, &extra) == 3 && pid != operation.worker.pid &&
          mothershipVDCReadProcess(pid, observed) && observed.startTime == start && observed.networkNamespace == operation.worker.networkNamespace &&
          observed.cgroupNamespace == operation.worker.cgroupNamespace &&
          executableMatches(observed, operation.successorExecutable) && mothershipVDCReadProcessFile(pid, "cgroup", cgroup) && cgroup.equals(operation.workerCgroup))
      { operation.replacement = observed; replaced = true; break; }
      ::usleep(50000);
    }
    if (replaced == false) return reject("replacement runtime was not observed; provider retains selected machine without cgroup reset");
    operation.phase = MothershipVDCRecoveryPhase::replaced;
    if (save() == false) return false;
    mothershipVDCTestFaultAfterRecoveryTransition(testFaultAfterPhase, MothershipVDCTestRecoveryFaultPhase::workerReplaced, operation);
  }
  if (executableMatches(operation.replacement, operation.successorExecutable) == false) return reject("replacement runtime identity no longer matches completed recovery");
  if (followerReplacement && mothershipVDCRetainFollowerNetworking(operation, false, failure) == false) return false;
  // Completion is a process/resource retention receipt. Async Neuron adoption,
  // application health and quorum remain separately observed qualification gates.
  operation.phase = MothershipVDCRecoveryPhase::complete;
  if (save() == false || mothershipVDCDurableWrite(directory, "complete", directoryName, failure) == false) return false;
  if (completedOperationID) *completedOperationID = operation.operationID;
  if (failure) failure->clear();
  return true;
}

// Typed Mothership owns the disposable OS boot configuration. The sealed
// provider only installs this material into its private root and enters init;
// the spare receives no Prodigy executable, boot record or transport secret.
static bool mothershipPrepareVirtualDatacenterSpare(const MothershipProdigyCluster& cluster,
    uint64_t hostNetns, String *failure)
{
  if (cluster.test.spareMachineCount == 0) return true;
  if (cluster.test.spareMachineCount != 1 || cluster.test.machineCount <= cluster.nBrains ||
      !cluster.bootstrapSshPrivateKeyPath.equals(prodigyDefaultBootstrapSSHPrivateKeyPath()) ||
      !Vault::validateSSHKeyPackageEd25519(cluster.bootstrapSshKeyPackage, failure) ||
      !Vault::validateSSHKeyPackageEd25519(cluster.bootstrapSshHostKeyPackage, failure))
  {
    if (failure && failure->empty()) failure->assign("SSH spare requires one worker and the default private-key path"_ctv);
    return false;
  }
  String directory;
  directory.snprintf<"{}/spare-bootstrap"_ctv>(cluster.test.workspaceRoot);
  if (!prodigyEnsureLocalDirectoryPath(directory, 0700, failure)) return false;
  auto write = [&](const char *name, const String& contents, mode_t mode = 0600) {
    String path;
    mothershipVirtualDatacenterPath(directory, name, path);
    return mothershipVirtualDatacenterWriteFile(path, contents, mode, failure);
  };
  String environment;
  environment.snprintf<"PRODIGY_DEV_MODE=1 PRODIGY_DEV_TEST_OVERCOMMIT_CPUS=1 PRODIGY_HOST_NETNS_INO={itoa} PRODIGY_BOOTSTRAP_BRAIN_COUNT={itoa} PRODIGY_STATE_DB=/containers/prodigy.state PRODIGY_CRASH_REPORT_PATH=/var/log/prodigy/crash.txt"_ctv>(hostNetns, uint64_t(cluster.nBrains));
  String sshConfig;
  sshConfig.assign("Port 22\nHostKey /etc/ssh/ssh_host_ed25519_key\nPidFile /run/sshd.pid\nAuthorizedKeysFile .ssh/authorized_keys\nPermitRootLogin prohibit-password\nPasswordAuthentication no\nKbdInteractiveAuthentication no\nPermitEmptyPasswords no\nUsePAM no\nAuthenticationMethods publickey\nPrintMotd no\nSubsystem sftp internal-sftp\nSetEnv "_ctv);
  sshConfig.append(environment); sshConfig.append('\n');
  String managerConfig;
  managerConfig.assign("[Manager]\nDefaultEnvironment="_ctv);
  managerConfig.append(environment); managerConfig.append('\n');
  String prodigyServiceConfig;
  prodigyServiceConfig.assign("[Service]\nEnvironment="_ctv);
  prodigyServiceConfig.append(environment);
  prodigyServiceConfig.append("\nStandardOutput=append:/var/log/prodigy/runtime.log\nStandardError=inherit\n"_ctv);
  return write("client-private", cluster.bootstrapSshKeyPackage.privateKeyOpenSSH) &&
      write("client-public", cluster.bootstrapSshKeyPackage.publicKeyOpenSSH) &&
      write("host-private", cluster.bootstrapSshHostKeyPackage.privateKeyOpenSSH) &&
      write("host-public", cluster.bootstrapSshHostKeyPackage.publicKeyOpenSSH) &&
      write("sshd_config", sshConfig) && write("manager.conf", managerConfig) &&
      write("prodigy.conf", prodigyServiceConfig) &&
      write("sshd.service", "[Unit]\nDescription=Disposable machine SSH\nDefaultDependencies=no\n[Service]\nExecStart=/usr/bin/sshd -D -e -f /etc/ssh/sshd_config\nStandardOutput=append:/var/log/prodigy/sshd.log\nStandardError=inherit\n"_ctv) &&
      write("machine.target", "[Unit]\nDescription=Disposable SSH machine\nDefaultDependencies=no\nRequires=sshd.service\nWants=multi-user.target\nAfter=sshd.service\n"_ctv) &&
      write("empty.target", "[Unit]\nDescription=Disposable machine environment\nDefaultDependencies=no\n"_ctv) &&
      write("passwd", "root:x:0:0:root:/root:/bin/bash\nsshd:x:74:74:SSH privilege separation:/var/empty:/usr/bin/nologin\nnobody:x:65534:65534:nobody:/:/usr/bin/nologin\n"_ctv, 0644) &&
      write("group", "root:x:0:\nsshd:x:74:\nnobody:x:65534:\n"_ctv, 0644) &&
      write("shadow", "root::0:0:99999:7:::\nsshd:!:0:0:99999:7:::\nnobody:!:0:0:99999:7:::\n"_ctv) &&
      write("nsswitch.conf", "passwd: files\ngroup: files\nshadow: files\nhosts: files dns\n"_ctv, 0644) &&
      write("ready", "1\n"_ctv);
}

static bool mothershipStartVirtualDatacenterProvider(const MothershipProdigyCluster& cluster, String *failure = nullptr)
{
  struct stat netns = {};
  if (::stat("/proc/self/ns/net", &netns) != 0 || netns.st_ino == 0)
  {
    if (failure)
    {
      failure->snprintf<"failed to identify Mothership network namespace: {}"_ctv>(String(std::strerror(errno)));
    }
    return false;
  }

  uint32_t mtu = cluster.test.interContainerMTU > 0 ? cluster.test.interContainerMTU : prodigyRuntimeTestInterContainerMTUDefault;
  String machineCount = {};
  String brainCount = {};
  String mtuText = {};
  String fakeBoundary = {};
  String netnsInode = {};
  String machineLogicalCores = {};
  String machineMemoryMB = {};
  String machineStorageMB = {};
  String storageDeviceCount = {};
  String storageDeviceMB = {};
  machineCount.assignItoa(cluster.test.machineCount);
  brainCount.assignItoa(cluster.nBrains);
  mtuText.assignItoa(mtu);
  fakeBoundary.assignItoa(cluster.test.enableFakeIpv4Boundary ? 1 : 0);
  netnsInode.assignItoa(netns.st_ino);
  machineLogicalCores.assignItoa(cluster.test.machineLogicalCores);
  machineMemoryMB.assignItoa(cluster.test.machineMemoryMB);
  machineStorageMB.assignItoa(cluster.test.machineStorageMB);
  storageDeviceCount.assignItoa(cluster.test.storageDeviceCount);
  storageDeviceMB.assignItoa(cluster.test.storageDeviceMB);
  String controlSocketPath = {};
  mothershipResolveTestClusterControlSocketPath(cluster, controlSocketPath);
  Vector<String> arguments = {};
  arguments.emplace_back("--launch"_ctv);
  arguments.push_back(cluster.test.workspaceRoot);
  arguments.push_back(std::move(machineCount));
  arguments.push_back(std::move(brainCount));
  arguments.push_back(std::move(mtuText));
  arguments.push_back(std::move(fakeBoundary));
  arguments.push_back(std::move(netnsInode));
  arguments.push_back(std::move(machineLogicalCores));
  arguments.push_back(std::move(machineMemoryMB));
  arguments.push_back(std::move(machineStorageMB));
  arguments.push_back(std::move(storageDeviceCount));
  arguments.push_back(std::move(storageDeviceMB));
  arguments.push_back(std::move(controlSocketPath));
  if (cluster.test.spareMachineCount != 0)
  {
    arguments.emplace_back();
    arguments.back().assignItoa(cluster.test.spareMachineCount);
  }
  // Launch first clears the previous disposable workspace. Publish new OS
  // material only afterward; the provider waits for the final ready receipt.
  return mothershipRunVirtualDatacenterProvider(std::move(arguments), failure) &&
      mothershipPrepareVirtualDatacenterSpare(cluster, netns.st_ino, failure);
}

