  bool readRoutableSubnets(const MothershipProdigyCluster& cluster,
                           RoutableSubnetRegistryReport& report, String& failure)
  {
    report = {}; socket.close();
    // Callers already resolved this exact cluster record. Configuring from it
    // avoids opening the exclusive cluster registry again while a caller holds
    // the BGP origin-policy lock and registry handle across this observation.
    if (!socket.configureCluster(cluster, &failure) || !socket.ensureConnected()) return false;
    Message::construct(socket.wBuffer, MothershipTopic::pullRoutableSubnets);
    if (!socket.send()) { failure = socket.ioFailureDetail(); socket.close(); return false; }
    Message *response = socket.recvExpectedTopic(MothershipTopic::pullRoutableSubnets);
    if (!response) { failure.assign("routable prefix observation unavailable"_ctv); socket.close(); return false; }
    uint8_t *args = response->args; String encoded = {};
    Message::extractToStringView(args, encoded);
    const bool valid = args == response->terminal() && BitseryEngine::deserializeSafe(encoded, report) && report.success;
    socket.close();
    if (!valid) failure.assign("routable prefix observation is invalid"_ctv);
    return valid;
  }

  bool readLocalCousinServicePermission(const MothershipProdigyCluster& cluster, uint128_t permissionUUID,
                                        ProdigyLocalCousinServicePermissionResponse& response, String& failure)
  {
    response = {};
    String targetName = cluster.name;
    if (permissionUUID == 0 || !configureControlTarget(targetName.c_str(), &failure)) return false;
    ProdigyLocalCousinServicePermissionQuery query = {};
    query.permissionUUID = permissionUUID;
    if (!requestTopicRoundTrip(MothershipTopic::pullLocalCousinServicePermission, query, response, failure) ||
        response.protocolVersion != 1 || !response.success || !response.found || !response.qualified ||
        !prodigyLocalCousinServicePermissionValid(response.permission) ||
        response.permission.permissionUUID != permissionUUID ||
        response.permission.localClusterUUID != cluster.clusterUUID ||
        response.permission.state != ProdigyLocalCousinServicePermissionState::active ||
        response.permission.acceptedAuthorityGeneration > response.currentAuthorityGeneration)
    {
      if (failure.empty()) failure.assign("active qualified cousin permission observation is unavailable"_ctv);
      return false;
    }
    return true;
  }

  // Graph replicas use the durable COUSIN route registry, but admission must
  // also prove that both Brains still serve the same current generation.  This
  // consumes the registry's receipts and the existing live permission/route
  // observations; it deliberately does not cache another health state.
  bool graphReplicaCousinRoutesReady(const MothershipProdigyCluster& owner,
                                     const MothershipProdigyCluster& replica,
                                     const DeploymentPlan& replicaPlan,
                                     const Vector<MothershipGraphReplicaRouteBinding>& bindings,
                                     String& failure)
  {
    if (!prodigyGraphDeploymentPlanCanonical(replicaPlan, true) || bindings.size() != 2) {
      failure.assign("graph replica requires the two exact retained COUSIN service bindings"_ctv);
      return false;
    }
    auto planCopy = replicaPlan;
    String planBytes, planSHA256;
    if (!BitseryEngine::serialize(planBytes, planCopy) || !prodigyComputeSHA256Hex(planBytes, planSHA256)) {
      failure.assign("graph replica plan cannot be canonically bound to COUSIN permissions"_ctv);
      return false;
    }
    auto observeLiveRoute = [&](const MothershipProdigyCluster& cluster, const CousinRouteRecord& route,
                                CousinRouteHalf half, const CousinRouteApplyReceipt& minimumReceipt) {
      ProdigyCousinRouteQuery query = {}; query.routeUUID = route.routeUUID;
      ProdigyCousinRouteResponse response = {};
      String targetName = cluster.name;
      if (!configureControlTarget(targetName.c_str(), &failure) ||
          !requestTopicRoundTrip(MothershipTopic::pullCousinRoute, query, response, failure) ||
          response.protocolVersion != ProdigyCousinRouteResponse::version || !response.success || !response.found ||
          !response.qualified || response.localClusterUUID != cluster.clusterUUID ||
          !prodigyCousinRouteResponseValid(response) || response.applyReceipt.localHalf != half ||
          response.route.priorOperationUUIDs != route.priorOperationUUIDs ||
          !cousinRouteExactMatches(response.route, route) ||
          !cousinRouteApplyReceiptMatchesCurrentRoute(response.applyReceipt, route) ||
          response.applyReceipt.localRuntimeRevision < minimumReceipt.localRuntimeRevision) {
        if (failure.empty()) failure.assign("graph replica COUSIN route is absent, stale, or not live on its required cluster half"_ctv);
        return false;
      }
      return true;
    };
    for (const auto& binding : bindings) {
      const uint64_t service = prodigyRuntimeStatefulServicePrefix(replicaPlan.config.applicationID,
          binding.purpose == ProdigyCousinServicePurpose::sibling ? 2 : 4);
      if ((binding.purpose != ProdigyCousinServicePurpose::sibling &&
           binding.purpose != ProdigyCousinServicePurpose::seeding) ||
          binding.route.sourceClusterUUID != replica.clusterUUID || binding.route.destinationClusterUUID != owner.clusterUUID ||
          binding.route.sourceApplicationID != replicaPlan.config.applicationID ||
          binding.route.destinationApplicationID != replicaPlan.config.applicationID ||
          binding.route.sourceCousinServicePrefix != service || binding.route.destinationCousinServicePrefix != service) {
        failure.assign("graph replica COUSIN route has the wrong application, direction, or service purpose"_ctv);
        return false;
      }
      ProdigyLocalCousinServicePermissionResponse ownerPermission = {}, replicaPermission = {};
      if (!readLocalCousinServicePermission(replica, binding.route.sourcePermissionUUID, replicaPermission, failure) ||
          !readLocalCousinServicePermission(owner, binding.route.destinationPermissionUUID, ownerPermission, failure)) return false;
      const auto& source = replicaPermission.permission;
      const auto& destination = ownerPermission.permission;
      const uint64_t authorizedService = MeshServices::constrainPrefixToGroup(service, 0);
      if (source.localHalf != CousinRouteHalf::source || destination.localHalf != CousinRouteHalf::destination ||
          source.permissionUUID != binding.route.sourcePermissionUUID || destination.permissionUUID != binding.route.destinationPermissionUUID ||
          source.purpose != binding.purpose || destination.purpose != binding.purpose ||
          source.localClusterUUID != replica.clusterUUID || source.peerClusterUUID != owner.clusterUUID ||
          destination.localClusterUUID != owner.clusterUUID || destination.peerClusterUUID != replica.clusterUUID ||
          source.localCousinServicePrefix != service || source.peerCousinServicePrefix != service ||
          destination.localCousinServicePrefix != service || destination.peerCousinServicePrefix != service ||
          source.authorizedService != authorizedService || destination.authorizedService != authorizedService ||
          source.localDeploymentID != replicaPlan.config.deploymentID() ||
          source.canonicalPlanSHA256 != planSHA256 ||
          source.artifactSHA256 != replicaPlan.config.containerBlobSHA256 ||
          source.artifactBytes != replicaPlan.config.containerBlobBytes ||
          destination.peerDeploymentID != source.localDeploymentID || destination.peerCanonicalPlanSHA256 != planSHA256 ||
          destination.peerArtifactSHA256 != replicaPlan.config.containerBlobSHA256 ||
          destination.peerArtifactBytes != replicaPlan.config.containerBlobBytes ||
          !prodigyCousinServicePermissionPeerScopeMatches(source, destination) ||
          !observeLiveRoute(replica, binding.route, CousinRouteHalf::source, binding.replicaReceipt) ||
          !observeLiveRoute(owner, binding.route, CousinRouteHalf::destination, binding.ownerReceipt)) {
        if (failure.empty()) failure.assign("graph replica COUSIN permission or route receipt is not exact and active"_ctv);
        return false;
      }
    }
    return true;
  }

  bool testPairCousinTransportDeploymentReady(const MothershipProdigyCluster& cluster,
                                              const ProdigyLocalCousinServicePermission& permission,
                                              DeploymentIdentityReport& report, String& failure)
  {
    if (!readDeploymentIdentity(cluster, permission.localDeploymentID, report, failure)) return false;
    const uint64_t versionID = permission.localDeploymentID & ((uint64_t(1) << 48) - 1);
    if (report.clusterUUID != cluster.clusterUUID || report.deploymentID != permission.localDeploymentID ||
        report.applicationID != permission.localApplicationID || report.versionID != versionID ||
        report.state != DeploymentState::running || !report.isStateful ||
        report.canonicalPlanSHA256 != permission.canonicalPlanSHA256 ||
        report.containerBlobSHA256 != permission.artifactSHA256 ||
        report.containerBlobBytes != permission.artifactBytes || report.nTarget == 0 ||
        report.nDeployed != report.nTarget || report.nHealthy != report.nTarget ||
        report.authorityGeneration == 0 || report.masterUUID == 0 || report.masterBootNs <= 0)
    {
      failure.assign("COUSIN transport permission does not name an exact wholly healthy live deployment"_ctv);
      return false;
    }
    return true;
  }

  bool bindTestPairCousinTransport(uint128_t routeUUID,
                                   const MothershipProdigyCluster& source,
                                   const MothershipProdigyCluster& target,
                                   MothershipTestPairBoundaryRecord& record,
                                   DeploymentIdentityReport& sourceReport,
                                   DeploymentIdentityReport& targetReport,
                                   String& failure)
  {
    auto& intent = record.cousinTransport;
    intent = {};
    {
      // Release the registry's process-exclusive lock before authenticated
      // cluster observations, whose target resolution opens the same registry.
      auto registry = openClusterRegistry();
      if (!registry.loadUsableCousinRoute(routeUUID, Time::now<TimeResolution::ms>(), intent.route, &failure) ||
          intent.route.sourceClusterUUID != source.clusterUUID || intent.route.destinationClusterUUID != target.clusterUUID ||
          !registry.loadCurrentCousinRouteApplyReceipt(routeUUID, CousinRouteHalf::source,
                                                       intent.sourceApplyReceipt, &failure) ||
          !registry.loadCurrentCousinRouteApplyReceipt(routeUUID, CousinRouteHalf::destination,
                                                       intent.destinationApplyReceipt, &failure))
      {
        if (failure.empty()) failure.assign("stateless transfer requires an active acknowledged COUSIN route from source to target"_ctv);
        return false;
      }
    }
    ProdigyLocalCousinServicePermissionResponse sourcePermission = {}, destinationPermission = {};
    if (!readLocalCousinServicePermission(source, intent.route.sourcePermissionUUID, sourcePermission, failure) ||
        !readLocalCousinServicePermission(target, intent.route.destinationPermissionUUID, destinationPermission, failure))
      return false;
    intent.sourcePermission = sourcePermission.permission;
    intent.destinationPermission = destinationPermission.permission;
    if (!testPairCousinTransportDeploymentReady(source, intent.sourcePermission, sourceReport, failure) ||
        !testPairCousinTransportDeploymentReady(target, intent.destinationPermission, targetReport, failure)) return false;
    return true;
  }

  bool testPairCousinTransportReady(const MothershipTestPairBoundaryRecord& record,
                                    MothershipProdigyCluster& source,
                                    MothershipProdigyCluster& target,
                                    String& failure)
  {
    if (record.version < 5) return true;
    if (!MothershipClusterRegistry::testPairCousinTransportIntentValid(record))
    {
      failure.assign("stateless transfer COUSIN transport intent is invalid"_ctv);
      return false;
    }
    const auto& expected = record.cousinTransport;
    CousinRouteRecord route = {};
    CousinRouteApplyReceipt sourceReceipt = {}, destinationReceipt = {};
    auto receiptCurrent = [&](const CousinRouteApplyReceipt& observed,
                              const CousinRouteApplyReceipt& original) {
      return cousinRouteApplyReceiptMatchesCurrentRoute(observed, route) &&
             observed.localHalf == original.localHalf &&
             observed.authorizationSHA256 == original.authorizationSHA256 &&
             observed.localClusterUUID == original.localClusterUUID &&
             observed.localRuntimeRevision >= original.localRuntimeRevision;
    };
    {
      auto registry = openClusterRegistry();
      if (!registry.loadUsableCousinRoute(expected.route.routeUUID, Time::now<TimeResolution::ms>(), route, &failure) ||
          route.priorOperationUUIDs != expected.route.priorOperationUUIDs ||
          !cousinRouteExactMatches(route, expected.route) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::source, sourceReceipt, &failure) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::destination, destinationReceipt, &failure) ||
          !receiptCurrent(sourceReceipt, expected.sourceApplyReceipt) ||
          !receiptCurrent(destinationReceipt, expected.destinationApplyReceipt))
      {
        if (failure.empty()) failure.assign("stateless transfer COUSIN route or durable receipt changed"_ctv);
        return false;
      }
    }
    ProdigyLocalCousinServicePermissionResponse sourcePermission = {}, destinationPermission = {};
    if (!readLocalCousinServicePermission(source, route.sourcePermissionUUID, sourcePermission, failure) ||
        !readLocalCousinServicePermission(target, route.destinationPermissionUUID, destinationPermission, failure) ||
        !prodigyLocalCousinServicePermissionEqual(sourcePermission.permission, expected.sourcePermission) ||
        !prodigyLocalCousinServicePermissionEqual(destinationPermission.permission, expected.destinationPermission))
    {
      if (failure.empty()) failure.assign("stateless transfer COUSIN permission changed or is no longer qualified"_ctv);
      return false;
    }
    DeploymentIdentityReport sourceDeployment = {}, destinationDeployment = {};
    if (!testPairCousinTransportDeploymentReady(source, expected.sourcePermission, sourceDeployment, failure) ||
        !testPairCousinTransportDeploymentReady(target, expected.destinationPermission, destinationDeployment, failure)) return false;
    ProdigyCousinRouteResponse sourceResponse = {}, destinationResponse = {};
    if (!observeCousinRouteSide(source, route, CousinRouteHalf::source, sourceResponse, failure) ||
        !observeCousinRouteSide(target, route, CousinRouteHalf::destination, destinationResponse, failure) ||
        !sourceResponse.found || !sourceResponse.qualified || !destinationResponse.found || !destinationResponse.qualified ||
        sourceResponse.route.priorOperationUUIDs != route.priorOperationUUIDs ||
        destinationResponse.route.priorOperationUUIDs != route.priorOperationUUIDs ||
        !cousinRouteExactMatches(sourceResponse.route, route) || !cousinRouteExactMatches(destinationResponse.route, route) ||
        !receiptCurrent(sourceResponse.applyReceipt, expected.sourceApplyReceipt) ||
        !receiptCurrent(destinationResponse.applyReceipt, expected.destinationApplyReceipt))
    {
      if (failure.empty()) failure.assign("stateless transfer COUSIN route is not freshly qualified on both clusters"_ctv);
      return false;
    }
    return true;
  }

  bool testPairDeploymentReady(const MothershipProdigyCluster& cluster, uint64_t deploymentID,
                               uint32_t machineIndex, const String& vip, uint16_t port,
                               DeploymentIdentityReport& report, String& failure)
  {
    if (cluster.deploymentMode != MothershipClusterDeploymentMode::test || cluster.test.enableFakeIpv4Boundary ||
        cluster.nBrains != 3 || cluster.test.machineCount != 3 || machineIndex == 0 || machineIndex > 3)
    {
      failure.assign("pair endpoint qualification requires independent three-Brain test clusters without fake boundaries"_ctv);
      return false;
    }
    String expectedAddress = {}, private6 = {}, public6 = {};
    mothershipVirtualDatacenterMachineAddresses(machineIndex, cluster.datacenterFragment, false,
                                                expectedAddress, private6, public6);
    uint128_t expectedMachine = 0;
    for (const ClusterMachine& machine : cluster.topology.machines)
    {
      bool matches = false;
      for (const ClusterMachineAddress& address : machine.addresses.privateAddresses)
        if (address.address == expectedAddress) matches = true;
      if (matches)
      {
        if (expectedMachine != 0) { failure.assign("ambiguous test machine identity"_ctv); return false; }
        expectedMachine = machine.uuid;
      }
    }
    if (expectedMachine == 0) { failure.assign("test machine identity is unavailable"_ctv); return false; }
    if (!readDeploymentIdentity(cluster, deploymentID, report, failure)) return false;
    if (!report.profileEligible || report.observedEndpointIPv4 != vip || report.observedEndpointPort != port ||
        report.observedEndpointMachineUUID != expectedMachine ||
        report.nTarget != 1 || report.nHealthy != report.nTarget || report.nDeployed != report.nTarget ||
        !prodigyIsSHA256HexDigest(report.canonicalPlanSHA256) || !prodigyIsSHA256HexDigest(report.containerBlobSHA256))
    {
      failure.assign("pair endpoint deployment is not the exact healthy single-machine stateless TCP profile"_ctv);
      return false;
    }
    return true;
  }

  bool productionWorkloadIdentity(const MothershipProdigyCluster& cluster, uint64_t deploymentID,
                                  MothershipProductionWorkloadIdentity& identity,
                                  DeploymentIdentityReport& report, String& failure)
  {
    identity = {}; report = {};
    if (cluster.deploymentMode == MothershipClusterDeploymentMode::test || cluster.nBrains != 3 ||
        cluster.topology.machines.size() != 3 || !readDeploymentIdentity(cluster, deploymentID, report, failure))
    {
      if (failure.empty()) failure.assign("production migration requires a non-test three-Brain cluster"_ctv);
      return false;
    }
    uint32_t endpointMatches = 0;
    for (const auto& machine : cluster.topology.machines)
      if (machine.uuid == report.observedEndpointMachineUUID && machine.isBrain) ++endpointMatches;
    struct in_addr endpoint4 = {};
    struct in6_addr endpoint6 = {};
    String endpointText = report.observedEndpointIPv4;
    const bool endpointIsIPv4 = ::inet_pton(AF_INET, endpointText.c_str(), &endpoint4) == 1;
    const bool endpointIsIPv6 = ::inet_pton(AF_INET6, endpointText.c_str(), &endpoint6) == 1;
    const bool endpointIsLoopback = endpointIsIPv4 ?
        (uint32_t(ntohl(endpoint4.s_addr)) >> 24) == 127 :
        (endpointIsIPv6 && IN6_IS_ADDR_LOOPBACK(&endpoint6));
    const bool endpointIsUnspecified = endpointIsIPv4 ? endpoint4.s_addr == INADDR_ANY :
        (endpointIsIPv6 && IN6_IS_ADDR_UNSPECIFIED(&endpoint6));
    if (!report.profileEligible || report.isStateful || report.useHostNetworkNamespace ||
        report.state != DeploymentState::running || report.applicationID == 0 ||
        report.applicationID != uint16_t(deploymentID >> 48) ||
        report.nTarget != 1 || report.nDeployed != 1 || report.nHealthy != 1 ||
        !prodigyIsSHA256HexDigest(report.canonicalPlanSHA256) ||
        !prodigyIsSHA256HexDigest(report.containerBlobSHA256) || report.containerBlobBytes == 0 ||
        report.authorityGeneration == 0 || report.masterUUID == 0 || report.masterBootNs <= 0 ||
        report.observedEndpointMachineUUID == 0 || endpointMatches != 1 ||
        report.observedEndpointPort == 0 || (!endpointIsIPv4 && !endpointIsIPv6) ||
        endpointIsLoopback || endpointIsUnspecified)
    {
      failure.assign("production migration endpoint is not an exact healthy single-machine stateless TCP deployment"_ctv);
      return false;
    }
    identity.clusterUUID = cluster.clusterUUID;
    identity.applicationID = report.applicationID;
    identity.deploymentID = report.deploymentID;
    identity.canonicalPlanSHA256 = report.canonicalPlanSHA256;
    identity.artifactSHA256 = report.containerBlobSHA256;
    identity.artifactBytes = report.containerBlobBytes;
    identity.replicas = report.nTarget;
    identity.endpointMachineUUID = report.observedEndpointMachineUUID;
    identity.endpointIPv4 = report.observedEndpointIPv4;
    identity.endpointTCPPort = report.observedEndpointPort;
    return mothershipProductionWorkloadIdentityValid(identity);
  }

  bool productionClusterHealthy(const MothershipProdigyCluster& cluster,
                                ClusterStatusReport& report, String& failure)
  {
    if (!readManagedClusterStatus(cluster, report, failure)) return false;
    if (!report.hasTopology || report.topology.version == 0 || report.topology.machines.size() != 3 ||
        report.machineReports.size() != 3)
    {
      failure.assign("production migration requires a fresh exact three-machine topology"_ctv);
      return false;
    }
    uint32_t masters = 0;
    for (const auto& machine : report.topology.machines)
    {
      String uuid = {}; uuid.assignItoh(machine.uuid);
      uint32_t matches = 0;
      const MachineStatusReport *status = nullptr;
      for (const auto& candidate : report.machineReports)
        if (candidate.machineUUID == uuid) { ++matches; status = &candidate; }
      if (machine.uuid == 0 || !machine.isBrain || matches != 1 || status == nullptr ||
          !status->isBrain || status->state != "healthy"_ctv || !status->controlPlaneReachable ||
          !status->runtimeReady || status->bootTimeMs <= 0 || status->hardwareFailure ||
          status->decommissioning || status->rebooting || status->updatingOS)
      {
        failure.assign("production migration cluster is not an exact healthy three-Brain topology"_ctv);
        return false;
      }
      if (status->currentMaster) ++masters;
    }
    if (masters != 1)
    {
      failure.assign("production migration cluster does not have exactly one observed master"_ctv);
      return false;
    }
    return true;
  }

  static bool productionWorkloadIdentityEqual(const MothershipProductionWorkloadIdentity& left,
                                              const MothershipProductionWorkloadIdentity& right)
  {
    String leftBytes = {}, rightBytes = {};
    auto leftCopy = left; auto rightCopy = right;
    BitseryEngine::serialize(leftBytes, leftCopy); BitseryEngine::serialize(rightBytes, rightCopy);
    return leftBytes == rightBytes;
  }

  bool productionPairTransportReady(const MothershipProductionPairRecord& record,
                                    MothershipProdigyCluster& source,
                                    MothershipProdigyCluster& target,
                                    String& failure)
  {
    const auto& expected = record.intent;
    CousinRouteRecord route = {};
    CousinRouteApplyReceipt sourceReceipt = {}, targetReceipt = {};
    auto receiptCurrent = [&](const CousinRouteApplyReceipt& observed,
                              const CousinRouteApplyReceipt& original) {
      return cousinRouteApplyReceiptMatchesCurrentRoute(observed, route) &&
          observed.localHalf == original.localHalf &&
          observed.authorizationSHA256 == original.authorizationSHA256 &&
          observed.localClusterUUID == original.localClusterUUID &&
          observed.localRuntimeRevision == original.localRuntimeRevision;
    };
    {
      auto registry = openClusterRegistry();
      String sourceIdentity = {}, targetIdentity = {};
      sourceIdentity.assignItoh(expected.route.sourceClusterUUID);
      targetIdentity.assignItoh(expected.route.destinationClusterUUID);
      if (!registry.getClusterByIdentity(sourceIdentity, source, &failure) ||
          !registry.getClusterByIdentity(targetIdentity, target, &failure) ||
          !registry.loadUsableCousinRoute(expected.route.routeUUID, Time::now<TimeResolution::ms>(), route, &failure) ||
          route.priorOperationUUIDs != expected.route.priorOperationUUIDs ||
          !cousinRouteExactMatches(route, expected.route) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::source,
                                                       sourceReceipt, &failure) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::destination,
                                                       targetReceipt, &failure) ||
          !receiptCurrent(sourceReceipt, expected.sourceRouteReceipt) ||
          !receiptCurrent(targetReceipt, expected.destinationRouteReceipt))
      {
        if (failure.empty()) failure.assign("production migration route or durable application receipt changed"_ctv);
        return false;
      }
    }
    if (source.deploymentMode == MothershipClusterDeploymentMode::test ||
        target.deploymentMode == MothershipClusterDeploymentMode::test)
    {
      failure.assign("production migration cannot use deploymentMode=test"_ctv);
      return false;
    }
    ProdigyLocalCousinServicePermissionResponse sourcePermission = {}, targetPermission = {};
    if (!readLocalCousinServicePermission(source, route.sourcePermissionUUID, sourcePermission, failure) ||
        !readLocalCousinServicePermission(target, route.destinationPermissionUUID, targetPermission, failure) ||
        !prodigyLocalCousinServicePermissionEqual(sourcePermission.permission, expected.sourcePermission) ||
        !prodigyLocalCousinServicePermissionEqual(targetPermission.permission, expected.destinationPermission))
    {
      if (failure.empty()) failure.assign("production migration COUSIN permission changed or is no longer qualified"_ctv);
      return false;
    }
    DeploymentIdentityReport sourceTransport = {}, targetTransport = {};
    if (!testPairCousinTransportDeploymentReady(source, expected.sourcePermission, sourceTransport, failure) ||
        !testPairCousinTransportDeploymentReady(target, expected.destinationPermission, targetTransport, failure)) return false;
    ProdigyCousinRouteResponse sourceResponse = {}, targetResponse = {};
    if (!observeCousinRouteSide(source, route, CousinRouteHalf::source, sourceResponse, failure) ||
        !observeCousinRouteSide(target, route, CousinRouteHalf::destination, targetResponse, failure) ||
        !sourceResponse.found || !sourceResponse.qualified || !targetResponse.found || !targetResponse.qualified ||
        !cousinRouteExactMatches(sourceResponse.route, route) || !cousinRouteExactMatches(targetResponse.route, route) ||
        !receiptCurrent(sourceResponse.applyReceipt, expected.sourceRouteReceipt) ||
        !receiptCurrent(targetResponse.applyReceipt, expected.destinationRouteReceipt))
    {
      if (failure.empty()) failure.assign("production migration COUSIN route is not freshly qualified on both clusters"_ctv);
      return false;
    }
    return true;
  }

  bool productionPairDataClusters(const MothershipProductionPairRecord& record,
                                  const MothershipProdigyCluster& routeSource,
                                  const MothershipProdigyCluster& routeDestination,
                                  MothershipProdigyCluster& dataSource,
                                  MothershipProdigyCluster& dataTarget,
                                  String& failure)
  {
    dataSource = {}; dataTarget = {};
    const auto& intent = record.intent;
    if (intent.protocolVersion != MothershipProductionPairIntent::statefulVersion ||
        routeSource.clusterUUID != intent.route.sourceClusterUUID ||
        routeDestination.clusterUUID != intent.route.destinationClusterUUID)
    {
      failure.assign("stateful data-role resolution requires the exact qualified route clusters"_ctv);
      return false;
    }
    if (routeSource.clusterUUID == intent.sourceWorkload.clusterUUID &&
        routeDestination.clusterUUID == intent.targetWorkload.clusterUUID)
    {
      dataSource = routeSource; dataTarget = routeDestination;
    }
    else if (routeSource.clusterUUID == intent.targetWorkload.clusterUUID &&
             routeDestination.clusterUUID == intent.sourceWorkload.clusterUUID)
    {
      dataSource = routeDestination; dataTarget = routeSource;
    }
    else
    {
      failure.assign("stateful data source and target do not exactly cover the qualified route clusters"_ctv);
      return false;
    }
    return true;
  }

  bool productionPairWorkloadsReady(const MothershipProductionPairRecord& record,
                                    const MothershipProdigyCluster& source,
                                    const MothershipProdigyCluster& target,
                                    bool requireSource,
                                    ClusterStatusReport& sourceStatus,
                                    ClusterStatusReport& targetStatus,
                                    String& failure)
  {
    sourceStatus = {}; targetStatus = {};
    if (!productionClusterHealthy(source, sourceStatus, failure) ||
        !productionClusterHealthy(target, targetStatus, failure)) return false;
    DeploymentIdentityReport report = {};
    MothershipProductionWorkloadIdentity observed = {};
    if (requireSource &&
        (!productionWorkloadIdentity(source, record.intent.sourceWorkload.deploymentID, observed, report, failure) ||
         !productionWorkloadIdentityEqual(observed, record.intent.sourceWorkload)))
    {
      if (failure.empty()) failure.assign("production migration source workload identity changed"_ctv);
      return false;
    }
    observed = {}; report = {};
    if (!productionWorkloadIdentity(target, record.intent.targetWorkload.deploymentID, observed, report, failure) ||
        !productionWorkloadIdentityEqual(observed, record.intent.targetWorkload))
    {
      if (failure.empty()) failure.assign("production migration target workload identity changed"_ctv);
      return false;
    }
    return true;
  }

  struct ProductionPairProviderState {
    bool selectedTarget = false;
    bool sourceReachable = false;
    bool targetReachable = false;
    uint64_t sourceFlows = 0;
    uint64_t targetFlows = 0;
    uint64_t sourceConnections = 0;
    uint64_t targetConnections = 0;
    uint64_t sourceRequestBytes = 0;
    uint64_t sourceResponseBytes = 0;
    uint64_t targetRequestBytes = 0;
    uint64_t targetResponseBytes = 0;
    uint64_t generation = 0;
    uint64_t pid = 0;
    String starttime = {};
  };

  void productionPairProviderArguments(const MothershipProductionPairRecord& record,
                                       const char *action, Vector<String>& arguments)
  {
    arguments.clear();
    String operation = {}, executorCluster = {}, executorMachine = {}, witnessMachine = {};
    String sourcePort = {}, targetPort = {}, listenerPort = {};
    mothershipAssignProviderHex128(record.intent.operationUUID, operation);
    mothershipAssignProviderHex128(record.intent.sourceWorkload.clusterUUID, executorCluster);
    mothershipAssignProviderHex128(record.intent.selectorMachineUUID, executorMachine);
    mothershipAssignProviderHex128(record.intent.ingressWitnessMachineUUID, witnessMachine);
    sourcePort.assignItoa(record.intent.sourceWorkload.endpointTCPPort);
    targetPort.assignItoa(record.intent.targetWorkload.endpointTCPPort);
    listenerPort.assignItoa(record.intent.selectorTCPPort);
    arguments.emplace_back(action);
    arguments.emplace_back("--operation-id"_ctv); arguments.push_back(operation);
    arguments.emplace_back("--executor-cluster-id"_ctv); arguments.push_back(executorCluster);
    arguments.emplace_back("--executor-machine-id"_ctv); arguments.push_back(executorMachine);
    arguments.emplace_back("--witness-machine-id"_ctv); arguments.push_back(witnessMachine);
    arguments.emplace_back("--state-dir"_ctv);
    arguments.emplace_back("/var/lib/prodigy/mothership-production-pairs"_ctv);
    arguments.emplace_back("--listen-address"_ctv); arguments.push_back(record.intent.selectorAddress);
    arguments.emplace_back("--listen-port"_ctv); arguments.push_back(listenerPort);
    arguments.emplace_back("--source-address"_ctv); arguments.push_back(record.intent.sourceWorkload.endpointIPv4);
    arguments.emplace_back("--source-port"_ctv); arguments.push_back(sourcePort);
    arguments.emplace_back("--target-address"_ctv); arguments.push_back(record.intent.targetWorkload.endpointIPv4);
    arguments.emplace_back("--target-port"_ctv); arguments.push_back(targetPort);
  }

  bool parseProductionPairProviderOutput(const MothershipProductionPairRecord& record,
                                         const String& output, bool removal,
                                         ProductionPairProviderState& state,
                                         String& failure)
  {
    state = {};
    simdjson::dom::parser parser; simdjson::dom::element document;
    if (output.size() > 64_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT)
    { failure.assign("production pair provider returned malformed JSON"_ctv); return false; }
    auto object = document.get_object(); bool success = false;
    if (object["success"].get(success) || !success)
    { failure.assign("production pair provider rejected the operation"_ctv); return false; }
    if (removal) return object.size() == 1;
    simdjson::dom::object encodedState;
    if (object.size() != 2 || object["state"].get(encodedState))
    { failure.assign("production pair provider omitted its exact state"_ctv); return false; }
    std::string_view operation, executorCluster, executorMachine, status, starttime;
    bool selected = false, sourceReachable = false, targetReachable = false;
    uint64_t sourceFlows = 0, targetFlows = 0, sourceConnections = 0, targetConnections = 0;
    uint64_t sourceRequestBytes = 0, sourceResponseBytes = 0;
    uint64_t targetRequestBytes = 0, targetResponseBytes = 0;
    uint64_t pid = 0, generation = 0, version = 0;
    simdjson::dom::array listener, sourceEndpoint, targetEndpoint;
    if (encodedState.size() != 22 || encodedState["version"].get(version) || version != 2 ||
        encodedState["operationID"].get(operation) || encodedState["listener"].get(listener) ||
        encodedState["executorClusterID"].get(executorCluster) ||
        encodedState["executorMachineID"].get(executorMachine) ||
        encodedState["source"].get(sourceEndpoint) || encodedState["target"].get(targetEndpoint) ||
        encodedState["selectedTarget"].get(selected) || encodedState["sourceFlows"].get(sourceFlows) ||
        encodedState["targetFlows"].get(targetFlows) ||
        encodedState["sourceConnections"].get(sourceConnections) ||
        encodedState["targetConnections"].get(targetConnections) ||
        encodedState["sourceRequestBytes"].get(sourceRequestBytes) ||
        encodedState["sourceResponseBytes"].get(sourceResponseBytes) ||
        encodedState["targetRequestBytes"].get(targetRequestBytes) ||
        encodedState["targetResponseBytes"].get(targetResponseBytes) ||
        encodedState["sourceReachable"].get(sourceReachable) ||
        encodedState["targetReachable"].get(targetReachable) || encodedState["pid"].get(pid) ||
        encodedState["starttime"].get(starttime) || encodedState["generation"].get(generation) ||
        encodedState["status"].get(status) || !sourceReachable || !targetReachable ||
        pid == 0 || generation == 0 || starttime.empty() || status != "running")
    { failure.assign("production pair provider state schema or process identity is invalid"_ctv); return false; }
    auto endpointMatches = [&](simdjson::dom::array endpoint, const String& address, uint16_t port) {
      if (endpoint.size() != 2) return false;
      auto iterator = endpoint.begin(); std::string_view observedAddress; uint64_t observedPort = 0;
      if ((*iterator).get(observedAddress)) return false; ++iterator;
      if ((*iterator).get(observedPort)) return false;
      return observedAddress.size() == address.size() &&
          (!observedAddress.size() || std::memcmp(observedAddress.data(), address.data(), address.size()) == 0) &&
          observedPort == port;
    };
    String expectedOperation = {}, expectedCluster = {}, expectedMachine = {};
    mothershipAssignProviderHex128(record.intent.operationUUID, expectedOperation);
    mothershipAssignProviderHex128(record.intent.sourceWorkload.clusterUUID, expectedCluster);
    mothershipAssignProviderHex128(record.intent.selectorMachineUUID, expectedMachine);
    auto textMatches = [](std::string_view observed, const String& expected) {
      return observed.size() == expected.size() &&
          (!observed.size() || std::memcmp(observed.data(), expected.data(), observed.size()) == 0);
    };
    if (operation.size() != expectedOperation.size() ||
        (operation.size() && std::memcmp(operation.data(), expectedOperation.data(), operation.size()) != 0) ||
        !textMatches(executorCluster, expectedCluster) || !textMatches(executorMachine, expectedMachine) ||
        !endpointMatches(listener, record.intent.selectorAddress, record.intent.selectorTCPPort) ||
        !endpointMatches(sourceEndpoint, record.intent.sourceWorkload.endpointIPv4,
                         record.intent.sourceWorkload.endpointTCPPort) ||
        !endpointMatches(targetEndpoint, record.intent.targetWorkload.endpointIPv4,
                         record.intent.targetWorkload.endpointTCPPort))
    { failure.assign("production pair provider state conflicts with the immutable pair identity"_ctv); return false; }
    state.selectedTarget = selected; state.sourceFlows = sourceFlows; state.targetFlows = targetFlows;
    state.sourceConnections = sourceConnections; state.targetConnections = targetConnections;
    state.sourceRequestBytes = sourceRequestBytes; state.sourceResponseBytes = sourceResponseBytes;
    state.targetRequestBytes = targetRequestBytes; state.targetResponseBytes = targetResponseBytes;
    state.sourceReachable = sourceReachable; state.targetReachable = targetReachable;
    state.generation = generation; state.pid = pid;
    state.starttime.setInvariant(starttime.data(), starttime.size());
    return true;
  }

  bool mothershipRunRemoteSealedPythonProvider(
      const MothershipProdigyCluster& cluster, const MothershipProdigyClusterMachine& executor,
      const char *providerName, const uint8_t *providerSource, uint64_t providerSourceBytes,
      const Vector<String>& arguments, int timeoutMilliseconds,
      String& output, String& failure)
  {
    output.clear();
    LIBSSH2_SESSION *session = nullptr; int fd = -1;
    if (!mothershipConnectSSHSession(executor, session, fd, &failure,
                                    &cluster.bootstrapSshKeyPackage,
                                    &cluster.bootstrapSshPrivateKeyPath)) return false;
    String stage = {};
    bool valid = prodigyRunBlockingSSHCommand(session, fd,
        "set -eu; d=$(mktemp -d /tmp/prodigy-g6-provider.XXXXXX); chmod 700 \"$d\"; printf '%s' \"$d\""_ctv,
        &stage, &failure, 30'000);
    constexpr const char *prefix = "/tmp/prodigy-g6-provider.";
    const size_t prefixBytes = std::strlen(prefix);
    if (valid && (stage.size() <= prefixBytes || std::memcmp(stage.data(), prefix, prefixBytes) != 0))
    { failure.assign("remote sealed provider staging directory is invalid"_ctv); valid = false; }
    for (size_t index = prefixBytes; valid && index < stage.size(); ++index)
      if (!std::isalnum(static_cast<unsigned char>(stage[index])))
      { failure.assign("remote sealed provider staging suffix is unsafe"_ctv); valid = false; }

    String remoteProvider = stage; remoteProvider.append("/provider.py"_ctv);
    int providerFD = -1;
    if (valid) valid = mothershipCreateSealedProviderFD(providerName, providerSource,
                                                        providerSourceBytes, providerFD, &failure);
    String providerPath = {};
    if (valid)
    {
      providerPath.snprintf<"/proc/self/fd/{itoa}"_ctv>(uint64_t(providerFD));
      valid = prodigyUploadLocalFileToSSHSession(session, fd, providerPath,
                                                 remoteProvider, 0700, &failure, 30'000);
    }
    if (providerFD >= 0) ::close(providerFD);

    String expectedSHA = {}, sourceBytes = {};
    sourceBytes.append(reinterpret_cast<const char *>(providerSource), providerSourceBytes);
    if (valid) valid = prodigyComputeSHA256Hex(sourceBytes, expectedSHA, &failure);
    if (valid)
    {
      // Open, validate, hash, and execute one immutable descriptor in a single
      // remote process.  A separate path-based sha256sum followed by python3
      // would leave a replacement window for the SSH account between proof
      // and execution.
      constexpr auto remoteExec =
          "import hashlib,os,stat,sys\n"
          "expected,directory,name,*arguments=sys.argv[1:]\n"
          "directory_fd=os.open(directory,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)\n"
          "directory_state=os.fstat(directory_fd)\n"
          "assert stat.S_ISDIR(directory_state.st_mode) and directory_state.st_uid==os.geteuid() and stat.S_IMODE(directory_state.st_mode)==0o700\n"
          "provider_fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW,dir_fd=directory_fd)\n"
          "provider_state=os.fstat(provider_fd)\n"
          "assert stat.S_ISREG(provider_state.st_mode) and provider_state.st_uid==os.geteuid() and provider_state.st_nlink==1 and stat.S_IMODE(provider_state.st_mode)==0o700\n"
          "digest=hashlib.sha256()\n"
          "while True:\n"
          " chunk=os.read(provider_fd,1048576)\n"
          " if not chunk: break\n"
          " digest.update(chunk)\n"
          "assert digest.hexdigest()==expected\n"
          "os.lseek(provider_fd,0,os.SEEK_SET)\n"
          "os.set_inheritable(provider_fd,True)\n"
          "os.close(directory_fd)\n"
          "os.execve('/usr/bin/python3',['/usr/bin/python3','/proc/self/fd/%d'%provider_fd,*arguments],os.environ)\n";
      String command = {}; command.assign("/usr/bin/python3 -c "_ctv);
      prodigyAppendShellSingleQuoted(command, String(remoteExec));
      command.append(' '); prodigyAppendShellSingleQuoted(command, expectedSHA);
      command.append(' '); prodigyAppendShellSingleQuoted(command, stage);
      command.append(" provider.py"_ctv);
      for (const auto& argument : arguments)
      { command.append(' '); prodigyAppendShellSingleQuoted(command, argument); }
      valid = prodigyRunBlockingSSHCommand(session, fd, command, &output, &failure,
                                           timeoutMilliseconds);
      if (!valid && failure.empty()) failure.assign("remote sealed provider validation or execution failed"_ctv);
    }
    if (!stage.empty())
    {
      String cleanup = {}; cleanup.assign("rm -rf -- "_ctv);
      prodigyAppendShellSingleQuoted(cleanup, stage);
      String ignored = {};
      (void)prodigyRunBlockingSSHCommand(session, fd, cleanup, nullptr, &ignored, 30'000);
    }
    mothershipCloseSSHSession(session, fd);
    return valid;
  }

  bool runProductionPairProvider(const MothershipProductionPairRecord& record,
                                 const MothershipProdigyCluster& source, const char *action,
                                 ProductionPairProviderState& state, String& output,
                                 String& providerEvidenceSHA256, String& failure)
  {
    MothershipProdigyClusterMachine executor = {};
    if (!resolvePhysicalFaultExecutor(source, record.intent.selectorMachineUUID,
                                      record.intent.selectorExecutorKind,
                                      record.intent.selectorLocalVMBoundaryUUID,
                                      record.intent.selectorCloudID,
                                      executor, failure)) return false;
    Vector<String> arguments = {};
    productionPairProviderArguments(record, action, arguments);
    // The selector is an externally reachable, operation-scoped ingress
    // owner.  Its sealed provider owns one exact tagged host-firewall
    // admission and removes only that rule during compensation or cleanup.
    arguments.emplace_back("--manage-firewall"_ctv);
    const bool removal = std::strcmp(action, "remove") == 0 ||
        std::strcmp(action, "abort-before-cutover") == 0;
    if (!mothershipRunRemoteSealedPythonProvider(source, executor,
          "mothership-production-pair-upload", mothershipProductionPairProviderSource,
          sizeof(mothershipProductionPairProviderSource), arguments, 30'000, output, failure) ||
        !parseProductionPairProviderOutput(record, output, removal, state, failure) ||
        !prodigyComputeSHA256Hex(output, providerEvidenceSHA256, &failure)) return false;
    return true;
  }

  bool parseProductionPairIngressWitness(const MothershipProductionPairRecord& record,
                                         const char *side, const String& output, String& failure)
  {
    simdjson::dom::parser parser; simdjson::dom::element document;
    if (output.size() > 8_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT)
    { failure.assign("production pair ingress witness returned malformed JSON"_ctv); return false; }
    auto object = document.get_object(); bool success = false; simdjson::dom::object witness;
    if (object.size() != 2 || object["success"].get(success) || !success || object["witness"].get(witness) ||
        witness.size() != 5)
    { failure.assign("production pair ingress witness rejected the observation"_ctv); return false; }
    uint64_t version = 0, port = 0; std::string_view operation, machine, observedSide; simdjson::dom::array selector;
    if (witness["version"].get(version) || version != 1 || witness["operationID"].get(operation) ||
        witness["witnessMachineID"].get(machine) || witness["side"].get(observedSide) ||
        witness["selector"].get(selector) || selector.size() != 2 || observedSide != side)
    { failure.assign("production pair ingress witness schema conflicts with its request"_ctv); return false; }
    auto it = selector.begin(); std::string_view address;
    if ((*it).get(address))
    { failure.assign("production pair ingress witness selector is malformed"_ctv); return false; }
    ++it;
    if ((*it).get(port))
    { failure.assign("production pair ingress witness selector is malformed"_ctv); return false; }
    String expectedOperation = {}, expectedMachine = {};
    mothershipAssignProviderHex128(record.intent.operationUUID, expectedOperation);
    mothershipAssignProviderHex128(record.intent.ingressWitnessMachineUUID, expectedMachine);
    auto same = [](std::string_view observed, const String& expected) {
      return observed.size() == expected.size() && (!observed.size() ||
          std::memcmp(observed.data(), expected.data(), observed.size()) == 0);
    };
    if (!same(operation, expectedOperation) || !same(machine, expectedMachine) ||
        address.size() != record.intent.selectorAddress.size() ||
        std::memcmp(address.data(), record.intent.selectorAddress.data(), address.size()) != 0 ||
        port != record.intent.selectorTCPPort)
    { failure.assign("production pair ingress witness does not bind the exact admitted selector"_ctv); return false; }
    return true;
  }

  bool productionPairIngressWitness(const MothershipProductionPairRecord& record,
                                    const MothershipProdigyCluster& source, const char *side,
                                    String& receiptSHA256, String& failure)
  {
    receiptSHA256.clear();
    if ((std::strcmp(side, "source") != 0 && std::strcmp(side, "target") != 0) ||
        record.intent.ingressWitnessMachineUUID == record.intent.selectorMachineUUID)
    { failure.assign("production pair ingress witness must be a distinct admitted topology machine"_ctv); return false; }
    ProductionPairProviderState before = {}, after = {};
    String beforeOutput = {}, afterOutput = {}, ignored = {}, output = {}, providerEvidence = {};
    if (!runProductionPairProvider(record, source, "query", before, beforeOutput, ignored, failure)) return false;
    const bool expectTarget = std::strcmp(side, "target") == 0;
    if (before.selectedTarget != expectTarget)
    { failure.assign("production pair ingress witness is on the wrong selector side"_ctv); return false; }
    MothershipProdigyClusterMachine executor = {};
    if (!resolvePhysicalFaultExecutor(source, record.intent.ingressWitnessMachineUUID,
                                      record.intent.ingressWitnessExecutorKind,
                                      record.intent.ingressWitnessLocalVMBoundaryUUID,
                                      record.intent.ingressWitnessCloudID, executor, failure)) return false;
    Vector<String> arguments = {};
    productionPairProviderArguments(record, expectTarget ? "witness-target" : "witness-source", arguments);
    if (!mothershipRunRemoteSealedPythonProvider(source, executor, "mothership-production-pair-ingress-witness",
          mothershipProductionPairProviderSource, sizeof(mothershipProductionPairProviderSource), arguments,
          30'000, output, failure) || !parseProductionPairIngressWitness(record, side, output, failure) ||
        !prodigyComputeSHA256Hex(output, providerEvidence, &failure) ||
        !runProductionPairProvider(record, source, "query", after, afterOutput, ignored, failure)) return false;
    const bool progressed = expectTarget ?
        (after.selectedTarget && after.targetConnections > before.targetConnections &&
         after.targetRequestBytes > before.targetRequestBytes && after.targetResponseBytes > before.targetResponseBytes) :
        (!after.selectedTarget && after.sourceConnections > before.sourceConnections &&
         after.sourceRequestBytes > before.sourceRequestBytes && after.sourceResponseBytes > before.sourceResponseBytes);
    if (!progressed)
    { failure.assign("distinct ingress witness did not traverse the expected selector side"_ctv); return false; }
    Vector<String> evidence = {};
    evidence.emplace_back("mothership-production-pair-ingress-witness-receipt-v1"_ctv);
    if (expectTarget) evidence.emplace_back("target-after-selection"_ctv);
    else evidence.emplace_back("source-before-selection"_ctv);
    evidence.push_back(providerEvidence);
    String encoded = {}; auto immutableIntent = record.intent;
    BitseryEngine::serialize(encoded, immutableIntent); evidence.push_back(encoded);
    String beforeCounters = {}, afterCounters = {};
    beforeCounters.snprintf<"{}:{}:{}:{}:{}"_ctv>(before.sourceConnections, before.targetConnections,
        before.sourceRequestBytes, before.targetRequestBytes, before.generation);
    afterCounters.snprintf<"{}:{}:{}:{}:{}"_ctv>(after.sourceConnections, after.targetConnections,
        after.sourceRequestBytes, after.targetRequestBytes, after.generation);
    evidence.push_back(beforeCounters); evidence.push_back(afterCounters);
    encoded.clear(); BitseryEngine::serialize(encoded, evidence);
    return prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
  }

  bool productionPairSelectorPhaseReceipt(const MothershipProductionPairRecord& record,
                                          MothershipProductionPairPhase phase,
                                          const ProductionPairProviderState& state,
                                          String& receiptSHA256, String& failure)
  {
    receiptSHA256.clear();
    if ((phase != MothershipProductionPairPhase::transitApplied &&
         phase != MothershipProductionPairPhase::targetSelected &&
         phase != MothershipProductionPairPhase::sourceDrained) ||
        state.pid == 0 || state.starttime.empty() || !state.sourceReachable || !state.targetReachable ||
        (phase == MothershipProductionPairPhase::transitApplied &&
         (state.selectedTarget || state.targetFlows != 0 || state.targetConnections != 0)) ||
        (phase == MothershipProductionPairPhase::targetSelected &&
         (!mothershipProductionPairReceiptValid(record.sourceIngressWitnessReceiptSHA256) ||
          !state.selectedTarget || state.sourceFlows == 0 || state.sourceConnections == 0 ||
          state.sourceRequestBytes == 0 || state.sourceResponseBytes == 0)) ||
        (phase == MothershipProductionPairPhase::sourceDrained &&
         (!mothershipProductionPairReceiptValid(record.sourceIngressWitnessReceiptSHA256) ||
          !mothershipProductionPairReceiptValid(record.targetIngressWitnessReceiptSHA256) ||
          !state.selectedTarget || state.sourceFlows != 0 || state.sourceConnections == 0 ||
          state.targetConnections == 0 || state.sourceRequestBytes == 0 ||
          state.sourceResponseBytes == 0 || state.targetRequestBytes == 0 ||
          state.targetResponseBytes == 0)))
    {
      failure.assign("selector state does not prove the requested Mothership production-pair phase"_ctv);
      return false;
    }
    String intentBytes = {}, intentSHA256 = {}, pid = {}, phaseText = {};
    auto intent = record.intent; BitseryEngine::serialize(intentBytes, intent);
    if (!prodigyComputeSHA256Hex(intentBytes, intentSHA256, &failure)) return false;
    pid.assignItoa(state.pid); phaseText.assignItoa(uint8_t(phase));
    Vector<String> evidence = {};
    evidence.emplace_back("mothership-production-pair-selector-receipt-v2"_ctv);
    evidence.push_back(phaseText); evidence.push_back(intentSHA256);
    evidence.push_back(record.targetAdmissionReceiptSHA256);
    evidence.emplace_back(phase >= MothershipProductionPairPhase::targetSelected ?
                          record.sourceIngressWitnessReceiptSHA256 : String());
    evidence.emplace_back(phase >= MothershipProductionPairPhase::targetSelected ?
                          record.transitApplyReceiptSHA256 : String());
    evidence.emplace_back(phase >= MothershipProductionPairPhase::sourceDrained ?
                          record.targetIngressWitnessReceiptSHA256 : String());
    evidence.emplace_back(phase >= MothershipProductionPairPhase::sourceDrained ?
                          record.targetSelectionReceiptSHA256 : String());
    evidence.push_back(pid); evidence.push_back(state.starttime);
    if (state.selectedTarget) evidence.emplace_back("target"_ctv);
    else evidence.emplace_back("source"_ctv);
    if (phase == MothershipProductionPairPhase::targetSelected)
    { evidence.emplace_back("source-witnessed"_ctv); evidence.emplace_back("source-active"_ctv); }
    else if (phase == MothershipProductionPairPhase::sourceDrained)
    { evidence.emplace_back("source-witnessed"_ctv); evidence.emplace_back("target-witnessed"_ctv);
      evidence.emplace_back("source-zero"_ctv); }
    else evidence.emplace_back("transit-ready"_ctv);
    evidence.emplace_back("source-reachable"_ctv); evidence.emplace_back("target-reachable"_ctv);
    String encoded = {}; BitseryEngine::serialize(encoded, evidence);
    return prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
  }

  bool productionPairSelectorPhaseMatches(const MothershipProductionPairRecord& record,
                                          MothershipProductionPairPhase phase,
                                          const ProductionPairProviderState& state,
                                          String& failure)
  {
    String observed = {};
    if (!productionPairSelectorPhaseReceipt(record, phase, state, observed, failure)) return false;
    const String *expected = phase == MothershipProductionPairPhase::transitApplied ?
        &record.transitApplyReceiptSHA256 :
        (phase == MothershipProductionPairPhase::targetSelected ?
         &record.targetSelectionReceiptSHA256 : &record.sourceDrainReceiptSHA256);
    if (observed != *expected)
    {
      failure.assign("selector process identity or Mothership phase evidence changed"_ctv);
      return false;
    }
    return true;
  }

  bool productionPhysicalBoundaryAdmissionReceipt(
      const MothershipProductionPairRecord& record,
      const MothershipPhysicalServiceTransitBoundary& boundary,
      const ClusterStatusReport& sourceStatus, const ClusterStatusReport& targetStatus,
      const String& selectorTransitReceiptSHA256,
      String& receiptSHA256, String& failure)
  {
    MothershipPhysicalFaultMachineObservation sourceObservation = {}, targetObservation = {};
    if (!physicalFaultMachineObservation(sourceStatus, boundary.sourceClusterUUID,
                                         boundary.sourceMachineUUID, sourceObservation, failure) ||
        !physicalFaultMachineObservation(targetStatus, boundary.targetClusterUUID,
                                         boundary.targetMachineUUID, targetObservation, failure)) return false;
    String sourceObservationBytes = {}, targetObservationBytes = {};
    BitseryEngine::serialize(sourceObservationBytes, sourceObservation);
    BitseryEngine::serialize(targetObservationBytes, targetObservation);
    String operation = {}, route = {}, sourceMachine = {}, targetMachine = {};
    String sourceBoundary = {}, targetBoundary = {}, mtu = {};
    operation.assignItoh(record.intent.operationUUID); route.assignItoh(boundary.routeUUID);
    sourceMachine.assignItoh(boundary.sourceMachineUUID); targetMachine.assignItoh(boundary.targetMachineUUID);
    sourceBoundary.assignItoh(boundary.sourceLocalVMBoundaryUUID);
    targetBoundary.assignItoh(boundary.targetLocalVMBoundaryUUID); mtu.assignItoa(boundary.pathMTU);
    Vector<String> evidence = {};
    evidence.emplace_back("mothership-physical-service-transit-admission-v3"_ctv);
    evidence.push_back(operation); evidence.push_back(route);
    evidence.push_back(sourceMachine); evidence.push_back(targetMachine);
    evidence.emplace_back(); evidence.back().assignItoa(uint8_t(boundary.sourceExecutorKind));
    evidence.emplace_back(); evidence.back().assignItoa(uint8_t(boundary.targetExecutorKind));
    evidence.push_back(sourceBoundary); evidence.push_back(targetBoundary);
    evidence.push_back(boundary.sourceCloudID); evidence.push_back(boundary.targetCloudID);
    evidence.push_back(boundary.sourceAddress); evidence.push_back(boundary.targetAddress);
    evidence.push_back(mtu); evidence.push_back(boundary.routeAuthorizationSHA256);
    evidence.push_back(sourceObservationBytes); evidence.push_back(targetObservationBytes);
    evidence.push_back(selectorTransitReceiptSHA256);
    String encoded = {}; BitseryEngine::serialize(encoded, evidence);
    return prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
  }

  bool productionPairPhysicalBoundaryReady(
      const MothershipProductionPairRecord& record,
      const MothershipProdigyCluster& source, const MothershipProdigyCluster& target,
      const MothershipPhysicalServiceTransitBoundary& boundary,
      String& failure)
  {
    String authorization = {};
    if (!mothershipPhysicalServiceTransitBoundaryValid(boundary, &failure) || boundary.closed ||
        boundary.boundaryUUID != record.intent.physicalBoundaryUUID ||
        boundary.pairOperationUUID != record.intent.operationUUID ||
        boundary.routeUUID != record.intent.route.routeUUID ||
        boundary.routeGeneration != record.intent.route.generation ||
        boundary.sourceClusterUUID != record.intent.route.sourceClusterUUID ||
        boundary.targetClusterUUID != record.intent.route.destinationClusterUUID ||
        boundary.sourceMachineUUID != record.intent.selectorMachineUUID ||
        boundary.targetMachineUUID != record.intent.targetWorkload.endpointMachineUUID ||
        boundary.sourceExecutorKind != record.intent.selectorExecutorKind ||
        boundary.sourceLocalVMBoundaryUUID != record.intent.selectorLocalVMBoundaryUUID ||
        boundary.sourceCloudID != record.intent.selectorCloudID ||
        boundary.sourceAddress != record.intent.selectorAddress ||
        boundary.targetAddress != record.intent.targetWorkload.endpointIPv4 ||
        boundary.sourceTCPPort != record.intent.selectorTCPPort ||
        boundary.targetTCPPort != record.intent.targetWorkload.endpointTCPPort ||
        boundary.pathMTU != record.intent.route.pathMTU ||
        !cousinRouteAuthorizationDigest(record.intent.route, authorization) ||
        authorization != boundary.routeAuthorizationSHA256)
    {
      if (failure.empty())
        failure.assign("production pair physical boundary conflicts with its immutable route or selector owner"_ctv);
      return false;
    }

    MothershipPhysicalFaultExecutorKind sourceKind = MothershipPhysicalFaultExecutorKind::localVM;
    MothershipPhysicalFaultExecutorKind targetKind = MothershipPhysicalFaultExecutorKind::localVM;
    uint128_t sourceVMBoundary = 0, targetVMBoundary = 0;
    String sourceCloudID = {}, targetCloudID = {};
    if (!describePhysicalFaultExecutorBoundary(source, boundary.sourceMachineUUID, sourceKind,
                                               sourceVMBoundary, sourceCloudID, failure) ||
        !describePhysicalFaultExecutorBoundary(target, boundary.targetMachineUUID, targetKind,
                                               targetVMBoundary, targetCloudID, failure) ||
        sourceKind != boundary.sourceExecutorKind || targetKind != boundary.targetExecutorKind ||
        sourceVMBoundary != boundary.sourceLocalVMBoundaryUUID ||
        targetVMBoundary != boundary.targetLocalVMBoundaryUUID ||
        sourceCloudID != boundary.sourceCloudID || targetCloudID != boundary.targetCloudID)
    {
      if (failure.empty())
        failure.assign("production pair physical executors no longer match the admitted boundary"_ctv);
      return false;
    }
    return true;
  }

  bool readManagedClusterStatus(const MothershipProdigyCluster& cluster,
                                ClusterStatusReport& report, String& failure)
  {
    report = {};
    socket.close();
    String targetName = cluster.name;
    if (!configureControlTarget(targetName.c_str(), &failure) || !socket.ensureConnected()) return false;
    Message::construct(socket.wBuffer, MothershipTopic::pullClusterReport);
    if (!socket.send()) { failure = socket.ioFailureDetail(); socket.close(); return false; }
    Message *response = socket.recvExpectedTopic(MothershipTopic::pullClusterReport, 1024);
    bool valid = response != nullptr;
    if (valid)
    {
      uint8_t *args = response->args;
      String encoded = {};
      valid = ProdigyIngressValidation::extractVariableStringView(args, response->terminal(), encoded) &&
              args == response->terminal() && BitseryEngine::deserializeSafe(encoded, report);
    }
    socket.close();
    if (!valid) failure.assign("current whole destination cluster observation is unavailable"_ctv);
    return valid;
  }

  bool physicalFaultMachineObservation(const ClusterStatusReport& report, uint128_t clusterUUID,
                                       uint128_t machineUUID,
                                       MothershipPhysicalFaultMachineObservation& observation,
                                       String& failure)
  {
    observation = {};
    if (!report.hasTopology || report.topology.version == 0 || machineUUID == 0)
    {
      failure.assign("physical fault requires a current versioned cluster topology"_ctv);
      return false;
    }
    String machineIdentity = {}; machineIdentity.assignItoh(machineUUID);
    uint32_t topologyMatches = 0, reportMatches = 0;
    const MachineStatusReport *status = nullptr;
    for (const auto& machine : report.topology.machines)
      if (machine.uuid == machineUUID) ++topologyMatches;
    for (const auto& candidate : report.machineReports)
      if (candidate.machineUUID == machineIdentity) { ++reportMatches; status = &candidate; }
    if (topologyMatches != 1 || reportMatches != 1 || status == nullptr ||
        status->state != "healthy"_ctv || !status->isBrain || !status->controlPlaneReachable ||
        !status->runtimeReady || status->bootTimeMs <= 0 || status->hardwareFailure ||
        status->decommissioning || status->rebooting || status->updatingOS)
    {
      failure.assign("physical fault machine is not one exact healthy commissioned Brain"_ctv);
      return false;
    }
    Vector<String> identity = {};
    identity.emplace_back(); identity.back().assignItoh(clusterUUID);
    identity.push_back(machineIdentity);
    identity.emplace_back(); identity.back().assignItoa(report.topology.version);
    identity.emplace_back(); identity.back().assignItoa(status->bootTimeMs);
    identity.push_back(status->state); identity.push_back(status->runningProdigyVersion);
    if (status->currentMaster) identity.emplace_back("master"_ctv);
    else identity.emplace_back("follower"_ctv);
    String encoded = {}; BitseryEngine::serialize(encoded, identity);
    observation.clusterUUID = clusterUUID; observation.machineUUID = machineUUID;
    observation.topologyVersion = report.topology.version;
    if (!prodigyComputeSHA256Hex(encoded, observation.stateSHA256, &failure)) return false;
    return mothershipPhysicalFaultMachineObservationValid(observation);
  }

  bool physicalFaultUnreadyMachineObservation(
      const ClusterStatusReport& report, uint128_t clusterUUID, uint128_t machineUUID,
      MothershipPhysicalFaultMachineObservation& observation, String& failure)
  {
    observation = {};
    if (!report.hasTopology || report.topology.version == 0 || machineUUID == 0)
    { failure.assign("unready local VM recovery requires a current versioned cluster topology"_ctv); return false; }
    String machineIdentity = {}; machineIdentity.assignItoh(machineUUID);
    uint32_t topologyMatches = 0, reportMatches = 0;
    const MachineStatusReport *status = nullptr;
    for (const auto& machine : report.topology.machines)
      if (machine.uuid == machineUUID && machine.isBrain && machine.kind == MachineConfig::MachineKind::vm &&
          machine.backing == ClusterMachineBacking::owned && machine.lifetime == MachineLifetime::owned)
        ++topologyMatches;
    for (const auto& candidate : report.machineReports)
      if (candidate.machineUUID == machineIdentity) { ++reportMatches; status = &candidate; }
    if (topologyMatches != 1 || reportMatches != 1 || status == nullptr || !status->isBrain ||
        status->currentMaster || status->controlPlaneReachable || status->runtimeReady ||
        status->bootTimeMs <= 0 || status->hardwareFailure || status->decommissioning ||
        status->rebooting || status->updatingOS || status->updateStage != "idle"_ctv)
    { failure.assign("unready local VM recovery requires one exact commissioned non-master Brain missing readiness"_ctv); return false; }
    Vector<String> identity = {};
    identity.emplace_back("mothership-unready-local-vm-recovery-v1"_ctv);
    identity.emplace_back(); identity.back().assignItoh(clusterUUID);
    identity.push_back(machineIdentity);
    identity.emplace_back(); identity.back().assignItoa(report.topology.version);
    identity.emplace_back(); identity.back().assignItoa(status->bootTimeMs);
    identity.push_back(status->state);
    identity.push_back(status->runningProdigyVersion);
    identity.push_back(status->approvedBundleSHA256);
    String encoded = {}; BitseryEngine::serialize(encoded, identity);
    observation.clusterUUID = clusterUUID; observation.machineUUID = machineUUID;
    observation.topologyVersion = report.topology.version;
    if (!prodigyComputeSHA256Hex(encoded, observation.stateSHA256, &failure)) return false;
    return mothershipPhysicalFaultMachineObservationValid(observation);
  }

  static bool topologyMachineForAddress(const ClusterStatusReport& report, const String& address,
                                        uint128_t& machineUUID)
  {
    machineUUID = 0;
    uint32_t matches = 0;
    for (const auto& machine : report.topology.machines)
    {
      for (const auto& candidate : machine.addresses.privateAddresses)
        if (candidate.address == address) { ++matches; machineUUID = machine.uuid; }
      for (const auto& candidate : machine.addresses.publicAddresses)
        if (candidate.address == address) { ++matches; machineUUID = machine.uuid; }
    }
    if (matches != 1 || !mothershipPhysicalFaultNumericAddressValid(address))
    {
      machineUUID = 0;
      return false;
    }
    return true;
  }

  static bool topologyMachineOwnsAddress(const ClusterStatusReport& report, uint128_t machineUUID,
                                         const String& address)
  {
    uint128_t owner = 0;
    return topologyMachineForAddress(report, address, owner) && owner == machineUUID;
  }

  // The registering caller never selects executable bytes.  This primitive
  // always stages the launcher compiled into Mothership, then makes the remote
  // Python process hash and execute the same opened descriptor.  Callers which
  // perform ordinary actions must use the digest-pinned wrapper below.
  bool runCurrentLocalVMBoundarySealedLauncher(const MothershipLocalVMBoundaryDescriptor& descriptor,
                                               const Vector<String>& arguments, int timeoutMilliseconds,
                                               String& output, String& failure)
  {
    output.clear();
    String expectedSHA = {}, sourceBytes = {};
    sourceBytes.append(reinterpret_cast<const char *>(mothershipLocalVMBoundarySource),
                       sizeof(mothershipLocalVMBoundarySource));
    if (!prodigyComputeSHA256Hex(sourceBytes, expectedSHA, &failure)) return false;

    MothershipProdigyClusterMachine host = {};
    host.ssh.address = descriptor.hostAddress; host.ssh.port = descriptor.hostPort;
    host.ssh.user = descriptor.hostUser; host.ssh.privateKeyPath = descriptor.hostPrivateKeyPath;
    host.ssh.hostPublicKeyOpenSSH = descriptor.hostPublicKeyOpenSSH;
    LIBSSH2_SESSION *session = nullptr; int fd = -1;
    if (!mothershipConnectSSHSession(host, session, fd, &failure)) return false;
    String stage = {};
    bool valid = prodigyRunBlockingSSHCommand(session, fd,
        "set -eu; d=$(mktemp -d /tmp/prodigy-g6-local-vm.XXXXXX); chmod 700 \"$d\"; printf '%s' \"$d\""_ctv,
        &stage, &failure, 30'000);
    constexpr const char *prefix = "/tmp/prodigy-g6-local-vm.";
    const size_t prefixBytes = std::strlen(prefix);
    if (valid && (stage.size() <= prefixBytes || std::memcmp(stage.data(), prefix, prefixBytes) != 0))
    { failure.assign("local VM sealed launcher staging directory is invalid"_ctv); valid = false; }
    for (size_t index = prefixBytes; valid && index < stage.size(); ++index)
      if (!std::isalnum(static_cast<unsigned char>(stage[index])))
      { failure.assign("local VM sealed launcher staging suffix is unsafe"_ctv); valid = false; }

    String launcher = stage; launcher.append("/launcher.py"_ctv);
    int launcherFD = -1;
    if (valid) valid = mothershipCreateSealedProviderFD("mothership-local-vm-boundary",
        mothershipLocalVMBoundarySource, sizeof(mothershipLocalVMBoundarySource), launcherFD, &failure);
    String launcherPath = {};
    if (valid)
    {
      launcherPath.snprintf<"/proc/self/fd/{itoa}"_ctv>(uint64_t(launcherFD));
      valid = prodigyUploadLocalFileToSSHSession(session, fd, launcherPath, launcher, 0700, &failure, 30'000);
    }
    if (launcherFD >= 0) ::close(launcherFD);
    if (valid)
    {
      constexpr auto remoteExec =
          "import hashlib,os,stat,sys\n"
          "expected,directory,name,*arguments=sys.argv[1:]\n"
          "directory_fd=os.open(directory,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)\n"
          "directory_state=os.fstat(directory_fd)\n"
          "assert stat.S_ISDIR(directory_state.st_mode) and directory_state.st_uid==os.geteuid() and stat.S_IMODE(directory_state.st_mode)==0o700\n"
          "launcher_fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW,dir_fd=directory_fd)\n"
          "launcher_state=os.fstat(launcher_fd)\n"
          "assert stat.S_ISREG(launcher_state.st_mode) and launcher_state.st_uid==os.geteuid() and launcher_state.st_nlink==1 and stat.S_IMODE(launcher_state.st_mode)==0o700\n"
          "digest=hashlib.sha256()\n"
          "while True:\n"
          " chunk=os.read(launcher_fd,1048576)\n"
          " if not chunk: break\n"
          " digest.update(chunk)\n"
          "assert digest.hexdigest()==expected\n"
          "os.lseek(launcher_fd,0,os.SEEK_SET)\n"
          "os.set_inheritable(launcher_fd,True)\n"
          "os.close(directory_fd)\n"
          "os.execve('/usr/bin/python3',['/usr/bin/python3','/proc/self/fd/%d'%launcher_fd,*arguments],os.environ)\n";
      String command = {}; command.assign("/usr/bin/python3 -c "_ctv);
      prodigyAppendShellSingleQuoted(command, String(remoteExec));
      command.append(' '); prodigyAppendShellSingleQuoted(command, expectedSHA);
      command.append(' '); prodigyAppendShellSingleQuoted(command, stage);
      command.append(" launcher.py"_ctv);
      for (const auto& argument : arguments)
      { command.append(' '); prodigyAppendShellSingleQuoted(command, argument); }
      valid = prodigyRunBlockingSSHCommand(session, fd, command, &output, &failure, timeoutMilliseconds);
      if (!valid && failure.empty()) failure.assign("local VM sealed launcher validation or execution failed"_ctv);
    }
    if (!stage.empty())
    {
      String cleanup = {}; cleanup.assign("rm -rf -- "_ctv); prodigyAppendShellSingleQuoted(cleanup, stage);
      String ignored = {}; (void)prodigyRunBlockingSSHCommand(session, fd, cleanup, nullptr, &ignored, 30'000);
    }
    mothershipCloseSSHSession(session, fd);
    return valid;
  }

  bool runLocalVMBoundarySealedLauncher(const MothershipLocalVMBoundaryDescriptor& descriptor,
                                        const Vector<String>& arguments, int timeoutMilliseconds,
                                        String& output, String& failure)
  {
    String expectedSHA = {}, sourceBytes = {};
    sourceBytes.append(reinterpret_cast<const char *>(mothershipLocalVMBoundarySource),
                       sizeof(mothershipLocalVMBoundarySource));
    if (!prodigyComputeSHA256Hex(sourceBytes, expectedSHA, &failure) ||
        expectedSHA != descriptor.executorSHA256)
    { if (failure.empty()) failure.assign("local VM boundary launcher digest is not Mothership-owned"_ctv); return false; }
    return runCurrentLocalVMBoundarySealedLauncher(
        descriptor, arguments, timeoutMilliseconds, output, failure);
  }

  bool inspectLocalVMBoundaryExecutor(const MothershipLocalVMBoundaryDescriptor& descriptor,
                                      const char *action, bool currentExecutorUpgrade,
                                      String& immutableStateSHA256, String& failure,
                                      uint64_t *observedPID = nullptr,
                                      String *observedStarttime = nullptr,
                                      uint128_t expectedOperationUUID = 0,
                                      uint128_t expectedCohortUUID = 0)
  {
    immutableStateSHA256.clear();
    if ((expectedOperationUUID == 0) != (expectedCohortUUID == 0))
    { failure.assign("local VM executor reconciliation requires one exact ownership pair"_ctv); return false; }
    Vector<String> arguments = {};
    arguments.emplace_back(action);
    arguments.emplace_back("--state"_ctv); arguments.push_back(descriptor.statePath);
    arguments.emplace_back("--task-id"_ctv); arguments.push_back(descriptor.taskID);
    if (expectedOperationUUID != 0)
    {
      String operation = {}, cohort = {};
      mothershipAssignProviderHex128(expectedOperationUUID, operation);
      mothershipAssignProviderHex128(expectedCohortUUID, cohort);
      arguments.emplace_back("--operation-id"_ctv); arguments.push_back(std::move(operation));
      arguments.emplace_back("--cohort-id"_ctv); arguments.push_back(std::move(cohort));
    }
    String output = {};
    bool valid = currentExecutorUpgrade ?
        runCurrentLocalVMBoundarySealedLauncher(descriptor, arguments, 30'000, output, failure) :
        runLocalVMBoundarySealedLauncher(descriptor, arguments, 30'000, output, failure);
    if (!valid) return false;

    simdjson::dom::parser parser; simdjson::dom::element document;
    if (output.size() > 64_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT)
    { failure.assign("local VM executor query returned malformed state"_ctv); return false; }
    auto object = document.get_object();
    if (object.size() < 10 || object.size() > 13)
    { failure.assign("local VM executor query returned an unsupported state schema"_ctv); return false; }
    for (auto field : object)
    {
      String key = {}; key.setInvariant(field.key.data(), field.key.size());
      if (key != "taskID"_ctv && key != "guestUUID"_ctv && key != "machineID"_ctv &&
          key != "overlay"_ctv && key != "ovmfVars"_ctv && key != "qmpSocket"_ctv &&
          key != "qemuStarttime"_ctv && key != "qemuPID"_ctv && key != "qemuCommand"_ctv &&
          key != "network"_ctv && key != "boundaryVerification"_ctv &&
          key != "lastColdReboot"_ctv && key != "completedColdReboots"_ctv)
      { failure.assign("local VM executor query contains an unknown state field"_ctv); return false; }
    }
    std::string_view taskID, guestUUID, machineID, overlay, ovmfVars, qmpSocket, starttime;
    uint64_t pid = 0;
    simdjson::dom::array qemuCommand;
    const auto stringViewMatches = [](std::string_view left, const String& right) {
      return left.size() == right.size() &&
          (left.empty() || std::memcmp(left.data(), right.data(), left.size()) == 0);
    };
    if (object["taskID"].get(taskID) || object["guestUUID"].get(guestUUID) ||
        object["machineID"].get(machineID) || object["overlay"].get(overlay) ||
        object["ovmfVars"].get(ovmfVars) || object["qmpSocket"].get(qmpSocket) ||
        object["qemuStarttime"].get(starttime) || object["qemuPID"].get(pid) ||
        object["qemuCommand"].get(qemuCommand) || !stringViewMatches(taskID, descriptor.taskID) || pid == 0 ||
        !mothershipLocalVMGuestUUIDMatches(descriptor.machineUUID, guestUUID))
    { failure.assign("local VM executor state conflicts with its registered task or guest identity"_ctv); return false; }
    auto safeText = [](std::string_view value) {
      if (value.empty() || value.size() > 4096) return false;
      for (char byte : value) if (byte == '\0' || byte == '\n' || byte == '\r') return false;
      return true;
    };
    if (machineID.size() != 32 || !safeText(overlay) || !safeText(ovmfVars) || !safeText(qmpSocket) ||
        starttime.empty() || !std::all_of(starttime.begin(), starttime.end(), [](char value) { return value >= '0' && value <= '9'; }))
    { failure.assign("local VM executor state contains an invalid machine, path, or process identity"_ctv); return false; }
    if (observedPID != nullptr) *observedPID = pid;
    if (observedStarttime != nullptr) observedStarttime->assign(starttime.data(), starttime.size());
    Vector<String> identity = {};
    auto add = [&](std::string_view value) { identity.emplace_back(); identity.back().setInvariant(value.data(), value.size()); };
    add(taskID); add(guestUUID); add(machineID); add(overlay); add(ovmfVars); add(qmpSocket);
    bool hasKVM = false, hasUUID = false, hasOverlay = false, hasVars = false, hasQMP = false;
    bool hasNoDefaults = false, forbiddenNetworkOption = false;
    Vector<String> netdevs = {}, devices = {};
    uint32_t argumentCount = 0;
    for (auto argumentElement : qemuCommand)
    {
      std::string_view argument;
      if (argumentElement.get(argument) || !safeText(argument) || ++argumentCount > 128)
      { failure.assign("local VM executor QEMU command is malformed"_ctv); return false; }
      add(argument);
    }
    for (uint32_t index = 0; index < argumentCount; ++index)
    {
      const String& argument = identity[6 + index];
      if (argument == "kvm"_ctv && index > 0 && identity[6 + index - 1] == "-accel"_ctv) hasKVM = true;
      if (argument == "-nodefaults"_ctv) hasNoDefaults = true;
      const bool netEquals = argument.size() >= 5 && std::memcmp(argument.data(), "-net=", 5) == 0;
      const bool nicEquals = argument.size() >= 5 && std::memcmp(argument.data(), "-nic=", 5) == 0;
      if (argument == "-net"_ctv || argument == "-nic"_ctv || netEquals || nicEquals)
        forbiddenNetworkOption = true;
      if (stringViewMatches(guestUUID, argument) && index > 0 && identity[6 + index - 1] == "-uuid"_ctv) hasUUID = true;
      if (argument.size() >= overlay.size() && std::search(argument.begin(), argument.end(), overlay.begin(), overlay.end()) != argument.end()) hasOverlay = true;
      if (argument.size() >= ovmfVars.size() && std::search(argument.begin(), argument.end(), ovmfVars.begin(), ovmfVars.end()) != argument.end()) hasVars = true;
      if (argument.size() >= qmpSocket.size() && std::search(argument.begin(), argument.end(), qmpSocket.begin(), qmpSocket.end()) != argument.end()) hasQMP = true;
      if (index > 0 && identity[6 + index - 1] == "-netdev"_ctv) netdevs.push_back(argument);
      if (index > 0 && identity[6 + index - 1] == "-device"_ctv) devices.push_back(argument);
    }
    auto starts = [](const String& value, const char *prefix) {
      const size_t count = std::strlen(prefix);
      return value.size() >= count && std::memcmp(value.data(), prefix, count) == 0;
    };
    auto exactDecimalPort = [&](const String& value, const char *prefix, const char *suffix) {
      const size_t prefixBytes = std::strlen(prefix), suffixBytes = std::strlen(suffix);
      if (!starts(value, prefix) || value.size() <= prefixBytes + suffixBytes ||
          std::memcmp(value.data() + value.size() - suffixBytes, suffix, suffixBytes) != 0) return false;
      uint64_t parsed = 0;
      for (size_t index = prefixBytes; index < value.size() - suffixBytes; ++index)
      {
        const char byte = value[index];
        if (byte < '0' || byte > '9') return false;
        parsed = parsed * 10 + uint64_t(byte - '0');
        if (parsed > 65535) return false;
      }
      return parsed >= 1024;
    };
    auto exactMulticastNetdev = [&](const String& value) {
      constexpr const char *prefix = "socket,id=clusterlan,mcast=";
      constexpr const char *separator = ",localaddr=";
      if (!starts(value, prefix)) return false;
      const auto separatorAt = std::search(value.begin() + std::strlen(prefix), value.end(),
                                           separator, separator + std::strlen(separator));
      if (separatorAt == value.end()) return false;
      String multicast = {}, local = {};
      multicast.append(value.data() + std::strlen(prefix),
                       size_t(separatorAt - value.begin() - std::strlen(prefix)));
      local.append(separatorAt + std::strlen(separator),
                   size_t(value.end() - separatorAt - std::strlen(separator)));
      const auto colon = std::find(multicast.begin(), multicast.end(), ':');
      if (colon == multicast.end() || std::find(colon + 1, multicast.end(), ':') != multicast.end()) return false;
      String multicastAddress = {}, multicastPort = {};
      multicastAddress.append(multicast.data(), size_t(colon - multicast.begin()));
      multicastPort.append(colon + 1, size_t(multicast.end() - colon - 1));
      struct in_addr multicastParsed = {}, localParsed = {};
      if (::inet_pton(AF_INET, multicastAddress.c_str(), &multicastParsed) != 1 ||
          ::inet_pton(AF_INET, local.c_str(), &localParsed) != 1) return false;
      const uint8_t multicastFirst = uint8_t(ntohl(multicastParsed.s_addr) >> 24);
      const uint32_t localHost = ntohl(localParsed.s_addr);
      const uint8_t localFirst = uint8_t(localHost >> 24);
      uint64_t port = 0;
      if (multicastPort.empty()) return false;
      for (char byte : multicastPort)
      {
        if (byte < '0' || byte > '9') return false;
        port = port * 10 + uint64_t(byte - '0');
        if (port > 65535) return false;
      }
      return multicastFirst >= 224 && multicastFirst <= 239 && port >= 1024 &&
          localHost != INADDR_ANY && localHost != 0xffffffffu && localFirst != 127 && localFirst != 0 &&
          !(localFirst == 169 && uint8_t(localHost >> 16) == 254) &&
          !(localFirst >= 224 && localFirst <= 239);
    };
    auto exactSafeUnicastEndpoint = [&](const String& value) {
      const auto colon = std::find(value.begin(), value.end(), ':');
      if (colon == value.end() || std::find(colon + 1, value.end(), ':') != value.end()) return false;
      String address = {}, portText = {};
      address.append(value.data(), size_t(colon - value.begin()));
      portText.append(colon + 1, size_t(value.end() - colon - 1));
      struct in_addr parsed = {};
      if (::inet_pton(AF_INET, address.c_str(), &parsed) != 1) return false;
      char canonical[INET_ADDRSTRLEN] = {};
      if (::inet_ntop(AF_INET, &parsed, canonical, sizeof(canonical)) == nullptr || address != String(canonical)) return false;
      uint64_t port = 0;
      if (portText.empty()) return false;
      for (char byte : portText)
      {
        if (byte < '0' || byte > '9') return false;
        port = port * 10 + uint64_t(byte - '0');
        if (port > 65535) return false;
      }
      const uint32_t host = ntohl(parsed.s_addr);
      const uint8_t first = uint8_t(host >> 24);
      return port >= 1024 && host != INADDR_ANY && host != 0xffffffffu && first != 0 && first != 127 &&
          !(first == 169 && uint8_t(host >> 16) == 254) && first < 224;
    };
    auto parseBoundedIndex = [](const String& value, size_t begin, size_t end, uint32_t& index) {
      if (begin >= end || end > value.size()) return false;
      uint64_t parsed = 0;
      for (size_t offset = begin; offset < end; ++offset)
      {
        const char byte = value[offset];
        if (byte < '0' || byte > '9') return false;
        parsed = parsed * 10 + uint64_t(byte - '0');
        if (parsed >= 4) return false;
      }
      index = uint32_t(parsed);
      return true;
    };
    auto exactUDPLinkNetdev = [&](const String& value, uint32_t& index, String& local, String& remote) {
      constexpr const char *prefix = "socket,id=clusterlink";
      constexpr const char *udp = ",udp=";
      constexpr const char *localAddress = ",localaddr=";
      if (!starts(value, prefix)) return false;
      const auto udpAt = std::search(value.begin() + std::strlen(prefix), value.end(), udp, udp + std::strlen(udp));
      if (udpAt == value.end() || !parseBoundedIndex(value, std::strlen(prefix), size_t(udpAt - value.begin()), index)) return false;
      const auto localAt = std::search(udpAt + std::strlen(udp), value.end(), localAddress, localAddress + std::strlen(localAddress));
      if (localAt == value.end()) return false;
      remote.clear(); local.clear();
      remote.append(udpAt + std::strlen(udp), size_t(localAt - udpAt - std::strlen(udp)));
      local.append(localAt + std::strlen(localAddress), size_t(value.end() - localAt - std::strlen(localAddress)));
      return local != remote && exactSafeUnicastEndpoint(local) && exactSafeUnicastEndpoint(remote);
    };
    auto exactUDPHubport = [&](const String& value, uint32_t& index) {
      constexpr const char *prefix = "hubport,id=clusterhub";
      constexpr const char *middle = ",hubid=0,netdev=clusterlink";
      if (!starts(value, prefix)) return false;
      const auto middleAt = std::search(value.begin() + std::strlen(prefix), value.end(), middle, middle + std::strlen(middle));
      if (middleAt == value.end() ||
          !parseBoundedIndex(value, std::strlen(prefix), size_t(middleAt - value.begin()), index)) return false;
      uint32_t linked = 0;
      return parseBoundedIndex(value, size_t(middleAt - value.begin()) + std::strlen(middle), value.size(), linked) && linked == index;
    };
    auto exactClusterDevice = [&](const String& value) {
      constexpr const char *prefix = "virtio-net-pci,netdev=clusterlan,mac=";
      if (!starts(value, prefix) || value.size() != std::strlen(prefix) + 17) return false;
      const uint8_t *mac = value.data() + std::strlen(prefix);
      if (mac[0] != '0' || mac[1] != '2') return false;
      for (size_t index = 2; index < 17; ++index)
      {
        if (index % 3 == 2) { if (mac[index] != ':') return false; }
        else if (!((mac[index] >= '0' && mac[index] <= '9') ||
                   (mac[index] >= 'a' && mac[index] <= 'f'))) return false;
      }
      return true;
    };
    auto exactUserDevice = [&](const String& value) {
      constexpr const char *prefix = "virtio-net-pci,netdev=guestnet,mac=";
      if (!starts(value, prefix) || value.size() != std::strlen(prefix) + 17) return false;
      const uint8_t *mac = value.data() + std::strlen(prefix);
      if (mac[0] != '0' || mac[1] != '2') return false;
      for (size_t index = 2; index < 17; ++index)
      {
        if (index % 3 == 2) { if (mac[index] != ':') return false; }
        else if (!((mac[index] >= '0' && mac[index] <= '9') ||
                   (mac[index] >= 'a' && mac[index] <= 'f'))) return false;
      }
      return true;
    };
    uint32_t userNet = 0, multicastNet = 0, userDevice = 0, clusterDevice = 0, terminalHubport = 0;
    bool udpLinks[4] = {}, udpHubports[4] = {};
    Vector<String> udpLocals = {}, udpRemotes = {};
    for (const auto& netdev : netdevs)
    {
      if (exactDecimalPort(netdev, "user,id=guestnet,hostfwd=tcp:127.0.0.1:", "-:22") ||
          exactDecimalPort(netdev, "user,restrict=on,id=guestnet,hostfwd=tcp:127.0.0.1:", "-:22"))
        ++userNet;
      else if (exactMulticastNetdev(netdev)) ++multicastNet;
      else if (netdev == "hubport,id=clusterlan,hubid=0"_ctv) ++terminalHubport;
      else
      {
        uint32_t index = 0; String local = {}, remote = {};
        if (exactUDPLinkNetdev(netdev, index, local, remote))
        {
          if (udpLinks[index]) { failure.assign("local VM executor repeats a UDP cluster link"_ctv); return false; }
          for (const auto& prior : udpLocals) if (prior == local) { failure.assign("local VM executor repeats a UDP cluster local endpoint"_ctv); return false; }
          for (const auto& prior : udpRemotes) if (prior == remote) { failure.assign("local VM executor repeats a UDP cluster remote endpoint"_ctv); return false; }
          udpLinks[index] = true; udpLocals.push_back(local); udpRemotes.push_back(remote);
        }
        else if (exactUDPHubport(netdev, index))
        {
          if (udpHubports[index]) { failure.assign("local VM executor repeats a UDP cluster hubport"_ctv); return false; }
          udpHubports[index] = true;
        }
        else
        { failure.assign("local VM executor uses an unapproved host-network QEMU backend"_ctv); return false; }
      }
    }
    for (const auto& device : devices)
    {
      if (exactUserDevice(device)) ++userDevice;
      else if (exactClusterDevice(device)) ++clusterDevice;
      else { failure.assign("local VM executor uses an unapproved QEMU network device"_ctv); return false; }
    }
    uint32_t udpCount = 0;
    for (uint32_t index = 0; index < 4; ++index)
    {
      if (udpLinks[index]) ++udpCount;
      if (udpLinks[index] != udpHubports[index]) { failure.assign("local VM executor UDP cluster link lacks its exact hubport"_ctv); return false; }
    }
    for (uint32_t index = 0; index < udpCount; ++index)
      if (!udpLinks[index]) { failure.assign("local VM executor UDP cluster links are not contiguous"_ctv); return false; }
    const bool legacyMulticast = multicastNet == 1 && udpCount == 0 && terminalHubport == 0 && clusterDevice == 1 &&
        netdevs.size() == 2 && devices.size() == 2;
    const bool udpStar = multicastNet == 0 && udpCount >= 1 && udpCount <= 4 && terminalHubport == 1 && clusterDevice == 1 &&
        netdevs.size() == 2 * udpCount + 2 && devices.size() == 2;
    const bool noClusterLAN = multicastNet == 0 && udpCount == 0 && terminalHubport == 0 && clusterDevice == 0 &&
        netdevs.size() == 1 && devices.size() == 1;
    const bool networkSafe = !forbiddenNetworkOption && hasNoDefaults && userNet == 1 && userDevice == 1 &&
        (legacyMulticast || udpStar || noClusterLAN);
    if (argumentCount == 0 || !hasKVM || !hasUUID || !hasOverlay || !hasVars || !hasQMP || !networkSafe)
    { failure.assign("local VM executor state does not prove the exact KVM, disk, firmware, UUID, QMP, and userspace-network boundary"_ctv); return false; }
    String encoded = {}; BitseryEngine::serialize(encoded, identity);
    return prodigyComputeSHA256Hex(encoded, immutableStateSHA256, &failure);
  }

  bool queryLocalVMBoundaryExecutor(const MothershipLocalVMBoundaryDescriptor& descriptor,
                                    String& immutableStateSHA256, String& failure,
                                    uint64_t *observedPID = nullptr,
                                    String *observedStarttime = nullptr)
  {
    return inspectLocalVMBoundaryExecutor(descriptor, "query", false,
                                          immutableStateSHA256, failure,
                                          observedPID, observedStarttime);
  }

  struct LocalVMGuestLinuxIdentity {
    String machineID;
    String bootID;
    uint64_t qemuPID = 0;
    String qemuStarttime;
  };

  bool queryLocalVMBoundaryGuestLinuxIdentity(
      const MothershipLocalVMBoundaryDescriptor& descriptor,
      LocalVMGuestLinuxIdentity& identity, String& failure)
  {
    identity = {};
    Vector<String> arguments = {};
    arguments.emplace_back("query-guest-identity"_ctv);
    arguments.emplace_back("--state"_ctv); arguments.push_back(descriptor.statePath);
    arguments.emplace_back("--task-id"_ctv); arguments.push_back(descriptor.taskID);
    String output = {};
    if (!runLocalVMBoundarySealedLauncher(descriptor, arguments, 45'000, output, failure)) return false;
    simdjson::dom::parser parser; simdjson::dom::element document;
    std::string_view machineID, bootID, qemuStarttime;
    uint64_t qemuPID = 0;
    if (output.size() > 4_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT || document.get_object().size() != 4 ||
        document["machineID"].get(machineID) || document["bootID"].get(bootID) ||
        document["qemuPID"].get(qemuPID) || document["qemuStarttime"].get(qemuStarttime))
    { failure.assign("local VM guest Linux identity query returned malformed state"_ctv); return false; }
    identity.machineID.assign(machineID.data(), machineID.size());
    identity.bootID.assign(bootID.data(), bootID.size());
    identity.qemuPID = qemuPID;
    identity.qemuStarttime.assign(qemuStarttime.data(), qemuStarttime.size());
    if (!mothershipLocalVMLinuxMachineIDValid(identity.machineID) ||
        !mothershipLocalVMLinuxBootIDValid(identity.bootID) || identity.qemuPID == 0 ||
        !mothershipLocalVMProcessStarttimeValid(identity.qemuStarttime))
    { identity = {}; failure.assign("local VM guest Linux identity query returned invalid state"_ctv); return false; }
    return true;
  }

  bool reconcileLocalVMBoundaryExecutorForUpgrade(
      const MothershipLocalVMBoundaryDescriptor& descriptor,
      String& immutableStateSHA256, String& failure,
      uint128_t expectedOperationUUID = 0,
      uint128_t expectedCohortUUID = 0)
  {
    return inspectLocalVMBoundaryExecutor(descriptor, "reconcile-executor", true,
                                          immutableStateSHA256, failure, nullptr, nullptr,
                                          expectedOperationUUID, expectedCohortUUID);
  }

  bool runLocalVMBoundaryExecutorAction(const MothershipLocalVMBoundaryDescriptor& descriptor,
                                        uint128_t operationUUID, const char *action,
                                        uint32_t timeoutMilliseconds, uint64_t& startedAtMonotonicMs,
                                        uint64_t& completedAtMonotonicMs,
                                        String& failure)
  {
    startedAtMonotonicMs = 0; completedAtMonotonicMs = 0;
    if (std::strcmp(action, "cold-reboot") != 0) { failure.assign("unsupported local VM executor action"_ctv); return false; }
    String observed = {}, beforeStarttime = {};
    uint64_t beforePID = 0;
    if (!queryLocalVMBoundaryExecutor(descriptor, observed, failure, &beforePID, &beforeStarttime) ||
        observed != descriptor.immutableStateSHA256)
    { if (failure.empty()) failure.assign("local VM boundary immutable state changed"_ctv); return false; }
    Vector<String> arguments = {};
    arguments.emplace_back("cold-reboot"_ctv); arguments.emplace_back("--state"_ctv); arguments.push_back(descriptor.statePath);
    arguments.emplace_back("--task-id"_ctv); arguments.push_back(descriptor.taskID);
    String operation = {}; mothershipAssignProviderHex128(operationUUID, operation);
    arguments.emplace_back("--operation-id"_ctv); arguments.push_back(operation);
    String output = {};
    bool valid = runLocalVMBoundarySealedLauncher(descriptor, arguments,
                                                   int(timeoutMilliseconds + 30'000), output, failure);
    if (!valid) return false;
    simdjson::dom::parser parser; simdjson::dom::element document;
    std::string_view observedOperation, phase, beforeStarttimeReceipt, afterStarttimeReceipt;
    std::string_view beforeIdentityStarttime, afterIdentityStarttime;
    bool completed = false;
    uint64_t beforePIDReceipt = 0, afterPIDReceipt = 0;
    uint64_t beforeIdentityPID = 0, afterIdentityPID = 0;
    simdjson::dom::object beforeIdentity, afterIdentity;
    const auto sameProcessIdentity = [](uint64_t leftPID, std::string_view leftStarttime,
                                        uint64_t rightPID, const String& rightStarttime) {
      return leftPID == rightPID && leftStarttime.size() == rightStarttime.size() &&
          (leftStarttime.empty() ||
           std::memcmp(leftStarttime.data(), rightStarttime.data(), leftStarttime.size()) == 0);
    };
    if (output.size() > 16_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT ||
        document.get_object().size() != 11 ||
        document["operationID"].get(observedOperation) || document["completed"].get(completed) ||
        document["phase"].get(phase) || phase != "completed" ||
        document["beforePID"].get(beforePIDReceipt) || document["beforeStarttime"].get(beforeStarttimeReceipt) ||
        document["afterPID"].get(afterPIDReceipt) || document["afterStarttime"].get(afterStarttimeReceipt) ||
        document["beforeIdentity"].get(beforeIdentity) || document["afterIdentity"].get(afterIdentity) ||
        document["startedAtMonotonicMs"].get(startedAtMonotonicMs) ||
        document["completedAtMonotonicMs"].get(completedAtMonotonicMs) || !completed ||
        beforeIdentity.size() != 2 || afterIdentity.size() != 2 ||
        beforeIdentity["pid"].get(beforeIdentityPID) || beforeIdentity["starttime"].get(beforeIdentityStarttime) ||
        afterIdentity["pid"].get(afterIdentityPID) || afterIdentity["starttime"].get(afterIdentityStarttime) ||
        observedOperation.size() != operation.size() ||
        (observedOperation.size() && std::memcmp(observedOperation.data(), operation.data(), operation.size()) != 0) ||
        beforeIdentityPID != beforePIDReceipt || afterIdentityPID != afterPIDReceipt ||
        beforeIdentityStarttime != beforeStarttimeReceipt || afterIdentityStarttime != afterStarttimeReceipt ||
        (!sameProcessIdentity(beforePIDReceipt, beforeStarttimeReceipt, beforePID, beforeStarttime) &&
         !sameProcessIdentity(afterPIDReceipt, afterStarttimeReceipt, beforePID, beforeStarttime)) ||
        afterPIDReceipt == 0 || afterStarttimeReceipt.empty() ||
        (beforePIDReceipt == afterPIDReceipt && beforeStarttimeReceipt == afterStarttimeReceipt) ||
        startedAtMonotonicMs == 0 ||
        completedAtMonotonicMs <= startedAtMonotonicMs ||
        completedAtMonotonicMs - startedAtMonotonicMs > timeoutMilliseconds)
    { failure.assign("local VM executor returned an invalid or unbounded cold reboot receipt"_ctv); return false; }
    uint64_t queriedAfterPID = 0; String queriedAfterStarttime = {}, afterImmutable = {};
    valid = queryLocalVMBoundaryExecutor(descriptor, afterImmutable, failure,
                                         &queriedAfterPID, &queriedAfterStarttime) &&
        afterImmutable == descriptor.immutableStateSHA256 && queriedAfterPID == afterPIDReceipt &&
        queriedAfterStarttime.size() == afterStarttimeReceipt.size() &&
        std::memcmp(queriedAfterStarttime.data(), afterStarttimeReceipt.data(), queriedAfterStarttime.size()) == 0 &&
        (afterPIDReceipt != beforePIDReceipt || afterStarttimeReceipt != beforeStarttimeReceipt);
    if (!valid && failure.empty())
      failure.assign("local VM executor did not prove a distinct verified post-reboot guest identity"_ctv);
    return valid;
  }

  enum class LocalAuthorityRecoveryExecutorPhase : uint8_t {
    armed = 0,
    released = 1,
    completed = 2,
  };

  struct LocalAuthorityRecoveryExecutorReceipt {
    LocalAuthorityRecoveryExecutorPhase phase = LocalAuthorityRecoveryExecutorPhase::armed;
    uint64_t beforePID = 0;
    String beforeStarttime;
    uint64_t afterPID = 0;
    String afterStarttime;
    uint64_t startedAtMonotonicMs = 0;
    uint64_t completedAtMonotonicMs = 0;
    uint64_t armedAtUnixMs = 0;
    uint64_t releasedAtUnixMs = 0;
    uint64_t notBeforeUnixMs = 0;
  };

  struct LocalAuthorityRecoveryTarget {
    MothershipLocalAuthorityRecoveryExecutor executor;
    MothershipLocalVMBoundaryDescriptor boundary;
    bool localSeed = false;
  };

  static bool localAuthorityRecoveryProcessStarttimeValid(std::string_view value)
  {
    return !value.empty() && value.size() <= 64 &&
        std::all_of(value.begin(), value.end(), [](char byte) { return byte >= '0' && byte <= '9'; });
  }

  bool deriveLocalAuthorityRecoveryExecutorOperationUUID(
      uint128_t operationUUID, uint128_t clusterUUID, uint128_t machineUUID,
      uint128_t boundaryUUID, uint128_t& executorOperationUUID, String& failure)
  {
    String material = {}, identity = {}, digest = {};
    material.assign("prodigy-local-authority-recovery-executor-v1|"_ctv);
    mothershipAssignProviderHex128(operationUUID, identity); material.append(identity); material.append('|');
    mothershipAssignProviderHex128(clusterUUID, identity); material.append(identity); material.append('|');
    mothershipAssignProviderHex128(machineUUID, identity); material.append(identity); material.append('|');
    mothershipAssignProviderHex128(boundaryUUID, identity); material.append(identity);
    if (!prodigyComputeSHA256Hex(material, digest, &failure) || digest.size() != 64)
      return false;
    executorOperationUUID = String::numberFromHexString<uint128_t>(digest.substr(0, 32, Copy::no));
    if (executorOperationUUID == 0)
    { failure.assign("local authority recovery derived an invalid executor operation identity"_ctv); return false; }
    return true;
  }

  bool parseLocalAuthorityRecoveryExecutorReceipt(
      const String& output, uint128_t expectedOperationUUID, uint128_t expectedCohortUUID,
      uint32_t timeoutMilliseconds, LocalAuthorityRecoveryExecutorReceipt& receipt,
      String& failure)
  {
    receipt = {};
    simdjson::dom::parser parser; simdjson::dom::element document;
    if (output.size() > 16_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT)
    { failure.assign("local authority recovery executor returned malformed JSON"_ctv); return false; }
    auto object = document.get_object();
    std::string_view operation, cohort, phase, beforeStarttime;
    bool completed = false;
    if (object["operationID"].get(operation) || object["cohortID"].get(cohort) ||
        object["phase"].get(phase) || object["completed"].get(completed) ||
        object["beforePID"].get(receipt.beforePID) ||
        object["beforeStarttime"].get(beforeStarttime) ||
        object["startedAtMonotonicMs"].get(receipt.startedAtMonotonicMs) ||
        object["armedAtUnixMs"].get(receipt.armedAtUnixMs) ||
        object["notBeforeUnixMs"].get(receipt.notBeforeUnixMs))
    { failure.assign("local authority recovery executor receipt is incomplete"_ctv); return false; }
    String expectedOperation = {}, expectedCohort = {};
    mothershipAssignProviderHex128(expectedOperationUUID, expectedOperation);
    mothershipAssignProviderHex128(expectedCohortUUID, expectedCohort);
    const auto equal = [](std::string_view observed, const String& expected) {
      return observed.size() == expected.size() &&
          (observed.empty() || std::memcmp(observed.data(), expected.data(), observed.size()) == 0);
    };
    if (!equal(operation, expectedOperation) || !equal(cohort, expectedCohort) ||
        receipt.beforePID == 0 || !localAuthorityRecoveryProcessStarttimeValid(beforeStarttime) ||
        receipt.startedAtMonotonicMs == 0 || receipt.armedAtUnixMs == 0 ||
        receipt.notBeforeUnixMs < receipt.armedAtUnixMs)
    { failure.assign("local authority recovery executor receipt conflicts with its exact cohort"_ctv); return false; }
    receipt.beforeStarttime.assign(beforeStarttime.data(), beforeStarttime.size());

    if (phase == "armed" && !completed && object.size() == 9)
    {
      receipt.phase = LocalAuthorityRecoveryExecutorPhase::armed;
      return true;
    }
    if (object["releasedAtUnixMs"].get(receipt.releasedAtUnixMs) || receipt.releasedAtUnixMs == 0 ||
        receipt.releasedAtUnixMs > UINT64_MAX - mothershipLocalAuthorityRecoveryReleaseGraceMilliseconds ||
        receipt.notBeforeUnixMs < receipt.releasedAtUnixMs + mothershipLocalAuthorityRecoveryReleaseGraceMilliseconds)
    { failure.assign("local authority recovery executor release lacks its durable grace interval"_ctv); return false; }
    if (phase == "released" && !completed && object.size() == 10)
    {
      receipt.phase = LocalAuthorityRecoveryExecutorPhase::released;
      return true;
    }
    if (phase != "completed" || !completed || object.size() != 15)
    { failure.assign("local authority recovery executor receipt has an unsupported phase"_ctv); return false; }

    std::string_view afterStarttime, beforeIdentityStarttime, afterIdentityStarttime;
    simdjson::dom::object beforeIdentity, afterIdentity;
    uint64_t beforeIdentityPID = 0, afterIdentityPID = 0;
    if (object["afterPID"].get(receipt.afterPID) ||
        object["afterStarttime"].get(afterStarttime) ||
        object["completedAtMonotonicMs"].get(receipt.completedAtMonotonicMs) ||
        object["beforeIdentity"].get(beforeIdentity) || object["afterIdentity"].get(afterIdentity) ||
        beforeIdentity.size() != 2 || afterIdentity.size() != 2 ||
        beforeIdentity["pid"].get(beforeIdentityPID) ||
        beforeIdentity["starttime"].get(beforeIdentityStarttime) ||
        afterIdentity["pid"].get(afterIdentityPID) ||
        afterIdentity["starttime"].get(afterIdentityStarttime) ||
        receipt.afterPID == 0 || !localAuthorityRecoveryProcessStarttimeValid(afterStarttime) ||
        beforeIdentityPID != receipt.beforePID || afterIdentityPID != receipt.afterPID ||
        beforeIdentityStarttime != beforeStarttime || afterIdentityStarttime != afterStarttime ||
        (receipt.beforePID == receipt.afterPID && beforeStarttime == afterStarttime) ||
        receipt.completedAtMonotonicMs <= receipt.startedAtMonotonicMs ||
        receipt.completedAtMonotonicMs - receipt.startedAtMonotonicMs > timeoutMilliseconds)
    { failure.assign("local authority recovery executor did not prove one bounded distinct reboot"_ctv); return false; }
    receipt.afterStarttime.assign(afterStarttime.data(), afterStarttime.size());
    receipt.phase = LocalAuthorityRecoveryExecutorPhase::completed;
    return true;
  }

  bool runLocalAuthorityRecoveryExecutor(
      const MothershipLocalVMBoundaryDescriptor& descriptor, uint128_t executorOperationUUID,
      uint128_t cohortOperationUUID, const char *action, uint64_t notBeforeUnixMs,
      uint32_t timeoutMilliseconds, LocalAuthorityRecoveryExecutorReceipt& receipt,
      String& receiptSHA256, String& failure)
  {
    Vector<String> arguments = {};
    arguments.emplace_back(action); arguments.emplace_back("--state"_ctv); arguments.push_back(descriptor.statePath);
    arguments.emplace_back("--task-id"_ctv); arguments.push_back(descriptor.taskID);
    String executorOperation = {}, cohortOperation = {};
    mothershipAssignProviderHex128(executorOperationUUID, executorOperation);
    mothershipAssignProviderHex128(cohortOperationUUID, cohortOperation);
    arguments.emplace_back("--operation-id"_ctv); arguments.push_back(executorOperation);
    arguments.emplace_back("--cohort-id"_ctv); arguments.push_back(cohortOperation);
    if (std::strcmp(action, "arm-cold-reboot") == 0)
    {
      String deadline = {}; deadline.assignItoa(notBeforeUnixMs);
      arguments.emplace_back("--not-before-unix-ms"_ctv); arguments.push_back(std::move(deadline));
    }
    else if (std::strcmp(action, "release-cold-reboot") != 0 && std::strcmp(action, "query") != 0)
    { failure.assign("unsupported local authority recovery executor action"_ctv); return false; }
    String output = {};
    if (!runLocalVMBoundarySealedLauncher(descriptor, arguments, 45'000, output, failure) ||
        !parseLocalAuthorityRecoveryExecutorReceipt(output, executorOperationUUID, cohortOperationUUID,
                                                    timeoutMilliseconds, receipt, failure) ||
        !prodigyComputeSHA256Hex(output, receiptSHA256, &failure)) return false;
    return true;
  }

  bool localAuthorityRecoveryTopologyMatches(
      const MothershipLocalAuthorityRecoveryCohortRecord& record,
      const ClusterStatusReport& report, String& failure)
  {
    if (!report.hasTopology ||
        !mothershipLocalAuthorityRecoveryTopologyMatches(record.request, report.topology))
    { failure.assign("local authority recovery did not observe its admitted or newer exact three owned VM Brain topology"_ctv); return false; }
    return true;
  }

  bool awaitLocalAuthorityRecoveryClusterHealth(
      const MothershipProdigyCluster& cluster,
      const MothershipLocalAuthorityRecoveryCohortRecord& record,
      uint32_t timeoutMilliseconds, ClusterStatusReport& status, String& failure)
  {
    status = {}; failure.clear();
    const auto deadline = std::chrono::steady_clock::now() +
        std::chrono::milliseconds(timeoutMilliseconds);
    String lastFailure = {};
    while (std::chrono::steady_clock::now() <= deadline)
    {
      ClusterStatusReport candidate = {}; String attemptFailure = {};
      if (productionClusterHealthy(cluster, candidate, attemptFailure) &&
          localAuthorityRecoveryTopologyMatches(record, candidate, attemptFailure))
      { status = std::move(candidate); return true; }
      if (!attemptFailure.empty()) lastFailure = attemptFailure;
      ::usleep(500'000);
    }
    if (lastFailure.empty())
      failure.assign("local authority recovery cluster health remained unavailable before its deadline"_ctv);
    else
      failure = lastFailure;
    return false;
  }

  bool localAuthorityRecoveryExecutorCompletionValid(
      const LocalAuthorityRecoveryTarget& target,
      const LocalAuthorityRecoveryExecutorReceipt& receipt, String& failure)
  {
    String immutable = {}, observedStarttime = {}; uint64_t observedPID = 0;
    const bool valid = receipt.phase == LocalAuthorityRecoveryExecutorPhase::completed &&
        queryLocalVMBoundaryExecutor(target.boundary, immutable, failure,
                                     &observedPID, &observedStarttime) &&
        immutable == target.executor.immutableBoundarySHA256 &&
        observedPID == receipt.afterPID && observedStarttime == receipt.afterStarttime;
    if (!valid && failure.empty())
      failure.assign("local authority recovery completion does not own the current exact VM boundary"_ctv);
    return valid;
  }

  bool reconcileLocalVMBoundaryExecutorBinding(
      MothershipLocalVMBoundaryDescriptor& boundary, String& failure,
      uint128_t expectedOperationUUID = 0,
      uint128_t expectedCohortUUID = 0)
  {
    String sourceBytes = {}, currentExecutorSHA256 = {};
    sourceBytes.append(reinterpret_cast<const char *>(mothershipLocalVMBoundarySource),
                       sizeof(mothershipLocalVMBoundarySource));
    if (!prodigyComputeSHA256Hex(sourceBytes, currentExecutorSHA256, &failure)) return false;
    const bool refreshRequired = boundary.executorSHA256 != currentExecutorSHA256;
    if ((expectedOperationUUID == 0) != (expectedCohortUUID == 0))
    { failure.assign("local VM executor reconciliation requires one exact ownership pair"_ctv); return false; }
    if (!refreshRequired && expectedOperationUUID != 0 && expectedCohortUUID != 0) return true;
    String immutable = {};
    if (!reconcileLocalVMBoundaryExecutorForUpgrade(
            boundary, immutable, failure, expectedOperationUUID, expectedCohortUUID) ||
        immutable != boundary.immutableStateSHA256)
    {
      if (failure.empty())
        failure.assign("local VM executor reconciliation changed immutable boundary identity"_ctv);
      return false;
    }
    if (!refreshRequired) return true;
    auto requested = boundary;
    requested.executorSHA256 = currentExecutorSHA256;
    MothershipLocalVMBoundaryDescriptor recorded = {}; bool resumed = false;
    auto registry = openClusterRegistry();
    if (!registry.refreshLocalVMBoundaryExecutor(boundary, requested, recorded, resumed, &failure)) return false;
    boundary = std::move(recorded);
    return true;
  }

  bool awaitLocalAuthorityRecoveryNonSeed(
      const LocalAuthorityRecoveryTarget& target, uint128_t cohortOperationUUID,
      uint32_t timeoutMilliseconds, String& completedReceiptSHA256, String& failure)
  {
    completedReceiptSHA256.clear(); failure.clear();
    const auto deadline = std::chrono::steady_clock::now() +
        std::chrono::milliseconds(timeoutMilliseconds);
    String lastFailure = {};
    while (std::chrono::steady_clock::now() <= deadline)
    {
      LocalAuthorityRecoveryExecutorReceipt receipt = {}; String receiptSHA256 = {}, attemptFailure = {};
      if (runLocalAuthorityRecoveryExecutor(
              target.boundary, target.executor.executorOperationUUID, cohortOperationUUID,
              "release-cold-reboot", 0, timeoutMilliseconds,
              receipt, receiptSHA256, attemptFailure))
      {
        if (receipt.phase == LocalAuthorityRecoveryExecutorPhase::completed)
        {
          if (localAuthorityRecoveryExecutorCompletionValid(target, receipt, attemptFailure))
          { completedReceiptSHA256 = std::move(receiptSHA256); return true; }
        }
        else if (receipt.phase == LocalAuthorityRecoveryExecutorPhase::released)
        {
          // Exact release has either started the original attempt or resumed
          // a child which died after stopping QEMU.  Its inherited state lock
          // prevents this polling loop from launching a concurrent attempt.
          attemptFailure.assign("local authority recovery executor reboot remains in progress"_ctv);
        }
        else
          attemptFailure.assign("local authority recovery executor regressed to armed after durable release"_ctv);
      }
      if (!attemptFailure.empty()) lastFailure = attemptFailure;
      ::usleep(500'000);
    }
    if (lastFailure.empty())
      failure.assign("local authority recovery non-seed reboot did not complete before its deadline"_ctv);
    else
      failure = lastFailure;
    return false;
  }

  template<typename T> static bool localRecoveryObjectDigest(T value,String& digest,String& failure) {
    String bytes;
    return BitseryEngine::serialize(bytes,value) && prodigyComputeSHA256Hex(bytes,digest,&failure);
  }
  static bool localRecoveryLine(String& value,uint64_t bytes) {
    if(value.size()!=bytes+1 || value[bytes]!='\n')return false;
    value=value.substr(0,bytes,Copy::yes);return true;
  }
  static String localRecoverySourceBundle(const MothershipLocalAuthorityRecoveryCohortRequest& request) {
    return request.protocolVersion==MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion ?
        request.admittedRuntime.sourceBundleSHA256 : String(mothershipLocalInterruptedUpgradeSourceBundle);
  }
  static String localRecoveryTargetBundle(const MothershipLocalAuthorityRecoveryCohortRequest& request) {
    return request.protocolVersion==MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion ?
        request.admittedRuntime.targetBundleSHA256 : String(mothershipLocalInterruptedUpgradeTargetBundle);
  }
  static String localRecoverySourceRuntime(const MothershipLocalAuthorityRecoveryCohortRequest& request) {
    return request.protocolVersion==MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion ?
        request.admittedRuntime.sourceProdigySHA256 : String(mothershipLocalInterruptedUpgradeSourceRuntime);
  }
  static String localRecoveryTargetRuntime(const MothershipLocalAuthorityRecoveryCohortRequest& request) {
    return request.protocolVersion==MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion ?
        request.admittedRuntime.targetProdigySHA256 : String(mothershipLocalInterruptedUpgradeTargetRuntime);
  }

  // The controller is itself the registered seed guest. Its verified local
  // branch must not invent an SSH pin for its own address.
  bool localRecoveryRuntimeCommand(const MothershipProdigyCluster& cluster,
      const LocalAuthorityRecoveryTarget& target,const std::string& command,String& output,String& failure,
      const String *uploadSource=nullptr,const String *uploadDestination=nullptr)
  {
    using namespace MothershipTidesMigration;
    output.clear();
    if(target.localSeed) {
      bool detected=false;uint128_t local=0;
      if(!resolveVerifiedDisposableLocalVMIdentity(detected,local,&failure) || !detected || local!=target.executor.machineUUID) {
        failure.assign("local runtime recovery is not executing in its exact registered seed guest"_ctv);return false;
      }
      if(uploadSource && (!uploadDestination || !prodigyRunLocalShellCommand(
          text("install -m 0600 "+quote(str(*uploadSource))+" "+quote(str(*uploadDestination))),&failure)))return false;
      char path[]="/tmp/mothership-local-runtime-output.XXXXXX";
      const int fd=::mkstemp(path);if(fd<0)return false;::close(fd);
      const bool ok=prodigyRunLocalShellCommand(text("set -euo pipefail; {\n"+command+"\n} > "+quote(path)),&failure);
      if(ok) Filesystem::openReadAtClose(-1,String(path),output,1024*1024);
      ::unlink(path);return ok;
    }
    MothershipProdigyClusterMachine machine;bool found=false;
    for(const auto& entry:cluster.topology.machines)if(entry.uuid==target.executor.machineUUID) {
      if(found)return false;found=true;mothershipPopulateRemoveMachineFromTopology(entry,machine);
      mothershipHydrateTopologyRemoteCandidateSSH(cluster,machine);
    }
    if(!found || machine.ssh.hostPublicKeyOpenSSH.empty())return false;
    LIBSSH2_SESSION *session=nullptr;int fd=-1;
    if(!mothershipConnectSSHSession(machine,session,fd,&failure,
        &cluster.bootstrapSshKeyPackage,&cluster.bootstrapSshPrivateKeyPath))return false;
    bool ok=!uploadSource || (uploadDestination && prodigyUploadLocalFileToSSHSession(
        session,fd,*uploadSource,*uploadDestination,0600,&failure,120'000));
    if(ok)ok=prodigyRunBlockingSSHCommand(session,fd,text("set -eu; "+command),&output,&failure,120'000);
    mothershipCloseSSHSession(session,fd);return ok;
  }

  static std::string localRecoveryRuntimeRoot(const MothershipLocalAuthorityRecoveryCohortRequest& request) {
    String operation;operation.assignItoh(request.operationUUID);
    return "/var/lib/prodigy/mothership-local-authority-runtime/"+MothershipTidesMigration::str(operation);
  }
  static std::string localRecoveryGatewayInventory(const MothershipLocalAuthorityRecoveryCohortRequest& request,
                                                   uint128_t machine,bool emptyOnly=false) {
    using namespace MothershipRetainedRecovery;
    InitialSeedRuntimeRepairManifest manifest;
    manifest.gatewayExecutableSHA="fdc9fe507e486c1c74967558ac9733767612d0a725e45448329c6dc96c758cf5";
    manifest.gatewayExecutableBytes=6441168;manifest.binding.gateways=request.runtime.gateways;
    const auto empty=initialSeedRepairInventoryProgram(manifest,machine,false);
    if(emptyOnly)return empty;
    // Absence after the preceding cold recovery is valid. Otherwise the same
    // typed gateway environment/executable/cgroup owner must prove both leaves.
    return "if test -z \"$(find /sys/fs/cgroup/containers.slice -name cgroup.procs -exec cat {} + 2>/dev/null)\"; then\n"+
        empty+"\nelse\n"+initialSeedRepairInventoryProgram(manifest,machine)+"\nfi";
  }

  bool localRecoveryRuntimeObservation(const MothershipProdigyCluster& cluster,
      const LocalAuthorityRecoveryTarget& target,const MothershipLocalAuthorityRecoveryCohortRequest& request,
      MothershipLocalRecoveryRuntimeMember& member,
      bool targetRuntime,String& failure)
  {
    using namespace MothershipTidesMigration;
    const std::string program=R"PY(python3 - <<'LOCAL_RUNTIME'
import hashlib,json,pathlib,re,subprocess
p=pathlib.Path
def value(k):return subprocess.check_output(['systemctl','show','-p',k,'--value','prodigy'],text=True).strip()
assert value('ActiveState')=='active' and value('FragmentPath')=='/etc/systemd/system/prodigy.service'
assert value('WorkingDirectory')==''
assert re.findall(r'path=([^ ;]+)',value('ExecStart'))==['/root/prodigy/prodigy']
pid=int(value('MainPID'));assert pid>1
env=dict(v.split(b'=',1) for v in p('/proc',str(pid),'environ').read_bytes().split(b'\0') if v)
assert env.get(b'PRODIGY_STATE_DB',b'/var/lib/prodigy/state')==b'/var/lib/prodigy/state'
assert env.get(b'PRODIGY_STATE_SECRETS_DB',b'/var/lib/prodigy/state.secrets')==b'/var/lib/prodigy/state.secrets'
def sha(path):
 with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
print(json.dumps(dict(machineID=p('/etc/machine-id').read_text().strip(),bootID=p('/proc/sys/kernel/random/boot_id').read_text().strip(),runtimeSHA=sha(p('/proc',str(pid),'exe')),installedSHA=sha(p('/root/prodigy/prodigy')),bundleSHA=sha(p('/root/prodigy/prodigy.bundle.tar.zst')))))
assert int(value('MainPID'))==pid
LOCAL_RUNTIME
)PY";
    String bytes;if(!localRecoveryRuntimeCommand(cluster,target,program,bytes,failure))return false;
    try {
      simdjson::dom::parser parser;simdjson::dom::element doc;
      require(parser.parse(bytes.data(),bytes.size()).get(doc)==simdjson::SUCCESS,"local runtime observation JSON is invalid");
      const String runtimeSHA=targetRuntime ? localRecoveryTargetRuntime(request) : localRecoverySourceRuntime(request);
      const String bundleSHA=targetRuntime ? localRecoveryTargetBundle(request) : localRecoverySourceBundle(request);
      require(text(field(doc,"runtimeSHA"))==runtimeSHA && text(field(doc,"installedSHA"))==runtimeSHA &&
              text(field(doc,"bundleSHA"))==bundleSHA,"local runtime observation is not the exact admitted release");
      if(!member.linuxMachineID.empty())require(member.linuxMachineID==text(field(doc,"machineID")),"local runtime guest machine ID changed");
      member.linuxMachineID=text(field(doc,"machineID"));member.beforeBootID=text(field(doc,"bootID"));
      member.machineUUID=target.executor.machineUUID;member.runtimeRoot="/root/prodigy"_ctv;
      return true;
    } catch(const std::exception& e) {failure.assign(e.what());return false;}
  }

  bool localRecoveryRuntimeFreshAuthority(const MothershipProdigyCluster& cluster,
      const MothershipLocalAuthorityRecoveryCohortRequest& request,const ProdigyApprovedUpgradeBundle& bundle,
      bool completed,String& failure)
  {
    ClusterStatusReport status;
    if(!productionClusterHealthy(cluster,status,failure) ||
       !mothershipLocalAuthorityRecoveryTopologyMatches(request,status.topology) ||
       !mothershipLocalRecoveryRuntimeReportValid(request,status,completed)) {
      if(failure.empty())failure.assign("local runtime recovery lacks its exact empty healthy runtime cohort"_ctv);
      return false;
    }
    String clusterName=cluster.name;
    if(!configureControlTarget(clusterName.c_str(),&failure))return false;
    ProdigyUpgradeAdmissionReportRequest query;query.operationID.assignItoh(request.runtime.upgradeOperationUUID);
    query.targetBundleSHA256=bundle.bundleSHA256;query.targetContractSHA256=bundle.contract.contractSHA256;
    query.requiredStagingBytes=bundle.contract.requiredFreeBytes;
    MothershipUpgradeAdmissionReport report;
    if(!requestUpgradeAdmissionReport(query,report,failure))return false;
    const uint32_t expectedDeployments = request.protocolVersion==
        MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion ?
        request.admittedRuntime.activeDeploymentCount : 0;
    if(report.clusterUUID!=cluster.clusterUUID || !report.master || !report.observationComplete ||
        !report.authorityQuorumHealthy || !report.authorityAcknowledged || !report.recoveryWitnessAcknowledged ||
        !report.commissionedPeerTransportVerified || !report.fleetInventoriesFresh || !report.fleetBundleDigestsFresh ||
        report.activeDeploymentCount!=expectedDeployments || report.healthyCommissionedBrainCount!=3 || report.peers.size()!=3) {
      failure.assign("local runtime recovery requires fresh exact inventory and current durable authority"_ctv);return false;
    }
    for(uint32_t peerIndex=0;peerIndex<report.peers.size();++peerIndex) {
      const auto& peer=report.peers[peerIndex];
      for(uint32_t prior=0;prior<peerIndex;++prior)
        if(report.peers[prior].machineUUID==peer.machineUUID) {
          failure.assign("local runtime recovery contains duplicate peer inventory"_ctv);return false;
        }
      bool match=false;
      for(const auto& member:request.runtime.members)if(peer.machineUUID==member.machineUUID) {
        const String expected=(completed || !member.installRequired) ? localRecoveryTargetBundle(request) :
                                                                      localRecoverySourceBundle(request);
        match=peer.localInstalledBundleVerified && peer.installedBundleSHA256==expected && peer.stateUploadFresh &&
            peer.authorityAcknowledged && peer.recoveryWitnessAcknowledged;
      }
      if(!match){failure.assign("local runtime recovery peer proof differs from its frozen members"_ctv);return false;}
    }
    for(const auto& authority:request.runtime.gateways) {
      ProdigyCrossClusterMasqueGatewayAuthorityQuery q;q.pairUUID=authority.pairUUID;q.localMachineUUID=authority.localMachineUUID;
      ProdigyCrossClusterMasqueGatewayAuthorityResponse response;
      if(!requestTopicRoundTrip(MothershipTopic::pullCrossClusterMasqueGatewayAuthority,q,response,failure) ||
          !response.success || !response.found || !response.qualified || response.localClusterUUID!=cluster.clusterUUID ||
          !mothershipPhysicalFaultExactSerializedEqual(authority,response.authority)) {
        if(failure.empty())failure.assign("local runtime recovery gateway authority changed");return false;
      }
    }
    return true;
  }

  static bool captureLocalRecoveryWorkloads(const ClusterStatusReport& report,
      Vector<MothershipLocalRecoveryWorkloadIdentity>& workloads,String& failure)
  {
    workloads.clear();
    if(report.nApplications!=report.applicationReports.size()) {
      failure.assign("local runtime recovery application inventory is incomplete"_ctv);return false;
    }
    for(const auto& application:report.applicationReports)
      for(const auto& deployment:application.deploymentReports) {
        MothershipLocalRecoveryWorkloadIdentity identity;
        if(!mothershipLocalRecoveryWorkloadIdentityFromReport(
            application.applicationID,deployment,identity)) {
          failure.assign("local runtime recovery observed a malformed deployment identity"_ctv);return false;
        }
        workloads.push_back(std::move(identity));
      }
    std::sort(workloads.begin(),workloads.end(),[](const auto& left,const auto& right) {
      return left.applicationID==right.applicationID ? left.deploymentID<right.deploymentID :
          left.applicationID<right.applicationID;
    });
    if(workloads.empty()) {
      failure.assign("local runtime recovery admitted-runtime mode requires an active workload"_ctv);return false;
    }
    for(uint32_t index=1;index<workloads.size();++index)
      if(workloads[index-1].applicationID==workloads[index].applicationID &&
          workloads[index-1].deploymentID==workloads[index].deploymentID) {
        failure.assign("local runtime recovery contains duplicate deployment identity"_ctv);return false;
      }
    return true;
  }

  bool prepareLocalRecoveryRuntimeIntent(const MothershipProdigyCluster& cluster,
      const Vector<LocalAuthorityRecoveryTarget>& targets,const char *upgradeText,const char *bundleText,
      const char *predecessorText,bool existing,MothershipLocalAuthorityRecoveryCohortRequest& request,
      ProdigyApprovedUpgradeBundle& bundle,String& failure)
  {
    using namespace MothershipTidesMigration;
    const bool admittedRuntime=std::strcmp(predecessorText,"--admitted-active-runtime")==0;
    uint128_t upgrade=0,predecessor=0;
    if(!prodigyParseCanonicalHex128(String(upgradeText),upgrade) ||
        (!admittedRuntime && !prodigyParseCanonicalHex128(String(predecessorText),predecessor)))return false;
    if(!admittedRuntime && (upgrade!=mothershipLocalInterruptedUpgradeOperationUUID() ||
        predecessor!=mothershipLocalInterruptedUpgradePredecessorUUID() ||
        cluster.clusterUUID!=mothershipLocalInterruptedUpgradeClusterUUID()))return false;
    MachineCpuArchitecture architecture=MachineCpuArchitecture::unknown;String path,clusterName=cluster.name;
    if(!resolveProdigyBundleTargetArchitecture(clusterName.c_str(),architecture,&failure) ||
        !prodigyResolveBundleArtifactInput(String(bundleText),architecture,path,&failure) ||
        !prodigyApproveBundleUpgradeContract(path,bundle,&failure) || !bundle.verifyRetainedSnapshot(&failure))return false;
    if(!admittedRuntime && (bundle.bundleSHA256!=mothershipLocalInterruptedUpgradeTargetBundle ||
        bundle.contract.prodigySHA256!=mothershipLocalInterruptedUpgradeTargetRuntime))return false;
    auto& intent=request.runtime;
    if(existing) {
      const uint32_t protocol=admittedRuntime ?
          MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion :
          MothershipLocalAuthorityRecoveryCohortRequest::interruptedUpgradeVersion;
      if(request.protocolVersion!=protocol ||
          intent.upgradeOperationUUID!=upgrade || intent.predecessorRecoveryUUID!=predecessor ||
          intent.bundlePath!=path || intent.targetContractSHA256!=bundle.contract.contractSHA256 ||
          (admittedRuntime && (request.admittedRuntime.targetBundleSHA256!=bundle.bundleSHA256 ||
            request.admittedRuntime.targetProdigySHA256!=bundle.contract.prodigySHA256 ||
            request.admittedRuntime.targetMothershipSHA256!=bundle.contract.mothershipSHA256)))return false;
    } else {
      request.protocolVersion=admittedRuntime ?
          MothershipLocalAuthorityRecoveryCohortRequest::admittedRuntimeUpgradeVersion :
          MothershipLocalAuthorityRecoveryCohortRequest::interruptedUpgradeVersion;
      intent.upgradeOperationUUID=upgrade;intent.predecessorRecoveryUUID=predecessor;
      intent.bundlePath=path;intent.targetContractSHA256=bundle.contract.contractSHA256;
      MothershipUpgradeAdmissionRecord admission;MothershipLocalAuthorityRecoveryCohortRecord prior;
      { auto registry=openClusterRegistry();
        if(!registry.loadUpgradeAdmission(cluster.clusterUUID,upgrade,admission,&failure) ||
            !registry.loadLocalRecoveryGateways(cluster.clusterUUID,intent.gateways,&failure) ||
            (!admittedRuntime && !registry.loadLocalAuthorityRecoveryCohort(predecessor,prior,&failure)))return false;
      }
      if(!localRecoveryObjectDigest(admission,intent.admissionSHA256,failure) ||
          (!admittedRuntime && !localRecoveryObjectDigest(prior,intent.predecessorRecoverySHA256,failure)))return false;
      if(!admission.eligible || admission.approvedPath!=uint8_t(MothershipUpgradePath::sameLogicalRollout) ||
          admission.clusterUUID!=cluster.clusterUUID || admission.operationID!=upgrade ||
          admission.targetBundleSHA256!=bundle.bundleSHA256 ||
          admission.targetContractSHA256!=bundle.contract.contractSHA256)return false;
      MothershipUpgradeIdentity source;source.releaseID=admission.sourceReleaseID;
      source.contractSHA256=admission.sourceContractSHA256;source.prodigySHA256=admission.sourceProdigySHA256;
      source.mothershipSHA256=admission.sourceMothershipSHA256;
      String architectureName(machineCpuArchitectureName(architecture));
      if(!prodigyValidateSameClusterUpgradeRelease(bundle,architectureName,cluster.clusterUUID,&source,true,&failure))return false;
      if(admittedRuntime) {
        auto& identity=request.admittedRuntime;
        identity.sourceBundleSHA256=admission.sourceBundleSHA256;
        identity.sourceContractSHA256=admission.sourceContractSHA256;
        identity.sourceReleaseID=admission.sourceReleaseID;
        identity.sourceProdigySHA256=admission.sourceProdigySHA256;
        identity.sourceMothershipSHA256=admission.sourceMothershipSHA256;
        identity.targetBundleSHA256=bundle.bundleSHA256;
        identity.targetReleaseID=bundle.contract.releaseID;
        identity.targetProdigySHA256=bundle.contract.prodigySHA256;
        identity.targetMothershipSHA256=bundle.contract.mothershipSHA256;
        identity.targetBinaryVersion=bundle.contract.binaryVersion;
        identity.authorityGeneration=admission.authorityGeneration;
        identity.masterUUID=admission.masterUUID;identity.masterBootNs=admission.masterBootNs;
        identity.semanticObservationSHA256=admission.semanticObservationSHA256;
        ClusterStatusReport status;
        if(!productionClusterHealthy(cluster,status,failure) ||
            !captureLocalRecoveryWorkloads(status,identity.workloads,failure))return false;
        identity.activeDeploymentCount=identity.workloads.size();
        for(const auto& observed:status.machineReports) {
          uint128_t machine=0;
          if(!prodigyParseCanonicalHex128(observed.machineUUID,machine) ||
              observed.approvedBundleSHA256!=identity.sourceBundleSHA256 ||
              observed.runningProdigyVersion.empty() ||
              (observed.currentMaster && machine!=identity.masterUUID) ||
              (!identity.sourceBinaryVersion.empty() && identity.sourceBinaryVersion!=observed.runningProdigyVersion))return false;
          identity.sourceBinaryVersion=observed.runningProdigyVersion;
        }
      }
      for(uint32_t i=0;i<targets.size();++i) {
        MothershipLocalRecoveryRuntimeMember member;member.installRequired=admittedRuntime || i!=0;
        if(!localRecoveryRuntimeObservation(cluster,targets[i],request,member,!member.installRequired,failure) ||
            !localRecoveryRuntimeCommand(cluster,targets[i],localRecoveryGatewayInventory(request,member.machineUUID),
                                         member.gatewayInventory,failure))return false;
        try {
          simdjson::dom::parser parser;simdjson::dom::element inventory;
          require(parser.parse(member.gatewayInventory.data(),member.gatewayInventory.size()).get(inventory)==simdjson::SUCCESS &&
                  text(field(inventory,"linuxMachineID"))==member.linuxMachineID &&
                  text(field(inventory,"bootID"))==member.beforeBootID,"local recovery inventory changed during admission");
        } catch(const std::exception& e){failure.assign(e.what());return false;}
        intent.members.push_back(std::move(member));
      }
      if(!mothershipLocalAuthorityRecoveryCohortRequestValid(request,&failure))return false;
      if(!localRecoveryRuntimeFreshAuthority(cluster,request,bundle,false,failure))return false;
    }
    auto registry=openClusterRegistry();
    Vector<CrossClusterMasqueGatewayAuthority> gateways;
    if(!registry.localRecoveryRuntimeAuthorityMatches(request,&failure) ||
        !registry.loadLocalRecoveryGateways(cluster.clusterUUID,gateways,&failure) ||
        !mothershipPhysicalFaultExactSerializedEqual(gateways,intent.gateways))return false;
    return true;
  }

  bool installLocalRecoveryRuntime(const MothershipProdigyCluster& cluster,
      const LocalAuthorityRecoveryTarget& target,uint32_t index,const ProdigyApprovedUpgradeBundle& bundle,
      MothershipLocalAuthorityRecoveryCohortRecord& record,String& failure)
  {
    using namespace MothershipTidesMigration;
    const auto& request=record.request;const auto member=request.runtime.members[index];
    if(record.boundaries[index].phase!=MothershipLocalAuthorityRecoveryPhase::armed)return false;
    auto progress=record.runtimeProgress[index];
    const auto root=localRecoveryRuntimeRoot(request),staged=root+"/runtime",fence=root+"/writers-fenced";
    String bindingSHA;if(!localRecoveryObjectDigest(request,bindingSHA,failure))return false;
    const auto prefix="test \"$(cat /etc/machine-id)\" = "+quote(str(member.linuxMachineID))+
        "; test \"$(cat /proc/sys/kernel/random/boot_id)\" = "+quote(str(member.beforeBootID))+"; "+
        runtimeServiceExecStartCheck("/root/prodigy");
    String output;
    // The executor can have durably released while the controller lost the
    // corresponding registry advance. Query that existing owner before any
    // original-boot install check; never infer another reboot is needed.
    LocalAuthorityRecoveryExecutorReceipt reboot;String rebootSHA;
    if(!runLocalAuthorityRecoveryExecutor(target.boundary,target.executor.executorOperationUUID,request.operationUUID,
        "query",0,request.timeoutMilliseconds,reboot,rebootSHA,failure))return false;
    if(!member.installRequired) {
      if(reboot.phase!=LocalAuthorityRecoveryExecutorPhase::armed)return true;
      auto observed=member;
      return localRecoveryRuntimeObservation(cluster,target,request,observed,true,failure) &&
          observed.beforeBootID==member.beforeBootID &&
          localRecoveryRuntimeCommand(cluster,target,localRecoveryGatewayInventory(request,member.machineUUID),output,failure) &&
          output==member.gatewayInventory;
    }
    if(reboot.phase!=LocalAuthorityRecoveryExecutorPhase::armed) {
      if(!progress.installDispatched || progress.stateSHA256.empty())return false;
      return localRecoveryRuntimeCommand(cluster,target,
          "test \"$(cat /etc/machine-id)\" = "+quote(str(member.linuxMachineID))+
          "; test \"$(cat "+quote(fence)+")\" = "+quote(str(bindingSHA))+
          "; test \"$(sha256sum /root/prodigy/prodigy | cut -d' ' -f1)\" = "+quote(str(bundle.contract.prodigySHA256))+
          "; test \"$(sha256sum /root/prodigy/prodigy.bundle.tar.zst | cut -d' ' -f1)\" = "+quote(str(bundle.bundleSHA256)),output,failure);
    }
    if(!progress.installDispatched) {
      auto observed=member;
      if(!localRecoveryRuntimeObservation(cluster,target,request,observed,false,failure) || observed.beforeBootID!=member.beforeBootID ||
          !localRecoveryRuntimeCommand(cluster,target,localRecoveryGatewayInventory(request,member.machineUUID),output,failure) ||
          output!=member.gatewayInventory)return false;
    }
    // Stage privately before service stop. Reentry never treats existence as
    // artifact verification and never overwrites an uncertain partial install.
    if(!localRecoveryRuntimeCommand(cluster,target,prefix+
        "test ! -L /var/lib/prodigy; test ! -L /var/lib/prodigy/mothership-local-authority-runtime; test ! -L "+quote(root)+
        "; umask 077; mkdir -p "+quote(root)+"; test \"$(stat -c %u "+quote(root)+")\" = 0; chmod 700 "+quote(root)+
        "; if test -e "+quote(root+"/binding")+"; then test \"$(cat "+quote(root+"/binding")+")\" = "+quote(str(bindingSHA))+
        "; else printf %s "+quote(str(bindingSHA))+" > "+quote(root+"/binding")+"; sync -f "+quote(root)+"; fi",output,failure))return false;
    String remoteBundle=text(root+"/approved.bundle.tar.zst"),remoteSHA;
    prodigyResolveBundleSHA256Path(remoteBundle,remoteSHA);
    if(!bundle.verifyRetainedSnapshot(&failure) || !localRecoveryRuntimeCommand(cluster,target,prefix+
        "test \"$(sha256sum "+quote(str(remoteBundle))+" | cut -d' ' -f1)\" = "+quote(str(bundle.bundleSHA256))+
        "; printf '%s\\n' "+quote(str(bundle.bundleSHA256))+" > "+quote(str(remoteSHA))+"; sync -f "+quote(root),
        output,failure,&bundle.retainedSnapshotPath,&remoteBundle))return false;
    String install;prodigyBuildBundleInstallCommand(remoteBundle,text(staged),install);
    if(!localRecoveryRuntimeCommand(cluster,target,prefix+"if test ! -e "+quote(staged)+"; then "+str(install)+
        "; fi; test \"$(sha256sum "+quote(staged+"/prodigy")+" | cut -d' ' -f1)\" = "+quote(str(bundle.contract.prodigySHA256))+
        "; test \"$(sha256sum "+quote(staged+"/prodigy.bundle.tar.zst")+" | cut -d' ' -f1)\" = "+quote(str(bundle.bundleSHA256)),output,failure))return false;
    if(!progress.installDispatched) {
      progress.installDispatched=true;auto registry=openClusterRegistry();
      if(!registry.checkpointLocalRecoveryRuntime(request.operationUUID,progress,record,&failure))return false;
    }
    if(!localRecoveryRuntimeCommand(cluster,target,prefix+
        "if test -e "+quote(fence)+"; then test \"$(cat "+quote(fence)+")\" = "+quote(str(bindingSHA))+"; fi; "+
        runtimeStartupFenceCommand(root,str(bindingSHA))+"; "+quiesceServiceCommand(true),output,failure))return false;
    if(!localRecoveryRuntimeCommand(cluster,target,localRecoveryGatewayInventory(request,member.machineUUID),output,failure) ||
        output!=member.gatewayInventory)return false;
    String stateSHA,secretsSHA;
    if(!localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state"),stateSHA,failure) ||
        !localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state.secrets"),secretsSHA,failure))return false;
    if(!localRecoveryLine(stateSHA,64) || !localRecoveryLine(secretsSHA,64))return false;
    if(progress.stateSHA256.empty()) {
      progress.stateSHA256=stateSHA;progress.secretsSHA256=secretsSHA;auto registry=openClusterRegistry();
      if(!registry.checkpointLocalRecoveryRuntime(request.operationUUID,progress,record,&failure))return false;
    } else if(stateSHA!=progress.stateSHA256 || secretsSHA!=progress.secretsSHA256)return false;
    const auto retained="/root/prodigy.local-recovery-"+str(bindingSHA).substr(0,16);
    if(!localRecoveryRuntimeCommand(cluster,target,prefix+
        retainedRuntimePublicationCommand("/root/prodigy",staged,retained,
            str(localRecoverySourceRuntime(request)),str(localRecoverySourceBundle(request)),
            str(bundle.contract.prodigySHA256))+
        "test \"$(sha256sum /root/prodigy/prodigy.bundle.tar.zst | cut -d' ' -f1)\" = "+quote(str(bundle.bundleSHA256)),output,failure))return false;
    if(!localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state"),stateSHA,failure) ||
        !localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state.secrets"),secretsSHA,failure))return false;
    if(!localRecoveryLine(stateSHA,64) || !localRecoveryLine(secretsSHA,64))return false;
    return stateSHA==progress.stateSHA256 && secretsSHA==progress.secretsSHA256;
  }

  bool activateLocalRecoveryRuntime(const MothershipProdigyCluster& cluster,
      const LocalAuthorityRecoveryTarget& target,uint32_t index,MothershipLocalAuthorityRecoveryCohortRecord& record,
      String& failure)
  {
    using namespace MothershipTidesMigration;
    const auto member=record.request.runtime.members[index];auto progress=record.runtimeProgress[index];
    const auto root=localRecoveryRuntimeRoot(record.request),fence=root+"/writers-fenced";
    String bindingSHA,boot,output;
    if(!localRecoveryObjectDigest(record.request,bindingSHA,failure) ||
        !localRecoveryRuntimeCommand(cluster,target,"test \"$(cat /etc/machine-id)\" = "+quote(str(member.linuxMachineID))+
        "; cat /proc/sys/kernel/random/boot_id",boot,failure))return false;
    if(!localRecoveryLine(boot,36) || boot==member.beforeBootID)return false;
    if(!progress.activationBootID.empty() && progress.activationBootID!=boot)return false;
    if(progress.activationBootID.empty()) {
      if(member.installRequired) {
        if(!localRecoveryRuntimeCommand(cluster,target,"test \"$(cat "+quote(fence)+")\" = "+quote(str(bindingSHA))+
            "; test \"$(systemctl show -p MainPID --value prodigy)\" = 0; "+
            localRecoveryGatewayInventory(record.request,member.machineUUID,true),output,failure))return false;
        String state,secrets;
        if(!localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state"),state,failure) ||
            !localRecoveryRuntimeCommand(cluster,target,MothershipRetainedRecovery::initialSeedRepairTreeProgram("/var/lib/prodigy/state.secrets"),secrets,failure))return false;
        if(!localRecoveryLine(state,64) || !localRecoveryLine(secrets,64) ||
            state!=progress.stateSHA256 || secrets!=progress.secretsSHA256)return false;
      }
      progress.activationBootID=boot;auto registry=openClusterRegistry();
      if(!registry.checkpointLocalRecoveryRuntime(record.request.operationUUID,progress,record,&failure))return false;
    }
    if(member.installRequired && !localRecoveryRuntimeCommand(cluster,target,
        runtimeServiceExecStartCheck("/root/prodigy")+"test \"$(cat /proc/sys/kernel/random/boot_id)\" = "+quote(str(boot))+
        "; test \"$(sha256sum /root/prodigy/prodigy | cut -d' ' -f1)\" = "+quote(str(localRecoveryTargetRuntime(record.request)))+
        "; test \"$(sha256sum /root/prodigy/prodigy.bundle.tar.zst | cut -d' ' -f1)\" = "+quote(str(localRecoveryTargetBundle(record.request)))+
        "; if test -e "+quote(fence)+"; then test \"$(cat "+quote(fence)+")\" = "+quote(str(bindingSHA))+
        "; rm -- "+quote(fence)+"; sync -f "+quote(root)+"; fi; systemctl start prodigy; systemctl is-active --quiet prodigy",output,failure))return false;
    auto observed=member;
    return localRecoveryRuntimeObservation(cluster,target,record.request,observed,true,failure) && observed.beforeBootID==boot;
  }

  void runRecoverLocalClusterAuthority(int argc, char *argv[])
  {
    String failure = {};
    uint128_t operationUUID = 0;
    uint64_t timeout = 0;
    const bool interruptedUpgrade=argc==7 && std::strcmp(argv[3],"--complete-interrupted-upgrade")==0;
    bool valid = (argc == 3 || interruptedUpgrade) && prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        mothershipParseUnsignedArgument(argv[2], mothershipLocalVMFaultMaximumRecoveryMilliseconds, timeout) &&
        timeout >= mothershipLocalAuthorityRecoveryMinimumTimeoutMilliseconds;
    if (!valid)
      failure.assign("usage: recoverLocalClusterAuthority OPERATION_UUID CLUSTER TIMEOUT_MS [--complete-interrupted-upgrade UPGRADE_OPERATION APPROVED_BUNDLE PREDECESSOR_RECOVERY|--admitted-active-runtime] (timeout must be 120000..300000)"_ctv);

    MothershipProdigyCluster cluster = {};
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[1]), cluster, &failure);
    }
    if (valid && (cluster.deploymentMode != MothershipClusterDeploymentMode::local || cluster.nBrains != 3 ||
                  cluster.topology.version == 0 || cluster.topology.machines.size() != 3))
    { failure.assign("local authority recovery requires one exact three-Brain deploymentMode=local topology"_ctv); valid = false; }

    bool existingCohort = false;
    MothershipLocalAuthorityRecoveryCohortRecord existingCohortRecord = {};
    if (valid)
    {
      auto registry = openClusterRegistry(); String readFailure = {};
      if (registry.loadLocalAuthorityRecoveryCohort(operationUUID, existingCohortRecord, &readFailure))
        existingCohort = true;
      else if (!readFailure.equal("record not found"_ctv))
      { failure = readFailure; valid = false; }
    }

    ClusterMachine seedMachine = {};
    if (valid) valid = findLocalAuthorityRecoverySeedMachine(cluster.topology, seedMachine, &failure);
    Vector<LocalAuthorityRecoveryTarget> targets = {};
    if (valid)
    {
      for (const auto& machine : cluster.topology.machines)
      {
        if (machine.uuid == 0 || machine.kind != MachineConfig::MachineKind::vm || !machine.isBrain ||
            machine.backing != ClusterMachineBacking::owned || machine.lifetime != MachineLifetime::owned)
        { failure.assign("local authority recovery topology is not three owned VM Brain boundaries"_ctv); valid = false; break; }
        LocalAuthorityRecoveryTarget target = {};
        {
          auto registry = openClusterRegistry();
          valid = registry.findActiveLocalVMBoundary(cluster.clusterUUID, machine.uuid,
                                                     target.boundary, &failure);
        }
        if (!valid) break;
        target.executor.machineUUID = machine.uuid;
        target.executor.boundaryUUID = target.boundary.vmBoundaryUUID;
        target.executor.immutableBoundarySHA256 = target.boundary.immutableStateSHA256;
        valid = deriveLocalAuthorityRecoveryExecutorOperationUUID(
            operationUUID, cluster.clusterUUID, machine.uuid, target.boundary.vmBoundaryUUID,
            target.executor.executorOperationUUID, failure);
        if (!valid) break;
        target.localSeed = machine.uuid == seedMachine.uuid;
        targets.push_back(std::move(target));
      }
    }
    if (valid)
    {
      std::sort(targets.begin(), targets.end(), [](const auto& left, const auto& right) {
        return left.executor.machineUUID < right.executor.machineUUID;
      });
      uint32_t seeds = 0;
      for (const auto& target : targets) if (target.localSeed) ++seeds;
      if (targets.size() != 3 || seeds != 1)
      { failure.assign("local authority recovery cannot identify exactly one local seed VM"_ctv); valid = false; }
    }

    MothershipLocalAuthorityRecoveryCohortRequest request = {};
    MothershipLocalAuthorityRecoveryCohortRecord record = {};
    ProdigyApprovedUpgradeBundle repairBundle;
    bool resumed = false;
    if (valid)
    {
      request.operationUUID = operationUUID; request.clusterUUID = cluster.clusterUUID;
      // A cohort retry must retain the generation admitted before its first
      // reboot.  The recovery itself may advance the live Brain topology, and
      // the completion proof below deliberately accepts that newer generation
      // only when the exact three owned VM identities are unchanged.
      request.topologyVersion = existingCohort ?
          existingCohortRecord.request.topologyVersion : cluster.topology.version;
      request.timeoutMilliseconds = uint32_t(timeout);
      for (const auto& target : targets) request.executors.push_back(target.executor);
      if(interruptedUpgrade) {
        if(existingCohort) {
          request.protocolVersion=existingCohortRecord.request.protocolVersion;
          request.runtime=existingCohortRecord.request.runtime;
          request.admittedRuntime=existingCohortRecord.request.admittedRuntime;
        }
        valid=prepareLocalRecoveryRuntimeIntent(cluster,targets,argv[4],argv[5],argv[6],existingCohort,
                                                request,repairBundle,failure);
        if(!valid && failure.empty())failure.assign("local runtime recovery admission or artifact binding failed"_ctv);
      }
      if (valid && existingCohort &&
          !mothershipLocalAuthorityRecoveryTopologyMatches(existingCohortRecord.request, cluster.topology))
      { failure.assign("local authority recovery current topology conflicts with its immutable cohort"_ctv); valid = false; }
      else if (valid && existingCohort &&
               !mothershipPhysicalFaultExactSerializedEqual(existingCohortRecord.request, request))
      { failure.assign("local authority recovery retry conflicts with its immutable cohort"_ctv); valid = false; }
    }
    for (auto& target : targets)
    {
      if (!valid) break;
      valid = reconcileLocalVMBoundaryExecutorBinding(
          target.boundary, failure,
          existingCohort ? target.executor.executorOperationUUID : uint128_t(0),
          existingCohort ? operationUUID : uint128_t(0));
      if (!valid && failure.empty())
        failure.assign("local authority recovery boundary identity changed"_ctv);
    }
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.admitLocalAuthorityRecoveryCohort(request, record, resumed, &failure);
    }
    if (valid && record.phase == MothershipLocalAuthorityRecoveryPhase::recovered)
    {
      if(interruptedUpgrade) {
        for(uint32_t i=0;valid && i<targets.size();++i) {
          auto member=request.runtime.members[i];
          valid=localRecoveryRuntimeObservation(cluster,targets[i],request,member,true,failure) &&
                member.beforeBootID==record.runtimeProgress[i].activationBootID;
        }
        if(valid)valid=localRecoveryRuntimeFreshAuthority(cluster,request,repairBundle,true,failure);
        if(!valid) {
          basics_log("recoverLocalClusterAuthority success=0 pending=1 resumed=1 failure=%s\n",failure.c_str());exit(75);
        }
      }
      basics_log("recoverLocalClusterAuthority success=1 pending=0 resumed=1 phase=%u operationUUID=%016llx%016llx clusterUUID=%016llx%016llx failure=\n",
          unsigned(record.phase), (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
          (unsigned long long)(cluster.clusterUUID >> 64), (unsigned long long)cluster.clusterUUID);
      return;
    }

    const uint64_t nowUnixMs = uint64_t(std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count());
    const uint64_t notBeforeUnixMs = nowUnixMs + mothershipLocalAuthorityRecoveryArmDelayMilliseconds;
    for (uint32_t index = 0; valid && index < targets.size(); ++index)
    {
      if (record.boundaries[index].phase != MothershipLocalAuthorityRecoveryPhase::admitted) continue;
      LocalAuthorityRecoveryExecutorReceipt receipt = {}; String receiptSHA256 = {};
      valid = runLocalAuthorityRecoveryExecutor(
          targets[index].boundary, targets[index].executor.executorOperationUUID, operationUUID,
          "arm-cold-reboot", notBeforeUnixMs, uint32_t(timeout), receipt, receiptSHA256, failure) &&
          receipt.phase == LocalAuthorityRecoveryExecutorPhase::armed;
      if (!valid)
      { if (failure.empty()) failure.assign("local authority recovery executor did not remain durably armed"_ctv); break; }
      auto registry = openClusterRegistry(); bool phaseResumed = false;
      valid = registry.advanceLocalAuthorityRecoveryCohort(
          operationUUID, targets[index].executor.boundaryUUID,
          MothershipLocalAuthorityRecoveryPhase::armed, receiptSHA256,
          record, phaseResumed, &failure);
      resumed = resumed || phaseResumed;
    }
    if (valid && record.phase < MothershipLocalAuthorityRecoveryPhase::armed)
    { failure.assign("local authority recovery has not durably armed every VM boundary"_ctv); valid = false; }

    bool recoveryPending = false;
    for (uint32_t index = 0; valid && index < targets.size(); ++index)
    {
      if (targets[index].localSeed ||
          record.boundaries[index].phase == MothershipLocalAuthorityRecoveryPhase::recovered) continue;
      if (record.boundaries[index].phase == MothershipLocalAuthorityRecoveryPhase::armed)
      {
        if(interruptedUpgrade && !installLocalRecoveryRuntime(cluster,targets[index],index,repairBundle,record,failure)) {
          valid=false;recoveryPending=true;break;
        }
        LocalAuthorityRecoveryExecutorReceipt receipt = {}; String receiptSHA256 = {};
        valid = runLocalAuthorityRecoveryExecutor(
            targets[index].boundary, targets[index].executor.executorOperationUUID, operationUUID,
            "release-cold-reboot", 0, uint32_t(timeout), receipt, receiptSHA256, failure) &&
            (receipt.phase == LocalAuthorityRecoveryExecutorPhase::released ||
             receipt.phase == LocalAuthorityRecoveryExecutorPhase::completed);
        if (!valid)
        { if (failure.empty()) failure.assign("local authority recovery executor did not durably release"_ctv); break; }
        auto registry = openClusterRegistry(); bool phaseResumed = false;
        valid = registry.advanceLocalAuthorityRecoveryCohort(
            operationUUID, targets[index].executor.boundaryUUID,
            MothershipLocalAuthorityRecoveryPhase::released, receiptSHA256,
            record, phaseResumed, &failure);
        resumed = resumed || phaseResumed;
      }
      String completedReceiptSHA256 = {};
      if (valid && record.boundaries[index].phase == MothershipLocalAuthorityRecoveryPhase::released &&
          !awaitLocalAuthorityRecoveryNonSeed(
              targets[index], operationUUID, uint32_t(timeout), completedReceiptSHA256, failure))
      { valid = false; recoveryPending = true; }
      if(valid && interruptedUpgrade && !activateLocalRecoveryRuntime(cluster,targets[index],index,record,failure)) {
        valid=false;recoveryPending=true;
      }
    }

    uint32_t seedIndex = targets.size();
    for (uint32_t index = 0; index < targets.size(); ++index)
      if (targets[index].localSeed) seedIndex = index;
    if (valid && seedIndex == targets.size())
    { failure.assign("local authority recovery lost its exact seed VM identity"_ctv); valid = false; }
    bool seedReleasedPending = false;
    if (valid && interruptedUpgrade && record.boundaries[seedIndex].phase == MothershipLocalAuthorityRecoveryPhase::armed &&
        !installLocalRecoveryRuntime(cluster,targets[seedIndex],seedIndex,repairBundle,record,failure)) {
      valid=false;recoveryPending=true;
    }
    if (valid && record.boundaries[seedIndex].phase == MothershipLocalAuthorityRecoveryPhase::armed)
    {
      LocalAuthorityRecoveryExecutorReceipt receipt = {}; String receiptSHA256 = {};
      valid = runLocalAuthorityRecoveryExecutor(
          targets[seedIndex].boundary, targets[seedIndex].executor.executorOperationUUID, operationUUID,
          "release-cold-reboot", 0, uint32_t(timeout), receipt, receiptSHA256, failure) &&
          (receipt.phase == LocalAuthorityRecoveryExecutorPhase::released ||
           receipt.phase == LocalAuthorityRecoveryExecutorPhase::completed);
      if (valid)
      {
        auto registry = openClusterRegistry(); bool phaseResumed = false;
        valid = registry.advanceLocalAuthorityRecoveryCohort(
            operationUUID, targets[seedIndex].executor.boundaryUUID,
            MothershipLocalAuthorityRecoveryPhase::released, receiptSHA256,
            record, phaseResumed, &failure);
        resumed = resumed || phaseResumed;
      }
      if (valid && receipt.phase == LocalAuthorityRecoveryExecutorPhase::released)
        seedReleasedPending = true;
    }
    if (valid && record.phase < MothershipLocalAuthorityRecoveryPhase::released)
    { failure.assign("local authority recovery has not durably released every VM boundary"_ctv); valid = false; }
    if (seedReleasedPending)
    {
      basics_log("recoverLocalClusterAuthority success=0 pending=1 resumed=%u phase=released operationUUID=%016llx%016llx clusterUUID=%016llx%016llx failure=cohort released; retry after the seed VM returns\n",
          unsigned(resumed), (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
          (unsigned long long)(cluster.clusterUUID >> 64), (unsigned long long)cluster.clusterUUID);
      exit(75);
    }

    Vector<String> completedReceiptSHA256s = {}; completedReceiptSHA256s.resize(targets.size());
    for (uint32_t index = 0; valid && index < targets.size(); ++index)
    {
      if (record.boundaries[index].phase == MothershipLocalAuthorityRecoveryPhase::recovered) continue;
      if (!targets[index].localSeed)
      {
        valid = awaitLocalAuthorityRecoveryNonSeed(
            targets[index], operationUUID, uint32_t(timeout),
            completedReceiptSHA256s[index], failure);
        if (!valid) recoveryPending = true;
        continue;
      }
      LocalAuthorityRecoveryExecutorReceipt receipt = {}; String receiptSHA256 = {};
      valid = runLocalAuthorityRecoveryExecutor(
          targets[index].boundary, targets[index].executor.executorOperationUUID, operationUUID,
          "release-cold-reboot", 0, uint32_t(timeout), receipt, receiptSHA256, failure);
      if (valid && receipt.phase == LocalAuthorityRecoveryExecutorPhase::released)
      { recoveryPending = true; valid = false; }
      if (valid) valid = localAuthorityRecoveryExecutorCompletionValid(targets[index], receipt, failure);
      if (!valid)
      {
        recoveryPending = true;
        if (failure.empty()) failure.assign("local authority recovery seed reboot is still pending exact boundary proof"_ctv);
        break;
      }
      completedReceiptSHA256s[index] = std::move(receiptSHA256);
      if(interruptedUpgrade && !activateLocalRecoveryRuntime(cluster,targets[index],index,record,failure)) {
        valid=false;recoveryPending=true;
      }
    }

    ClusterStatusReport status = {};
    if (valid && !awaitLocalAuthorityRecoveryClusterHealth(
                     cluster, record, uint32_t(timeout), status, failure))
    { valid = false; recoveryPending = true; }
    if(valid && interruptedUpgrade && !localRecoveryRuntimeFreshAuthority(cluster,request,repairBundle,true,failure)) {
      valid=false;recoveryPending=true;
    }
    if (valid)
    {
      for (uint32_t index = 0; valid && index < targets.size(); ++index)
      {
        if (record.boundaries[index].phase == MothershipLocalAuthorityRecoveryPhase::recovered) continue;
        auto registry = openClusterRegistry(); bool phaseResumed = false;
        valid = registry.advanceLocalAuthorityRecoveryCohort(
            operationUUID, targets[index].executor.boundaryUUID,
            MothershipLocalAuthorityRecoveryPhase::recovered, completedReceiptSHA256s[index],
            record, phaseResumed, &failure);
        resumed = resumed || phaseResumed;
      }
    }

    if (!valid && recoveryPending)
    {
      basics_log("recoverLocalClusterAuthority success=0 pending=1 resumed=%u phase=%u operationUUID=%016llx%016llx clusterUUID=%016llx%016llx failure=%s\n",
          unsigned(resumed), unsigned(record.phase),
          (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
          (unsigned long long)(cluster.clusterUUID >> 64), (unsigned long long)cluster.clusterUUID,
          failure.c_str());
      exit(75);
    }
    const bool recovered = valid && record.phase == MothershipLocalAuthorityRecoveryPhase::recovered;
    basics_log("recoverLocalClusterAuthority success=%u pending=0 resumed=%u phase=%u operationUUID=%016llx%016llx clusterUUID=%016llx%016llx failure=%s\n",
        unsigned(recovered), unsigned(resumed), unsigned(record.phase),
        (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
        (unsigned long long)(cluster.clusterUUID >> 64), (unsigned long long)cluster.clusterUUID,
        failure.c_str());
    if (!recovered) exit(EXIT_FAILURE);
  }

  void runPrepareProductionPair(int argc, char *argv[])
  {
    String failure = {};
    String listenerAddress = argc > 5 ? String(argv[5]) : String();
    uint128_t operationUUID = 0, routeUUID = 0, boundaryUUID = 0;
    uint64_t sourceDeploymentID = 0, targetDeploymentID = 0, listenerPort = 0;
    bool valid = argc == 7 && prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[1]), routeUUID) && routeUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[2]), boundaryUUID) && boundaryUUID != 0 &&
        mothershipParseUnsignedArgument(argv[3], UINT64_MAX, sourceDeploymentID) && sourceDeploymentID != 0 &&
        mothershipParseUnsignedArgument(argv[4], UINT64_MAX, targetDeploymentID) && targetDeploymentID != 0 &&
        mothershipProductionPairIngressAddressValid(listenerAddress) &&
        mothershipParseUnsignedArgument(argv[6], UINT16_MAX, listenerPort) && listenerPort != 0 &&
        listenerPort != uint16_t(ReservedPorts::neuron) &&
        listenerPort != uint16_t(ReservedPorts::brain) &&
        listenerPort != uint16_t(ReservedPorts::mothership) &&
        listenerPort != uint16_t(ReservedPorts::clusterPairControl);
    if (!valid) failure.assign("usage: prepareProductionPair OPERATION_UUID ROUTE_UUID BOUNDARY_UUID SOURCE_DEPLOYMENT_ID TARGET_DEPLOYMENT_ID INGRESS_ADDRESS INGRESS_PORT"_ctv);

    MothershipProductionPairRecord record = {};
    bool existing = false, resumed = false;
    if (valid)
    {
      auto registry = openClusterRegistry(); String readFailure = {};
      if (registry.loadProductionPair(operationUUID, record, &readFailure))
      {
        existing = true;
        valid = record.intent.route.routeUUID == routeUUID &&
            record.intent.physicalBoundaryUUID == boundaryUUID &&
            record.intent.sourceWorkload.deploymentID == sourceDeploymentID &&
            record.intent.targetWorkload.deploymentID == targetDeploymentID &&
            record.intent.selectorAddress == listenerAddress &&
            record.intent.selectorTCPPort == listenerPort;
        if (!valid) failure.assign("production pair retry conflicts with its immutable operation identity"_ctv);
        if (valid && record.phase == MothershipProductionPairPhase::abortedBeforeTransit)
        { failure.assign("production pair was durably aborted before transit; use a new operation UUID"_ctv); valid = false; }
      }
      else if (!readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
    }

    MothershipProdigyCluster source = {}, target = {};
    if (valid && !existing)
    {
      MothershipProductionPairIntent intent = {};
      intent.operationUUID = operationUUID; intent.physicalBoundaryUUID = boundaryUUID;
      intent.selectorAddress = listenerAddress; intent.selectorTCPPort = uint16_t(listenerPort);
      {
        auto registry = openClusterRegistry();
        valid = registry.loadUsableCousinRoute(routeUUID, Time::now<TimeResolution::ms>(), intent.route, &failure) &&
            registry.loadCurrentCousinRouteApplyReceipt(routeUUID, CousinRouteHalf::source,
                                                        intent.sourceRouteReceipt, &failure) &&
            registry.loadCurrentCousinRouteApplyReceipt(routeUUID, CousinRouteHalf::destination,
                                                        intent.destinationRouteReceipt, &failure);
        String sourceIdentity = {}, targetIdentity = {};
        sourceIdentity.assignItoh(intent.route.sourceClusterUUID);
        targetIdentity.assignItoh(intent.route.destinationClusterUUID);
        valid = valid && registry.getClusterByIdentity(sourceIdentity, source, &failure) &&
            registry.getClusterByIdentity(targetIdentity, target, &failure);
      }
      if (valid && (source.deploymentMode == MothershipClusterDeploymentMode::test ||
                    target.deploymentMode == MothershipClusterDeploymentMode::test ||
                    source.nBrains != 3 || target.nBrains != 3))
      { failure.assign("production pair requires two distinct non-test three-Brain clusters"_ctv); valid = false; }
      ProdigyLocalCousinServicePermissionResponse sourcePermission = {}, targetPermission = {};
      DeploymentIdentityReport sourceTransport = {}, targetTransport = {}, sourceWorkload = {}, targetWorkload = {};
      ClusterStatusReport admissionSourceStatus = {}, admissionTargetStatus = {};
      if (valid) valid = readLocalCousinServicePermission(source, intent.route.sourcePermissionUUID,
                                                          sourcePermission, failure) &&
          readLocalCousinServicePermission(target, intent.route.destinationPermissionUUID,
                                            targetPermission, failure);
      if (valid)
      {
        intent.sourcePermission = sourcePermission.permission;
        intent.destinationPermission = targetPermission.permission;
        valid = testPairCousinTransportDeploymentReady(source, intent.sourcePermission, sourceTransport, failure) &&
            testPairCousinTransportDeploymentReady(target, intent.destinationPermission, targetTransport, failure) &&
            productionWorkloadIdentity(source, sourceDeploymentID, intent.sourceWorkload, sourceWorkload, failure) &&
            productionWorkloadIdentity(target, targetDeploymentID, intent.targetWorkload, targetWorkload, failure);
        if (valid)
        {
          valid = productionClusterHealthy(source, admissionSourceStatus, failure) &&
              productionClusterHealthy(target, admissionTargetStatus, failure) &&
              topologyMachineForAddress(admissionSourceStatus, intent.selectorAddress,
                                        intent.selectorMachineUUID);
          if (!valid && failure.empty())
            failure.assign("production ingress address does not resolve to one exact live source machine"_ctv);
        }
        if (valid)
        {
          valid = describePhysicalFaultExecutorBoundary(
              source, intent.selectorMachineUUID, intent.selectorExecutorKind,
              intent.selectorLocalVMBoundaryUUID, intent.selectorCloudID, failure);
          // The ingress proof must originate outside both the relay owner and
          // the source endpoint owner.  A witness on the source workload host
          // can turn a public selector probe into a provider hairpin instead
          // of proving ingress from another admitted machine.
          for (const auto& machine : source.topology.machines)
            if (valid && machine.uuid != intent.selectorMachineUUID &&
                machine.uuid != intent.sourceWorkload.endpointMachineUUID &&
                !topologyMachineOwnsAddress(admissionSourceStatus, machine.uuid,
                                            intent.sourceWorkload.endpointIPv4) &&
                intent.ingressWitnessMachineUUID == 0)
            {
              MothershipPhysicalFaultExecutorKind kind = MothershipPhysicalFaultExecutorKind::localVM;
              uint128_t boundary = 0; String cloudID = {}, candidateFailure = {};
              if (describePhysicalFaultExecutorBoundary(source, machine.uuid, kind, boundary, cloudID, candidateFailure))
              {
                intent.ingressWitnessMachineUUID = machine.uuid;
                intent.ingressWitnessExecutorKind = kind;
                intent.ingressWitnessLocalVMBoundaryUUID = boundary;
                intent.ingressWitnessCloudID = cloudID;
              }
            }
          if (valid && intent.ingressWitnessMachineUUID == 0)
          { failure.assign("production pair requires a distinct admitted topology machine for ingress witnessing"_ctv); valid = false; }
          if (valid) valid = mothershipProductionPairIntentValid(intent, &failure);
        }
      }
      if (valid)
      {
        // Do not make an immutable prepared record until the exact route and
        // its application receipts are freshly observable from both owners.
        // Otherwise a receipt change between discovery and admission can
        // strand an open coordinator which cannot be retried with new facts.
        MothershipProductionPairRecord preflight = {};
        ClusterStatusReport preflightSourceStatus = {}, preflightTargetStatus = {};
        valid = mothershipProductionPairBegin(intent, Time::now<TimeResolution::ms>(),
                                              preflight, &failure) &&
            productionPairTransportReady(preflight, source, target, failure) &&
            productionPairWorkloadsReady(preflight, source, target, true,
                                         preflightSourceStatus, preflightTargetStatus, failure);
      }
      if (valid)
      {
        auto registry = openClusterRegistry();
        valid = registry.admitProductionPair(intent, Time::now<TimeResolution::ms>(), record, resumed, &failure);
      }
    }

    if (valid)
    {
      auto registry = openClusterRegistry();
      String sourceIdentity = {}, targetIdentity = {};
      sourceIdentity.assignItoh(record.intent.route.sourceClusterUUID);
      targetIdentity.assignItoh(record.intent.route.destinationClusterUUID);
      valid = registry.getClusterByIdentity(sourceIdentity, source, &failure) &&
          registry.getClusterByIdentity(targetIdentity, target, &failure);
    }
    ClusterStatusReport sourceStatus = {}, targetStatus = {};
    if (valid) valid = productionPairTransportReady(record, source, target, failure) &&
        productionPairWorkloadsReady(record, source, target, true, sourceStatus, targetStatus, failure);
    if (valid && !topologyMachineOwnsAddress(sourceStatus, record.intent.selectorMachineUUID,
                                             record.intent.selectorAddress))
    {
      failure.assign("production ingress address is not owned by the exact live source machine"_ctv);
      valid = false;
    }

    if (valid && record.phase == MothershipProductionPairPhase::prepared)
    {
      String evidence = {}, receipt = {};
      BitseryEngine::serialize(evidence, targetStatus);
      valid = prodigyComputeSHA256Hex(evidence, receipt, &failure);
      if (valid)
      {
        auto registry = openClusterRegistry();
        valid = registry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::targetAdmitted,
                                               receipt, Time::now<TimeResolution::ms>(), record, resumed, &failure);
      }
    }

    MothershipPhysicalServiceTransitBoundary boundary = {};
    bool selectorLaunchAttemptedDuringPrepare = false;
    if (valid && record.phase == MothershipProductionPairPhase::targetAdmitted)
    {
      String readFailure = {};
      bool boundaryExists = false;
      {
        // TidesDB owns an exclusive process lock.  Do not retain this handle
        // across the remote selector launch or the later phase transition,
        // both of which have their own independently scoped registry writes.
        auto registry = openClusterRegistry();
        boundaryExists = registry.loadPhysicalServiceTransitBoundary(boundaryUUID, boundary, &readFailure);
      }
      if (!boundaryExists)
      {
        if (!readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
        else
        {
          boundary.boundaryUUID = boundaryUUID; boundary.pairOperationUUID = operationUUID;
          boundary.routeUUID = record.intent.route.routeUUID;
          boundary.routeGeneration = record.intent.route.generation;
          boundary.sourceClusterUUID = record.intent.route.sourceClusterUUID;
          boundary.targetClusterUUID = record.intent.route.destinationClusterUUID;
          boundary.sourceMachineUUID = record.intent.selectorMachineUUID;
          boundary.targetMachineUUID = record.intent.targetWorkload.endpointMachineUUID;
          boundary.sourceExecutorKind = record.intent.selectorExecutorKind;
          boundary.sourceLocalVMBoundaryUUID = record.intent.selectorLocalVMBoundaryUUID;
          boundary.sourceCloudID = record.intent.selectorCloudID;
          MothershipPhysicalFaultExecutorKind sourceKind = MothershipPhysicalFaultExecutorKind::localVM;
          uint128_t sourceVMBoundary = 0; String sourceCloudID = {};
          valid = describePhysicalFaultExecutorBoundary(
              source, boundary.sourceMachineUUID, sourceKind,
              sourceVMBoundary, sourceCloudID, failure) &&
              sourceKind == record.intent.selectorExecutorKind &&
              sourceVMBoundary == record.intent.selectorLocalVMBoundaryUUID &&
              sourceCloudID == record.intent.selectorCloudID &&
              describePhysicalFaultExecutorBoundary(
                  target, boundary.targetMachineUUID, boundary.targetExecutorKind,
                  boundary.targetLocalVMBoundaryUUID, boundary.targetCloudID, failure);
          // This boundary models the actual inter-cluster relay leg.  The
          // source-side packets originate on the selector machine, not on the
          // retired workload endpoint behind that selector.
          boundary.sourceAddress = record.intent.selectorAddress;
          boundary.targetAddress = record.intent.targetWorkload.endpointIPv4;
          boundary.sourceTCPPort = record.intent.selectorTCPPort;
          boundary.targetTCPPort = record.intent.targetWorkload.endpointTCPPort;
          boundary.pathMTU = record.intent.route.pathMTU;
          boundary.admittedAtMs = record.transitionedAtMs;
          valid = valid && cousinRouteAuthorizationDigest(record.intent.route, boundary.routeAuthorizationSHA256);
          if (!valid && failure.empty())
            failure.assign("production pair source ingress no longer has its admitted physical executor"_ctv);
        }
      }
      else
      {
        valid = productionPairPhysicalBoundaryReady(record, source, target, boundary, failure);
      }
      if (valid)
      {
        ProductionPairProviderState state = {}; String output = {}, providerEvidence = {}, transitReceipt = {};
        selectorLaunchAttemptedDuringPrepare = true;
        const bool launched = runProductionPairProvider(record, source, "launch", state, output, providerEvidence, failure);
        valid = launched && productionPairSelectorPhaseReceipt(record, MothershipProductionPairPhase::transitApplied,
                                                                state, transitReceipt, failure);
        if (!valid && failure.empty()) failure.assign("production pair provider did not launch in source-selected state"_ctv);
        if (valid && !boundaryExists)
        {
          valid = productionPhysicalBoundaryAdmissionReceipt(record, boundary, sourceStatus, targetStatus,
                                                             transitReceipt,
                                                             boundary.admissionReceiptSHA256, failure) &&
              mothershipPhysicalServiceTransitBoundaryValid(boundary, &failure);
          if (valid)
          {
            auto registry = openClusterRegistry();
            MothershipPhysicalServiceTransitBoundary recordedBoundary = {};
            valid = registry.admitPhysicalServiceTransitBoundary(boundary, recordedBoundary, resumed, &failure);
            if (valid) boundary = std::move(recordedBoundary);
          }
        }
        else if (valid)
        {
          String expectedAdmissionReceipt = {};
          valid = productionPhysicalBoundaryAdmissionReceipt(record, boundary, sourceStatus, targetStatus,
                                                             transitReceipt, expectedAdmissionReceipt, failure) &&
              expectedAdmissionReceipt == boundary.admissionReceiptSHA256;
          if (!valid && failure.empty())
            failure.assign("production pair physical boundary admission evidence changed before transit became durable"_ctv);
        }
        if (valid)
        {
          auto phaseRegistry = openClusterRegistry();
          // advanceProductionPair clears its output on an opening/write
          // failure.  Keep the admitted record intact so the compensation
          // below can still address and remove the provisional selector.
          MothershipProductionPairRecord advancedRecord = {};
          valid = phaseRegistry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::transitApplied,
                                                      transitReceipt, Time::now<TimeResolution::ms>(), advancedRecord, resumed, &failure);
          if (valid) record = std::move(advancedRecord);
        }
      }
    }
    else if (valid && record.phase >= MothershipProductionPairPhase::transitApplied &&
             record.phase < MothershipProductionPairPhase::cleanupComplete)
    {
      auto registry = openClusterRegistry();
      valid = registry.loadPhysicalServiceTransitBoundary(boundaryUUID, boundary, &failure) &&
          productionPairPhysicalBoundaryReady(record, source, target, boundary, failure);
      if (valid)
      {
        ProductionPairProviderState state = {}; String output = {}, providerEvidence = {};
        valid = runProductionPairProvider(record, source, "query", state, output, providerEvidence, failure);
        MothershipProductionPairPhase selectorPhase = record.phase >= MothershipProductionPairPhase::sourceDrained ?
            MothershipProductionPairPhase::sourceDrained :
            (record.phase >= MothershipProductionPairPhase::targetSelected ?
             MothershipProductionPairPhase::targetSelected : MothershipProductionPairPhase::transitApplied);
        if (valid) valid = productionPairSelectorPhaseMatches(record, selectorPhase, state, failure);
      }
    }
    else if (valid && record.phase == MothershipProductionPairPhase::abortBeforeCutoverPending)
    {
      failure.assign("production pair pre-cutover abort is pending; resume abortBeforeCutover"_ctv);
      valid = false;
    }

    // Launch is intentionally provisional until both the physical boundary and
    // durable transit phase commit.  Compensate every later prepare failure;
    // remove is idempotent and leaves only a retry-safe tombstone, never a
    // live relay or a permanently locked selector scope.
    if (!valid && selectorLaunchAttemptedDuringPrepare && record.phase < MothershipProductionPairPhase::transitApplied)
    {
      ProductionPairProviderState aborted = {}; String abortOutput = {}, abortEvidence = {}, abortFailure = {};
      if (!runProductionPairProvider(record, source, "remove", aborted, abortOutput, abortEvidence, abortFailure))
        failure.snprintf<"{}; selector abort failed: {}"_ctv>(failure, abortFailure);
    }

    String operation = {}, boundaryText = {}; operation.assignItoh(operationUUID); boundaryText.assignItoh(boundaryUUID);
    basics_log("prepareProductionPair success=%u resumed=%u operationUUID=%s boundaryUUID=%s phase=%u ingress=%s:%u failure=%s\n",
        unsigned(valid), unsigned(existing || resumed), operation.c_str(), boundaryText.c_str(),
        unsigned(valid ? record.phase : MothershipProductionPairPhase::prepared), listenerAddress.c_str(),
        unsigned(listenerPort), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runRegisterLocalVMBoundary(int argc, char *argv[])
  {
    String failure = {};
    MothershipLocalVMBoundaryDescriptor requested = {}, recorded = {};
    MothershipProdigyCluster cluster = {};
    uint64_t port = 0;
    bool resumed = false;
    bool valid = argc == 10 && prodigyParseCanonicalHex128(String(argv[1]), requested.machineUUID) &&
        requested.machineUUID != 0 && prodigyParseCanonicalHex128(String(argv[2]), requested.vmBoundaryUUID) &&
        requested.vmBoundaryUUID != 0 && mothershipParseUnsignedArgument(argv[5], UINT16_MAX, port) && port != 0;
    if (valid)
    {
      requested.taskID.assign(argv[3]); requested.hostAddress.assign(argv[4]); requested.hostPort = uint16_t(port);
      requested.hostUser.assign(argv[6]); requested.hostPrivateKeyPath.assign(argv[7]);
      requested.hostPublicKeyOpenSSH.assign(argv[8]); requested.statePath.assign(argv[9]);
      String launcherBytes = {};
      launcherBytes.append(reinterpret_cast<const char *>(mothershipLocalVMBoundarySource),
                           sizeof(mothershipLocalVMBoundarySource));
      valid = prodigyComputeSHA256Hex(launcherBytes, requested.executorSHA256, &failure);
      for (uint32_t index = 0; index < 64; ++index) requested.immutableStateSHA256.append('0');
      // A positive placeholder permits structural validation before the
      // registry supplies either the original timestamp or the one new
      // registration timestamp below.
      requested.registeredAtMs = 1;
      if (valid) { auto registry = openClusterRegistry(); valid = registry.getClusterByIdentity(String(argv[0]), cluster, &failure); }
    }
    uint32_t selected = 0;
    if (valid)
    {
      requested.clusterUUID = cluster.clusterUUID;
      for (const auto& machine : cluster.topology.machines)
        if (machine.uuid == requested.machineUUID && machine.kind == MachineConfig::MachineKind::vm && machine.isBrain) ++selected;
      valid = cluster.deploymentMode == MothershipClusterDeploymentMode::local && cluster.nBrains == 3 &&
          cluster.topology.machines.size() == 3 && selected == 1 &&
          mothershipLocalVMBoundaryDescriptorValid(requested, &failure);
      if (!valid && failure.empty())
        failure.assign("local VM boundary registration requires one exact VM in a three-Brain deploymentMode=local cluster"_ctv);
    }
    if (valid)
    {
      MothershipLocalVMBoundaryDescriptor prior = {};
      auto registry = openClusterRegistry(); String readFailure = {};
      if (registry.loadLocalVMBoundary(requested.vmBoundaryUUID, prior, &readFailure))
        requested.registeredAtMs = prior.registeredAtMs;
      else if (readFailure.equal("record not found"_ctv))
        requested.registeredAtMs = Time::now<TimeResolution::ms>();
      else
      { failure = readFailure; valid = false; }
    }
    String immutable = {};
    if (valid) valid = queryLocalVMBoundaryExecutor(requested, immutable, failure);
    if (valid)
    {
      requested.immutableStateSHA256 = immutable;
      auto registry = openClusterRegistry();
      valid = registry.registerLocalVMBoundary(requested, recorded, resumed, &failure);
    }
    basics_log("registerLocalVMBoundary success=%u resumed=%u clusterUUID=%016llx%016llx machineUUID=%016llx%016llx boundaryUUID=%016llx%016llx failure=%s\n",
        unsigned(valid), unsigned(resumed),
        (unsigned long long)(requested.clusterUUID >> 64), (unsigned long long)requested.clusterUUID,
        (unsigned long long)(requested.machineUUID >> 64), (unsigned long long)requested.machineUUID,
        (unsigned long long)(requested.vmBoundaryUUID >> 64), (unsigned long long)requested.vmBoundaryUUID,
        failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runInspectLocalVMBoundaries(int argc, char *argv[])
  {
    String failure = {};
    MothershipProdigyCluster cluster = {};
    Vector<uint128_t> expectedMachineUUIDs = {};
    Vector<MothershipLocalVMBoundaryDescriptor> boundaries = {};
    bool valid = argc == 1;
    if (!valid) failure.assign("usage: inspectLocalVMBoundaries CLUSTER"_ctv);
    if (valid)
    {
      MothershipClusterRegistry registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[0]), cluster, &failure);
      if (valid && (cluster.deploymentMode != MothershipClusterDeploymentMode::local || cluster.nBrains != 3 ||
                    cluster.topology.version == 0 || cluster.topology.machines.size() != 3))
      { failure.assign("local VM boundary inspection requires one exact three-Brain deploymentMode=local topology"_ctv); valid = false; }
      if (valid)
      {
        for (const auto& machine : cluster.topology.machines)
        {
          if (machine.uuid == 0 || machine.kind != MachineConfig::MachineKind::vm || !machine.isBrain)
          { failure.assign("local VM boundary inspection requires three VM Brain machine identities"_ctv); valid = false; break; }
          expectedMachineUUIDs.push_back(machine.uuid);
        }
      }
      if (valid) valid = registry.listLocalVMBoundaries(cluster.clusterUUID, boundaries, &failure) &&
          MothershipClusterRegistry::activeLocalVMBoundariesExactForMachines(
              cluster.clusterUUID, expectedMachineUUIDs, boundaries, &failure);
    }
    // The executor query can create bounded remote query-side effects, but
    // inspection itself never writes the registry or invokes a VM lifecycle action.
    const bool inspectable = valid;
    for (auto& boundary : boundaries)
    {
      if (!inspectable || boundary.retired) continue;
      String boundaryUUID = {}, machineUUID = {}, observedImmutable = {}, observedStarttime = {}, queryFailure = {};
      boundaryUUID.assignItoh(boundary.vmBoundaryUUID);
      machineUUID.assignItoh(boundary.machineUUID);
      uint64_t observedPID = 0;
      bool queried = queryLocalVMBoundaryExecutor(boundary, observedImmutable, queryFailure,
                                                   &observedPID, &observedStarttime);
      const bool boundaryValid = queried && observedImmutable == boundary.immutableStateSHA256;
      valid = valid && boundaryValid;
      if (!boundaryValid && failure.empty())
        failure.assign(queried ? "local VM boundary immutable state changed" :
                                "local VM boundary sealed query failed");
      // Never print the public key: its optional OpenSSH comment is operator
      // supplied and has no diagnostic value for a read-only inspection.
      basics_log("localVMBoundary boundaryUUID=%s machineUUID=%s taskID=%s host=%s:%u hostUser=%s statePath=%s executorSHA256=%s registeredImmutableStateSHA256=%s querySuccess=%u observedImmutableStateSHA256=%s observedPID=%llu observedStarttime=%s\n",
                 boundaryUUID.c_str(), machineUUID.c_str(), boundary.taskID.c_str(),
                 boundary.hostAddress.c_str(), unsigned(boundary.hostPort), boundary.hostUser.c_str(),
                 boundary.statePath.c_str(), boundary.executorSHA256.c_str(), boundary.immutableStateSHA256.c_str(),
                 unsigned(queried), observedImmutable.c_str(), (unsigned long long)observedPID, observedStarttime.c_str());
    }
    String clusterUUID = {}; clusterUUID.assignItoh(cluster.clusterUUID);
    basics_log("inspectLocalVMBoundaries success=%u clusterUUID=%s activeCount=%u result=%s failure=%s\n",
               unsigned(valid), clusterUUID.c_str(), unsigned(expectedMachineUUIDs.size()),
               valid ? "verified" : "failed", failure.c_str());
    if (!valid)
      exit(EXIT_FAILURE);
  }

  static uint32_t localVMClusterLANIPv6ReceiptFailureMask(
      std::string_view interfaceName, std::string_view macView,
      std::string_view subnetView, std::string_view addressView,
      std::string_view dropInView)
  {
    constexpr const char *dropIn =
        "/etc/systemd/network/10-cloud-init-lan0.network.d/50-prodigy-cluster-lan-ipv6.conf";
    const auto exact = [](std::string_view value, const char *expected) {
      return value == std::string_view(expected, std::strlen(expected));
    };
    const auto lowercaseMAC = [](std::string_view value) {
      if (value.size() != 17 || value[0] != '0' || value[1] != '2') return false;
      for (size_t offset = 2; offset < value.size(); ++offset)
      {
        if (offset % 3 == 2) { if (value[offset] != ':') return false; }
        else if (!((value[offset] >= '0' && value[offset] <= '9') ||
                   (value[offset] >= 'a' && value[offset] <= 'f'))) return false;
      }
      return true;
    };
    String subnetText = {}, addressText = {};
    subnetText.assign(subnetView.data(), subnetView.size());
    addressText.assign(addressView.data(), addressView.size());
    IPPrefix subnet = {}, addressPrefix = {};
    const bool subnetParsed = parseCIDRPrefix(subnetText.c_str(), subnet);
    const bool addressParsed = parseCIDRPrefix(addressText.c_str(), addressPrefix);
    const auto slash = std::find(addressText.begin(), addressText.end(), '/');
    String hostAddressText = {};
    if (slash != addressText.end())
      hostAddressText.append(addressText.data(), size_t(slash - addressText.begin()));
    IPAddress hostAddress = {};
    const bool hostParsed = ClusterMachine::parseIPAddressLiteral(hostAddressText, hostAddress);

    uint32_t failures = 0;
    if (!exact(interfaceName, "lan0")) failures |= 1u << 0;
    if (!exact(dropInView, dropIn)) failures |= 1u << 1;
    if (!lowercaseMAC(macView)) failures |= 1u << 2;
    if (!subnetParsed) failures |= 1u << 3;
    if (!addressParsed) failures |= 1u << 4;
    if (!hostParsed) failures |= 1u << 5;
    if (!subnet.network.is6) failures |= 1u << 6;
    if (subnet.cidr != 64) failures |= 1u << 7;
    if (subnet.network.v6[0] != 0xfd) failures |= 1u << 8;
    if (!addressPrefix.network.is6) failures |= 1u << 9;
    if (addressPrefix.cidr != 64) failures |= 1u << 10;
    if (!addressPrefix.equals(subnet)) failures |= 1u << 11;
    if (!hostAddress.is6) failures |= 1u << 12;
    if (hostAddress.equals(subnet.network)) failures |= 1u << 13;
    return failures;
  }

  void runConfigureLocalVMClusterLANIPv6(int argc, char *argv[])
  {
    String failure = {};
    MothershipProdigyCluster cluster = {};
    Vector<uint128_t> expectedMachineUUIDs = {};
    Vector<MothershipLocalVMBoundaryDescriptor> boundaries = {};
    bool valid = argc == 1;
    if (!valid) failure.assign("usage: configureLocalVMClusterLANIPv6 CLUSTER"_ctv);
    if (valid)
    {
      MothershipClusterRegistry registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[0]), cluster, &failure);
      if (valid && (cluster.deploymentMode != MothershipClusterDeploymentMode::local || cluster.nBrains != 3 ||
                    cluster.topology.version == 0 || cluster.topology.machines.size() != 3))
      { failure.assign("cluster LAN IPv6 configuration requires one exact three-Brain deploymentMode=local topology"_ctv); valid = false; }
      if (valid)
      {
        for (const auto& machine : cluster.topology.machines)
        {
          if (machine.uuid == 0 || machine.kind != MachineConfig::MachineKind::vm || !machine.isBrain)
          { failure.assign("cluster LAN IPv6 configuration requires three VM Brain machine identities"_ctv); valid = false; break; }
          expectedMachineUUIDs.push_back(machine.uuid);
        }
      }
      if (valid) valid = registry.listLocalVMBoundaries(cluster.clusterUUID, boundaries, &failure) &&
          MothershipClusterRegistry::activeLocalVMBoundariesExactForMachines(
              cluster.clusterUUID, expectedMachineUUIDs, boundaries, &failure);
    }
    if (valid)
    {
      std::sort(boundaries.begin(), boundaries.end(), [](const auto& left, const auto& right) {
        return left.machineUUID < right.machineUUID;
      });
      for (const auto& boundary : boundaries)
      {
        if (boundary.retired || boundary.taskID != boundaries.front().taskID)
        { failure.assign("cluster LAN IPv6 configuration requires one shared active VM task identity"_ctv); valid = false; break; }
      }
    }

    Vector<uint64_t> observedPIDs = {};
    Vector<String> observedStarttimes = {};
    if (valid)
    {
      // Refresh the embedded launcher binding and prove all three immutable VM
      // boundaries before the first guest network mutation. A retry can safely
      // resume because the sealed action itself is idempotent.
      for (auto& boundary : boundaries)
      {
        if (!reconcileLocalVMBoundaryExecutorBinding(boundary, failure))
        { valid = false; break; }
        String immutable = {}, starttime = {};
        uint64_t pid = 0;
        if (!queryLocalVMBoundaryExecutor(boundary, immutable, failure, &pid, &starttime) ||
            immutable != boundary.immutableStateSHA256)
        {
          if (failure.empty()) failure.assign("cluster LAN IPv6 configuration found changed immutable VM state"_ctv);
          valid = false; break;
        }
        observedPIDs.push_back(pid);
        observedStarttimes.push_back(std::move(starttime));
      }
    }

    String sharedSubnet = {};
    Vector<String> configuredAddresses = {};
    Vector<String> configuredMACs = {};
    uint32_t configured = 0;
    for (uint32_t index = 0; valid && index < boundaries.size(); ++index)
    {
      auto& boundary = boundaries[index];
      Vector<String> arguments = {};
      arguments.emplace_back("configure-cluster-lan-ipv6"_ctv);
      arguments.emplace_back("--state"_ctv); arguments.push_back(boundary.statePath);
      arguments.emplace_back("--task-id"_ctv); arguments.push_back(boundary.taskID);
      String output = {};
      valid = runLocalVMBoundarySealedLauncher(boundary, arguments, 60'000, output, failure);
      if (!valid) break;

      simdjson::dom::parser parser; simdjson::dom::element document;
      if (output.size() > 16_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
          document.type() != simdjson::dom::element_type::OBJECT)
      { failure.assign("cluster LAN IPv6 owner returned malformed receipt"_ctv); valid = false; break; }
      auto object = document.get_object();
      if (object.size() != 5)
      { failure.assign("cluster LAN IPv6 owner returned unsupported receipt schema"_ctv); valid = false; break; }
      for (auto field : object)
      {
        String key = {}; key.setInvariant(field.key.data(), field.key.size());
        if (key != "interface"_ctv && key != "mac"_ctv && key != "subnet"_ctv &&
            key != "address"_ctv && key != "dropIn"_ctv)
        { failure.assign("cluster LAN IPv6 owner receipt contains an unknown field"_ctv); valid = false; break; }
      }
      if (!valid) break;
      std::string_view interfaceName, macView, subnetView, addressView, dropInView;
      if (object["interface"].get(interfaceName) || object["mac"].get(macView) ||
          object["subnet"].get(subnetView) || object["address"].get(addressView) ||
          object["dropIn"].get(dropInView))
      { failure.assign("cluster LAN IPv6 owner receipt has invalid field types"_ctv); valid = false; break; }
      const uint32_t receiptFailures = localVMClusterLANIPv6ReceiptFailureMask(
          interfaceName, macView, subnetView, addressView, dropInView);
      if (receiptFailures != 0)
      {
        failure.snprintf<"cluster LAN IPv6 owner receipt is not one exact private lan0 /64 assignment mask={itoa}"_ctv>(
            uint64_t(receiptFailures));
        valid = false;
        break;
      }
      String subnetText = {}, addressText = {}, mac = {};
      subnetText.assign(subnetView.data(), subnetView.size());
      addressText.assign(addressView.data(), addressView.size());
      mac.assign(macView.data(), macView.size());
      if (!sharedSubnet.empty() && sharedSubnet != subnetText)
      { failure.assign("cluster LAN IPv6 owners derived different task subnets"_ctv); valid = false; break; }
      for (const auto& prior : configuredAddresses)
        if (prior == addressText)
        { failure.assign("cluster LAN IPv6 owners derived duplicate guest addresses"_ctv); valid = false; break; }
      for (const auto& prior : configuredMACs)
        if (prior == mac)
        { failure.assign("cluster LAN IPv6 owners reported duplicate guest MACs"_ctv); valid = false; break; }
      if (!valid) break;

      String immutable = {}, afterStarttime = {}; uint64_t afterPID = 0;
      if (!queryLocalVMBoundaryExecutor(boundary, immutable, failure, &afterPID, &afterStarttime) ||
          immutable != boundary.immutableStateSHA256 || afterPID != observedPIDs[index] ||
          afterStarttime != observedStarttimes[index])
      {
        if (failure.empty()) failure.assign("cluster LAN IPv6 action changed its immutable VM process boundary"_ctv);
        valid = false; break;
      }
      if (sharedSubnet.empty()) sharedSubnet = subnetText;
      configuredAddresses.push_back(addressText);
      configuredMACs.push_back(mac);
      String machineUUID = {}; machineUUID.assignItoh(boundary.machineUUID);
      basics_log("configureLocalVMClusterLANIPv6 memberSuccess=1 machineUUID=%s mac=%s address=%s\n",
                 machineUUID.c_str(), mac.c_str(), addressText.c_str());
      ++configured;
    }

    String clusterUUID = {}; clusterUUID.assignItoh(cluster.clusterUUID);
    basics_log("configureLocalVMClusterLANIPv6 success=%u clusterUUID=%s configured=%u subnet=%s failure=%s\n",
               unsigned(valid), clusterUUID.c_str(), unsigned(configured), sharedSubnet.c_str(), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runRecoverUnreadyLocalClusterMachine(int argc, char *argv[])
  {
    String failure = {};
    uint128_t operationUUID = 0, boundaryUUID = 0, upgradeOperationUUID = 0;
    uint64_t timeout = 0;
    bool valid = argc == 6 && prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[1]), boundaryUUID) && boundaryUUID != 0 &&
        std::strcmp(argv[2], "recover-unready-upgrade") == 0 &&
        mothershipParseUnsignedArgument(argv[3], mothershipLocalVMFaultMaximumRecoveryMilliseconds, timeout) && timeout > 0 &&
        prodigyParseCanonicalHex128(String(argv[4]), upgradeOperationUUID) && upgradeOperationUUID != 0;
    MothershipLocalVMBoundaryDescriptor boundary = {};
    MothershipProdigyCluster cluster = {};
    MothershipUpgradeAdmissionRecord upgradeAdmission = {};
    ProdigyApprovedUpgradeBundle targetBundle = {};
    String targetBundlePath = {}, upgradeAdmissionSHA256 = {}, clusterIdentity = {};
    if (valid)
    {
      {
        auto registry = openClusterRegistry();
        valid = registry.loadLocalVMBoundary(boundaryUUID, boundary, &failure);
        if (valid)
        {
          clusterIdentity.assignItoh(boundary.clusterUUID);
          valid = registry.getClusterByIdentity(clusterIdentity, cluster, &failure);
        }
      }
      if (valid && (boundary.retired || cluster.deploymentMode != MothershipClusterDeploymentMode::local ||
                    cluster.nBrains != 3 || cluster.topology.machines.size() != 3))
      { failure.assign("unready local VM recovery requires an active three-Brain deploymentMode=local boundary"_ctv); valid = false; }
      if (valid) valid = reconcileLocalVMBoundaryExecutorBinding(boundary, failure);
      MachineCpuArchitecture architecture = MachineCpuArchitecture::unknown;
      String targetInput = {}; targetInput.assign(argv[5]);
      if (valid) valid = resolveProdigyBundleTargetArchitecture(clusterIdentity.c_str(), architecture, &failure) &&
          prodigyResolveBundleArtifactInput(targetInput, architecture, targetBundlePath, &failure) &&
          prodigyApproveBundleUpgradeContract(targetBundlePath, targetBundle, &failure);
      if (valid)
      {
        auto registry = openClusterRegistry();
        valid = registry.loadUpgradeAdmission(
            cluster.clusterUUID, upgradeOperationUUID, upgradeAdmission, &failure);
      }
      if (valid)
      {
        String encoded = {}; auto copy = upgradeAdmission;
        valid = BitseryEngine::serialize(encoded, copy) &&
            prodigyComputeSHA256Hex(encoded, upgradeAdmissionSHA256, &failure) &&
            upgradeAdmission.eligible && upgradeAdmission.approvedPath == 1 &&
            upgradeAdmission.targetBundleSHA256 == targetBundle.bundleSHA256 &&
            upgradeAdmission.targetContractSHA256 == targetBundle.contract.contractSHA256;
        if (!valid && failure.empty()) failure.assign("unready local VM recovery differs from its admitted upgrade"_ctv);
      }
    }

    MothershipLocalVMMachineFaultRecord record = {};
    MothershipLocalVMMachineFaultRequest request = {};
    bool resumed = false, alreadyAdmitted = false;
    if (valid)
    {
      auto registry = openClusterRegistry(); String readFailure = {};
      if (registry.loadLocalVMMachineFault(operationUUID, record, &readFailure))
      {
        alreadyAdmitted = true; request = record.request;
        valid = request.protocolVersion == MothershipLocalVMMachineFaultRequest::unreadyUpgradeRecoveryVersion &&
            request.vmBoundaryUUID == boundaryUUID && request.clusterUUID == cluster.clusterUUID &&
            request.machineUUID == boundary.machineUUID &&
            request.action == MothershipLocalVMMachineFaultAction::recoverUnreadyUpgrade &&
            request.durationMilliseconds == timeout && request.upgradeOperationUUID == upgradeOperationUUID &&
            request.targetBundleSHA256 == targetBundle.bundleSHA256 &&
            request.targetContractSHA256 == targetBundle.contract.contractSHA256 &&
            request.upgradeAdmissionSHA256 == upgradeAdmissionSHA256 &&
            request.expectedBoundarySHA256 == boundary.immutableStateSHA256;
        if (!valid) failure.assign("unready local VM recovery retry conflicts with its durable request"_ctv);
      }
      else if (!readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
    }
    if (valid && alreadyAdmitted && record.hasReceipt)
    {
      basics_log("faultLocalClusterMachine success=1 resumed=1 restored=1 inventoryComplete=1 freshUpgradeAdmissionRequired=1 mode=recover-unready-upgrade operationUUID=%016llx%016llx boundaryUUID=%016llx%016llx failure=\n",
          (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
          (unsigned long long)(boundaryUUID >> 64), (unsigned long long)boundaryUUID);
      return;
    }

    LocalVMGuestLinuxIdentity beforeGuest = {};
    MothershipPhysicalFaultMachineObservation before = {};
    ProdigyUpgradeAdmissionReportRequest observationRequest = {};
    if (valid && !alreadyAdmitted)
    {
      String immutable = {}, starttime = {}; uint64_t pid = 0;
      valid = queryLocalVMBoundaryExecutor(boundary, immutable, failure, &pid, &starttime) &&
          immutable == boundary.immutableStateSHA256 &&
          queryLocalVMBoundaryGuestLinuxIdentity(boundary, beforeGuest, failure) &&
          beforeGuest.qemuPID == pid && beforeGuest.qemuStarttime == starttime;
      if (!valid && failure.empty()) failure.assign("unready local VM recovery could not bind the exact live guest process"_ctv);
      ClusterStatusReport beforeReport = {};
      if (valid) valid = readManagedClusterStatus(cluster, beforeReport, failure) &&
          physicalFaultUnreadyMachineObservation(beforeReport, cluster.clusterUUID,
                                                 boundary.machineUUID, before, failure);
      String clusterIdentity = {}; clusterIdentity.assignItoh(cluster.clusterUUID);
      if (valid) valid = configureControlTarget(clusterIdentity.c_str(), &failure);
      observationRequest.operationID.assignItoh(upgradeOperationUUID);
      observationRequest.targetBundleSHA256 = targetBundle.bundleSHA256;
      observationRequest.targetContractSHA256 = targetBundle.contract.contractSHA256;
      observationRequest.requiredStagingBytes = targetBundle.contract.requiredFreeBytes;
      MothershipUpgradeAdmissionReport preRecovery = {};
      if (valid) valid = requestUpgradeAdmissionReport(observationRequest, preRecovery, failure) &&
          mothershipLocalVMUnreadyUpgradePreRecoveryReportValid(
              preRecovery, upgradeAdmission, cluster, boundary.machineUUID, &failure);
      if (valid)
      {
        request.protocolVersion = MothershipLocalVMMachineFaultRequest::unreadyUpgradeRecoveryVersion;
        request.operationUUID = operationUUID; request.vmBoundaryUUID = boundaryUUID;
        request.clusterUUID = cluster.clusterUUID; request.machineUUID = boundary.machineUUID;
        request.action = MothershipLocalVMMachineFaultAction::recoverUnreadyUpgrade;
        request.durationMilliseconds = uint32_t(timeout); request.expectedBootSHA256 = before.stateSHA256;
        request.upgradeOperationUUID = upgradeOperationUUID;
        request.targetBundleSHA256 = targetBundle.bundleSHA256;
        request.targetContractSHA256 = targetBundle.contract.contractSHA256;
        request.upgradeAdmissionSHA256 = upgradeAdmissionSHA256;
        request.expectedBoundarySHA256 = boundary.immutableStateSHA256;
        request.expectedLinuxMachineID = beforeGuest.machineID;
        request.expectedLinuxBootID = beforeGuest.bootID;
        request.expectedQemuPID = beforeGuest.qemuPID;
        request.expectedQemuStarttime = beforeGuest.qemuStarttime;
        request.incompleteObservationReceiptVersion = preRecovery.observationReceiptVersion;
        auto registry = openClusterRegistry();
        valid = registry.admitLocalVMMachineFault(request, before, record, resumed, &failure);
      }
    }
    else if (valid)
    {
      before = record.admission;
      observationRequest.operationID.assignItoh(request.upgradeOperationUUID);
      observationRequest.targetBundleSHA256 = request.targetBundleSHA256;
      observationRequest.targetContractSHA256 = request.targetContractSHA256;
      observationRequest.requiredStagingBytes = targetBundle.contract.requiredFreeBytes;
    }

    uint64_t faultedAt = 0, executorRestoredAt = 0;
    bool rebooted = false;
    if (valid)
    {
      valid = runLocalVMBoundaryExecutorAction(boundary, operationUUID, "cold-reboot",
                                               uint32_t(timeout), faultedAt, executorRestoredAt, failure);
      rebooted = valid;
    }
    LocalVMGuestLinuxIdentity afterGuest = {};
    String afterImmutable = {}, afterStarttime = {}; uint64_t afterPID = 0;
    if (valid) valid = queryLocalVMBoundaryExecutor(boundary, afterImmutable, failure, &afterPID, &afterStarttime) &&
        afterImmutable == request.expectedBoundarySHA256 &&
        queryLocalVMBoundaryGuestLinuxIdentity(boundary, afterGuest, failure) &&
        afterGuest.qemuPID == afterPID && afterGuest.qemuStarttime == afterStarttime &&
        afterGuest.machineID == request.expectedLinuxMachineID &&
        afterGuest.bootID != request.expectedLinuxBootID &&
        (afterGuest.qemuPID != request.expectedQemuPID ||
         afterGuest.qemuStarttime != request.expectedQemuStarttime);
    if (!valid && rebooted && failure.empty())
      failure.assign("unready local VM recovery did not prove a distinct guest boot on the unchanged boundary"_ctv);

    MothershipPhysicalFaultMachineObservation after = {};
    const int64_t deadline = Time::now<TimeResolution::ms>() + int64_t(timeout);
    while (valid && Time::now<TimeResolution::ms>() <= deadline)
    {
      ClusterStatusReport afterReport = {}; String observationFailure = {};
      if (readManagedClusterStatus(cluster, afterReport, observationFailure) &&
          physicalFaultMachineObservation(afterReport, cluster.clusterUUID,
                                          boundary.machineUUID, after, observationFailure) &&
          after.stateSHA256 != request.expectedBootSHA256) break;
      after = {}; ::usleep(500'000);
    }
    if (valid && !mothershipPhysicalFaultMachineObservationValid(after))
    { failure.assign("unready local VM recovery did not restore one healthy commissioned Brain before its deadline"_ctv); valid = false; }

    MothershipUpgradeAdmissionReport completed = {};
    String completedReportSHA256 = {};
    if (valid) valid = requestUpgradeAdmissionReport(observationRequest, completed, failure) &&
        localVMUnreadyUpgradeReportValid(completed, upgradeAdmission, cluster,
                                         boundary.machineUUID, true,
                                         request.incompleteObservationReceiptVersion, failure) &&
        hashUpgradeAdmissionReport(completed, completedReportSHA256, failure);
    MothershipLocalVMMachineFaultReceipt receipt = {};
    if (valid)
    {
      receipt.protocolVersion = MothershipLocalVMMachineFaultReceipt::unreadyUpgradeRecoveryVersion;
      receipt.operationUUID = operationUUID; receipt.vmBoundaryUUID = boundaryUUID;
      receipt.before = record.admission; receipt.after = after;
      receipt.restoredBootSHA256 = after.stateSHA256;
      receipt.faultedAtMonotonicMilliseconds = faultedAt;
      receipt.restoredAtMonotonicMilliseconds = executorRestoredAt;
      receipt.restored = true;
      receipt.beforeLinuxMachineID = request.expectedLinuxMachineID;
      receipt.beforeLinuxBootID = request.expectedLinuxBootID;
      receipt.beforeQemuPID = request.expectedQemuPID;
      receipt.beforeQemuStarttime = request.expectedQemuStarttime;
      receipt.afterLinuxMachineID = afterGuest.machineID;
      receipt.afterLinuxBootID = afterGuest.bootID;
      receipt.afterQemuPID = afterGuest.qemuPID;
      receipt.afterQemuStarttime = afterGuest.qemuStarttime;
      receipt.completedObservationReceiptVersion = completed.observationReceiptVersion;
      receipt.completedUpgradeReportSHA256 = completedReportSHA256;
      auto registry = openClusterRegistry();
      valid = registry.recordLocalVMMachineFaultReceipt(request, receipt, record, resumed, &failure);
    }
    basics_log("faultLocalClusterMachine success=%u resumed=%u restored=%u inventoryComplete=%u freshUpgradeAdmissionRequired=%u mode=recover-unready-upgrade operationUUID=%016llx%016llx boundaryUUID=%016llx%016llx failure=%s\n",
        unsigned(valid), unsigned(resumed), unsigned(rebooted), unsigned(valid && record.hasReceipt),
        unsigned(valid && record.hasReceipt),
        (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
        (unsigned long long)(boundaryUUID >> 64), (unsigned long long)boundaryUUID, failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runFaultLocalClusterMachine(int argc, char *argv[])
  {
    if (argc == 6 && std::strcmp(argv[2], "recover-unready-upgrade") == 0)
    { runRecoverUnreadyLocalClusterMachine(argc, argv); return; }
    String failure = {};
    uint128_t operationUUID = 0, boundaryUUID = 0;
    uint64_t timeout = 0;
    bool valid = argc == 4 && prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[1]), boundaryUUID) && boundaryUUID != 0 &&
        std::strcmp(argv[2], "cold-reboot") == 0 &&
        mothershipParseUnsignedArgument(argv[3], mothershipLocalVMFaultMaximumRecoveryMilliseconds, timeout) && timeout > 0;
    MothershipLocalVMBoundaryDescriptor boundary = {};
    MothershipProdigyCluster cluster = {};
    MothershipLocalVMMachineFaultRecord record = {};
    bool resumed = false;
    if (valid)
    {
      auto registry = openClusterRegistry();
      String clusterIdentity = {};
      valid = registry.loadLocalVMBoundary(boundaryUUID, boundary, &failure);
      if (valid)
      {
        clusterIdentity.assignItoh(boundary.clusterUUID);
        valid = registry.getClusterByIdentity(clusterIdentity, cluster, &failure);
      }
    }
    if (valid && (boundary.retired || cluster.deploymentMode != MothershipClusterDeploymentMode::local ||
                  cluster.nBrains != 3 || cluster.topology.machines.size() != 3))
    { failure.assign("local VM fault requires an active three-Brain deploymentMode=local boundary"_ctv); valid = false; }

    ClusterStatusReport beforeReport = {};
    MothershipPhysicalFaultMachineObservation before = {}, after = {};
    if (valid) valid = readManagedClusterStatus(cluster, beforeReport, failure) &&
        physicalFaultMachineObservation(beforeReport, cluster.clusterUUID, boundary.machineUUID, before, failure);

    MothershipLocalVMMachineFaultRequest request = {};
    bool alreadyAdmitted = false;
    if (valid)
    {
      auto registry = openClusterRegistry(); String readFailure = {};
      if (registry.loadLocalVMMachineFault(operationUUID, record, &readFailure))
      {
        alreadyAdmitted = true; request = record.request;
        valid = request.vmBoundaryUUID == boundaryUUID && request.clusterUUID == cluster.clusterUUID &&
            request.machineUUID == boundary.machineUUID && request.action == MothershipLocalVMMachineFaultAction::coldReboot &&
            request.durationMilliseconds == timeout;
        if (!valid) failure.assign("local VM fault retry conflicts with its durable request"_ctv);
      }
      else if (!readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
    }
    if (valid && alreadyAdmitted && record.hasReceipt)
    {
      basics_log("faultLocalClusterMachine success=1 resumed=1 restored=1 operationUUID=%016llx%016llx boundaryUUID=%016llx%016llx failure=\n",
          (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
          (unsigned long long)(boundaryUUID >> 64), (unsigned long long)boundaryUUID);
      return;
    }
    if (valid && !alreadyAdmitted)
    {
      request.operationUUID = operationUUID; request.vmBoundaryUUID = boundaryUUID;
      request.clusterUUID = cluster.clusterUUID; request.machineUUID = boundary.machineUUID;
      request.action = MothershipLocalVMMachineFaultAction::coldReboot;
      request.durationMilliseconds = uint32_t(timeout); request.expectedBootSHA256 = before.stateSHA256;
      auto registry = openClusterRegistry();
      valid = registry.admitLocalVMMachineFault(request, before, record, resumed, &failure);
    }
    else if (valid && before.stateSHA256 != request.expectedBootSHA256)
    {
      // The exact executor operation is idempotent, so asking it again only
      // returns the original durable reboot receipt.
      resumed = true;
    }

    uint64_t faultedAt = 0, executorRestoredAt = 0;
    if (valid) valid = runLocalVMBoundaryExecutorAction(boundary, operationUUID, "cold-reboot",
                                                        uint32_t(timeout), faultedAt, executorRestoredAt, failure);
    const int64_t deadline = Time::now<TimeResolution::ms>() + int64_t(timeout);
    while (valid && Time::now<TimeResolution::ms>() <= deadline)
    {
      ClusterStatusReport afterReport = {}; String observationFailure = {};
      if (readManagedClusterStatus(cluster, afterReport, observationFailure) &&
          physicalFaultMachineObservation(afterReport, cluster.clusterUUID, boundary.machineUUID, after, observationFailure) &&
          after.stateSHA256 != request.expectedBootSHA256) break;
      after = {}; ::usleep(500'000);
    }
    if (valid && !mothershipPhysicalFaultMachineObservationValid(after))
    { failure.assign("local VM fault did not recover as a new healthy boot before its deadline"_ctv); valid = false; }
    String immutable = {};
    if (valid) valid = queryLocalVMBoundaryExecutor(boundary, immutable, failure) &&
        immutable == boundary.immutableStateSHA256;
    if (valid && immutable != boundary.immutableStateSHA256)
    { failure.assign("local VM boundary immutable identity changed across cold reboot"_ctv); valid = false; }
    MothershipLocalVMMachineFaultReceipt receipt = {};
    if (valid)
    {
      receipt.operationUUID = operationUUID; receipt.vmBoundaryUUID = boundaryUUID;
      receipt.before = record.admission;
      receipt.after = after; receipt.restoredBootSHA256 = after.stateSHA256;
      receipt.faultedAtMonotonicMilliseconds = faultedAt;
      receipt.restoredAtMonotonicMilliseconds = executorRestoredAt;
      receipt.restored = true;
      auto registry = openClusterRegistry(); valid = registry.recordLocalVMMachineFaultReceipt(
          request, receipt, record, resumed, &failure);
    }
    basics_log("faultLocalClusterMachine success=%u resumed=%u restored=%u operationUUID=%016llx%016llx boundaryUUID=%016llx%016llx failure=%s\n",
        unsigned(valid), unsigned(resumed), unsigned(valid && record.hasReceipt),
        (unsigned long long)(operationUUID >> 64), (unsigned long long)operationUUID,
        (unsigned long long)(boundaryUUID >> 64), (unsigned long long)boundaryUUID, failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  struct PhysicalFaultProviderRequest {
    uint128_t operationUUID = 0;
    const char *role = nullptr;
    uint128_t guestUUID = 0;
    String peerAddress;
    String gatewayEndpoint;
    String flowTarget;
    String flowIdentity;
    uint32_t durationMilliseconds = 0;
  };

  struct PhysicalFaultProviderReceipt {
    bool active = false;
    bool restored = false;
    uint64_t installedAtMonotonicMs = 0;
    uint64_t autoRestoreDeadlineMonotonicMs = 0;
    uint64_t restoredAtMonotonicMs = 0;
  };

  static bool physicalFaultProviderRequestValid(const PhysicalFaultProviderRequest& request,
                                                String& failure)
  {
    if (request.operationUUID == 0 || request.role == nullptr ||
        (std::strcmp(request.role, "source") != 0 && std::strcmp(request.role, "target") != 0) ||
        request.guestUUID == 0 || !mothershipPhysicalFaultNumericAddressValid(request.peerAddress) ||
        !mothershipPhysicalFaultNumericAddressValid(request.gatewayEndpoint) ||
        request.flowTarget.empty() || !mothershipPhysicalFaultFlowIdentityValid(request.flowIdentity) ||
        request.durationMilliseconds == 0 ||
        request.durationMilliseconds > mothershipPhysicalFaultMaximumDurationMilliseconds)
    { failure.assign("physical fault provider request lacks one exact authenticated lifecycle identity"_ctv); return false; }
    return true;
  }

  static bool physicalFaultProviderIdentityMatches(
      std::string_view operation, std::string_view observedRole, std::string_view guest,
      std::string_view peer, std::string_view gateway, std::string_view flowTarget,
      std::string_view flowIdentity, uint64_t duration, std::string_view boot,
      const PhysicalFaultProviderRequest& request)
  {
    String expectedOperation = {}, expectedGuest = {};
    mothershipAssignProviderHex128(request.operationUUID, expectedOperation);
    mothershipAssignProviderHex128(request.guestUUID, expectedGuest);
    const auto equal = [](std::string_view observed, const String& expected) {
      return observed.size() == expected.size() &&
          (!observed.empty() || std::memcmp(observed.data(), expected.data(), observed.size()) == 0);
    };
    return equal(operation, expectedOperation) && observedRole == request.role && equal(guest, expectedGuest) &&
        equal(peer, request.peerAddress) && equal(gateway, request.gatewayEndpoint) &&
        equal(flowTarget, request.flowTarget) && equal(flowIdentity, request.flowIdentity) &&
        duration == request.durationMilliseconds && !boot.empty();
  }

  bool parsePhysicalFaultProviderReceipt(const String& output,
                                         const PhysicalFaultProviderRequest& request,
                                         bool allowActive, bool allowTerminal,
                                         PhysicalFaultProviderReceipt& receipt, String& failure)
  {
    receipt = {};
    if (!physicalFaultProviderRequestValid(request, failure)) return false;
    simdjson::dom::parser parser; simdjson::dom::element document;
    if (output.size() > 16_KB || parser.parse(output.data(), output.size()).get(document) != simdjson::SUCCESS ||
        document.type() != simdjson::dom::element_type::OBJECT)
    { failure.assign("physical fault provider returned malformed JSON"_ctv); return false; }
    auto object = document.get_object();
    std::string_view operation, observedRole, guest, peer, gateway, target, identity, boot, phase;
    uint64_t duration = 0, installed = 0, deadline = 0, restoredAt = 0, routeMetric = 0;
    bool didRestore = false, authenticated = false;
    // Active and terminal receipts intentionally have disjoint exact schemas.
    // This rejects accidental acceptance of a future provider field as proof.
    const bool active = object.size() == 15 && !object["phase"].get(phase) &&
        phase == "applied" && !object["routeMetric"].get(routeMetric) &&
        !object["authenticated"].get(authenticated) && authenticated;
    const bool terminal = object.size() == 13 && !object["restoredAtMonotonicMs"].get(restoredAt);
    if ((!active && !terminal) || object["operationID"].get(operation) || object["role"].get(observedRole) ||
        object["guestID"].get(guest) || object["peerAddress"].get(peer) ||
        object["gatewayEndpoint"].get(gateway) || object["flowTarget"].get(target) ||
        object["flowIdentity"].get(identity) || object["durationMilliseconds"].get(duration) ||
        object["bootID"].get(boot) || object["installedAtMonotonicMs"].get(installed) ||
        object["autoRestoreDeadlineMonotonicMs"].get(deadline) || object["restored"].get(didRestore) ||
        !physicalFaultProviderIdentityMatches(operation, observedRole, guest, peer, gateway, target, identity,
                                              duration, boot, request) || installed == 0 || deadline < installed ||
        deadline - installed != request.durationMilliseconds || (active && didRestore) ||
        (terminal && (!didRestore || restoredAt < installed)))
    { failure.assign("physical fault provider receipt conflicts with its exact lifecycle request"_ctv); return false; }
    if (active && !allowActive) { failure.assign("physical fault provider returned active receipt at terminal boundary"_ctv); return false; }
    if (terminal && !allowTerminal) { failure.assign("physical fault provider returned terminal receipt before cleanup boundary"_ctv); return false; }
    if (terminal && restoredAt > deadline + mothershipPhysicalFaultRestorationSlackMilliseconds)
    { failure.assign("physical fault terminal receipt exceeds its bounded restoration deadline"_ctv); return false; }
    receipt.active = active; receipt.restored = terminal;
    receipt.installedAtMonotonicMs = installed; receipt.autoRestoreDeadlineMonotonicMs = deadline;
    receipt.restoredAtMonotonicMs = restoredAt;
    return true;
  }

  bool describePhysicalFaultExecutorBoundary(
      const MothershipProdigyCluster& cluster, uint128_t machineUUID,
      MothershipPhysicalFaultExecutorKind& kind, uint128_t& localVMBoundaryUUID,
      String& cloudID, String& failure)
  {
    localVMBoundaryUUID = 0; cloudID.clear();
    uint32_t topologyMatches = 0;
    const ClusterMachine *topologyMachine = nullptr;
    for (const auto& machine : cluster.topology.machines)
      if (machine.uuid == machineUUID) { ++topologyMatches; topologyMachine = &machine; }
    if (topologyMatches != 1)
    { failure.assign("physical fault target is absent or ambiguous in durable topology"_ctv); return false; }
    if (cluster.deploymentMode == MothershipClusterDeploymentMode::local)
    {
      MothershipLocalVMBoundaryDescriptor boundary = {};
      auto registry = openClusterRegistry();
      if (!registry.findActiveLocalVMBoundary(cluster.clusterUUID, machineUUID, boundary, &failure)) return false;
      String immutable = {};
      if (!queryLocalVMBoundaryExecutor(boundary, immutable, failure) ||
          immutable != boundary.immutableStateSHA256)
      { if (failure.empty()) failure.assign("local fault endpoint no longer has its exact verified VM boundary"_ctv); return false; }
      kind = MothershipPhysicalFaultExecutorKind::localVM;
      localVMBoundaryUUID = boundary.vmBoundaryUUID;
      return true;
    }
    if (cluster.deploymentMode != MothershipClusterDeploymentMode::remote ||
        !mothershipClusterProviderIsIaaS(cluster.provider) || topologyMachine == nullptr ||
        topologyMachine->kind != MachineConfig::MachineKind::vm ||
        topologyMachine->backing != ClusterMachineBacking::cloud ||
        topologyMachine->cloud.cloudID.empty() || topologyMachine->ssh.address.empty() ||
        topologyMachine->ssh.port == 0 || topologyMachine->ssh.user != "root"_ctv ||
        topologyMachine->ssh.hostPublicKeyOpenSSH.empty())
    { failure.assign("physical fault target is neither a registered local VM nor a root-managed provider cloud VM"_ctv); return false; }
    kind = MothershipPhysicalFaultExecutorKind::providerCloudVM;
    cloudID = topologyMachine->cloud.cloudID;
    return true;
  }

  bool resolvePhysicalFaultExecutor(
      const MothershipProdigyCluster& cluster, uint128_t machineUUID,
      MothershipPhysicalFaultExecutorKind expectedKind, uint128_t expectedLocalVMBoundaryUUID,
      const String& expectedCloudID, MothershipProdigyClusterMachine& executor,
      String& failure)
  {
    executor = {};
    MothershipPhysicalFaultExecutorKind observedKind = MothershipPhysicalFaultExecutorKind::localVM;
    uint128_t observedBoundaryUUID = 0; String observedCloudID = {};
    if (!describePhysicalFaultExecutorBoundary(cluster, machineUUID, observedKind,
                                               observedBoundaryUUID, observedCloudID, failure) ||
        observedKind != expectedKind || observedBoundaryUUID != expectedLocalVMBoundaryUUID ||
        observedCloudID != expectedCloudID)
    {
      if (failure.empty()) failure.assign("physical fault executor no longer matches its admitted isolation boundary"_ctv);
      return false;
    }
    uint32_t matches = 0;
    for (const auto& machine : cluster.topology.machines)
      if (machine.uuid == machineUUID)
      {
        executor.ssh = machine.ssh;
        ++matches;
      }
    if (matches != 1 || executor.ssh.address.empty() || executor.ssh.port == 0 ||
        executor.ssh.user.empty() || executor.ssh.hostPublicKeyOpenSSH.empty())
    { failure.assign("physical fault target has no exact pinned guest SSH execution boundary"_ctv); return false; }
    return true;
  }

  void physicalFaultProviderArguments(const char *command, const PhysicalFaultProviderRequest& request,
                                      Vector<String>& arguments)
  {
    String operation = {}, guest = {}, duration = {};
    mothershipAssignProviderHex128(request.operationUUID, operation);
    mothershipAssignProviderHex128(request.guestUUID, guest);
    duration.assignItoa(request.durationMilliseconds);
    arguments.clear(); arguments.emplace_back(command);
    arguments.emplace_back("--state-root"_ctv); arguments.emplace_back("/var/lib/prodigy/mothership-physical-faults"_ctv);
    arguments.emplace_back("--operation-id"_ctv); arguments.push_back(operation);
    arguments.emplace_back("--role"_ctv); arguments.emplace_back(request.role);
    arguments.emplace_back("--guest-id"_ctv); arguments.push_back(guest);
    arguments.emplace_back("--peer-address"_ctv); arguments.push_back(request.peerAddress);
    arguments.emplace_back("--duration-ms"_ctv); arguments.push_back(duration);
    arguments.emplace_back("--gateway-endpoint"_ctv); arguments.push_back(request.gatewayEndpoint);
    arguments.emplace_back("--flow-target"_ctv); arguments.push_back(request.flowTarget);
    arguments.emplace_back("--flow-identity"_ctv); arguments.push_back(request.flowIdentity);
  }

  bool runPhysicalFaultProviderLifecycle(const MothershipProdigyCluster& cluster,
                                         MothershipPhysicalFaultExecutorKind executorKind,
                                         uint128_t localVMBoundaryUUID, const String& cloudID,
                                         const char *command, const PhysicalFaultProviderRequest& request,
                                         bool allowActive, bool allowTerminal,
                                         PhysicalFaultProviderReceipt& receipt, String& failure)
  {
    if (!physicalFaultProviderRequestValid(request, failure)) return false;
    MothershipProdigyClusterMachine executor = {};
    if (!resolvePhysicalFaultExecutor(cluster, request.guestUUID, executorKind, localVMBoundaryUUID,
                                      cloudID, executor, failure)) return false;
    Vector<String> arguments = {}; physicalFaultProviderArguments(command, request, arguments);
    String output = {};
    if (!mothershipRunRemoteSealedPythonProvider(
          cluster, executor, "mothership-physical-fault-upload",
          mothershipPhysicalFaultProviderSource, sizeof(mothershipPhysicalFaultProviderSource),
          arguments, int(request.durationMilliseconds + 30'000), output, failure)) return false;
    return parsePhysicalFaultProviderReceipt(output, request, allowActive, allowTerminal, receipt, failure);
  }

  bool runPhysicalFaultProvider(const MothershipProdigyCluster& cluster, uint128_t operationUUID,
                                const char *role, uint128_t guestUUID, const String& peerAddress,
                                uint32_t durationMilliseconds,
                                MothershipPhysicalFaultExecutorKind executorKind,
                                uint128_t localVMBoundaryUUID, const String& cloudID,
                                PhysicalFaultProviderReceipt& receipt, String& failure)
  {
    // Legacy faultClusterNetwork remains terminal: it invokes the reusable
    // lifecycle in order, leaving a qualification owner free to put workload
    // and convergence checks between apply and remove.
    PhysicalFaultProviderRequest request = {};
    request.operationUUID = operationUUID; request.role = role; request.guestUUID = guestUUID;
    request.peerAddress = peerAddress; request.gatewayEndpoint = peerAddress;
    request.flowTarget = "peer-host"_ctv; request.flowIdentity = "host:"_ctv;
    request.flowIdentity.append(peerAddress); request.durationMilliseconds = durationMilliseconds;
    PhysicalFaultProviderReceipt applied = {}, observed = {};
    if (!runPhysicalFaultProviderLifecycle(cluster, executorKind, localVMBoundaryUUID, cloudID,
                                           "apply", request, true, false, applied, failure) ||
        !runPhysicalFaultProviderLifecycle(cluster, executorKind, localVMBoundaryUUID, cloudID,
                                           "query", request, true, true, observed, failure)) return false;
    if (observed.restored) { receipt = observed; return true; }
    ::usleep(useconds_t(durationMilliseconds) * 1000);
    if (!runPhysicalFaultProviderLifecycle(cluster, executorKind, localVMBoundaryUUID, cloudID,
                                           "query", request, true, true, observed, failure)) return false;
    // remove is idempotent, so a deadline-driven terminal query is still
    // followed by a terminal cleanup receipt from the exact same operation.
    return runPhysicalFaultProviderLifecycle(cluster, executorKind, localVMBoundaryUUID, cloudID,
                                             "remove", request, false, true, receipt, failure);
  }

  void runFaultClusterNetwork(int argc, char *argv[])
  {
    String failure = {}, directionText = argc > 2 ? String(argv[2]) : String();
    uint128_t operationUUID = 0, boundaryUUID = 0; uint64_t duration = 0;
    MothershipPhysicalFaultDirection direction = MothershipPhysicalFaultDirection::both;
    bool validDirection = directionText == "both"_ctv || directionText == "source-to-target"_ctv ||
        directionText == "target-to-source"_ctv;
    if (directionText == "source-to-target"_ctv) direction = MothershipPhysicalFaultDirection::sourceToTarget;
    else if (directionText == "target-to-source"_ctv) direction = MothershipPhysicalFaultDirection::targetToSource;
    bool valid = argc == 4 && validDirection &&
        prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[1]), boundaryUUID) && boundaryUUID != 0 &&
        mothershipParseUnsignedArgument(argv[3], mothershipPhysicalFaultMaximumDurationMilliseconds, duration) && duration != 0;
    if (!valid) failure.assign("usage: faultClusterNetwork OPERATION_UUID BOUNDARY_UUID both|source-to-target|target-to-source DURATION_MS"_ctv);
    MothershipPhysicalServiceTransitBoundary boundary = {};
    MothershipProductionPairRecord pair = {};
    MothershipProdigyCluster source = {}, target = {};
    MothershipPhysicalClusterNetworkFaultRecord record = {};
    bool resumed = false, existingFault = false;
    if (valid)
    {
      auto registry = openClusterRegistry(); String readFailure = {};
      String sourceIdentity = {}, targetIdentity = {};
      valid = registry.loadPhysicalServiceTransitBoundary(boundaryUUID, boundary, &failure) && !boundary.closed &&
          registry.loadProductionPair(boundary.pairOperationUUID, pair, &failure) &&
          pair.phase >= MothershipProductionPairPhase::transitApplied &&
          pair.phase < MothershipProductionPairPhase::cleanupComplete;
      sourceIdentity.assignItoh(boundary.sourceClusterUUID);
      targetIdentity.assignItoh(boundary.targetClusterUUID);
      valid = valid && registry.getClusterByIdentity(sourceIdentity, source, &failure) &&
          registry.getClusterByIdentity(targetIdentity, target, &failure);
      if (valid && registry.loadPhysicalClusterNetworkFault(operationUUID, record, &readFailure))
      {
        existingFault = true;
      }
      else if (valid && !readFailure.empty() && !readFailure.equal("record not found"_ctv))
      { failure = readFailure; valid = false; }
    }

    ClusterStatusReport sourceReport = {}, targetReport = {};
    MothershipPhysicalFaultMachineObservation sourceBefore = {}, targetBefore = {}, sourceAfter = {}, targetAfter = {};
    if (valid) valid = productionPairTransportReady(pair, source, target, failure) &&
        readManagedClusterStatus(source, sourceReport, failure) &&
        topologyMachineOwnsAddress(sourceReport, boundary.sourceMachineUUID, pair.intent.selectorAddress) &&
        physicalFaultMachineObservation(sourceReport, source.clusterUUID, boundary.sourceMachineUUID, sourceBefore, failure) &&
        readManagedClusterStatus(target, targetReport, failure) &&
        topologyMachineOwnsAddress(targetReport, boundary.targetMachineUUID, boundary.targetAddress) &&
        physicalFaultMachineObservation(targetReport, target.clusterUUID, boundary.targetMachineUUID, targetBefore, failure);
    if (!valid && failure.empty()) failure.assign("physical fault selector or target endpoint no longer owns its admitted address"_ctv);
    MothershipPhysicalClusterNetworkFaultRequest request = {};
    if (valid)
    {
      request.operationUUID = operationUUID; request.boundaryUUID = boundaryUUID;
      request.sourceClusterUUID = boundary.sourceClusterUUID; request.targetClusterUUID = boundary.targetClusterUUID;
      request.sourceMachineUUID = boundary.sourceMachineUUID; request.targetMachineUUID = boundary.targetMachineUUID;
      request.direction = direction; request.durationMilliseconds = uint32_t(duration);
      request.routeUUID = boundary.routeUUID; request.routeGeneration = boundary.routeGeneration;
      request.routeAuthorizationSHA256 = boundary.routeAuthorizationSHA256;
      request.sourceAddress = boundary.sourceAddress; request.targetAddress = boundary.targetAddress;
      request.sourceTopologyVersion = sourceBefore.topologyVersion;
      request.targetTopologyVersion = targetBefore.topologyVersion;
      if (existingFault)
      {
        valid = mothershipPhysicalClusterNetworkFaultRequestEqual(record.request, request) &&
            mothershipPhysicalFaultMachineObservationEqual(record.sourceAdmission, sourceBefore) &&
            mothershipPhysicalFaultMachineObservationEqual(record.targetAdmission, targetBefore);
        resumed = valid;
        if (!valid) failure.assign("physical network fault retry no longer matches its freshly qualified route or endpoint proof"_ctv);
      }
      if (valid && existingFault && record.hasReceipt)
      {
        String encoded = {}; auto receipt = record.receipt; BitseryEngine::serialize(encoded, receipt);
        String digest = {}; valid = prodigyComputeSHA256Hex(encoded, digest, &failure);
        basics_log("faultClusterNetwork success=%u resumed=1 restored=1 operationUUID=%s boundaryUUID=%s receiptSHA256=%s failure=%s\n",
            unsigned(valid), argv[0], argv[1], digest.c_str(), failure.c_str());
        if (!valid) exit(EXIT_FAILURE);
        return;
      }
      if (!existingFault)
      {
        auto registry = openClusterRegistry();
        valid = registry.admitPhysicalClusterNetworkFault(request, sourceBefore, targetBefore,
                                                          record, resumed, &failure);
      }
    }

    PhysicalFaultProviderReceipt sourceProvider = {}, targetProvider = {};
    String sourceFailure = {}, targetFailure = {};
    if (valid)
    {
      const bool runSource = direction == MothershipPhysicalFaultDirection::both ||
          direction == MothershipPhysicalFaultDirection::sourceToTarget;
      const bool runTarget = direction == MothershipPhysicalFaultDirection::both ||
          direction == MothershipPhysicalFaultDirection::targetToSource;
      std::future<bool> sourceFuture, targetFuture;
      if (runSource) sourceFuture = std::async(std::launch::async, [&]() {
        return runPhysicalFaultProvider(source, operationUUID, "source", boundary.sourceMachineUUID,
                                        boundary.targetAddress, uint32_t(duration), boundary.sourceExecutorKind,
                                        boundary.sourceLocalVMBoundaryUUID, boundary.sourceCloudID,
                                        sourceProvider, sourceFailure);
      });
      if (runTarget) targetFuture = std::async(std::launch::async, [&]() {
        return runPhysicalFaultProvider(target, operationUUID, "target", boundary.targetMachineUUID,
                                        boundary.sourceAddress, uint32_t(duration), boundary.targetExecutorKind,
                                        boundary.targetLocalVMBoundaryUUID, boundary.targetCloudID,
                                        targetProvider, targetFailure);
      });
      const bool sourceOK = !runSource || sourceFuture.get();
      const bool targetOK = !runTarget || targetFuture.get();
      valid = sourceOK && targetOK;
      if (!valid) failure = !sourceOK ? sourceFailure : targetFailure;
    }
    if (valid) valid = readManagedClusterStatus(source, sourceReport, failure) &&
        physicalFaultMachineObservation(sourceReport, source.clusterUUID, boundary.sourceMachineUUID, sourceAfter, failure) &&
        readManagedClusterStatus(target, targetReport, failure) &&
        physicalFaultMachineObservation(targetReport, target.clusterUUID, boundary.targetMachineUUID, targetAfter, failure);
    MothershipPhysicalClusterNetworkFaultReceipt receipt = {};
    if (valid)
    {
      receipt.operationUUID = operationUUID; receipt.boundaryUUID = boundaryUUID;
      receipt.admission = request;
      receipt.sourceBefore = record.sourceAdmission; receipt.targetBefore = record.targetAdmission;
      receipt.sourceAfter = sourceAfter; receipt.targetAfter = targetAfter;
      if (direction == MothershipPhysicalFaultDirection::both ||
          direction == MothershipPhysicalFaultDirection::sourceToTarget)
      {
        receipt.sourceInstalledAtMonotonicMilliseconds = sourceProvider.installedAtMonotonicMs;
        receipt.sourceRestoredAtMonotonicMilliseconds = sourceProvider.restoredAtMonotonicMs;
        receipt.sourceRestored = true;
      }
      if (direction == MothershipPhysicalFaultDirection::both ||
          direction == MothershipPhysicalFaultDirection::targetToSource)
      {
        receipt.targetInstalledAtMonotonicMilliseconds = targetProvider.installedAtMonotonicMs;
        receipt.targetRestoredAtMonotonicMilliseconds = targetProvider.restoredAtMonotonicMs;
        receipt.targetRestored = true;
      }
      receipt.restored = true;
      auto registry = openClusterRegistry();
      valid = registry.recordPhysicalClusterNetworkFaultReceipt(request, receipt, record, resumed, &failure);
    }
    String digest = {};
    if (valid)
    {
      String encoded = {}; auto copy = record.receipt; BitseryEngine::serialize(encoded, copy);
      valid = prodigyComputeSHA256Hex(encoded, digest, &failure);
    }
    basics_log("faultClusterNetwork success=%u resumed=%u restored=%u operationUUID=%s boundaryUUID=%s receiptSHA256=%s failure=%s\n",
        unsigned(valid), unsigned(resumed), unsigned(valid && record.hasReceipt), argc > 0 ? argv[0] : "",
        argc > 1 ? argv[1] : "", digest.c_str(), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  bool testPairWholeDestinationReady(const MothershipTestPairBoundaryRecord& record,
                                     const MothershipProdigyCluster& target, String& failure)
  {
    // Each call obtains current observations through the authenticated target
    // control connection. A prior healthy report is never stored as permission
    // to select traffic or request source retirement.
    ClusterStatusReport clusterReport = {};
    DeploymentIdentityReport deploymentReport = {};
    DeploymentIdentityReport cousinTransportReport = {};
    MothershipProdigyCluster source = {};
    if (record.version >= 5)
    {
      {
        auto registry = openClusterRegistry();
        if (!registry.getClusterByIdentity(record.boundary.sourceClusterUUID, source, &failure)) return false;
      }
      MothershipProdigyCluster targetCopy = target;
      if (!testPairCousinTransportReady(record, source, targetCopy, failure) ||
          !readDeploymentIdentity(target, record.cousinTransport.destinationPermission.localDeploymentID,
                                  cousinTransportReport, failure)) return false;
    }
    return readManagedClusterStatus(target, clusterReport, failure) &&
           readDeploymentIdentity(target, record.targetDeploymentID, deploymentReport, failure) &&
           MothershipClusterRegistry::testPairWholeDestinationReady(
               record, clusterReport, deploymentReport, &failure,
               record.version >= 5 ? &cousinTransportReport : nullptr);
  }

  bool runTestPairProvider(const MothershipTestPairBoundaryRecord& record, const char *action,
                           const Vector<String>& extra, String& failure,
                           MothershipVirtualDatacenterPairDrainObservation *observation = nullptr,
                           MothershipVirtualDatacenterPairGuestResetFence *resetFence = nullptr,
                           String *completedBootID = nullptr)
  {
    const auto& d = record.boundary;
    if (!mothershipVirtualDatacenterPairBoundaryDescriptorValid(d, &failure)) return false;
    Vector<String> args = {};
    args.emplace_back(std::strcmp(action, "prepare") == 0 ? "--pair-launch" : "--pair-action");
    if (std::strcmp(action, "prepare") != 0) args.emplace_back(action);
    String directory = {}; directory.snprintf<"{}/{}"_ctv>(String(mothershipVirtualDatacenterPairBoundaryRoot), d.operationID);
    args.push_back(directory); args.push_back(d.operationID); args.push_back(d.sourceClusterUUID); args.push_back(d.targetClusterUUID);
    args.push_back(d.sourceWorkspace); args.push_back(d.sourceRuntimeIdentity);
    args.emplace_back(); args.back().assignItoa(d.sourceMachineIndex); args.push_back(d.sourceMachinePrivate4);
    args.push_back(d.targetWorkspace); args.push_back(d.targetRuntimeIdentity);
    args.emplace_back(); args.back().assignItoa(d.targetMachineIndex); args.push_back(d.targetMachinePrivate4);
    args.push_back(d.endpointIPv4); args.emplace_back(); args.back().assignItoa(d.endpointPort);
    for (const String& value : extra) args.push_back(value);
    if (observation == nullptr && resetFence == nullptr) return mothershipRunVirtualDatacenterProvider(std::move(args), &failure);
    String output = {};
    const bool providerSucceeded = mothershipRunVirtualDatacenterProvider(std::move(args), &output, &failure);
    if (!output.empty()) std::fwrite(output.data(), 1, output.size(), stdout);
    if (resetFence)
    {
      if (providerSucceeded && mothershipVirtualDatacenterParsePairGuestResetObservation(output, d, *resetFence, completedBootID)) return true;
      if (failure.empty()) failure.assign("guest reset observation is unavailable or does not bind the recorded pair"_ctv);
      return false;
    }
    return providerSucceeded && mothershipVirtualDatacenterParsePairDrainObservation(output, d, *observation, &failure);
  }

  bool observeAndRecordTestPairSourceDrain(MothershipTestPairBoundaryRecord& record, String& failure)
  {
    if ((record.version != 3 && record.version != 5) || record.closed || record.selectorGeneration != 1)
    {
      failure.assign("source drain requires an open migration with the destination selected"_ctv);
      return false;
    }
    MothershipProdigyCluster source = {}, target = {};
    { auto registry = openClusterRegistry();
      if (!registry.getClusterByIdentity(record.boundary.sourceClusterUUID, source, &failure) ||
          !registry.getClusterByIdentity(record.boundary.targetClusterUUID, target, &failure)) return false; }
    auto currentBoundary = record.boundary;
    String expected = {}, current = {};
    if (!bindTestPairRuntimes(source, target, currentBoundary, failure)) return false;
    BitseryEngine::serialize(expected, record.boundary); BitseryEngine::serialize(current, currentBoundary);
    if (expected != current) { failure.assign("paired runtime identity changed"_ctv); return false; }
    // Re-read the complete destination on every attempt; the durable drain
    // receipt is evidence of progress, never permission for a later retirement.
    if (!testPairWholeDestinationReady(record, target, failure)) return false;
    MothershipVirtualDatacenterPairDrainObservation observation = {};
    if (!runTestPairProvider(record, "drain", {}, failure, &observation) ||
        !observation.selectedTarget || !observation.drainCapability || observation.sourceFlows != 0)
    {
      if (failure.empty()) failure.assign("source connections have not drained"_ctv);
      return false;
    }
    auto registry = openClusterRegistry();
    MothershipTestPairBoundaryRecord updated = {};
    if (!registry.recordTestPairSourceDrain(record, observation, updated, &failure)) return false;
    record = std::move(updated);
    return true;
  }

  bool bindTestPairRuntimes(const MothershipProdigyCluster& source,
                            const MothershipProdigyCluster& target,
                            MothershipVirtualDatacenterPairBoundaryDescriptor& d, String& failure)
  {
    if (source.deploymentMode != MothershipClusterDeploymentMode::test ||
        target.deploymentMode != MothershipClusterDeploymentMode::test ||
        source.test.enableFakeIpv4Boundary || target.test.enableFakeIpv4Boundary ||
        source.nBrains != 3 || target.nBrains != 3 || source.test.machineCount != 3 || target.test.machineCount != 3 ||
        source.clusterUUID == target.clusterUUID)
    {
      failure.assign("paired admission requires two independent three-Brain test clusters"_ctv);
      return false;
    }
    d.sourceClusterUUID.assignItoh(source.clusterUUID); d.targetClusterUUID.assignItoh(target.clusterUUID);
    d.sourceWorkspace = source.test.workspaceRoot; d.targetWorkspace = target.test.workspaceRoot;
    String path = {};
    mothershipVirtualDatacenterPath(d.sourceWorkspace, "virtual-datacenter.identity", path);
    bool valid = mothershipReadProcFile(path, d.sourceRuntimeIdentity);
    mothershipVirtualDatacenterPath(d.targetWorkspace, "virtual-datacenter.identity", path);
    valid = valid && mothershipReadProcFile(path, d.targetRuntimeIdentity);
    while (!d.sourceRuntimeIdentity.empty() && d.sourceRuntimeIdentity[d.sourceRuntimeIdentity.size() - 1] == '\n') d.sourceRuntimeIdentity.resize(d.sourceRuntimeIdentity.size() - 1);
    while (!d.targetRuntimeIdentity.empty() && d.targetRuntimeIdentity[d.targetRuntimeIdentity.size() - 1] == '\n') d.targetRuntimeIdentity.resize(d.targetRuntimeIdentity.size() - 1);
    d.sourceParentNamespace.snprintf<"pvd-p-{}"_ctv>(d.sourceRuntimeIdentity);
    d.targetParentNamespace.snprintf<"pvd-p-{}"_ctv>(d.targetRuntimeIdentity);
    String private6 = {}, public6 = {};
    mothershipVirtualDatacenterMachineAddresses(d.sourceMachineIndex, source.datacenterFragment, false, d.sourceMachinePrivate4, private6, public6);
    mothershipVirtualDatacenterMachineAddresses(d.targetMachineIndex, target.datacenterFragment, false, d.targetMachinePrivate4, private6, public6);
    return valid && mothershipVirtualDatacenterPairBoundaryDescriptorValid(d, &failure);
  }

  bool readStatelessAdmissionReceipt(Message *response, MothershipTopic expected,
                                     StatelessDeploymentAdmissionReceipt& receipt, String& failure)
  {
    if (!response || MothershipTopic(response->topic) != expected)
    {
      failure.assign("stateless admission outcome is unavailable; resume the same paired operation"_ctv);
      return false;
    }
    uint8_t *args = response->args;
    String serialized = {};
    if (!ProdigyIngressValidation::extractVariableStringView(args, response->terminal(), serialized) ||
        args != response->terminal() || !BitseryEngine::deserializeSafe(serialized, receipt) || receipt.version != 2)
    {
      failure.assign("stateless admission receipt is malformed"_ctv);
      return false;
    }
    return true;
  }

  bool admitTestPairTarget(MothershipTestPairBoundaryRecord& record, const String& artifactPath, String& failure)
  {
    if (!record.guestResetFence.bootID.empty())
    { failure.assign("test pair awaits guest reset cleanup"_ctv); return false; }
    if ((record.version != 2 && record.version != 3 && record.version != 5) || record.closed)
    {
      failure.assign("operation has no open paired target request"_ctv);
      return false;
    }
    MothershipProdigyCluster target = {}, source = {};
    {
      auto registry = openClusterRegistry();
      if (!registry.getClusterByIdentity(record.boundary.targetClusterUUID, target, &failure) ||
          !registry.getClusterByIdentity(record.boundary.sourceClusterUUID, source, &failure)) return false;
    }
    auto observedBoundary = record.boundary;
    if (!bindTestPairRuntimes(source, target, observedBoundary, failure)) return false;
    String expectedBytes = {}, observedBytes = {};
    BitseryEngine::serialize(expectedBytes, record.boundary); BitseryEngine::serialize(observedBytes, observedBoundary);
    if (expectedBytes != observedBytes)
    {
      failure.assign("paired cluster runtime identity changed"_ctv);
      return false;
    }
    if (record.version >= 5 && !testPairCousinTransportReady(record, source, target, failure)) return false;
    String digest = {}; uint64_t bytes = 0;
    if (!mothershipValidateDiscombobulatorContainerBlobContract(artifactPath, &failure) ||
        !prodigyComputeFileSHA256Hex(artifactPath, digest, &bytes, &failure) ||
        digest != record.targetBlobSHA256 || bytes != record.targetBlobBytes)
    {
      if (failure.empty()) failure.assign("target artifact differs from paired request"_ctv);
      return false;
    }
    uint128_t operationID = 0;
    if (!prodigyParseCanonicalHex128(record.boundary.operationID, operationID)) return false;
    socket.close();
    DeploymentPlan targetPlan;
    if (!BitseryEngine::deserializeSafe(record.targetRequestPlan, targetPlan) ||
        !configureControlTarget(target.name.c_str(), &failure) || !admitTruthDeploymentPlacement(targetPlan, failure) ||
        !socket.ensureConnected()) return false;
    const int64_t admissionDeadlineMs = Time::now<TimeResolution::ms>() + 30'000;
    StatelessDeploymentAdmissionReceipt receipt = {};
    auto queryAdmission = [&]() {
      Message::construct(socket.wBuffer, MothershipTopic::pullStatelessDeploymentAdmission, uint8_t(1), operationID);
      if (!socket.send()) { failure = socket.ioFailureDetail(); return false; }
      receipt = {};
      return readStatelessAdmissionReceipt(socket.recvExpectedTopic(MothershipTopic::pullStatelessDeploymentAdmission),
                                           MothershipTopic::pullStatelessDeploymentAdmission, receipt, failure);
    };
    bool valid = queryAdmission();
    // Machine readiness does not establish current Brain peer capabilities.
    // After election or reconnect, observe their authenticated negotiation
    // within the same bounded admission window before sending any mutation.
    for (uint32_t polls = 0; polls < 300 && valid && receipt.supported && !receipt.peersCapable &&
           Time::now<TimeResolution::ms>() < admissionDeadlineMs; ++polls)
    {
      ::usleep(100'000);
      valid = queryAdmission();
    }
    if (valid && (!receipt.supported || !receipt.peersCapable || receipt.currentAuthorityGeneration == 0 ||
                  receipt.currentMasterUUID == 0 || receipt.currentMasterBootNs <= 0))
    {
      failure = receipt.failure;
      if (failure.empty()) failure.assign("current target authority has not acknowledged stateless admission capability"_ctv);
      valid = false;
    }
    if (valid && (!receipt.accepted || !receipt.live))
    {
      ProdigyStatelessDeploymentAdmissionRequest request = {};
      request.operationID = operationID; request.clusterUUID = target.clusterUUID;
      request.expectedAuthorityGeneration = receipt.currentAuthorityGeneration;
      request.expectedMasterUUID = receipt.currentMasterUUID; request.expectedMasterBootNs = receipt.currentMasterBootNs;
      request.requestPlanSHA256 = record.targetRequestPlanSHA256;
      request.artifactSHA256 = record.targetBlobSHA256; request.artifactBytes = record.targetBlobBytes;
      String header = {}; BitseryEngine::serialize(header, request);
      uint32_t offset = Message::appendHeader(socket.wBuffer, MothershipTopic::admitStatelessDeployment);
      Message::appendValue(socket.wBuffer, header); Message::appendValue(socket.wBuffer, record.targetRequestPlan);
      Message::appendFile(socket.wBuffer, artifactPath); Message::finish(socket.wBuffer, offset);
      valid = socket.send();
      if (valid) valid = readStatelessAdmissionReceipt(socket.recvExpectedTopic(MothershipTopic::admitStatelessDeployment),
                                                       MothershipTopic::admitStatelessDeployment, receipt, failure);
      else failure.assign("target admission send outcome is unknown; resume the same paired operation"_ctv);
    }
    // A local commit is provisional until the target's commissioned peers
    // acknowledge the same authority snapshot. Poll the existing operation;
    // never persist its acceptance identity or repeat launch while it is pending.
    for (uint32_t polls = 0; polls < 300 && valid && !receipt.accepted && receipt.failure.empty() && receipt.launchPending &&
           MothershipClusterRegistry::testPairTargetAdmissionIdentityMatches(record, receipt) &&
           Time::now<TimeResolution::ms>() < admissionDeadlineMs; ++polls)
    {
      ::usleep(100'000);
      valid = queryAdmission();
    }
    socket.close();
    if (valid && !receipt.accepted)
    {
      failure = receipt.failure;
      if (failure.empty()) failure.assign("target admission is not durably acknowledged by its peers; resume the same paired operation"_ctv);
      valid = false;
    }
    if (valid)
    {
      auto registry = openClusterRegistry(); MothershipTestPairBoundaryRecord updated = {};
      valid = registry.recordTestPairTargetAdmission(record, receipt, updated, &failure);
      if (valid) record = std::move(updated);
    }
    return valid;
  }

  void runAdmitTestPairTarget(int argc, char *argv[])
  {
    String failure = {}; TestPairLifecycleLock lock; MothershipTestPairBoundaryRecord record = {};
    bool valid = argc == 2 && lockTestPairLifecycle(lock, failure);
    if (valid) { auto registry = openClusterRegistry(); valid = registry.loadTestPairBoundary(String(argv[0]), record, &failure); }
    valid = valid && admitTestPairTarget(record, String(argv[1]), failure);
    basics_log("admitTestPairTarget success=%u accepted=%u migrationQualified=%u failure=%s\n",
               unsigned(valid), unsigned(valid), unsigned(valid && record.version >= 5), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  bool readPairedSourceRetirementReceipt(Message *response, MothershipTopic expected,
                                         PairedSourceRetirementReceipt& receipt, String& failure)
  {
    uint8_t *args = response ? response->args : nullptr;
    String encoded = {};
    if (!response || MothershipTopic(response->topic) != expected ||
        !ProdigyIngressValidation::extractVariableStringView(args, response->terminal(), encoded) ||
        args != response->terminal() || !BitseryEngine::deserializeSafe(encoded, receipt) ||
        (receipt.version != 1 && receipt.version != 2))
    {
      failure.assign("source retirement outcome is unavailable; resume the same paired operation"_ctv);
      return false;
    }
    if (!receipt.failure.empty()) { failure = receipt.failure; return false; }
    return true;
  }

  void runRetireTestPairSource(int argc, char *argv[])
  {
    String failure = {};
    TestPairLifecycleLock lock;
    MothershipTestPairBoundaryRecord record = {};
    MothershipProdigyCluster source = {}, target = {};
    PairedSourceRetirementReceipt receipt = {};
    uint128_t operationID = 0;
    bool valid = argc == 1 && lockTestPairLifecycle(lock, failure);
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.loadTestPairBoundary(String(argv[0]), record, &failure) &&
              registry.getClusterByIdentity(record.boundary.sourceClusterUUID, source, &failure) &&
              registry.getClusterByIdentity(record.boundary.targetClusterUUID, target, &failure) &&
              prodigyParseCanonicalHex128(record.boundary.operationID, operationID);
    }
    if (valid)
    {
      auto currentBoundary = record.boundary;
      String expected = {}, current = {};
      valid = bindTestPairRuntimes(source, target, currentBoundary, failure);
      BitseryEngine::serialize(expected, record.boundary); BitseryEngine::serialize(current, currentBoundary);
      if (valid && expected != current) { failure.assign("paired runtime identity changed"_ctv); valid = false; }
    }
    if (valid && !record.guestResetFence.bootID.empty())
    { failure.assign("test pair awaits guest reset cleanup"_ctv); valid = false; }
    // A saved healthy or drained observation cannot authorize this command.
    valid = valid && observeAndRecordTestPairSourceDrain(record, failure);
    const int64_t deadlineMs = Time::now<TimeResolution::ms>() + 30'000;
    auto connectSource = [&]() {
      socket.close();
      String sourceName = source.name;
      return configureControlTarget(sourceName.c_str(), &failure) && socket.ensureConnected();
    };
    auto query = [&]() {
      Message::construct(socket.wBuffer, MothershipTopic::pullPairedSourceRetirement, uint8_t(1), operationID);
      if (!socket.send()) { failure = socket.ioFailureDetail(); return false; }
      receipt = {};
      return readPairedSourceRetirementReceipt(socket.recvExpectedTopic(MothershipTopic::pullPairedSourceRetirement),
                                               MothershipTopic::pullPairedSourceRetirement, receipt, failure);
    };
    valid = valid && connectSource() && query();
    for (uint32_t polls = 0; valid && receipt.supported && !receipt.peersCapable && polls < 300 &&
         Time::now<TimeResolution::ms>() < deadlineMs; ++polls)
    {
      ::usleep(100'000); valid = query();
    }
    if (valid && (!receipt.supported || !receipt.peersCapable || receipt.currentAuthorityGeneration == 0 ||
                  receipt.currentMasterUUID == 0 || receipt.currentMasterBootNs <= 0))
    {
      failure.assign("current source authority has not acknowledged paired retirement capability"_ctv); valid = false;
    }
    auto matchesFence = [&]() {
      ProdigyPairedSourceRetirementFence fence = {};
      if (!BitseryEngine::deserializeSafe(receipt.sealedFence, fence) || !prodigyPairedSourceRetirementFenceValid(fence) ||
          fence.operationID != operationID || fence.sourceClusterUUID != source.clusterUUID ||
          fence.targetClusterUUID != target.clusterUUID || fence.sourceDeploymentID != record.sourceDeploymentID ||
          fence.targetDeploymentID != record.targetDeploymentID || fence.sourceNormalizedPlanSHA256 != record.sourcePlanSHA256 ||
          fence.sourceBlobSHA256 != record.sourceBlobSHA256)
      {
        failure.assign("source retirement fence conflicts with the paired operation"_ctv); return false;
      }
      return true;
    };
    if (valid && !receipt.sealedFence.empty()) valid = matchesFence();
    if (valid && receipt.sealedFence.empty())
    {
      DeploymentIdentityReport sourceReport = {};
      valid = readDeploymentIdentity(source, record.sourceDeploymentID, sourceReport, failure) &&
              sourceReport.profileEligible && !sourceReport.isStateful &&
              sourceReport.canonicalPlanSHA256 == record.sourcePlanSHA256 &&
              sourceReport.containerBlobSHA256 == record.sourceBlobSHA256 && sourceReport.containerBlobBytes != 0;
      if (!valid && failure.empty()) failure.assign("live source differs from the paired operation"_ctv);
      // Capability negotiation may have consumed time. Revalidate immediately
      // before requesting the durable fence, then acquire the current source tuple.
      valid = valid && observeAndRecordTestPairSourceDrain(record, failure) && connectSource() && query();
      if (valid && !receipt.sealedFence.empty()) valid = matchesFence();
      if (valid && receipt.sealedFence.empty())
      {
        if (!receipt.supported || !receipt.peersCapable || receipt.currentAuthorityGeneration == 0 ||
            receipt.currentMasterUUID == 0 || receipt.currentMasterBootNs <= 0)
        {
          failure.assign("source authority changed before retirement preparation"_ctv); valid = false;
        }
      }
      if (valid && receipt.sealedFence.empty())
      {
        ProdigyPairedSourceRetirementRequest request = {};
        request.operationID = operationID;
        request.sourceClusterUUID = source.clusterUUID; request.targetClusterUUID = target.clusterUUID;
        request.sourceDeploymentID = record.sourceDeploymentID; request.targetDeploymentID = record.targetDeploymentID;
        request.expectedAuthorityGeneration = receipt.currentAuthorityGeneration;
        request.expectedMasterUUID = receipt.currentMasterUUID; request.expectedMasterBootNs = receipt.currentMasterBootNs;
        request.sourceNormalizedPlanSHA256 = record.sourcePlanSHA256;
        request.sourceBlobSHA256 = record.sourceBlobSHA256; request.sourceBlobBytes = sourceReport.containerBlobBytes;
        String encoded = {}; BitseryEngine::serialize(encoded, request);
        Message::construct(socket.wBuffer, MothershipTopic::preparePairedSourceRetirement, encoded);
        valid = socket.send() && readPairedSourceRetirementReceipt(
          socket.recvExpectedTopic(MothershipTopic::preparePairedSourceRetirement),
          MothershipTopic::preparePairedSourceRetirement, receipt, failure);
      }
    }
    // Neuron honors the application's shutdown grace (up to 120 seconds).
    // Start a separate terminal window after preparation, allowing that grace
    // plus 30 seconds for destruction and durable peer acknowledgements.
    const int64_t terminalDeadlineMs = Time::now<TimeResolution::ms>() + 150'000;
    bool reportedSealed = false;
    for (uint32_t polls = 0; valid && !receipt.terminal && polls < 1500 &&
         Time::now<TimeResolution::ms>() < terminalDeadlineMs; ++polls)
    {
      if (!receipt.sealedFence.empty() && !matchesFence()) { valid = false; break; }
      if (receipt.sealed && !reportedSealed)
      {
        basics_log("retireTestPairSource progress=sealed terminal=0\n");
        std::fflush(stdout);
        reportedSealed = true;
      }
      ::usleep(100'000); valid = query();
    }
    if (valid) valid = receipt.sealed && receipt.terminal && matchesFence();
    socket.close();
    if (!valid && failure.empty()) failure.assign("source retirement is pending; resume the same paired operation"_ctv);
    basics_log("retireTestPairSource success=%u sealed=%u terminal=%u migrationQualified=%u failure=%s\n",
               unsigned(valid), unsigned(receipt.sealed), unsigned(receipt.terminal),
               unsigned(valid && record.version >= 5), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  bool retireProductionPairSource(const MothershipProductionPairRecord& record,
                                  const MothershipProdigyCluster& source,
                                  const MothershipProdigyCluster& target,
                                  String& receiptSHA256, String& failure)
  {
    receiptSHA256.clear();
    const uint128_t operationID = record.intent.operationUUID;
    PairedSourceRetirementReceipt receipt = {};
    auto connectSource = [&]() {
      socket.close();
      String sourceName = source.name;
      return configureControlTarget(sourceName.c_str(), &failure) && socket.ensureConnected();
    };
    auto query = [&]() {
      Message::construct(socket.wBuffer, MothershipTopic::pullPairedSourceRetirement, uint8_t(1), operationID);
      if (!socket.send()) { failure = socket.ioFailureDetail(); return false; }
      receipt = {};
      return readPairedSourceRetirementReceipt(socket.recvExpectedTopic(MothershipTopic::pullPairedSourceRetirement),
                                               MothershipTopic::pullPairedSourceRetirement, receipt, failure);
    };
    bool valid = connectSource() && query();
    const int64_t capabilityDeadline = Time::now<TimeResolution::ms>() + 30'000;
    for (uint32_t polls = 0; valid && receipt.supported && !receipt.peersCapable && polls < 300 &&
         Time::now<TimeResolution::ms>() < capabilityDeadline; ++polls)
    { ::usleep(100'000); valid = query(); }
    if (valid && (!receipt.supported || !receipt.peersCapable || receipt.currentAuthorityGeneration == 0 ||
                  receipt.currentMasterUUID == 0 || receipt.currentMasterBootNs <= 0))
    { failure.assign("current production source authority has not acknowledged paired retirement capability"_ctv); valid = false; }
    auto matchesFence = [&]() {
      ProdigyPairedSourceRetirementFence fence = {};
      if (!BitseryEngine::deserializeSafe(receipt.sealedFence, fence) ||
          !prodigyPairedSourceRetirementFenceValid(fence) || fence.operationID != operationID ||
          fence.sourceClusterUUID != source.clusterUUID || fence.targetClusterUUID != target.clusterUUID ||
          fence.sourceDeploymentID != record.intent.sourceWorkload.deploymentID ||
          fence.targetDeploymentID != record.intent.targetWorkload.deploymentID ||
          fence.sourceNormalizedPlanSHA256 != record.intent.sourceWorkload.canonicalPlanSHA256 ||
          fence.sourceBlobSHA256 != record.intent.sourceWorkload.artifactSHA256)
      { failure.assign("production source retirement fence conflicts with the durable pair"_ctv); return false; }
      return true;
    };
    if (valid && !receipt.sealedFence.empty()) valid = matchesFence();
    if (valid && receipt.sealedFence.empty())
    {
      DeploymentIdentityReport sourceReport = {};
      MothershipProductionWorkloadIdentity sourceIdentity = {};
      const bool stateful = record.intent.protocolVersion == MothershipProductionPairIntent::statefulVersion;
      if (stateful) {
        valid = readDeploymentIdentity(source, record.intent.sourceWorkload.deploymentID, sourceReport, failure) &&
            sourceReport.isStateful && sourceReport.canonicalPlanSHA256 == record.intent.sourceWorkload.canonicalPlanSHA256 &&
            sourceReport.containerBlobSHA256 == record.intent.sourceWorkload.artifactSHA256;
      } else valid = productionWorkloadIdentity(source, record.intent.sourceWorkload.deploymentID,
                                         sourceIdentity, sourceReport, failure) &&
          productionWorkloadIdentityEqual(sourceIdentity, record.intent.sourceWorkload);
      if (!valid && failure.empty()) failure.assign("live source differs from the production pair"_ctv);
      ProductionPairProviderState drainState = {}; String drainOutput = {}, providerEvidence = {};
      if (!stateful) valid = valid && runProductionPairProvider(record, source, "drain", drainState, drainOutput,
                                                 providerEvidence, failure) &&
          productionPairSelectorPhaseMatches(record, MothershipProductionPairPhase::sourceDrained,
                                             drainState, failure);
      valid = valid && connectSource() && query();
      if (valid && !receipt.sealedFence.empty()) valid = matchesFence();
      if (valid && receipt.sealedFence.empty() &&
          (!receipt.supported || !receipt.peersCapable || receipt.currentAuthorityGeneration == 0 ||
           receipt.currentMasterUUID == 0 || receipt.currentMasterBootNs <= 0))
      { failure.assign("source authority changed before production retirement preparation"_ctv); valid = false; }
      if (valid && receipt.sealedFence.empty())
      {
        ProdigyPairedSourceRetirementRequest request = {};
        request.operationID = operationID;
        request.sourceClusterUUID = source.clusterUUID; request.targetClusterUUID = target.clusterUUID;
        request.sourceDeploymentID = record.intent.sourceWorkload.deploymentID;
        request.targetDeploymentID = record.intent.targetWorkload.deploymentID;
        request.expectedAuthorityGeneration = receipt.currentAuthorityGeneration;
        request.expectedMasterUUID = receipt.currentMasterUUID;
        request.expectedMasterBootNs = receipt.currentMasterBootNs;
        request.sourceNormalizedPlanSHA256 = record.intent.sourceWorkload.canonicalPlanSHA256;
        request.sourceBlobSHA256 = record.intent.sourceWorkload.artifactSHA256;
        request.sourceBlobBytes = record.intent.sourceWorkload.artifactBytes;
        String encoded = {}; BitseryEngine::serialize(encoded, request);
        Message::construct(socket.wBuffer, MothershipTopic::preparePairedSourceRetirement, encoded);
        valid = socket.send() && readPairedSourceRetirementReceipt(
            socket.recvExpectedTopic(MothershipTopic::preparePairedSourceRetirement),
            MothershipTopic::preparePairedSourceRetirement, receipt, failure);
      }
    }
    const int64_t terminalDeadline = Time::now<TimeResolution::ms>() + 150'000;
    bool reportedSealed = false;
    for (uint32_t polls = 0; valid && !receipt.terminal && polls < 1500 &&
         Time::now<TimeResolution::ms>() < terminalDeadline; ++polls)
    {
      if (!receipt.sealedFence.empty() && !matchesFence()) { valid = false; break; }
      if (receipt.sealed && !reportedSealed)
      {
        basics_log("productionPair progress=sealed terminal=0\n"); std::fflush(stdout); reportedSealed = true;
      }
      ::usleep(100'000); valid = query();
    }
    if (valid) valid = receipt.sealed && receipt.terminal && matchesFence() &&
        prodigyComputeSHA256Hex(receipt.sealedFence, receiptSHA256, &failure);
    socket.close();
    if (!valid && failure.empty()) failure.assign("production source retirement is pending; resume the exact operation"_ctv);
    return valid;
  }

  bool exchangeStatefulDataAuthority(const MothershipProdigyCluster& cluster,
      const StatefulDataAuthorityOperation& request, StatefulDataAuthorityOperation& response,
      const String *artifactPath, String& failure)
  {
    socket.close(); String name = cluster.name;
    if (!configureControlTarget(name.c_str(), &failure) || !socket.ensureConnected()) return false;
    auto copy = request; String encoded; BitseryEngine::serialize(encoded, copy);
    const uint32_t offset = Message::appendHeader(socket.wBuffer, MothershipTopic::statefulDataAuthority);
    Message::appendValue(socket.wBuffer, encoded);
    if (artifactPath) Message::appendFile(socket.wBuffer, *artifactPath);
    Message::finish(socket.wBuffer, offset);
    if (!socket.send()) { failure = socket.ioFailureDetail(); return false; }
    Message *message = socket.recvExpectedTopic(MothershipTopic::statefulDataAuthority);
    if (!message || MothershipTopic(message->topic) != MothershipTopic::statefulDataAuthority) {
      failure.assign("stateful command outcome is unknown; resume the exact pair operation"_ctv); return false;
    }
    auto *args = message->args; String payload;
    const bool preparation = request.version == 2 && request.preparationQuery;
    if (!ProdigyIngressValidation::extractVariableStringView(args, message->terminal(), payload) ||
        args != message->terminal() || !BitseryEngine::deserializeSafe(payload, response) ||
        response.deploymentID != request.deploymentID ||
        (preparation
         ? (response.version != 2 || !response.preparationQuery ||
            !prodigyStatefulDataAuthorityPreparationContextEqual(response.preparation, request.preparation))
         : (response.version != 1 || response.pairIntentSHA256 != request.pairIntentSHA256 ||
            !prodigyStatefulDataAuthorityEqual(response.authority, request.authority)))) {
      failure.assign("stateful owner returned a mismatched operation receipt"_ctv); return false;
    }
    if (!response.failure.empty()) { failure = response.failure; return false; }
    return true;
  }

  bool compensateNametagStatefulTarget(const MothershipProductionPairRecord& record,
      const MothershipProdigyCluster& source, const MothershipProdigyCluster& target,
      const StatefulDataAuthorityOperation& catchup, String& receiptSHA256, String& failure)
  {
    PairedSourceRetirementReceipt receipt;
    String authorityBytes, authorityDigest;
    auto data = catchup.authority;
    BitseryEngine::serialize(authorityBytes, data);
    if (!prodigyComputeSHA256Hex(authorityBytes, authorityDigest)) return false;
    auto query = [&]() {
      socket.close(); String name = target.name;
      if (!configureControlTarget(name.c_str(), &failure) || !socket.ensureConnected()) return false;
      Message::construct(socket.wBuffer, MothershipTopic::pullPairedSourceRetirement, uint8_t(1), record.intent.operationUUID);
      return socket.send() && readPairedSourceRetirementReceipt(socket.recvExpectedTopic(MothershipTopic::pullPairedSourceRetirement),
          MothershipTopic::pullPairedSourceRetirement, receipt, failure);
    };
    auto matches = [&]() {
      ProdigyScopedPairedSourceRetirementFence scoped;
      if (receipt.version != 2 || !BitseryEngine::deserializeSafe(receipt.scopedFence, scoped) || scoped.version != 4) return false;
      const auto& fence = scoped.fence;
      if (!prodigyPairedSourceRetirementFenceValid(fence) || !fence.hasStatefulScope || !fence.catchupTargetCompensation ||
          fence.operationID != record.intent.operationUUID || fence.sourceClusterUUID != target.clusterUUID ||
          fence.targetClusterUUID != source.clusterUUID || fence.sourceDeploymentID != record.intent.targetWorkload.deploymentID ||
          fence.targetDeploymentID != record.intent.sourceWorkload.deploymentID || fence.shardGroup != record.intent.stateful.shardGroup ||
          fence.pairIntentSHA256 != catchup.pairIntentSHA256 || fence.dataAuthoritySHA256 != authorityDigest ||
          fence.sourceBlobSHA256 != record.intent.targetWorkload.artifactSHA256 ||
          fence.sourceBlobBytes != record.intent.targetWorkload.artifactBytes) return false;
      for (const auto& member : fence.cohort)
        if (std::find(record.intent.stateful.targetMachineUUIDs.begin(), record.intent.stateful.targetMachineUUIDs.end(), member.machineUUID) ==
            record.intent.stateful.targetMachineUUIDs.end()) return false;
      return true;
    };
    if (!query()) return false;
    if (receipt.sealedFence.empty()) {
      DeploymentIdentityReport identity;
      if (!readDeploymentIdentity(target, record.intent.targetWorkload.deploymentID, identity, failure, false) ||
          !identity.isStateful || identity.containerBlobSHA256 != record.intent.targetWorkload.artifactSHA256 ||
          identity.containerBlobBytes != record.intent.targetWorkload.artifactBytes || !query()) return false;
      ProdigyPairedSourceRetirementRequest request;
      request.version = 2; request.catchupTargetCompensation = true; request.operationID = record.intent.operationUUID;
      request.sourceClusterUUID = target.clusterUUID; request.targetClusterUUID = source.clusterUUID;
      request.sourceDeploymentID = record.intent.targetWorkload.deploymentID; request.targetDeploymentID = record.intent.sourceWorkload.deploymentID;
      request.expectedAuthorityGeneration = receipt.currentAuthorityGeneration; request.expectedMasterUUID = receipt.currentMasterUUID;
      request.expectedMasterBootNs = receipt.currentMasterBootNs; request.sourceNormalizedPlanSHA256 = identity.canonicalPlanSHA256;
      request.sourceBlobSHA256 = identity.containerBlobSHA256; request.sourceBlobBytes = identity.containerBlobBytes;
      request.shardGroup = record.intent.stateful.shardGroup; request.pairIntentSHA256 = catchup.pairIntentSHA256;
      request.dataAuthoritySHA256 = authorityDigest;
      String encoded; BitseryEngine::serialize(encoded, request);
      Message::construct(socket.wBuffer, MothershipTopic::preparePairedSourceRetirement, encoded);
      if (!socket.send() || !readPairedSourceRetirementReceipt(socket.recvExpectedTopic(MothershipTopic::preparePairedSourceRetirement),
          MothershipTopic::preparePairedSourceRetirement, receipt, failure)) return false;
    }
    for (uint32_t poll = 0; poll < 1500 && !receipt.terminal; ++poll) {
      if (!receipt.sealedFence.empty() && !matches()) { failure.assign("target compensation conflicts with its durable shard admission"_ctv); return false; }
      ::usleep(100'000); if (!query()) return false;
    }
    socket.close();
    if (!receipt.sealed || !receipt.terminal || !matches()) {
      failure.assign("exact catchup target compensation is pending; resume this abort"_ctv); return false;
    }
    return prodigyComputeSHA256Hex(receipt.scopedFence, receiptSHA256);
  }

  bool abortNametagStatefulPairBeforeFence(MothershipProductionPairRecord& record, String& failure)
  {
    if (record.phase == MothershipProductionPairPhase::statefulAbortedBeforeFence) return true;
    MothershipProdigyCluster routeSource, routeDestination, source, target;
    if (!productionPairTransportReady(record, routeSource, routeDestination, failure) ||
        !productionPairDataClusters(record, routeSource, routeDestination, source, target, failure)) return false;
    const auto operation = record.intent.operationUUID;
    if (record.phase != MothershipProductionPairPhase::statefulAbortBeforeFencePending) {
      auto copy = record.intent; String bytes, digest;
      BitseryEngine::serialize(bytes, copy); bytes.append("abortBeforeFence"_ctv);
      if (!prodigyComputeSHA256Hex(bytes, digest)) return false;
      auto registry = openClusterRegistry();
      if (!registry.abortProductionPairStatefulBeforeFence(operation, digest, Time::now<TimeResolution::ms>(), false, record, &failure)) return false;
    }
    auto observe = [&](StatefulDataAuthorityOperation command, MothershipProductionPairPhase phase,
        MothershipProductionStatefulReceipt& proof) {
      StatefulDataAuthorityOperation response;
      auto query = command; query.query = true;
      if (!exchangeStatefulDataAuthority(source, query, response, nullptr, failure)) return false;
      if (!response.accepted) {
        command.expectedAuthorityGeneration = response.expectedAuthorityGeneration; command.expectedMasterUUID = response.expectedMasterUUID;
        command.expectedMasterBootNs = response.expectedMasterBootNs;
        if (!exchangeStatefulDataAuthority(source, command, response, nullptr, failure)) return false;
      }
      for (uint32_t poll = 0; poll < 300 && !response.ready; ++poll) {
        ::usleep(100'000); if (!exchangeStatefulDataAuthority(source, query, response, nullptr, failure)) return false;
      }
      if (!response.ready || response.cohort.size() != 3 || response.receipts.size() != 3) {
        failure.assign("abort awaits three fresh source-owned cleanup/snapshot receipts"_ctv); return false;
      }
      proof.phase = phase; proof.operationUUID = operation; proof.intentSHA256 = command.pairIntentSHA256;
      proof.observedMasterUUID = response.expectedMasterUUID; proof.observedMasterBootNs = response.expectedMasterBootNs;
      proof.observedAuthorityGeneration = response.expectedAuthorityGeneration; proof.cohort = response.cohort;
      for (const auto& member : response.receipts) proof.members.push_back({member.containerUUID, member.machineUUID, member.receipt});
      auto registry = openClusterRegistry();
      return registry.observeProductionPairStatefulAbort(operation, proof, Time::now<TimeResolution::ms>(), record, &failure);
    };
    if (record.statefulReceipts.empty()) {
      StatefulDataAuthorityOperation preparing; MothershipProductionStatefulReceipt snapshot;
      if (!mothershipProductionPairStatefulCommand(record, MothershipProductionPairPhase::snapshotVerified, preparing) ||
          !observe(preparing, MothershipProductionPairPhase::snapshotVerified, snapshot)) return false;
    }
    String targetReceipt;
    if (record.statefulAbortTargetAdmissionIssued) {
      StatefulDataAuthorityOperation catchup, response;
      if (!mothershipProductionPairStatefulCommand(record, MothershipProductionPairPhase::catchupVerified, catchup)) return false;
      auto query = catchup; query.query = true;
      if (!exchangeStatefulDataAuthority(target, query, response, nullptr, failure)) return false;
      if (!response.accepted) {
        // A lost initial command may have had no effects. Re-establish only
        // its empty non-writer admission, never the artifact launch substep.
        catchup.expectedAuthorityGeneration = response.expectedAuthorityGeneration; catchup.expectedMasterUUID = response.expectedMasterUUID;
        catchup.expectedMasterBootNs = response.expectedMasterBootNs;
        if (!exchangeStatefulDataAuthority(target, catchup, response, nullptr, failure)) return false;
        for (uint32_t poll = 0; poll < 300 && !response.accepted; ++poll) {
          ::usleep(100'000); if (!exchangeStatefulDataAuthority(target, query, response, nullptr, failure)) return false;
        }
        if (!response.accepted) return false;
      }
      if (!compensateNametagStatefulTarget(record, source, target, catchup, targetReceipt, failure)) return false;
    } else {
      String evidence; auto snapshot = record.statefulReceipts.front();
      BitseryEngine::serialize(evidence, snapshot); evidence.append("no-target-command-issued"_ctv);
      if (!prodigyComputeSHA256Hex(evidence, targetReceipt)) return false;
    }
    // Remove seeding peers first: a disconnected target may otherwise retain
    // source snapshot cursors forever. The source remains writer throughout.
    { auto registry = openClusterRegistry();
      if (!registry.observeProductionPairStatefulTargetCompensation(operation, targetReceipt,
          Time::now<TimeResolution::ms>(), record, &failure)) return false; }
    if (!record.hasStatefulAbortReceipt) {
      StatefulDataAuthorityOperation cleanup; MothershipProductionStatefulReceipt proof;
      if (!mothershipProductionPairStatefulCommand(record, MothershipProductionPairPhase::snapshotVerified, cleanup)) return false;
      cleanup.authority.mode = StatefulDataAuthorityMode::retainedSource;
      cleanup.authority.authorityEpoch = record.intent.stateful.sourceRetainedEpoch;
      cleanup.authority.snapshotBoundarySHA256 = record.statefulReceipts.front().members.front().receipt.snapshotReceiptSHA256;
      if (!observe(cleanup, MothershipProductionPairPhase::statefulAbortedBeforeFence, proof)) return false;
    }
    String evidence, digest; auto cleanup = record.statefulAbortReceipt;
    BitseryEngine::serialize(evidence, cleanup); evidence.append(targetReceipt);
    if (!prodigyComputeSHA256Hex(evidence, digest)) return false;
    auto registry = openClusterRegistry();
    return registry.abortProductionPairStatefulBeforeFence(operation, digest, Time::now<TimeResolution::ms>(), true,
        record, &failure, &cleanup, &targetReceipt);
  }

  bool advanceNametagStatefulPair(MothershipProductionPairRecord& record, const String& artifactPath, String& failure)
  {
    MothershipProdigyCluster routeSource, routeDestination, source, target;
    if (!productionPairTransportReady(record, routeSource, routeDestination, failure) ||
        !productionPairDataClusters(record, routeSource, routeDestination, source, target, failure)) return false;
    const auto& intent = record.intent;
    String artifactDigest; uint64_t artifactBytes = 0;
    if (!mothershipValidateDiscombobulatorContainerBlobContract(artifactPath, &failure) ||
        !prodigyComputeFileSHA256Hex(artifactPath, artifactDigest, &artifactBytes, &failure) ||
        artifactDigest != intent.targetWorkload.artifactSHA256 || artifactBytes != intent.targetWorkload.artifactBytes) return false;
    bool resumed = false;
    if (record.phase == MothershipProductionPairPhase::prepared) {
      DeploymentIdentityReport observed;
      if (!readDeploymentIdentity(source, intent.sourceWorkload.deploymentID, observed, failure) ||
          !observed.live || !observed.isStateful || observed.canonicalPlanSHA256 != intent.sourceWorkload.canonicalPlanSHA256 ||
          observed.containerBlobSHA256 != intent.sourceWorkload.artifactSHA256 || observed.containerBlobBytes != artifactBytes) {
        failure.assign("stateful declaration does not bind the authenticated current source deployment"_ctv); return false;
      }
      String evidence, digest; BitseryEngine::serialize(evidence, observed);
      evidence.append(intent.stateful.targetDeploymentPlan);
      if (!prodigyComputeSHA256Hex(evidence, digest)) return false;
      auto registry = openClusterRegistry();
      return registry.advanceProductionPair(intent.operationUUID, MothershipProductionPairPhase::targetAdmitted,
          digest, Time::now<TimeResolution::ms>(), record, resumed, &failure);
    }
    constexpr MothershipProductionPairPhase phases[] = {
      MothershipProductionPairPhase::snapshotVerified, MothershipProductionPairPhase::catchupVerified,
      MothershipProductionPairPhase::sourceWriterFenced, MothershipProductionPairPhase::fencedCatchupVerified,
      MothershipProductionPairPhase::targetOwnershipActive};
    const auto order = mothershipProductionPairPhaseOrder(intent, record.phase);
    if ((order >= 2 && order < 7) || record.phase == MothershipProductionPairPhase::targetSelected) {
      const auto phase = order == 8 ? MothershipProductionPairPhase::sourceCleanupVerified : phases[order - 2];
      { auto registry = openClusterRegistry();
        if (!registry.prepareProductionPairStatefulCommand(intent.operationUUID, phase, Time::now<TimeResolution::ms>(), record, &failure)) return false; }
      StatefulDataAuthorityOperation command, response;
      if (!mothershipProductionPairStatefulCommand(record, phase, command)) return false;
      const auto& cluster = command.authority.localClusterUUID == source.clusterUUID ? source : target;
      auto query = command; query.query = true;
      if (!exchangeStatefulDataAuthority(cluster, query, response, nullptr, failure)) return false;
      if (!response.accepted) {
        command.expectedAuthorityGeneration = response.expectedAuthorityGeneration;
        command.expectedMasterUUID = response.expectedMasterUUID; command.expectedMasterBootNs = response.expectedMasterBootNs;
        if (!exchangeStatefulDataAuthority(cluster, command, response, nullptr, failure)) return false;
      }
      // Persisted desired authority may be visible before peer ACKs or after an
      // election. Poll only this exact operation; no operator app proof enters.
      for (uint32_t poll = 0; poll < 300 && !response.accepted; ++poll) {
        ::usleep(100'000);
        if (!exchangeStatefulDataAuthority(cluster, query, response, nullptr, failure)) return false;
      }
      if (!response.accepted) { failure.assign("stateful desired authority awaits durable peer acknowledgements"_ctv); return false; }
      if (phase == MothershipProductionPairPhase::catchupVerified && response.cohort.empty()) {
        command.launchTarget = true;
        command.expectedAuthorityGeneration = response.expectedAuthorityGeneration;
        command.expectedMasterUUID = response.expectedMasterUUID; command.expectedMasterBootNs = response.expectedMasterBootNs;
        if (!exchangeStatefulDataAuthority(cluster, command, response, &artifactPath, failure)) return false;
      }
      auto gateObserved = [&]() {
        if (response.cohort.size() != 3 || response.receipts.size() != 3) return false;
        return phase == MothershipProductionPairPhase::catchupVerified
            ? std::all_of(response.receipts.begin(), response.receipts.end(), [](const auto& member) {
                return prodigyStatefulDataAuthorityReceiptStaged(member.receipt);
              }) : response.ready;
      };
      for (uint32_t poll = 0; poll < 300 && !gateObserved(); ++poll) {
        ::usleep(100'000);
        if (!exchangeStatefulDataAuthority(cluster, query, response, nullptr, failure)) return false;
      }
      if (!gateObserved()) {
        failure.assign("stateful gate awaits three fresh authenticated application receipts"_ctv); return false;
      }
      MothershipProductionStatefulReceipt proof;
      proof.phase = phase; proof.operationUUID = intent.operationUUID; proof.intentSHA256 = command.pairIntentSHA256;
      proof.observedMasterUUID = response.expectedMasterUUID; proof.observedMasterBootNs = response.expectedMasterBootNs;
      proof.observedAuthorityGeneration = response.expectedAuthorityGeneration; proof.cohort = response.cohort;
      for (const auto& member : response.receipts) proof.members.push_back({member.containerUUID, member.machineUUID, member.receipt});
      auto registry = openClusterRegistry();
      return registry.applyProductionPairStatefulReceipt(intent.operationUUID, proof, Time::now<TimeResolution::ms>(), record, resumed, &failure);
    }
    if (record.phase == MothershipProductionPairPhase::targetOwnershipActive) {
      StatefulDataAuthorityOperation query, response;
      if (!mothershipProductionPairStatefulCommand(record, MothershipProductionPairPhase::targetOwnershipActive, query)) return false;
      query.query = true;
      if (!exchangeStatefulDataAuthority(target, query, response, nullptr, failure) || !response.ready ||
          !productionPairTransportReady(record, routeSource, routeDestination, failure) ||
          !productionPairDataClusters(record, routeSource, routeDestination, source, target, failure)) return false;
      String evidence, digest; BitseryEngine::serialize(evidence, response);
      auto route = intent.route; String routeBytes; BitseryEngine::serialize(routeBytes, route); evidence.append(routeBytes);
      if (!prodigyComputeSHA256Hex(evidence, digest)) return false;
      auto registry = openClusterRegistry();
      return registry.advanceProductionPair(intent.operationUUID, MothershipProductionPairPhase::targetSelected,
          digest, Time::now<TimeResolution::ms>(), record, resumed, &failure);
    }
    if (record.phase == MothershipProductionPairPhase::sourceCleanupVerified) {
      String digest;
      if (!retireProductionPairSource(record, source, target, digest, failure)) return false;
      auto registry = openClusterRegistry();
      return registry.advanceProductionPair(intent.operationUUID, MothershipProductionPairPhase::sourceRetired,
          digest, Time::now<TimeResolution::ms>(), record, resumed, &failure);
    }
    if (record.phase == MothershipProductionPairPhase::sourceRetired) {
      auto registry = openClusterRegistry();
      return registry.advanceProductionPair(intent.operationUUID, MothershipProductionPairPhase::cleanupComplete,
          record.sourceRetirementReceiptSHA256, Time::now<TimeResolution::ms>(), record, resumed, &failure);
    }
    return record.phase == MothershipProductionPairPhase::cleanupComplete;
  }

  // Versioned declaration input contains immutable intent/plan, never app
  // receipts. Every data, route and retirement proof is collected from owners.
  void runNametagStatefulPair(int argc, char *argv[])
  {
    String encoded, failure;
    MothershipProductionPairIntent intent; MothershipProductionPairRecord record;
    bool resumed = false;
    const bool abort = argc == 3 && String(argv[2]) == "abortBeforeFence"_ctv;
    if (argc == 2 || abort) Filesystem::openReadAtClose(-1, String(argv[0]), encoded, 2 * 1024 * 1024);
    bool valid = (argc == 2 || abort) && !encoded.empty() &&
        BitseryEngine::deserializeSafe(encoded, intent) && intent.protocolVersion == MothershipProductionPairIntent::statefulVersion &&
        mothershipProductionPairIntentValid(intent, &failure);
    if (valid) { auto registry = openClusterRegistry();
      valid = registry.admitProductionPair(intent, Time::now<TimeResolution::ms>(), record, resumed, &failure); }
    if (valid && abort && record.phase == MothershipProductionPairPhase::prepared)
      valid = advanceNametagStatefulPair(record, String(argv[1]), failure);
    if (valid) valid = abort ? abortNametagStatefulPairBeforeFence(record, failure) : advanceNametagStatefulPair(record, String(argv[1]), failure);
    basics_log("nametagStatefulPair success=%u phase=%u complete=%u failure=%s\n", unsigned(valid), unsigned(record.phase),
        unsigned(valid && mothershipProductionPairTerminal(record.phase)), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runPrepareNametagStatefulPair(int argc, char *argv[])
  {
    String failure = {}, requestBytes = {}, artifactPath = {};
    MothershipNametagStatefulPreparationRequest request = {};
    uint64_t sourceDeploymentID = 0, shardGroup = 0;
    bool valid = argc == 9 &&
        prodigyParseCanonicalHex128(String(argv[0]), request.operationUUID) && request.operationUUID != 0 &&
        prodigyParseCanonicalHex128(String(argv[1]), request.routeUUID) && request.routeUUID != 0 &&
        mothershipParseUnsignedArgument(argv[3], UINT64_MAX, sourceDeploymentID) && sourceDeploymentID != 0 &&
        mothershipParseUnsignedArgument(argv[4], UINT16_MAX, shardGroup);
    if (!valid) failure.assign("usage: prepareNametagStatefulPair OPERATION_UUID ROUTE_UUID SOURCE_CLUSTER SOURCE_DEPLOYMENT_ID SHARD_GROUP TARGET_CLUSTER TARGET_PLAN_JSON TARGET_ARTIFACT OUTPUT_INTENT_BIN"_ctv);

    MothershipProdigyCluster source = {}, target = {};
    CousinRouteRecord route = {}; CousinRouteApplyReceipt routeSourceReceipt = {}, routeDestinationReceipt = {};
    if (valid) {
      auto registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[2]), source, &failure) &&
          registry.getClusterByIdentity(String(argv[5]), target, &failure) &&
          registry.loadUsableCousinRoute(request.routeUUID, Time::now<TimeResolution::ms>(), route, &failure) &&
          registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::source,
                                                       routeSourceReceipt, &failure) &&
          registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::destination,
                                                       routeDestinationReceipt, &failure);
      if (valid && (source.clusterUUID == target.clusterUUID || source.deploymentMode == MothershipClusterDeploymentMode::test ||
          target.deploymentMode == MothershipClusterDeploymentMode::test || source.nBrains != 3 || target.nBrains != 3 ||
          route.sourceClusterUUID != target.clusterUUID || route.destinationClusterUUID != source.clusterUUID)) {
        failure.assign("Nametag stateful preparation requires an outbound target-to-source route across distinct non-test three-Brain clusters"_ctv);
        valid = false;
      }
    }
    request.sourceClusterUUID = source.clusterUUID; request.targetClusterUUID = target.clusterUUID;
    request.sourceDeploymentID = sourceDeploymentID; request.shardGroup = uint32_t(shardGroup);

    DeploymentPlan targetPlan = {}; bool returnAfterOkay = false;
    if (valid) valid = prepareDeploymentPlan(target.name.c_str(), argv[6], argv[7], targetPlan,
                                             artifactPath, returnAfterOkay, failure);
    socket.close();
    if (valid) {
      auto planCopy = targetPlan;
      valid = BitseryEngine::serialize(request.targetDeploymentPlan, planCopy) &&
          mothershipNametagStatefulPreparationRequestValid(request) &&
          BitseryEngine::serialize(requestBytes, request);
      if (!valid && failure.empty()) failure.assign("Nametag stateful preparation request could not be canonicalized"_ctv);
    }
    String requestSHA256 = {};
    if (valid) valid = prodigyComputeSHA256Hex(requestBytes, requestSHA256, &failure);
    if (valid) {
      MothershipNametagStatefulPreparationRecord prior = {}; String readFailure = {};
      auto registry = openClusterRegistry();
      if (registry.loadNametagStatefulPreparation(request.operationUUID, prior, &readFailure)) {
        if (prior.requestSHA256 != requestSHA256) { failure.assign("Nametag stateful preparation retry conflicts with its immutable request"_ctv); valid = false; }
        else { String encoded = {}; auto copy = prior.intent; BitseryEngine::serialize(encoded, copy);
          valid = ContainerStore::atomicWriteRuntimeFile(String(argv[8]), encoded, &failure);
          basics_log("prepareNametagStatefulPair success=%u resumed=1 operationUUID=%s failure=%s\n", unsigned(valid), argv[0], failure.c_str());
          if (!valid) exit(EXIT_FAILURE); return;
        }
      } else if (!readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
    }
    ProdigyLocalCousinServicePermissionResponse routeSourcePermission = {}, routeDestinationPermission = {};
    ClusterStatusReport sourceStatus = {}, targetStatus = {}; DeploymentIdentityReport sourceReport = {};
    if (valid) valid = source.deploymentMode != MothershipClusterDeploymentMode::test && target.deploymentMode != MothershipClusterDeploymentMode::test &&
        productionClusterHealthy(source, sourceStatus, failure) && productionClusterHealthy(target, targetStatus, failure) &&
        readLocalCousinServicePermission(target, route.sourcePermissionUUID, routeSourcePermission, failure) &&
        readLocalCousinServicePermission(source, route.destinationPermissionUUID, routeDestinationPermission, failure) &&
        routeSourcePermission.permission.purpose == ProdigyCousinServicePurpose::statefulCousin &&
        routeDestinationPermission.permission.purpose == ProdigyCousinServicePurpose::statefulCousin &&
        readDeploymentIdentity(source, request.sourceDeploymentID, sourceReport, failure);
    MothershipProductionWorkloadIdentity sourceWorkload = {}, targetWorkload = {};
    String artifactDigest = {}; uint64_t artifactBytes = 0;
    if (valid) {
      String targetPlanDigest = {};
      const uint64_t selectedShardReplicaCount = uint64_t(sourceReport.nShardGroups) * 3;
      valid = sourceReport.isStateful && sourceReport.applicationID >= 3 && sourceReport.applicationID <= 4 &&
          prodigyDeploymentIdentityReportVersionSupported(sourceReport.version, 2) && sourceReport.nShardGroups == 3 &&
          request.shardGroup < sourceReport.nShardGroups && selectedShardReplicaCount <= UINT32_MAX &&
          sourceReport.nTarget == selectedShardReplicaCount && sourceReport.nDeployed == selectedShardReplicaCount &&
          sourceReport.nHealthy == selectedShardReplicaCount &&
          sourceReport.clusterUUID == source.clusterUUID &&
          mothershipValidateDiscombobulatorContainerBlobContract(artifactPath, &failure) &&
          prodigyComputeFileSHA256Hex(artifactPath, artifactDigest, &artifactBytes, &failure) &&
          prodigyComputeSHA256Hex(request.targetDeploymentPlan, targetPlanDigest, &failure) &&
          targetPlan.isStateful && targetPlan.config.type == ApplicationType::stateful &&
          targetPlan.config.applicationID == sourceReport.applicationID && targetPlan.config.containerBlobSHA256 == artifactDigest &&
          targetPlan.config.containerBlobBytes == artifactBytes &&
          !targetPlan.stateful.neverShard &&
          StatefulMeshRoles::forShardGroup(targetPlan.stateful, targetPlan.config.applicationID,
              request.shardGroup).hasDistinctServices();
      sourceWorkload.clusterUUID = source.clusterUUID; sourceWorkload.applicationID = sourceReport.applicationID;
      sourceWorkload.deploymentID = sourceReport.deploymentID; sourceWorkload.canonicalPlanSHA256 = sourceReport.canonicalPlanSHA256;
      sourceWorkload.artifactSHA256 = sourceReport.containerBlobSHA256; sourceWorkload.artifactBytes = sourceReport.containerBlobBytes; sourceWorkload.replicas = 3;
      targetWorkload.clusterUUID = target.clusterUUID; targetWorkload.applicationID = targetPlan.config.applicationID;
      targetWorkload.deploymentID = targetPlan.config.deploymentID(); targetWorkload.canonicalPlanSHA256 = targetPlanDigest;
      targetWorkload.artifactSHA256 = artifactDigest; targetWorkload.artifactBytes = artifactBytes; targetWorkload.replicas = 3;
      valid = valid && mothershipProductionWorkloadIdentityValid(sourceWorkload, true) &&
          mothershipProductionWorkloadIdentityValid(targetWorkload, true);
    }
    Vector<uint128_t> targetMachines = {};
    if (valid) { for (const auto& machine : targetStatus.topology.machines) targetMachines.push_back(machine.uuid); std::sort(targetMachines.begin(), targetMachines.end()); }
    StatefulDataAuthorityOperation challenge = {}, response = {};
    if (valid) {
      challenge.version = 2; challenge.query = true; challenge.preparationQuery = true;
      challenge.deploymentID = request.sourceDeploymentID; challenge.preparation.requestUUID = Random::generateNumberWithNBits<128, uint128_t>();
      challenge.preparation.clusterUUID = source.clusterUUID; challenge.preparation.applicationID = sourceReport.applicationID;
      challenge.preparation.deploymentID = request.sourceDeploymentID;
      challenge.preparation.shardGroup = request.shardGroup; challenge.preparation.nShardGroups = sourceReport.nShardGroups;
      // A stale first round is intentionally used only to learn current master
      // identity; no member is addressed until the canonical cohort is returned.
      (void)exchangeStatefulDataAuthority(source, challenge, response, nullptr, failure);
      challenge.expectedAuthorityGeneration = response.expectedAuthorityGeneration; challenge.expectedMasterUUID = response.expectedMasterUUID;
      challenge.expectedMasterBootNs = response.expectedMasterBootNs; failure.clear();
      valid = challenge.preparation.requestUUID != 0 && challenge.expectedAuthorityGeneration != 0 && challenge.expectedMasterUUID != 0 &&
          exchangeStatefulDataAuthority(source, challenge, response, nullptr, failure) && response.accepted && response.cohort.size() == 3 &&
          std::all_of(response.cohort.begin(), response.cohort.end(), [&](const auto& member) {
            return member.isSource && member.shardGroup == request.shardGroup;
          });
      if (valid) challenge.cohort = response.cohort;
      for (uint32_t poll = 0; valid && poll < 300; ++poll) {
        valid = exchangeStatefulDataAuthority(source, challenge, response, nullptr, failure);
        if (valid && response.ready) break;
        if (valid) ::usleep(100'000);
      }
      valid = valid && response.ready && prodigyStatefulDataAuthorityPreparationMembersAgree(challenge.preparation, challenge.cohort, response.preparationMembers);
    }
    MothershipProductionPairIntent intent = {}; MothershipNametagStatefulPreparationRecord prepared = {}, recorded = {}; bool resumed = false;
    if (valid) {
      const auto& proof = response.preparationMembers.front().preparation;
      const uint128_t dataset = proof.hasAuthority ? 0 : Random::generateNumberWithNBits<128, uint128_t>();
      const uint128_t snapshot = Random::generateNumberWithNBits<128, uint128_t>();
      valid = mothershipSynthesizeNametagStatefulPreparation(request, route, routeSourcePermission.permission, routeDestinationPermission.permission,
          routeSourceReceipt, routeDestinationReceipt, sourceWorkload, targetWorkload, challenge.preparation, challenge.cohort,
          response.preparationMembers, targetMachines, dataset, snapshot, intent, &failure);
      prepared.requestSHA256 = requestSHA256; prepared.intent = intent;
      if (valid) { auto registry = openClusterRegistry(); valid = registry.persistNametagStatefulPreparation(prepared, recorded, resumed, &failure); }
    }
    if (valid) { String encoded = {}; auto copy = recorded.intent; BitseryEngine::serialize(encoded, copy); valid = ContainerStore::atomicWriteRuntimeFile(String(argv[8]), encoded, &failure); }
    basics_log("prepareNametagStatefulPair success=%u resumed=%u operationUUID=%s failure=%s\n", unsigned(valid), unsigned(resumed), argc ? argv[0] : "", failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  static ProdigyInitialAllMastersSeedBootstrapScope nametagInitialSeedScope(
      const MothershipNametagInitialSeedRecord& record,const MothershipNametagAllMastersIntent& intent,
      const MothershipNametagInitialSeedPlan& bound,uint128_t clusterUUID,uint32_t group)
  {
    ProdigyInitialAllMastersSeedBootstrapScope scope; auto& b=scope.bootstrap;
    b.sourceClusterUUID=intent.sites[0].clusterUUID; b.targetClusterUUID=clusterUUID;
    b.targetDeploymentID=bound.deploymentID; b.qualificationRunUUID=record.operationUUID;
    b.successorOperationUUID=record.operationUUID; b.shardGroup=group; b.expectedSeedGeneration=1;
    scope.baselineOperationUUID=record.baselineOperationUUID; scope.nShardGroups=bound.nShardGroups;
    scope.planSHA256=bound.planSHA256; scope.artifactSHA256=bound.artifactSHA256; scope.artifactBytes=bound.artifactBytes;
    return scope;
  }

  bool installNametagInitialSeedPlan(const MothershipNametagInitialSeedRecord& supplied,
      uint32_t index, const MothershipProdigyCluster& cluster, String& failure)
  {
    // The registry, not the caller's copy, owns the exact scope and progress.
    MothershipNametagInitialSeedRecord record;
    { auto registry = openClusterRegistry();
      if (!registry.loadNametagInitialSeed(supplied.operationUUID, record, &failure)) return false; }
    auto suppliedInitial = supplied, storedInitial = record;
    suppliedInitial.dispatchMask = suppliedInitial.completedMask = 0;
    storedInitial.dispatchMask = storedInitial.completedMask = 0;
    String suppliedBytes, storedBytes;
    if (!mothershipNametagInitialSeedRecordValid(record) || index >= record.plans.size() ||
        !BitseryEngine::serialize(suppliedBytes, suppliedInitial) ||
        !BitseryEngine::serialize(storedBytes, storedInitial) || suppliedBytes != storedBytes) {
      failure.assign("initial bootstrap does not match its durable journal"_ctv); return false;
    }
    MothershipNametagAllMastersIntent intent;
    if (!BitseryEngine::deserializeSafe(record.intentBytes, intent)) return false;
    const auto& bound = record.plans[index];
    String clusterName = cluster.name;
    if (bound.site >= intent.sites.size() || cluster.clusterUUID != intent.sites[bound.site].clusterUUID) {
      failure.assign("initial bootstrap target cluster differs from durable intent"_ctv); return false;
    }
    DeploymentPlan plan;
    if (!BitseryEngine::deserializeSafe(bound.normalizedPlan, plan)) return false;
    const int64_t deadline = Time::now<TimeResolution::ms>() + 15 * 60 * 1000;
    for (uint32_t group = 0; group < bound.nShardGroups; ++group) {
      ProdigyInitialAllMastersSeedBootstrapOperation request;
      request.query = true; request.deploymentPlan = bound.normalizedPlan;
      request.scope = nametagInitialSeedScope(record,intent,bound,cluster.clusterUUID,group);
      bool ready = false;
      while (Time::now<TimeResolution::ms>() < deadline) {
        ProdigyInitialAllMastersSeedBootstrapOperation reply;
        if (!configureControlTarget(clusterName.c_str(), &failure) ||
            !requestTopicRoundTrip(MothershipTopic::statefulDataAuthority, request, reply, failure)) return false;
        auto expected = request, observed = reply;
        expected.expectedAuthorityGeneration = observed.expectedAuthorityGeneration = 0;
        expected.expectedMasterUUID = observed.expectedMasterUUID = 0;
        expected.expectedMasterBootNs = observed.expectedMasterBootNs = 0;
        expected.accepted = observed.accepted = expected.ready = observed.ready = false;
        expected.failure.clear(); observed.failure.clear();
        String a, z;
        if (!BitseryEngine::serialize(a, expected) || !BitseryEngine::serialize(z, observed) || a != z ||
            !reply.expectedAuthorityGeneration || !reply.expectedMasterUUID || reply.expectedMasterBootNs <= 0) {
          failure.assign("initial bootstrap returned a mismatched authority response"_ctv); return false;
        }
        if (!reply.failure.empty()) { failure = reply.failure; return false; }
        if (request.expectedMasterUUID && (request.expectedMasterUUID != reply.expectedMasterUUID ||
            request.expectedMasterBootNs != reply.expectedMasterBootNs)) {
          failure.assign("initial bootstrap master incarnation changed during admission"_ctv); return false;
        }
        if (reply.accepted && reply.ready) { ready = true; break; }
        request.expectedAuthorityGeneration = reply.expectedAuthorityGeneration;
        request.expectedMasterUUID = reply.expectedMasterUUID; request.expectedMasterBootNs = reply.expectedMasterBootNs;
        request.query = reply.accepted;
        ::usleep(100'000);
      }
      if (!ready) { failure.assign("initial bootstrap authority peer acknowledgement timed out"_ctv); return false; }
    }
    auto matches = [&](const DeploymentIdentityReport& observed) {
      return observed.found && observed.clusterUUID == cluster.clusterUUID &&
          observed.deploymentID == bound.deploymentID && observed.applicationID == bound.applicationID &&
          observed.canonicalPlanSHA256 == bound.planSHA256 && observed.containerBlobSHA256 == bound.artifactSHA256 &&
          observed.containerBlobBytes == bound.artifactBytes &&
          observed.normalizedDeploymentPlan == bound.normalizedPlan;
    };
    DeploymentIdentityReport observed;
    if (!readDeploymentIdentity(cluster, bound.deploymentID, observed, failure, false, true)) return false;
    if (observed.found && !matches(observed)) {
      failure.assign("existing initial deployment differs from durable plan or artifact"_ctv); return false;
    }
    const uint8_t bit = uint8_t(1u << index);
    if (!observed.found) {
      String artifactDigest; uint64_t artifactBytes = 0;
      if (!mothershipValidateDiscombobulatorContainerBlobContract(bound.artifactPath, &failure) ||
          !prodigyComputeFileSHA256Hex(bound.artifactPath, artifactDigest, &artifactBytes, &failure) ||
          artifactDigest != bound.artifactSHA256 || artifactBytes != bound.artifactBytes) {
        if (failure.empty()) failure.assign("initial bootstrap artifact changed after journaling"_ctv);
        return false;
      }
      // Record intent before issuing the ordinary lifecycle request. A retry
      // first reconciles the exact deployment identity, including a lost ACK.
      if (!(record.dispatchMask & bit)) {
        auto registry = openClusterRegistry();
        if (!registry.updateNametagInitialSeedProgress(record.operationUUID, index, false, &failure)) return false;
      }
      DeploymentDispatchResult dispatch;
      if (!configureControlTarget(clusterName.c_str(), &failure) ||
          !dispatchValidatedDeployment(plan, bound.artifactPath, true, false, dispatch)) {
        if (failure.empty()) failure = dispatch.failure;
        return false;
      }
    } else if (!(record.dispatchMask & bit)) {
      auto registry = openClusterRegistry();
      if (!registry.updateNametagInitialSeedProgress(record.operationUUID, index, false, &failure)) return false;
    }
    const auto kind = bound.nShardGroups == 3 ? DeploymentIdentityStoreKind::kv : DeploymentIdentityStoreKind::graph;
    while (Time::now<TimeResolution::ms>() < deadline) {
      if (!readDeploymentIdentity(cluster, bound.deploymentID, observed, failure, false, true)) return false;
      if (observed.found && !matches(observed)) {
        failure.assign("initial deployment identity changed while awaiting readiness"_ctv); return false;
      }
      if (mothershipNametagAllMastersDeploymentReadyForSeedSelection(observed, cluster.clusterUUID,
            bound.deploymentID, bound.applicationID, bound.nShardGroups, kind)) {
        auto registry = openClusterRegistry();
        return registry.updateNametagInitialSeedProgress(record.operationUUID, index, true, &failure);
      }
      ::usleep(100'000);
    }
    failure.assign("initial deployment did not reach its exact healthy cohort before deadline"_ctv);
    return false;
  }

  void runBootstrapNametagAllMasters(int argc, char *argv[])
  {
    String failure, intentBytes, planBytes;
    auto readBounded = [&](const char *path, String& bytes, size_t maximum) {
      bytes.clear(); struct stat st = {};
      int fd = ::open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
      bool valid = fd >= 0 && ::fstat(fd, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0 && uint64_t(st.st_size) <= maximum;
      while (valid) {
        char buffer[4096]; ssize_t n = ::read(fd, buffer, sizeof(buffer));
        if (n < 0 && errno == EINTR) continue;
        if (n < 0) { valid = false; break; }
        if (!n) break;
        bytes.append(buffer, size_t(n)); if (bytes.size() > maximum) valid = false;
      }
      if (fd >= 0) ::close(fd);
      return valid;
    };
    MothershipNametagAllMastersIntent intent;
    MothershipNametagInitialSeedRecord proposed, recorded; bool resumed = false;
    bool valid = argc == 2 && readBounded(argv[0], intentBytes, 1024 * 1024) &&
        BitseryEngine::deserializeSafe(intentBytes, intent) && mothershipNametagAllMastersIntentValid(intent) &&
        intent.protocolVersion == MothershipNametagAllMastersIntent::seedRouteVersion &&
        readBounded(argv[1], planBytes, 65536);
    simdjson::dom::parser parser; simdjson::dom::element document; simdjson::dom::array entries;
    valid = valid && parser.parse(planBytes.data(), planBytes.size()).get(document) == simdjson::SUCCESS &&
        document.get(entries) == simdjson::SUCCESS && entries.size() == 8;
    Vector<MothershipProdigyCluster> clusters;
    if (valid) {
      proposed.operationUUID = intent.operationUUID; proposed.baselineOperationUUID = intent.sourceBaselineOperationUUID;
      proposed.intentBytes = intentBytes;
      valid = prodigyComputeSHA256Hex(intentBytes, proposed.intentSHA256, &failure);
      MothershipNametagSourceBaselineRecord baseline; bool found = false; String encoded;
      { auto registry = openClusterRegistry();
        valid = valid && registry.loadNametagSourceBaseline(intent.sourceBaselineOperationUUID, baseline, found, &failure) && found;
        for (uint32_t site = 0; valid && site < 3; ++site) {
          MothershipProdigyCluster cluster; String id; id.assignItoh(intent.sites[site].clusterUUID);
          valid = registry.getClusterByIdentity(id, cluster, &failure) &&
              mothershipNametagAllMastersSiteIdentityMatches(site, intent.sites[site].clusterUUID, cluster);
          if (valid) clusters.push_back(std::move(cluster));
        }
      }
      valid = valid && BitseryEngine::serialize(encoded, baseline.receipt) &&
          prodigyComputeSHA256Hex(encoded, proposed.baselineReceiptSHA256, &failure);
    }
    if (valid) for (auto entry : entries) {
      simdjson::dom::object object; uint64_t site = 0, app = 0; std::string_view plan, artifact;
      valid = !entry.get(object) && object.size() == 4 && !object["site"].get(site) && site >= 1 && site <= 2 &&
          !object["applicationID"].get(app) && (app == 2 || app == 3 || app == 4 || app == 5) &&
          !object["plan"].get(plan) && plan.size() > 2 && plan.size() <= 4096 && plan[0] == '@' && plan[1] == '/' &&
          !object["artifact"].get(artifact) && !artifact.empty() && artifact.size() <= 4096 && artifact[0] == '/';
      if (!valid) break;
      String planArgument, artifactArgument; planArgument.assign(plan.data(), plan.size()); artifactArgument.assign(artifact.data(), artifact.size());
      DeploymentPlan deployment; MothershipNametagInitialSeedPlan bound; bool early = false;
      valid = prepareDeploymentPlan(clusters[site].name.c_str(), planArgument.c_str(), artifactArgument.c_str(),
          deployment, bound.artifactPath, early, failure) &&
          mothershipValidateDiscombobulatorContainerBlobContract(bound.artifactPath, &failure) &&
          prodigyComputeFileSHA256Hex(bound.artifactPath, bound.artifactSHA256, &bound.artifactBytes, &failure);
      if (!valid) break;
      deployment.config.containerBlobSHA256 = bound.artifactSHA256; deployment.config.containerBlobBytes = bound.artifactBytes;
      bound.site = uint8_t(site); bound.applicationID = uint16_t(app); bound.deploymentID = deployment.config.deploymentID();
      bound.nShardGroups = app == 3 || app == 4 ? 3 : 1;
      valid = BitseryEngine::serialize(bound.normalizedPlan, deployment) &&
          prodigyComputeSHA256Hex(bound.normalizedPlan, bound.planSHA256, &failure);
      if (!valid) break;
      proposed.plans.push_back(std::move(bound));
    }
    if (valid) {
      std::sort(proposed.plans.begin(), proposed.plans.end(), [](const auto& a, const auto& b) {
        return a.site < b.site || (a.site == b.site && a.applicationID < b.applicationID);
      });
      auto registry = openClusterRegistry();
      valid = registry.persistNametagInitialSeed(proposed, resumed, &failure) &&
          registry.loadNametagInitialSeed(proposed.operationUUID, recorded, &failure);
    }
    for (uint32_t i = 0; valid && i < recorded.plans.size(); ++i)
      valid = installNametagInitialSeedPlan(recorded, i, clusters[recorded.plans[i].site], failure);
    if (!valid && failure.empty()) failure.assign("initial bootstrap requires the exact intent and eight private all-masters plan/artifact inputs"_ctv);
    basics_log("bootstrapNametagAllMasters success=%u resumed=%u failure=%s\n", unsigned(valid), unsigned(resumed), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  bool prepareNametagExpiredCutRecovery(MothershipNametagAllMastersPreparation& preparation, String& failure)
  {
    auto& intent = preparation.intent;
    if (!intent.isExpiredCutRecovery()) return true;
    MothershipNametagAllMastersRecord prior; MothershipNametagInitialSeedRecord bootstrap;
    MothershipNametagSourceBaselineRecord baseline; MothershipNametagAllMastersIntent claim;
    MothershipProdigyCluster source; bool baselineFound = false, claimed = false;
    String encoded, digest, sourceID;
    {
      auto registry = openClusterRegistry();
      if (!registry.loadNametagAllMasters(intent.predecessorOperationUUID, prior, &failure) ||
          !BitseryEngine::serialize(encoded, prior) || !prodigyComputeSHA256Hex(encoded, digest, &failure) ||
          digest != intent.predecessorRecordSHA256 ||
          !registry.loadNametagInitialSeed(intent.predecessorOperationUUID, bootstrap, &failure) ||
          !registry.loadNametagSourceBaseline(prior.intent.sourceBaselineOperationUUID, baseline, baselineFound, &failure) || !baselineFound ||
          !registry.loadNametagExpiredCutRecoveryPreparation(intent.predecessorOperationUUID, claim, claimed, &failure)) return false;
      sourceID.assignItoh(prior.intent.sites[0].clusterUUID);
      if (!registry.getClusterByIdentity(sourceID, source, &failure)) return false;
    }
    encoded.clear();
    if (!BitseryEngine::serialize(encoded, bootstrap) || !prodigyComputeSHA256Hex(encoded, intent.initialSeedRecordSHA256, &failure)) return false;
    encoded.clear();
    if (!BitseryEngine::serialize(encoded, baseline) || !prodigyComputeSHA256Hex(encoded, intent.predecessorBaselineSHA256, &failure)) return false;
    for (size_t i = 0; i < preparation.sourceRepairApplications.size(); ++i) {
      MothershipNametagSourceRepairPlan bound;
      bound.applicationID = preparation.sourceRepairApplications[i];
      bound.previousDeploymentID = bound.applicationID == 3 ? prior.intent.sites[0].hotDeploymentID :
          bound.applicationID == 4 ? prior.intent.sites[0].coldDeploymentID : prior.intent.sites[0].radarDeploymentID;
      DeploymentPlan plan; String artifact; bool early = false;
      if (!prepareDeploymentPlan(source.name.c_str(), preparation.sourceRepairPlanPaths[i].c_str(),
          preparation.sourceRepairArtifactPaths[i].c_str(), plan, artifact, early, failure) ||
          !mothershipValidateDiscombobulatorContainerBlobContract(artifact, &failure) ||
          !prodigyComputeFileSHA256Hex(artifact, bound.artifactSHA256, &bound.artifactBytes, &failure)) return false;
      plan.config.containerBlobSHA256 = bound.artifactSHA256; plan.config.containerBlobBytes = bound.artifactBytes;
      bound.successorDeploymentID = plan.config.deploymentID();
      if (!BitseryEngine::serialize(bound.normalizedPlan, plan) || !prodigyComputeSHA256Hex(bound.normalizedPlan, bound.planSHA256, &failure)) return false;
      if (claimed) {
        const auto old = std::find_if(claim.sourceRepairPlans.begin(), claim.sourceRepairPlans.end(),
            [&](const auto& value) { return value.applicationID == bound.applicationID; });
        if (old == claim.sourceRepairPlans.end()) return false;
        bound.predecessor = old->predecessor;
      } else {
        DeploymentIdentityReport unlaunched;
        if (!readDeploymentIdentity(source, bound.previousDeploymentID, bound.predecessor, failure) ||
            !readDeploymentIdentity(source, bound.successorDeploymentID, unlaunched, failure, false, true) || unlaunched.found) {
          if (failure.empty()) failure.assign("source repair must be prepared against the live predecessor before successor admission"_ctv);
          return false;
        }
      }
      if (!mothershipNametagSourceRepairPlanValid(bound)) { failure.assign("source repair permits only exact predecessor image and version replacement"_ctv); return false; }
      intent.sourceRepairPlans.push_back(std::move(bound));
    }
    std::sort(intent.sourceRepairPlans.begin(), intent.sourceRepairPlans.end(), [](const auto& a, const auto& b) { return a.applicationID < b.applicationID; });
    bool resumed = false;
    auto registry = openClusterRegistry();
    return registry.persistNametagExpiredCutRecoveryPreparation(intent, resumed, &failure);
  }

  void runPrepareNametagAllMasters(int argc, char *argv[])
  {
    String failure = {}, bytes = {}, intentSHA256 = {};
    MothershipNametagAllMastersPreparation preparation = {};
    bool valid = argc == 2;
    const int fd = valid ? ::open(argv[0], O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK) : -1;
    struct stat state = {};
    valid = valid && fd >= 0 && ::fstat(fd, &state) == 0 && S_ISREG(state.st_mode) &&
        state.st_size > 0 && state.st_size <= 1024 * 1024;
    for (char buffer[4096] = {}; valid;) {
      const ssize_t count = ::read(fd, buffer, sizeof(buffer));
      if (count < 0 && errno == EINTR) continue;
      if (count < 0) { valid = false; break; }
      if (count == 0) break;
      bytes.append(buffer, size_t(count));
      if (bytes.size() > 1024 * 1024) { valid = false; break; }
    }
    if (fd >= 0) ::close(fd);
    simdjson::dom::parser parser; simdjson::dom::element document;
    valid = valid && !bytes.empty() && parser.parse(bytes.data(), bytes.size()).get(document) == simdjson::SUCCESS &&
        mothershipParseNametagAllMastersPreparationJSON(document, preparation, failure);
    if (!valid && failure.empty())
      failure.assign("usage: prepareNametagAllMasters OPERATOR_JSON_PATH OUTPUT_INTENT_BIN (bounded regular JSON file required)"_ctv);
    if (valid) {
      auto registry = openClusterRegistry();
      Vector<MothershipProdigyCluster> sites = {};
      for (uint32_t site = 0; valid && site < preparation.intent.sites.size(); ++site) {
        MothershipProdigyCluster cluster = {};
        valid = registry.getClusterByIdentity(preparation.siteNames[site], cluster, &failure) &&
            mothershipNametagAllMastersPreparedSiteMatches(site, preparation.siteNames[site], cluster);
        if (valid) {
          preparation.intent.sites[site].clusterUUID = cluster.clusterUUID;
          sites.push_back(std::move(cluster));
        }
        if (!valid && failure.empty())
          failure.assign("all-masters preparation requires the registered EWR, ORD and LAN three-Brain clusters in that order"_ctv);
      }
      bool pairs[3][3] = {};
      for (const uint128_t operationUUID : preparation.pairOperationUUIDs) {
        if (!valid) break;
        MothershipClusterPairEnrollmentIntent pair = {};
        valid = registry.loadClusterPairEnrollmentIntent(operationUUID, pair, &failure) &&
            pair.operationUUID == operationUUID && pair.pairUUID != 0 && pair.firstQualified && pair.secondQualified;
        uint32_t first = UINT32_MAX, second = UINT32_MAX;
        for (uint32_t site = 0; valid && site < sites.size(); ++site) {
          if (sites[site].clusterUUID == pair.firstClusterUUID) first = site;
          if (sites[site].clusterUUID == pair.secondClusterUUID) second = site;
        }
        valid = valid && first < 3 && second < 3 && first != second;
        const uint32_t left = first < second ? first : second;
        const uint32_t right = first < second ? second : first;
        valid = valid && !pairs[left][right];
        if (valid) pairs[left][right] = true;
        for (uint32_t direction = 0; valid && direction < 2; ++direction) {
          const uint32_t local = direction == 0 ? first : second;
          if (!valid) break;
          const uint32_t peer = local == first ? second : first;
          for (const ClusterMachine& machine : sites[local].topology.machines) {
            CrossClusterMasqueGatewayAuthority authority = {};
            valid = machine.isBrain && machine.uuid != 0 &&
                registry.loadCrossClusterMasqueGateway(pair.pairUUID, machine.uuid, authority, &failure) &&
                prodigyCrossClusterMasqueGatewayAuthorityStructurallyValid(authority) &&
                authority.state == CrossClusterMasqueGatewayState::active &&
                authority.pairUUID == pair.pairUUID && authority.pairOperationUUID == operationUUID &&
                authority.localClusterUUID == sites[local].clusterUUID && authority.peerClusterUUID == sites[peer].clusterUUID &&
                authority.localMachineUUID == machine.uuid;
            if (valid) preparation.intent.directGatewayAuthorities.push_back(std::move(authority));
            else if (failure.empty())
              failure.assign("all-masters preparation requires each current active gateway authority for the enrolled pair topology"_ctv);
            if (!valid) break;
          }
        }
      }
      valid = valid && pairs[0][1] && pairs[0][2] && pairs[1][2];
      if (!valid && failure.empty())
        failure.assign("all-masters preparation requires exactly the EWR/ORD, EWR/LAN and ORD/LAN enrollments"_ctv);
    }
    if (valid && !prepareNametagExpiredCutRecovery(preparation, failure)) {
      valid = false;
      if (failure.empty()) failure.assign("expired-cut recovery preparation does not match its immutable predecessor or exact repair inputs"_ctv);
    }
    if (valid) {
      valid = mothershipNametagAllMastersIntentValid(preparation.intent) &&
          BitseryEngine::serialize(bytes, preparation.intent) && prodigyComputeSHA256Hex(bytes, intentSHA256, &failure);
      if (!valid && failure.empty())
        failure.assign("all-masters preparation lacks the exact eighteen-authority direct topology or distinct deployment identities"_ctv);
    }
    if (valid) valid = ContainerStore::atomicWriteRuntimeFile(String(argv[1]), bytes, &failure);
    basics_log("prepareNametagAllMasters success=%u intentSHA256=%s failure=%s\n",
        unsigned(valid), intentSHA256.c_str(), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  bool validateNametagSeedRoute(const MothershipNametagAllMastersRecord& record,
      const MothershipNametagAllMastersSeedPlacement& row, const ProdigyStatefulStoreSeedAuthority& authority,
      String& failure)
  {
    if (record.intent.protocolVersion != MothershipNametagAllMastersIntent::seedRouteVersion &&
        !record.intent.isExpiredCutRecovery()) {
      failure.assign("source-cut seeding requires versioned durable seed route references"_ctv); return false;
    }
    const auto reference = std::find_if(record.intent.seedRoutes.begin(), record.intent.seedRoutes.end(), [&](const auto& value) {
      return value.site == row.site && value.applicationID == row.applicationID && value.shardGroup == row.shardGroup;
    });
    if (reference == record.intent.seedRoutes.end() || reference->routeUUID != authority.seedRouteUUID) {
      failure.assign("missing exact seed route reference"_ctv); return false;
    }
    CousinRouteRecord route = {};
    CousinRouteApplyReceipt sourceReceipt = {}, destinationReceipt = {};
    MothershipProdigyCluster target = {}, source = {}; String targetID = {}, sourceID = {};
    targetID.assignItoh(row.targetClusterUUID); sourceID.assignItoh(row.sourceClusterUUID);
    {
      auto registry = openClusterRegistry();
      if (!registry.getClusterByIdentity(targetID, target, &failure) || !registry.getClusterByIdentity(sourceID, source, &failure) ||
          !registry.loadUsableCousinRoute(reference->routeUUID, Time::now<TimeResolution::ms>(), route, &failure) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::source, sourceReceipt, &failure) ||
          !registry.loadCurrentCousinRouteApplyReceipt(route.routeUUID, CousinRouteHalf::destination, destinationReceipt, &failure)) return false;
    }
    const uint64_t service = prodigyRuntimeStatefulServicePrefix(row.applicationID, 4);
    const bool gatewayPair = std::any_of(record.intent.directGatewayAuthorities.begin(), record.intent.directGatewayAuthorities.end(),
      [&](const auto& gateway) { return gateway.pairUUID == route.pairUUID && gateway.localClusterUUID == row.targetClusterUUID &&
          gateway.peerClusterUUID == row.sourceClusterUUID && gateway.state == CrossClusterMasqueGatewayState::active; });
    if (!gatewayPair || route.sourceClusterUUID != row.targetClusterUUID || route.destinationClusterUUID != row.sourceClusterUUID ||
        route.sourceApplicationID != row.applicationID || route.destinationApplicationID != row.applicationID ||
        !service || route.sourceCousinServicePrefix != service || route.destinationCousinServicePrefix != service ||
        route.expiresAtMs < int64_t(authority.retainUntilMilliseconds)) {
      failure.assign("seed route does not bind the exact target-to-source cohort, gateway, service and cut lifetime"_ctv); return false;
    }
    ProdigyLocalCousinServicePermissionResponse subscriber = {}, advertiser = {};
    if (!readLocalCousinServicePermission(target, route.sourcePermissionUUID, subscriber, failure) ||
        !readLocalCousinServicePermission(source, route.destinationPermissionUUID, advertiser, failure)) return false;
    const auto& left = subscriber.permission; const auto& right = advertiser.permission;
    uint16_t slot = 0, peerSlot = 0;
    if (left.localHalf != CousinRouteHalf::source || right.localHalf != CousinRouteHalf::destination ||
        left.purpose != ProdigyCousinServicePurpose::seeding || right.purpose != ProdigyCousinServicePurpose::seeding ||
        left.localDeploymentID != row.targetDeploymentID || right.localDeploymentID != row.sourceDeploymentID ||
        left.peerDeploymentID != row.sourceDeploymentID || right.peerDeploymentID != row.targetDeploymentID ||
        left.destinationShardGroup != row.shardGroup || right.destinationShardGroup != row.shardGroup ||
        left.destinationShardGroups != authority.nShardGroups || right.destinationShardGroups != authority.nShardGroups ||
        !prodigyCousinServicePermissionPeerScopeMatches(left, right) ||
        !prodigyCousinServicePermissionSingleSlot(left, slot) || !prodigyCousinServicePermissionSingleSlot(right, peerSlot) ||
        slot != peerSlot || route.slots != left.slots || route.slots != right.slots || !route.slots.contains(slot)) {
      failure.assign("seed route permissions do not bind exact deployment, shard and slot"_ctv); return false;
    }
    if (route.endpointKind == CousinRouteEndpointKind::privateContainer) {
      DeploymentIdentityReport sourceReport = {};
      ProdigyCousinDiscoveryQuery query = {}; query.permissionUUID = route.sourcePermissionUUID; query.slot = slot;
      ProdigyCousinDiscoveryResponse discovery = {};
      if (!readDeploymentIdentity(source, row.sourceDeploymentID, sourceReport, failure) ||
          !configureControlTarget(target.name.c_str(), &failure) ||
          !requestTopicRoundTrip(MothershipTopic::pullCousinCounterparts, query, discovery, failure) ||
          discovery.protocolVersion != ProdigyCousinDiscoveryResponse::version || !discovery.success ||
          discovery.records.size() > ProdigyCousinDiscoveryMaximumRecords ||
          std::count_if(discovery.records.begin(), discovery.records.end(), [&](const auto& counterpart) {
            return mothershipNametagPrivateSeedCounterpartMatches(row, authority, route, left, right, slot,
                sourceReport, counterpart);
          }) != 1) {
        if (failure.empty()) failure.assign("private seed route lacks the exact current retained source counterpart"_ctv);
        return false;
      }
    } else {
      RoutableSubnetRegistryReport ranges = {};
      if (!readRoutableSubnets(source, ranges, failure)) return false;
      const auto range = std::find_if(ranges.subnets.begin(), ranges.subnets.end(), [&](const auto& value) {
        return value.uuid == route.destinationRoutablePrefixUUID;
      });
      if (range == ranges.subnets.end() || !cousinRouteDestinationRangeContainsAddress(route, range->subnet)) {
        failure.assign("seed route destination is outside its registered source prefix"_ctv); return false;
      }
    }
    ProdigyCousinRouteResponse targetResponse = {}, sourceResponse = {};
    return observeCousinRouteSide(target, route, CousinRouteHalf::source, targetResponse, failure) &&
        observeCousinRouteSide(source, route, CousinRouteHalf::destination, sourceResponse, failure) &&
        targetResponse.found && sourceResponse.found && targetResponse.qualified && sourceResponse.qualified &&
        cousinRouteExactMatches(targetResponse.route, route) &&
        cousinRouteExactMatches(sourceResponse.route, route) &&
        cousinRouteApplyReceiptMatchesCurrentRoute(targetResponse.applyReceipt, route) &&
        cousinRouteApplyReceiptMatchesCurrentRoute(sourceResponse.applyReceipt, route);
  }

  void runNametagAllMasters(int argc, char *argv[])
  {
    String failure = {}, bytes = {}, baselineFixture = {};
    MothershipNametagAllMastersIntent intent = {};
    bool valid = argc == 1;
    int fd = valid ? ::open(argv[0], O_RDONLY | O_CLOEXEC | O_NOFOLLOW) : -1;
    if (fd < 0) valid = false;
    for (char buffer[4096] = {}; valid;) {
      const ssize_t count = ::read(fd, buffer, sizeof(buffer));
      if (count < 0 || (count == 0 && bytes.empty())) { valid = false; break; }
      if (count == 0) break;
      bytes.append(buffer, size_t(count));
      if (bytes.size() > 1024 * 1024) { valid = false; break; }
    }
    if (fd >= 0) ::close(fd);
    valid = valid && BitseryEngine::deserializeSafe(bytes, intent) && mothershipNametagAllMastersIntentValid(intent);
    if (!valid) failure.assign("usage: nametagAllMasters VERSIONED_INTENT_BIN (valid exact all-masters intent required)"_ctv);
    MothershipNametagAllMastersRecord proposed = {}, recorded = {}; bool resumed = false;
    Vector<DeploymentIdentityReport> pulseObservations = {}, hotObservations = {}, coldObservations = {}, radarObservations = {};
    Vector<MothershipProdigyCluster> siteClusters = {};
    if (valid) {
      Vector<DeploymentIdentityReport> app6Observations = {};
      DeploymentIdentityReport ewrTruthObservation = {};
      for (uint32_t index = 0; valid && index < intent.sites.size(); ++index) {
        MothershipProdigyCluster cluster = {}; DeploymentIdentityReport pulse = {}, hot = {}, cold = {}, radar = {}, truth = {}, app6 = {};
        String clusterIdentity = {}; clusterIdentity.assignItoh(intent.sites[index].clusterUUID);
        // Control-target resolution opens the same registry; release each local
        // registry handle before entering a control-plane operation.
        {
          auto registry = openClusterRegistry();
          valid = registry.getClusterByIdentity(clusterIdentity, cluster, &failure) &&
              mothershipNametagAllMastersSiteIdentityMatches(index, intent.sites[index].clusterUUID, cluster) && cluster.nBrains == 3;
        }
        valid = valid &&
            readDeploymentIdentity(cluster, intent.sites[index].pulseDeploymentID, pulse, failure) &&
            readDeploymentIdentity(cluster, intent.sites[index].hotDeploymentID, hot, failure) &&
            readDeploymentIdentity(cluster, intent.sites[index].coldDeploymentID, cold, failure) &&
            readDeploymentIdentity(cluster, intent.sites[index].radarDeploymentID, radar, failure) &&
            readDeploymentIdentity(cluster, intent.sites[index].app6DeploymentID, app6, failure) &&
            (index != 0 || readDeploymentIdentity(cluster, intent.sites[index].truthDeploymentID, truth, failure)) &&
            // A new source-cut operation starts before any remote seed receipt.
            (index == 0 && intent.protocolVersion == MothershipNametagAllMastersIntent::version ?
             mothershipNametagAllMastersSiteObserved(intent.sites[index], pulse, hot, cold, radar, &truth) :
             index == 0 ? mothershipNametagAllMastersSiteReadyForSeedSelection(intent.sites[index], pulse, hot, cold, radar, &truth) :
             mothershipNametagAllMastersSiteReadyForSeedSelection(intent.sites[index], pulse, hot, cold, radar, nullptr));
        if (valid) {
          // Keep the authenticated reports until the bounded seed placement is
          // synthesized.  The caller supplied no container identities.
          pulseObservations.push_back(pulse); hotObservations.push_back(hot);
          coldObservations.push_back(cold); radarObservations.push_back(radar);
          siteClusters.push_back(cluster);
          app6Observations.push_back(std::move(app6)); if (index == 0) ewrTruthObservation = std::move(truth);
        }
        if (!valid && failure.empty()) failure.assign("Nametag all-masters seed selection lacks an exact healthy target plan or EWR Truth writer"_ctv);
      }
      if (valid && (!mothershipNametagApp6IdentitySetObserved(app6Observations, intent.sites) ||
          !mothershipNametagTruthWriterObserved(ewrTruthObservation, intent.sites[0]))) {
        valid = false; failure.assign("Nametag all-masters requires exact app6 identities and the EWR Truth writer"_ctv);
      }
      if (valid) {
        MothershipApplicationPlacement truthPlacement = {};
        {
          auto registry = openClusterRegistry();
          valid = registry.loadTruthPlacement(truthPlacement, &failure) &&
              truthPlacement.ownerClusterUUID == intent.sites[0].clusterUUID;
        }
        for (uint32_t site = 0; valid && site < siteClusters.size(); ++site) {
          ClusterStatusReport status = {};
          valid = readManagedClusterStatus(siteClusters[site], status, failure) &&
              mothershipNametagAllMastersTruthDeploymentCardinalityObserved(status, site == 0);
        }
        if (!valid && failure.empty()) failure.assign("Nametag all-masters requires exactly the authenticated EWR Truth deployment and no ORD/LAN Truth deployment"_ctv);
      }
      // Each pair is represented by both local gateway authorities.  Reload
      // the durable record byte-for-byte, then require its current authenticated
      // QUIC readiness before the seed authority can leave Mothership.
      for (const auto& requested : intent.directGatewayAuthorities) {
        if (!valid) break;
        uint32_t localSite = UINT32_MAX;
        for (uint32_t site = 0; site < intent.sites.size(); ++site)
          if (intent.sites[site].clusterUUID == requested.localClusterUUID) localSite = site;
        CrossClusterMasqueGatewayAuthority persisted = {};
        String requestedBytes = {}, persistedBytes = {};
        auto requestedCopy = requested;
        {
          auto registry = openClusterRegistry();
          valid = localSite < siteClusters.size() &&
              registry.loadCrossClusterMasqueGateway(requested.pairUUID, requested.localMachineUUID, persisted, &failure);
        }
        valid = valid &&
            BitseryEngine::serialize(requestedBytes, requestedCopy) &&
            BitseryEngine::serialize(persistedBytes, persisted) && requestedBytes == persistedBytes &&
            waitForCrossClusterMasqueGatewayReadiness(siteClusters[localSite], persisted, failure);
        if (!valid && failure.empty()) failure.assign("Nametag all-masters requires current direct MASQUE readiness for every site pair"_ctv);
      }
    }
    if (valid) {
      auto copy = intent;
      valid = BitseryEngine::serialize(bytes, copy) && prodigyComputeSHA256Hex(bytes, proposed.requestSHA256, &failure);
      proposed.intent = intent;
      if (valid && intent.isExpiredCutRecovery()) {
        MothershipNametagAllMastersRecord prior; MothershipNametagInitialSeedRecord bootstrap;
        auto registry = openClusterRegistry();
        valid = registry.validateNametagExpiredCutRecovery(intent, prior, bootstrap, &failure) &&
            mothershipNametagExpiredCutRecoveryReportsMatch(intent, bootstrap, pulseObservations, hotObservations, coldObservations, radarObservations);
        if (!valid && failure.empty()) failure.assign("source repair or remote bootstrap reports differ from the immutable prepared plans"_ctv);
      }
      if (valid && intent.protocolVersion >= MothershipNametagAllMastersIntent::sourceCutVersion) {
        MothershipNametagSourceBaselineRecord baseline = {}; bool found = false;
        const auto& site = intent.sites[0];
        {
          auto registry = openClusterRegistry();
          valid = registry.loadNametagSourceBaseline(intent.sourceBaselineOperationUUID, baseline, found, &failure) && found &&
              baseline.command.ewrClusterUUID == site.clusterUUID && baseline.command.pulseDeploymentID == site.pulseDeploymentID &&
              baseline.command.hotDeploymentID == site.hotDeploymentID && baseline.command.coldDeploymentID == site.coldDeploymentID &&
              baseline.command.radarDeploymentID == site.radarDeploymentID && baseline.command.truthDeploymentID == site.truthDeploymentID;
          if (valid && intent.isExpiredCutRecovery()) {
            MothershipNametagAllMastersRecord prior; MothershipNametagSourceBaselineRecord oldBaseline; bool oldFound = false;
            valid = registry.loadNametagAllMasters(intent.predecessorOperationUUID, prior, &failure) &&
                registry.loadNametagSourceBaseline(prior.intent.sourceBaselineOperationUUID, oldBaseline, oldFound, &failure) && oldFound &&
                baseline.command.probeDeploymentID == oldBaseline.command.probeDeploymentID;
          }
        }
        if (valid) baselineFixture = baseline.command.fixtureManifestSHA256;
        if (!valid && failure.empty()) failure.assign("source cut requires the exact durable completed EWR source baseline"_ctv);
        proposed.protocolVersion = MothershipNametagAllMastersRecord::sourceCutVersion;
        proposed.phase = MothershipNametagAllMastersRecord::Phase::sourceCutsPreparing;
        struct Source { uint16_t app; DeploymentIdentityStoreKind kind; uint32_t groups; const Vector<DeploymentIdentityReport> *reports; };
        const Source sources[] = {{MeshRegistry::Pulse::applicationID, DeploymentIdentityStoreKind::graph, 1, &pulseObservations},
          {MeshRegistry::Hot::applicationID, DeploymentIdentityStoreKind::kv, 3, &hotObservations},
          {MeshRegistry::Cold::applicationID, DeploymentIdentityStoreKind::kv, 3, &coldObservations},
          {MeshRegistry::Radar::applicationID, DeploymentIdentityStoreKind::graph, 1, &radarObservations}};
        // Keep the frozen source copy available across bounded delivery and recovery.
        const int64_t retainUntil = Time::now<TimeResolution::ms>() + 3'600'000;
        for (const auto& source : sources) for (uint32_t group = 0; valid && group < source.groups; ++group) {
          const auto& report = source.reports->front();
          const auto* selected = nametagSourceCutMember(report, group);
          if (!selected) { valid = false; break; }
          MothershipNametagSourceCutProgress cut = {};
          cut.request.operationUUID = mothershipNametagSeedOperationUUID(proposed);
          cut.request.requestUUID = Random::generateNumberWithNBits<128, uint128_t>();
          cut.request.sourceClusterUUID = report.clusterUUID; cut.request.sourceDeploymentID = report.deploymentID;
          cut.request.sourceContainerUUID = selected->containerUUID; cut.request.applicationID = source.app;
          cut.request.storeKind = source.kind; cut.request.shardGroup = group; cut.request.nShardGroups = source.groups;
          cut.request.retainUntilMilliseconds = retainUntil;
          valid = prodigyStatefulStoreSourceCutValid(cut.request);
          if (valid) proposed.sourceCuts.push_back(std::move(cut));
        }
        if (valid) {
          auto registry = openClusterRegistry();
          valid = registry.persistNametagAllMasters(proposed, recorded, resumed, &failure);
        }
        for (uint32_t i = 0; valid && i < recorded.sourceCuts.size(); ++i) {
          auto cut = recorded.sourceCuts[i];
          if (recorded.phase == MothershipNametagAllMastersRecord::Phase::remoteSeeded) continue;
          if (cut.released || cut.request.retainUntilMilliseconds <= Time::now<TimeResolution::ms>()) {
            valid = false; failure.assign("persisted source cut is released or expired"_ctv); break;
          }
          if (cut.proof.ready) continue;
          if (cut.dispatched && cut.request.memberRequestUUID == 0) {
            valid = false; failure.assign("source cut dispatch outcome is ambiguous; refusing a new challenge"_ctv); break;
          }
          if (!cut.dispatched) {
            MothershipNametagAllMastersRecord progressed = {};
            {
              auto registry = openClusterRegistry();
              valid = registry.updateNametagAllMastersSourceCut(intent.operationUUID, i, true, nullptr, progressed, &failure);
            }
            if (!valid) break;
            recorded = std::move(progressed); cut = recorded.sourceCuts[i];
          }
          for (uint32_t poll = 0; valid && poll < 300 && !recorded.sourceCuts[i].proof.ready; ++poll) {
            ProdigyStatefulStoreSourceCut reply = {};
            const auto request = recorded.sourceCuts[i].request;
            valid = configureControlTarget(siteClusters[0].name.c_str(), &failure) &&
                requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, request, reply, failure);
            if (!valid) break;
            auto expected = request;
            if (expected.memberRequestUUID == 0) expected.memberRequestUUID = reply.memberRequestUUID;
            valid = prodigyStatefulStoreSourceCutResponseMatches(expected, reply) && reply.failure.empty();
            if (!valid) {
              if (!reply.failure.empty()) failure = reply.failure;
              else failure.assign("source cut returned an invalid challenge"_ctv);
              break;
            }
            MothershipNametagAllMastersRecord progressed = {};
            {
              auto registry = openClusterRegistry();
              valid = registry.updateNametagAllMastersSourceCut(intent.operationUUID, i, false, &reply, progressed, &failure);
            }
            if (valid) recorded = std::move(progressed);
            if (valid && !reply.ready) ::usleep(100'000);
          }
          if (valid && !recorded.sourceCuts[i].proof.ready) { valid = false; failure.assign("source cut did not become ready"_ctv); }
        }
        for (uint32_t i = 0; valid && i < recorded.sourceCuts.size(); ++i) {
          const auto& cut = recorded.sourceCuts[i];
          if (cut.released || recorded.phase == MothershipNametagAllMastersRecord::Phase::remoteSeeded) continue;
          auto query = cut.request; query.action = ProdigyStatefulStoreSourceCutAction::query;
          query.cutUUID = cut.proof.cutUUID; query.cutGeneration = cut.proof.cutGeneration;
          ProdigyStatefulStoreSourceCut reply = {};
          valid = configureControlTarget(siteClusters[0].name.c_str(), &failure) &&
              requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, query, reply, failure) &&
              prodigyStatefulStoreSourceCutResponseMatches(query, reply) && reply.ready && reply.failure.empty() &&
              reply.contentSHA256 == cut.proof.contentSHA256 && reply.headsSHA256 == cut.proof.headsSHA256 &&
              cut.request.retainUntilMilliseconds > Time::now<TimeResolution::ms>();
          if (!valid && failure.empty()) failure.assign("retained native source cut is no longer current"_ctv);
        }
        if (valid && recorded.phase == MothershipNametagAllMastersRecord::Phase::sourceCutsPreparing) {
          MothershipNametagAllMastersRecord progressed = {};
          auto registry = openClusterRegistry();
          valid = registry.installNametagAllMastersSourceCutPlacements(intent.operationUUID, pulseObservations, hotObservations,
              coldObservations, radarObservations, baselineFixture, progressed, &failure);
          if (valid) recorded = std::move(progressed);
        }
      }
      if (valid && intent.protocolVersion == MothershipNametagAllMastersIntent::version && !mothershipNametagAllMastersSeedPlacementsSynthesize(
              intent, pulseObservations, hotObservations, coldObservations, radarObservations, proposed.seedPlacements)) {
        valid = false; failure.assign("Nametag all-masters seed placement could not bind every authenticated replica"_ctv);
      }
      if (valid && intent.protocolVersion == MothershipNametagAllMastersIntent::version) { auto registry = openClusterRegistry(); valid = registry.persistNametagAllMasters(proposed, recorded, resumed, &failure); }
      // The registry record is the only authority source. Convert each
      // persisted remote row into one exact target command; no live deployment
      // observation is reused for delivery. Persist acceptance before moving
      // to the next target so Mothership can resume after a process restart.
      for (uint32_t rowIndex = 0; valid && rowIndex < recorded.seedPlacements.size(); ++rowIndex) {
        auto row = recorded.seedPlacements[rowIndex];
        if (row.deliveryApplied && (recorded.protocolVersion < MothershipNametagAllMastersRecord::sourceCutVersion || row.catchupObserved)) continue;
        {
          auto registry = openClusterRegistry();
          valid = registry.claimNametagAllMastersSeedDelivery(recorded.intent.operationUUID, rowIndex, recorded, &failure);
          if (!valid) break;
          row = recorded.seedPlacements[rowIndex];
        }
        MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(row.targetClusterUUID);
        {
          auto registry = openClusterRegistry();
          valid = registry.getClusterByIdentity(identity, cluster, &failure);
        }
        valid = valid && configureControlTarget(cluster.name.c_str(), &failure) && socket.ensureConnected();
        ProdigyStatefulStoreSeedAuthority authority = {};
        if (valid) {
          authority.authorityGeneration = row.seedGeneration; authority.operationUUID = recorded.intent.operationUUID;
          authority.applicationID = row.applicationID; authority.storeKind = row.storeKind; authority.shardGroup = row.shardGroup;
          authority.nShardGroups = (row.applicationID == MeshRegistry::Hot::applicationID || row.applicationID == MeshRegistry::Cold::applicationID) ? 3 : 1;
          authority.targetClusterUUID = row.targetClusterUUID; authority.targetDeploymentID = row.targetDeploymentID; authority.targetContainerUUID = row.targetContainerUUID;
          authority.sourceClusterUUID = row.sourceClusterUUID; authority.sourceDeploymentID = row.sourceDeploymentID; authority.sourceContainerUUID = row.sourceContainerUUID;
          authority.seedGeneration = row.seedGeneration; authority.fixtureSHA256 = row.fixtureSHA256;
          authority.expectedCatchupWatermarkSHA256 = row.expectedCatchupWatermarkSHA256;
          authority.sourceContentWatermarkSHA256 = row.sourceContentWatermarkSHA256;
          authority.sourceCatchupWatermarkSHA256 = row.sourceCatchupWatermarkSHA256;
          if (recorded.protocolVersion >= MothershipNametagAllMastersRecord::sourceCutVersion)
            valid = mothershipNametagSourceCutAuthority(recorded, row, authority);
          String encoded = {}; auto copy = authority;
          valid = valid && prodigyStatefulStoreSeedAuthorityValid(authority);
          if (valid && recorded.protocolVersion >= MothershipNametagAllMastersRecord::sourceCutVersion)
            valid = validateNametagSeedRoute(recorded, row, authority, failure) && configureControlTarget(cluster.name.c_str(), &failure) && socket.ensureConnected();
          valid = valid && BitseryEngine::serialize(encoded, copy);
          if (valid) {
            Message::construct(socket.wBuffer, MothershipTopic::applyNametagAllMastersSeedAuthority, encoded);
            valid = socket.send();
            Message *response = valid ? socket.recvExpectedTopic(MothershipTopic::applyNametagAllMastersSeedAuthority) : nullptr;
            uint8_t applied = 0;
            if (!response) valid = false;
            else { uint8_t *reply = response->args; Message::extractArg<ArgumentNature::fixed>(reply, applied); valid = reply == response->terminal() && applied == 1; }
          }
          if (valid && authority.protocolVersion == ProdigyStatefulStoreSeedAuthority::qualificationSeedFaultVersion) {
            ProdigyNametagQualificationSeedFault arm = {}, reply = {};
            arm.runUUID = authority.qualificationRunUUID; arm.challengeUUID = authority.qualificationChallengeUUID;
            arm.executionGeneration = authority.qualificationExecutionGeneration;
            arm.deadlineAtMilliseconds = authority.qualificationDeadlineAtMilliseconds;
            arm.stage = ProdigyNametagQualificationSeedFaultStage::arm; arm.authority = authority;
            bool armed = false;
            while (Time::now<TimeResolution::ms>() < arm.deadlineAtMilliseconds) {
              if (!requestTopicRoundTrip(MothershipTopic::nametagQualification, arm, reply, failure) ||
                  !prodigyNametagQualificationSeedFaultResponseMatches(arm, reply) || !reply.failure.empty()) {
                valid = false; break;
              }
              if (reply.ready) { armed = true; break; }
              ::usleep(100'000);
            }
            if (!armed) { valid = false; if (failure.empty()) failure.assign("seed fault arm was not acknowledged"_ctv); }
          }
        }
        socket.close();
        if (valid) {
          MothershipNametagAllMastersRecord progressed = {};
          auto registry = openClusterRegistry();
          valid = registry.markNametagAllMastersSeedDelivered(recorded.intent.operationUUID, row, progressed, &failure);
          if (valid) recorded = std::move(progressed);
        }
        if (!valid && failure.empty()) failure.assign("persisted Nametag all-masters seed authority was not accepted by its exact target"_ctv);
      }
      // Recover only a previously observed durable row. The old receipt is an
      // expectation; Brain requests a new receipt from the still-live store.
      if (valid && recorded.protocolVersion >= MothershipNametagAllMastersRecord::sourceCutVersion) {
        for (const auto& row : recorded.seedPlacements) {
          if (!row.deliveryApplied || !row.catchupObserved) continue;
          ProdigyStatefulStoreProofRecovery request = {};
          request.expected = row.nativeSourceCutReceipt;
          request.nonce = Random::generateNumberWithNBits<128, uint128_t>();
          MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(row.targetClusterUUID);
          ProdigyStatefulStoreProofRecovery reply = {};
          {
            auto registry = openClusterRegistry();
            valid = mothershipNametagSourceCutAuthority(recorded, row, request.authority) &&
                prodigyStatefulStoreProofRecoveryValid(request) && registry.getClusterByIdentity(identity, cluster, &failure);
          }
          valid = valid && configureControlTarget(cluster.name.c_str(), &failure) &&
              requestTopicRoundTrip(MothershipTopic::statefulStoreProofRecovery, request, reply, failure);
          String expectedBytes, replyBytes; auto expected = request; expected.response = true; expected.accepted = true;
          valid = valid && reply.response && reply.accepted && prodigyStatefulStoreProofRecoveryValid(reply) &&
              BitseryEngine::serialize(expectedBytes, expected) && BitseryEngine::serialize(replyBytes, reply) && expectedBytes == replyBytes;
          if (!valid) { if (failure.empty()) failure.assign("native proof recovery was not accepted by its exact target"_ctv); break; }
        }
      }
      // Delivery only admits a bounded native seed authority.  Completion is
      // the fresh receipt-backed cohort proof, never the pre-seed identity
      // observation used to choose target containers.
      for (uint32_t poll = 0; valid && poll < 300; ++poll) {
        Vector<DeploymentIdentityReport> pulse = {}, hot = {}, cold = {}, radar = {}, app6 = {};
        DeploymentIdentityReport truth = {};
        bool converged = siteClusters.size() == 3;
        for (uint32_t site = 0; converged && site < siteClusters.size(); ++site) {
          DeploymentIdentityReport onePulse = {}, oneHot = {}, oneCold = {}, oneRadar = {}, oneApp6 = {}, oneTruth = {};
          converged = readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].pulseDeploymentID, onePulse, failure) &&
              readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].hotDeploymentID, oneHot, failure) &&
              readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].coldDeploymentID, oneCold, failure) &&
              readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].radarDeploymentID, oneRadar, failure) &&
              readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].app6DeploymentID, oneApp6, failure) &&
              (site != 0 || readDeploymentIdentity(siteClusters[site], recorded.intent.sites[site].truthDeploymentID, oneTruth, failure)) &&
              // Keep EWR's baseline live while recording each remote target
              // independently; requiring all remote rows here would lose
              // restart-resume progress until the final target catches up.
              (site == 0 && recorded.protocolVersion < MothershipNametagAllMastersRecord::sourceCutVersion ? mothershipNametagAllMastersSiteObserved(recorded.intent.sites[site], onePulse, oneHot, oneCold, oneRadar, &oneTruth) :
               site == 0 ? mothershipNametagAllMastersSiteReadyForSeedSelection(recorded.intent.sites[site], onePulse, oneHot, oneCold, oneRadar, &oneTruth) :
               mothershipNametagAllMastersSiteReadyForSeedSelection(recorded.intent.sites[site], onePulse, oneHot, oneCold, oneRadar, nullptr));
          pulse.push_back(std::move(onePulse)); hot.push_back(std::move(oneHot)); cold.push_back(std::move(oneCold));
          radar.push_back(std::move(oneRadar)); app6.push_back(std::move(oneApp6)); if (site == 0) truth = std::move(oneTruth);
        }
        // Persist each native receipt before requiring remote App6 traffic;
        // clients cannot obtain its Truth receipt until their stores seed.
        if (converged) {
          MothershipNametagAllMastersRecord progressed = {};
          auto registry = openClusterRegistry();
          converged = registry.recordNametagAllMastersSeedObservations(recorded.intent.operationUUID,
              pulse, hot, cold, radar, progressed, &failure);
          if (converged) recorded = std::move(progressed);
        }
        if (converged && recorded.protocolVersion >= MothershipNametagAllMastersRecord::sourceCutVersion) {
          // Durable history alone is not live evidence: every target must have
          // independently republished a current, matching native receipt.
          for (const auto& row : recorded.seedPlacements) {
            const auto *reports = row.applicationID == MeshRegistry::Pulse::applicationID ? &pulse :
                (row.applicationID == MeshRegistry::Hot::applicationID ? &hot :
                 (row.applicationID == MeshRegistry::Cold::applicationID ? &cold : &radar));
            ProdigyStatefulStoreSeedAuthority authority = {};
            if (row.site >= reports->size() || !mothershipNametagSourceCutAuthority(recorded, row, authority)) { converged = false; break; }
            const auto& report = (*reports)[row.site];
            auto found = std::find_if(report.statefulRuntimeCohort.begin(), report.statefulRuntimeCohort.end(), [&](const auto& member) {
              return member.containerUUID == row.targetContainerUUID && member.shardGroup == row.shardGroup &&
                  member.nativeSourceCutReceipt.state == ProdigyStatefulStoreReceiptState::active &&
                  prodigyStatefulStoreReceiptMatchesSourceCutAuthority(member.nativeSourceCutReceipt, authority);
            });
            if (report.version < 5 || report.clusterUUID != row.targetClusterUUID || report.deploymentID != row.targetDeploymentID ||
                found == report.statefulRuntimeCohort.end()) { converged = false; break; }
          }
        }
        // A target reply is merely authority acceptance. Completion requires
        // every persisted remote row to have the matching native receipt and
        // the same still-live EWR baseline proof.
        converged = converged && recorded.phase == MothershipNametagAllMastersRecord::Phase::remoteSeeded &&
            (recorded.protocolVersion >= MothershipNametagAllMastersRecord::sourceCutVersion ||
             mothershipNametagAllMastersSeedPlacementsObserved(recorded.seedPlacements, pulse, hot, cold, radar));
        converged = converged && mothershipNametagApp6TruthMeshSetObserved(app6, recorded.intent.sites, truth);
        if (converged) break;
        if (poll == 299) { valid = false; failure.assign("Nametag all-masters timed out waiting for native seed receipts and current app6 Truth traffic"_ctv); break; }
        ::usleep(100'000);
      }
        if (valid && recorded.phase == MothershipNametagAllMastersRecord::Phase::remoteSeeded) {
          for (uint32_t i = 0; valid && i < recorded.sourceCuts.size(); ++i) {
            if (recorded.sourceCuts[i].released ||
                recorded.sourceCuts[i].request.retainUntilMilliseconds <= Time::now<TimeResolution::ms>()) continue;
            auto release = recorded.sourceCuts[i].request;
            release.action = ProdigyStatefulStoreSourceCutAction::release;
            release.cutUUID = recorded.sourceCuts[i].proof.cutUUID; release.cutGeneration = recorded.sourceCuts[i].proof.cutGeneration;
            bool released = false;
            for (uint32_t poll = 0; valid && poll < 300 && !released; ++poll) {
              ProdigyStatefulStoreSourceCut reply = {};
              valid = configureControlTarget(siteClusters[0].name.c_str(), &failure) &&
                  requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, release, reply, failure) &&
                  prodigyStatefulStoreSourceCutResponseMatches(release, reply) && reply.failure.empty();
              if (!valid) break;
              if (!reply.released) { ::usleep(100'000); continue; }
              MothershipNametagAllMastersRecord progressed = {};
              {
                auto registry = openClusterRegistry();
                valid = registry.updateNametagAllMastersSourceCut(intent.operationUUID, i, false, &reply, progressed, &failure);
              }
              if (valid) { recorded = std::move(progressed); released = true; }
            }
            if (valid && !released) { valid = false; failure.assign("source cut release did not complete"_ctv); }
          }
        }
    }
    basics_log("nametagAllMasters success=%u resumed=%u operationUUID=%s failure=%s\n", unsigned(valid), unsigned(resumed),
        argc ? argv[0] : "", failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  // Resume the exact durable source-cut challenges for a successor. A lost
  // first reply is ambiguous and must never mint a replacement challenge.
  bool prepareNametagSeedSuccessorCuts(MothershipNametagSeedSuccessor& recorded,
      const Vector<DeploymentIdentityReport>& reports, String& failure)
  {
    for (uint32_t index = 0; index < recorded.sourceCuts.size(); ++index) {
      auto cut = recorded.sourceCuts[index];
      if (cut.released || cut.request.retainUntilMilliseconds <= Time::now<TimeResolution::ms>()) {
        failure.assign("successor source cut expired or was released"_ctv); return false;
      }
      if (cut.dispatched && !cut.request.memberRequestUUID) {
        failure.assign("successor source cut dispatch outcome is ambiguous"_ctv); return false;
      }
      if (!cut.dispatched) {
        MothershipNametagSeedSuccessor next = {};
        auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorCut(recorded.operationUUID, index, true, nullptr, reports, next, &failure)) return false;
        recorded = std::move(next);
      }
      MothershipProdigyCluster source = {}; String identity = {};
      identity.assignItoh(recorded.sourceCuts[index].request.sourceClusterUUID);
      { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, source, &failure)) return false; }
      for (uint32_t poll = 0; poll < 300 && !recorded.sourceCuts[index].proof.ready; ++poll) {
        const auto request = recorded.sourceCuts[index].request;
        ProdigyStatefulStoreSourceCut reply = {};
        if (!configureControlTarget(source.name.c_str(), &failure) ||
            !requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, request, reply, failure)) return false;
        auto expected = request;
        if (!expected.memberRequestUUID) expected.memberRequestUUID = reply.memberRequestUUID;
        if (!prodigyStatefulStoreSourceCutResponseMatches(expected, reply) || !reply.failure.empty()) {
          failure.assign("successor source cut returned an invalid challenge"_ctv); return false;
        }
        MothershipNametagSeedSuccessor next = {};
        { auto registry = openClusterRegistry();
          if (!registry.updateNametagSeedSuccessorCut(recorded.operationUUID, index, false, &reply, reports, next, &failure)) return false; }
        recorded = std::move(next);
        if (!reply.ready) ::usleep(100'000);
      }
      cut = recorded.sourceCuts[index];
      if (!cut.proof.ready) { failure.assign("successor source cut did not become ready"_ctv); return false; }
      auto query = cut.request; query.action = ProdigyStatefulStoreSourceCutAction::query;
      query.cutUUID = cut.proof.cutUUID; query.cutGeneration = cut.proof.cutGeneration;
      ProdigyStatefulStoreSourceCut reply = {};
      if (!configureControlTarget(source.name.c_str(), &failure) ||
          !requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, query, reply, failure) ||
          !prodigyStatefulStoreSourceCutResponseMatches(query, reply) || !reply.ready || !reply.failure.empty() ||
          reply.contentSHA256 != cut.proof.contentSHA256 || reply.headsSHA256 != cut.proof.headsSHA256 ||
          cut.request.retainUntilMilliseconds <= Time::now<TimeResolution::ms>()) {
        if (failure.empty()) failure.assign("successor retained source cut is no longer current"_ctv);
        return false;
      }
    }
    return true;
  }

  bool deliverNametagSeedSuccessorAuthority(MothershipNametagSeedSuccessor& recorded,
      const MothershipNametagAllMastersRecord& prior, const Vector<DeploymentIdentityReport>& reports,
      uint32_t index, uint128_t challenge, int64_t deadline, String& failure)
  {
    if (index >= recorded.targets.size()) return false;
    auto target = recorded.targets[index];
    if (!target.authority.protocolVersion) {
      ProdigyStatefulStoreSeedAuthority authority = {};
      if (!mothershipNametagSeedSuccessorAuthority(recorded, prior, index, challenge, deadline, authority)) return false;
      MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.installNametagSeedSuccessorAuthority(recorded.operationUUID, index, authority, reports, next, &failure)) return false; }
      recorded = std::move(next); target = recorded.targets[index];
    }
    if ((index == recorded.heldTargetIndex &&
         (target.authority.qualificationChallengeUUID != challenge ||
          target.authority.qualificationDeadlineAtMilliseconds != deadline)) ||
        (index != recorded.heldTargetIndex && (challenge || deadline))) return false;
    if (target.deliveryApplied) return true;
    if (!target.deliveryDispatched) {
      MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorDelivery(recorded.operationUUID, index, true, reports, next, &failure)) return false; }
      recorded = std::move(next); target = recorded.targets[index];
    }
    MothershipProdigyCluster cluster = {}; String identity = {};
    identity.assignItoh(target.authority.targetClusterUUID);
    { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
    if (!configureControlTarget(cluster.name.c_str(), &failure) || !socket.ensureConnected()) return false;
    auto authority = target.authority; String encoded = {};
    if (!BitseryEngine::serialize(encoded, authority)) return false;
    Message::construct(socket.wBuffer, MothershipTopic::applyNametagAllMastersSeedAuthority, encoded);
    if (!socket.send()) return false;
    Message *response = socket.recvExpectedTopic(MothershipTopic::applyNametagAllMastersSeedAuthority);
    if (!response) return false;
    uint8_t applied = 0; uint8_t *args = response->args;
    Message::extractArg<ArgumentNature::fixed>(args, applied);
    if (args != response->terminal() || applied != 1) return false;
    if (authority.protocolVersion == ProdigyStatefulStoreSeedAuthority::qualificationSeedFaultVersion) {
      ProdigyNametagQualificationSeedFault arm = {}, reply = {};
      arm.runUUID = authority.qualificationRunUUID; arm.challengeUUID = authority.qualificationChallengeUUID;
      arm.executionGeneration = authority.qualificationExecutionGeneration;
      arm.deadlineAtMilliseconds = authority.qualificationDeadlineAtMilliseconds;
      arm.stage = ProdigyNametagQualificationSeedFaultStage::arm; arm.authority = authority;
      bool armed = false;
      while (Time::now<TimeResolution::ms>() < arm.deadlineAtMilliseconds) {
        if (!requestTopicRoundTrip(MothershipTopic::nametagQualification, arm, reply, failure) ||
            !prodigyNametagQualificationSeedFaultResponseMatches(arm, reply) || !reply.failure.empty()) return false;
        if (reply.ready) { armed = true; break; }
        ::usleep(100'000);
      }
      if (!armed) { failure.assign("successor seed arm was not acknowledged"_ctv); return false; }
    }
    MothershipNametagSeedSuccessor next = {};
    { auto registry = openClusterRegistry();
      if (!registry.updateNametagSeedSuccessorDelivery(recorded.operationUUID, index, false, reports, next, &failure)) return false; }
    recorded = std::move(next);
    return true;
  }

  bool observeNametagSeedSuccessorHold(MothershipNametagSeedSuccessor& recorded,
      const Vector<DeploymentIdentityReport>& reports, String& failure)
  {
    if (recorded.heldTargetIndex >= recorded.targets.size()) return false;
    const auto& target = recorded.targets[recorded.heldTargetIndex];
    const auto& authority = target.authority;
    if (!target.deliveryApplied || authority.protocolVersion != ProdigyStatefulStoreSeedAuthority::qualificationSeedFaultVersion) return false;
    MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(authority.targetClusterUUID);
    { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
    ProdigyNametagQualificationSeedFault query = {}, reply = {};
    query.runUUID = authority.qualificationRunUUID; query.challengeUUID = authority.qualificationChallengeUUID;
    query.executionGeneration = authority.qualificationExecutionGeneration;
    query.deadlineAtMilliseconds = authority.qualificationDeadlineAtMilliseconds;
    query.stage = ProdigyNametagQualificationSeedFaultStage::query; query.authority = authority;
    while (Time::now<TimeResolution::ms>() < query.deadlineAtMilliseconds) {
      if (!configureControlTarget(cluster.name.c_str(), &failure) ||
          !requestTopicRoundTrip(MothershipTopic::nametagQualification, query, reply, failure) ||
          !prodigyNametagQualificationSeedFaultResponseMatches(query, reply) || !reply.failure.empty()) return false;
      if (reply.held) {
        MothershipNametagSeedSuccessor next = {};
        { auto registry = openClusterRegistry();
          if (!registry.recordNametagSeedSuccessorHeld(recorded.operationUUID, reply, reports, next, &failure)) return false; }
        recorded = std::move(next); return true;
      }
      ::usleep(100'000);
    }
    failure.assign("successor seed did not reach the held applied-progress boundary"_ctv);
    return false;
  }

  bool releaseNametagSeedSuccessorHold(MothershipNametagSeedSuccessor& recorded,
      const Vector<DeploymentIdentityReport>& reports, String& failure)
  {
    if (recorded.stage >= MothershipNametagSeedSuccessorStage::resumed) return true;
    if (recorded.heldTargetIndex >= recorded.targets.size()) return false;
    MothershipNametagSeedSuccessor next = {};
    { auto registry = openClusterRegistry();
      if (!registry.updateNametagSeedSuccessorRelease(recorded.operationUUID, true, nullptr, reports, next, &failure)) return false; }
    recorded = std::move(next);
    const auto authority = recorded.targets[recorded.heldTargetIndex].authority;
    MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(authority.targetClusterUUID);
    { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
    ProdigyNametagQualificationSeedFault request = {}, reply = {};
    request.runUUID = authority.qualificationRunUUID; request.challengeUUID = authority.qualificationChallengeUUID;
    request.executionGeneration = authority.qualificationExecutionGeneration;
    request.deadlineAtMilliseconds = authority.qualificationDeadlineAtMilliseconds;
    request.stage = ProdigyNametagQualificationSeedFaultStage::release; request.authority = authority;
    while (Time::now<TimeResolution::ms>() < request.deadlineAtMilliseconds) {
      if (!configureControlTarget(cluster.name.c_str(), &failure) ||
          !requestTopicRoundTrip(MothershipTopic::nametagQualification, request, reply, failure) ||
          !prodigyNametagQualificationSeedFaultResponseMatches(request, reply) || !reply.failure.empty()) return false;
      if (reply.ready) {
        { auto registry = openClusterRegistry();
          if (!registry.updateNametagSeedSuccessorRelease(recorded.operationUUID, false, &reply, reports, next, &failure)) return false; }
        recorded = std::move(next); return true;
      }
      ::usleep(100'000);
    }
    failure.assign("successor held seed was not released before the deadline"_ctv); return false;
  }

  bool releaseNametagSeedSuccessorCuts(MothershipNametagSeedSuccessor& recorded,
      const Vector<DeploymentIdentityReport>& reports, String& failure)
  {
    if (!mothershipNametagSeedSuccessorNativeComplete(recorded)) return false;
    for (uint32_t index = 0; index < recorded.sourceCuts.size(); ++index) {
      auto cut = recorded.sourceCuts[index];
      if (cut.released) continue;
      MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorCutRelease(recorded.operationUUID, index, true, nullptr, reports, next, &failure)) return false; }
      recorded = std::move(next); cut = recorded.sourceCuts[index];
      MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(cut.request.sourceClusterUUID);
      { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
      auto request = cut.request; request.action = ProdigyStatefulStoreSourceCutAction::release;
      request.cutUUID = cut.proof.cutUUID; request.cutGeneration = cut.proof.cutGeneration;
      bool released = false;
      for (uint32_t poll = 0; poll < 300 && !released; ++poll) {
        ProdigyStatefulStoreSourceCut reply = {};
        if (!configureControlTarget(cluster.name.c_str(), &failure) ||
            !requestTopicRoundTrip(MothershipTopic::statefulStoreSourceCut, request, reply, failure) ||
            !prodigyStatefulStoreSourceCutResponseMatches(request, reply) || !reply.failure.empty()) return false;
        if (!reply.released) { ::usleep(100'000); continue; }
        { auto registry = openClusterRegistry();
          if (!registry.updateNametagSeedSuccessorCutRelease(recorded.operationUUID, index, false, &reply, reports, next, &failure)) return false; }
        recorded = std::move(next); released = true;
      }
      if (!released) { failure.assign("successor source cut release did not complete"_ctv); return false; }
    }
    return recorded.stage == MothershipNametagSeedSuccessorStage::complete;
  }

  bool rebootNametagSeedSuccessorBrain(MothershipNametagSeedSuccessor& recorded, bool source,
      MothershipNametagSeedRebootFence fence, const Vector<DeploymentIdentityReport>& reports,
      int64_t deadline, String& failure)
  {
    if (!fence.clusterUUID || !fence.machineUUID || !fence.dispatchUUID || deadline <= Time::now<TimeResolution::ms>() ||
        recorded.heldTargetIndex >= recorded.targets.size()) return false;
    if ((source && (recorded.sourceCuts.empty() || fence.clusterUUID != recorded.sourceCuts[0].request.sourceClusterUUID)) ||
        (!source && fence.clusterUUID != recorded.targets[recorded.heldTargetIndex].authority.targetClusterUUID)) return false;
    if (!source && fence.machineUUID == recorded.targets[recorded.heldTargetIndex].machineUUID) return false;
    if (source) for (const auto& cut : recorded.sourceCuts) {
      bool found = false;
      for (const auto& report : reports) for (const auto& member : report.statefulRuntimeCohort) {
        if (report.clusterUUID == fence.clusterUUID && member.containerUUID == cut.request.sourceContainerUUID) {
          if (member.machineUUID == fence.machineUUID) return false;
          found = true;
        }
      }
      if (!found) return false;
    }
    MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(fence.clusterUUID);
    { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
    auto queryBoot = [&](uint128_t challenge, String& boot) -> bool {
      ProdigyNametagQualificationMachineBoot request = {}, reply = {};
      request.runUUID = recorded.qualificationRunUUID; request.challengeUUID = challenge;
      request.executionGeneration = recorded.executionGeneration; request.deadlineAtMilliseconds = deadline;
      request.clusterUUID = fence.clusterUUID; request.machineUUID = fence.machineUUID;
      while (Time::now<TimeResolution::ms>() < deadline) {
        socket.close();
        if (configureControlTarget(cluster.name.c_str(), &failure) &&
            requestTopicRoundTrip(MothershipTopic::nametagQualification, request, reply, failure) &&
            prodigyNametagQualificationMachineBootMatches(request, reply) && reply.ready && reply.failure.empty()) {
          boot = reply.bootID; failure.clear(); socket.close(); return true;
        }
        socket.close(); ::usleep(100'000);
      }
      return false;
    };
    auto saved = source ? recorded.sourceReboot : recorded.destinationReboot;
    if (!saved.dispatchUUID) {
      ClusterStatusReport status = {};
      if (!productionClusterHealthy(cluster, status, failure)) return false;
      String machine = {}; machine.assignItoh(fence.machineUUID);
      if (std::count_if(status.machineReports.begin(), status.machineReports.end(), [&](const auto& m) {
            return m.machineUUID == machine && m.currentMaster;
          }) != 1 || !queryBoot(fence.dispatchUUID, fence.beforeBootID)) return false;
      MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorReboot(recorded.operationUUID, source, fence, reports, next, &failure)) return false; }
      recorded = std::move(next); saved = source ? recorded.sourceReboot : recorded.destinationReboot;
    }
    if (saved.clusterUUID != fence.clusterUUID || saved.machineUUID != fence.machineUUID || saved.dispatchUUID != fence.dispatchUUID) return false;
    if (saved.observed) return true;
    if (saved.dispatched && !saved.providerAccepted) {
      failure.assign("reboot submission outcome is ambiguous after restart"_ctv); return false;
    }
    if (!saved.dispatched) {
      saved.dispatched = true; MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorReboot(recorded.operationUUID, source, saved, reports, next, &failure)) return false; }
      recorded = std::move(next);
      uint64_t topologyVersion = 0;
      if (!submitRemoteCloudMachineReboot(cluster, saved.machineUUID, topologyVersion, failure)) return false;
      saved.providerAccepted = true;
      { auto registry = openClusterRegistry();
        if (!registry.updateNametagSeedSuccessorReboot(recorded.operationUUID, source, saved, reports, next, &failure)) return false; }
      recorded = std::move(next);
    }
    uint128_t afterChallenge = saved.dispatchUUID ^ uint128_t(1);
    if (!afterChallenge) afterChallenge = uint128_t(2);
    String after = {};
    while (Time::now<TimeResolution::ms>() < deadline) {
      if (queryBoot(afterChallenge, after) && after != saved.beforeBootID) {
        if (!prepareNametagSeedSuccessorCuts(recorded, reports, failure) ||
            !observeNametagSeedSuccessorHold(recorded, reports, failure)) return false;
        saved.afterBootID = after; saved.observed = true;
        MothershipNametagSeedSuccessor next = {};
        { auto registry = openClusterRegistry();
          if (!registry.updateNametagSeedSuccessorReboot(recorded.operationUUID, source, saved, reports, next, &failure)) return false; }
        recorded = std::move(next); return true;
      }
      ::usleep(100'000);
    }
    failure.assign("successor Brain reboot did not produce a different authenticated boot identity"_ctv); return false;
  }

  bool runNametagSeedSuccessorTransfer(MothershipNametagSeedSuccessor& recorded,
      const MothershipNametagAllMastersRecord& prior, Vector<DeploymentIdentityReport>& reports,
      uint128_t challenge, int64_t deadline, MothershipNametagSeedRebootFence sourceReboot,
      MothershipNametagSeedRebootFence destinationReboot, String& failure)
  {
    if (recorded.stage == MothershipNametagSeedSuccessorStage::complete) return true;
    if (!challenge || recorded.heldTargetIndex >= recorded.targets.size() ||
        deadline <= Time::now<TimeResolution::ms>()) return false;
    if (recorded.stage < MothershipNametagSeedSuccessorStage::resumed) {
      if (!prepareNametagSeedSuccessorCuts(recorded, reports, failure)) return false;
      if (!deliverNametagSeedSuccessorAuthority(recorded, prior, reports, recorded.heldTargetIndex,
                                                 challenge, deadline, failure)) return false;
      for (uint32_t i = 0; i < recorded.targets.size(); ++i) {
        if (i != recorded.heldTargetIndex &&
            !deliverNametagSeedSuccessorAuthority(recorded, prior, reports, i, 0, 0, failure)) return false;
      }
      if (!observeNametagSeedSuccessorHold(recorded, reports, failure)) return false;
    }
    auto refreshNative = [&]() -> bool {
      Vector<DeploymentIdentityReport> fresh = {};
      for (const auto& old : reports) {
        const bool target = std::any_of(recorded.targets.begin(), recorded.targets.end(), [&](const auto& t) {
          return t.targetDeploymentID == old.deploymentID && t.authority.targetClusterUUID == old.clusterUUID;
        });
        if (!target) fresh.push_back(old);
      }
      for (const auto& target : recorded.targets) {
        if (std::any_of(fresh.begin(), fresh.end(), [&](const auto& r) {
              return r.deploymentID == target.targetDeploymentID && r.clusterUUID == target.authority.targetClusterUUID;
            })) continue;
        MothershipProdigyCluster cluster = {}; String identity = {}; identity.assignItoh(target.authority.targetClusterUUID);
        { auto registry = openClusterRegistry(); if (!registry.getClusterByIdentity(identity, cluster, &failure)) return false; }
        DeploymentIdentityReport report = {};
        if (!readDeploymentIdentity(cluster, target.targetDeploymentID, report, failure)) return false;
        fresh.push_back(std::move(report));
      }
      MothershipNametagSeedSuccessor next = {};
      { auto registry = openClusterRegistry();
        if (!registry.recordNametagSeedSuccessorNative(recorded.operationUUID, fresh, next, &failure)) return false; }
      reports = std::move(fresh); recorded = std::move(next); return true;
    };
    // For the replica scenario the other members complete their native seed
    // before the selected member is released; the site attempt is separate.
    while (Time::now<TimeResolution::ms>() < deadline) {
      if (!refreshNative()) return false;
      bool othersReady = true;
      for (uint32_t i = 0; i < recorded.targets.size(); ++i)
        if (i != recorded.heldTargetIndex && !recorded.targets[i].nativeReceipt.protocolVersion) othersReady = false;
      if (othersReady) break;
      ::usleep(100'000);
    }
    for (uint32_t i = 0; i < recorded.targets.size(); ++i)
      if (i != recorded.heldTargetIndex && !recorded.targets[i].nativeReceipt.protocolVersion) {
        failure.assign("successor peers did not finish seeding before release"_ctv); return false;
      }
    if (recorded.stage < MothershipNametagSeedSuccessorStage::resumed &&
        recorded.qualificationRow == uint8_t(ProdigyNametagQualificationRow::brainHardRebootCatchup) &&
        (!rebootNametagSeedSuccessorBrain(recorded, true, sourceReboot, reports, deadline, failure) ||
         !rebootNametagSeedSuccessorBrain(recorded, false, destinationReboot, reports, deadline, failure))) return false;
    if (!releaseNametagSeedSuccessorHold(recorded, reports, failure)) return false;
    while (Time::now<TimeResolution::ms>() < deadline && !mothershipNametagSeedSuccessorNativeComplete(recorded)) {
      if (!refreshNative()) return false;
      if (!mothershipNametagSeedSuccessorNativeComplete(recorded)) ::usleep(100'000);
    }
    if (!mothershipNametagSeedSuccessorNativeComplete(recorded)) {
      failure.assign("successor did not publish all native seed receipts"_ctv); return false;
    }
    return releaseNametagSeedSuccessorCuts(recorded, reports, failure);
  }

  void runProductionPair(int argc, char *argv[])
  {
    String failure = {}, action = argc > 1 ? String(argv[1]) : String(), receiptSHA256 = {};
    uint128_t operationUUID = 0;
    bool valid = argc == 2 && prodigyParseCanonicalHex128(String(argv[0]), operationUUID) && operationUUID != 0 &&
        (action == "query"_ctv || action == "selectTarget"_ctv || action == "drain"_ctv ||
         action == "retireSource"_ctv || action == "cleanup"_ctv || action == "abortBeforeTransit"_ctv ||
         action == "abortBeforeCutover"_ctv);
    if (!valid) failure.assign("usage: productionPair OPERATION_UUID query|selectTarget|drain|retireSource|cleanup|abortBeforeTransit|abortBeforeCutover"_ctv);
    MothershipProductionPairRecord record = {};
    MothershipProdigyCluster source = {}, target = {};
    MothershipPhysicalServiceTransitBoundary physicalBoundary = {};
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.loadProductionPair(operationUUID, record, &failure);
      if (valid && record.intent.protocolVersion != MothershipProductionPairIntent::version) {
        failure.assign("stateful pairs use nametagStatefulPair; physical productionPair actions are forbidden"_ctv); valid = false;
      }
      String sourceIdentity = {}, targetIdentity = {};
      sourceIdentity.assignItoh(record.intent.route.sourceClusterUUID);
      targetIdentity.assignItoh(record.intent.route.destinationClusterUUID);
      valid = valid && registry.getClusterByIdentity(sourceIdentity, source, &failure) &&
          registry.getClusterByIdentity(targetIdentity, target, &failure);
    }
    if (valid && (record.phase == MothershipProductionPairPhase::transitApplied ||
                  record.phase == MothershipProductionPairPhase::abortBeforeCutoverPending))
    {
      auto registry = openClusterRegistry();
      valid = registry.loadPhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID,
                                                           physicalBoundary, &failure) &&
          productionPairPhysicalBoundaryReady(record, source, target, physicalBoundary, failure);
    }

    bool resumed = false;
    if (valid && action == "abortBeforeCutover"_ctv)
    {
      if (record.phase == MothershipProductionPairPhase::abortedBeforeCutover)
      {
        receiptSHA256 = record.cleanupReceiptSHA256;
        MothershipPhysicalServiceTransitBoundary boundary = {};
        auto registry = openClusterRegistry(); bool closeResumed = false;
        valid = registry.closePhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID,
                                                              receiptSHA256, boundary, closeResumed, &failure);
        resumed = valid && closeResumed;
      }
      else
      {
        ProductionPairProviderState state = {}; String output = {}, queryEvidence = {}, providerEvidence = {};
        if (record.phase == MothershipProductionPairPhase::transitApplied)
        {
          valid = runProductionPairProvider(record, source, "query", state, output, queryEvidence, failure) &&
              productionPairSelectorPhaseMatches(record, MothershipProductionPairPhase::transitApplied, state, failure);
          // Source counters are cumulative observations and may contain traffic
          // from a failed, non-durable witness attempt.  Before selection, that
          // traffic still reached only the source workload.  Safe compensation
          // therefore requires zero live flows and proves the target side was
          // never selected or observed; source history need not be zero.
          if (valid && (state.selectedTarget || state.sourceFlows != 0 || state.targetFlows != 0 ||
                        state.targetConnections != 0 || state.targetRequestBytes != 0 ||
                        state.targetResponseBytes != 0))
          { failure.assign("production pair pre-cutover abort requires the exact source-selected zero-flow selector state"_ctv); valid = false; }
          if (valid)
          {
            Vector<String> evidence = {};
            evidence.emplace_back("mothership-production-pair-pre-cutover-abort-pending-receipt-v1"_ctv);
            evidence.push_back(record.targetAdmissionReceiptSHA256);
            evidence.push_back(record.transitApplyReceiptSHA256);
            evidence.push_back(queryEvidence);
            evidence.push_back(physicalBoundary.admissionReceiptSHA256);
            String encoded = {}; BitseryEngine::serialize(encoded, evidence);
            valid = prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
          }
          if (valid)
          {
            auto registry = openClusterRegistry(); bool pendingResumed = false;
            valid = registry.prepareProductionPairAbortBeforeCutover(operationUUID, receiptSHA256,
                Time::now<TimeResolution::ms>(), record, pendingResumed, &failure);
            resumed = pendingResumed;
          }
        }
        else if (record.phase != MothershipProductionPairPhase::abortBeforeCutoverPending)
        { failure.assign("production pair pre-cutover abort requires an unwitnessed applied transit or durable pending abort"_ctv); valid = false; }
        if (valid) valid = runProductionPairProvider(record, source, "abort-before-cutover", state, output,
                                                     providerEvidence, failure);
        if (valid)
        {
          Vector<String> evidence = {};
          evidence.emplace_back("mothership-production-pair-pre-cutover-abort-receipt-v2"_ctv);
          evidence.push_back(record.cleanupReceiptSHA256);
          evidence.push_back(providerEvidence);
          String encoded = {}; BitseryEngine::serialize(encoded, evidence);
          valid = prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
        }
        if (valid)
        {
          auto registry = openClusterRegistry(); bool abortResumed = false;
          valid = registry.abortProductionPairBeforeCutover(operationUUID, receiptSHA256,
              Time::now<TimeResolution::ms>(), record, abortResumed, &failure);
          resumed = abortResumed;
        }
        if (valid)
        {
          MothershipPhysicalServiceTransitBoundary boundary = {};
          auto registry = openClusterRegistry(); bool closeResumed = false;
          valid = registry.closePhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID,
                                                                receiptSHA256, boundary, closeResumed, &failure);
          resumed = resumed || closeResumed;
        }
      }
    }
    else if (valid && action == "abortBeforeTransit"_ctv)
    {
      if (record.phase != MothershipProductionPairPhase::prepared &&
          record.phase != MothershipProductionPairPhase::targetAdmitted &&
          record.phase != MothershipProductionPairPhase::abortedBeforeTransit)
      { failure.assign("production pair pre-transit abort requires a prepared phase"_ctv); valid = false; }
      ProductionPairProviderState state = {}; String output = {}, providerEvidence = {};
      if (valid) valid = runProductionPairProvider(record, source, "remove", state, output, providerEvidence, failure);
      MothershipPhysicalServiceTransitBoundary boundary = {}; bool boundaryExists = false;
      if (valid)
      {
        auto registry = openClusterRegistry(); String readFailure = {};
        boundaryExists = registry.loadPhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID, boundary, &readFailure);
        if (!boundaryExists && !readFailure.equal("record not found"_ctv)) { failure = readFailure; valid = false; }
        if (boundaryExists && boundary.pairOperationUUID != operationUUID)
        { failure.assign("production pair abort physical boundary conflicts with operation identity"_ctv); valid = false; }
      }
      if (valid)
      {
        Vector<String> evidence = {};
        evidence.emplace_back("mothership-production-pair-pre-transit-abort-receipt-v1"_ctv);
        evidence.push_back(record.targetAdmissionReceiptSHA256);
        evidence.push_back(providerEvidence);
        evidence.push_back(boundaryExists ? boundary.admissionReceiptSHA256 : String());
        String encoded = {}; BitseryEngine::serialize(encoded, evidence);
        valid = prodigyComputeSHA256Hex(encoded, receiptSHA256, &failure);
      }
      if (valid && boundaryExists)
      {
        auto registry = openClusterRegistry(); bool closeResumed = false;
        valid = registry.closePhysicalServiceTransitBoundaryBeforeTransit(record.intent.physicalBoundaryUUID,
            receiptSHA256, boundary, closeResumed, &failure);
        resumed = closeResumed;
      }
      if (valid)
      {
        auto registry = openClusterRegistry(); bool abortResumed = false;
        valid = registry.abortProductionPairBeforeTransit(operationUUID, receiptSHA256,
            Time::now<TimeResolution::ms>(), record, abortResumed, &failure);
        resumed = resumed || abortResumed;
      }
    }
    else if (valid && action == "cleanup"_ctv)
    {
      if (record.phase < MothershipProductionPairPhase::sourceRetired)
      { failure.assign("production pair cleanup requires durable source retirement"_ctv); valid = false; }
      if (valid && record.phase == MothershipProductionPairPhase::cleanupComplete)
      {
        MothershipPhysicalServiceTransitBoundary boundary = {};
        auto registry = openClusterRegistry();
        bool closeResumed = false;
        valid = registry.closePhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID,
                                                              record.cleanupReceiptSHA256,
                                                              boundary, closeResumed, &failure);
        receiptSHA256 = record.cleanupReceiptSHA256; resumed = valid && closeResumed;
      }
      else if (valid)
      {
        CousinRouteRecord terminalRoute = {};
        CousinRouteApplyReceipt sourceReceipt = {}, targetReceipt = {};
        {
          auto registry = openClusterRegistry();
          valid = registry.loadCousinRoute(record.intent.route.routeUUID, terminalRoute, &failure) &&
              cousinRouteTerminal(terminalRoute) && terminalRoute.generation > record.intent.route.generation &&
              cousinRouteScopeMatches(record.intent.route, terminalRoute) &&
              registry.loadCurrentCousinRouteApplyReceipt(terminalRoute.routeUUID, CousinRouteHalf::source,
                                                          sourceReceipt, &failure) &&
              registry.loadCurrentCousinRouteApplyReceipt(terminalRoute.routeUUID, CousinRouteHalf::destination,
                                                          targetReceipt, &failure) &&
              cousinRouteApplyReceiptMatchesCurrentRoute(sourceReceipt, terminalRoute) &&
              cousinRouteApplyReceiptMatchesCurrentRoute(targetReceipt, terminalRoute);
        }
        ProductionPairProviderState state = {}; String output = {}, providerEvidence = {};
        if (valid) valid = runProductionPairProvider(record, source, "remove", state, output, providerEvidence, failure);
        if (valid)
        {
          String evidence = {}, encoded = {};
          Vector<String> ownerEvidence = {};
          ownerEvidence.emplace_back("mothership-production-pair-cleanup-receipt-v1"_ctv);
          ownerEvidence.push_back(record.sourceRetirementReceiptSHA256);
          ownerEvidence.push_back(providerEvidence);
          BitseryEngine::serialize(evidence, ownerEvidence);
          BitseryEngine::serialize(encoded, terminalRoute); evidence.append(encoded);
          encoded.clear(); BitseryEngine::serialize(encoded, sourceReceipt); evidence.append(encoded);
          encoded.clear(); BitseryEngine::serialize(encoded, targetReceipt); evidence.append(encoded);
          valid = prodigyComputeSHA256Hex(evidence, receiptSHA256, &failure);
        }
        if (valid)
        {
          auto registry = openClusterRegistry();
          valid = registry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::cleanupComplete,
                                                 receiptSHA256, Time::now<TimeResolution::ms>(), record, resumed, &failure);
        }
        if (valid)
        {
          MothershipPhysicalServiceTransitBoundary boundary = {};
          auto registry = openClusterRegistry();
          bool closeResumed = false;
          valid = registry.closePhysicalServiceTransitBoundary(record.intent.physicalBoundaryUUID,
                                                                receiptSHA256, boundary, closeResumed, &failure);
          resumed = resumed || closeResumed;
        }
      }
    }
    else if (valid)
    {
      if (record.phase < MothershipProductionPairPhase::transitApplied ||
          record.phase >= MothershipProductionPairPhase::cleanupComplete)
      { failure.assign("production pair action requires an active applied transit"_ctv); valid = false; }
      if (valid) valid = productionPairTransportReady(record, source, target, failure);

      ClusterStatusReport sourceStatus = {}, targetStatus = {};
      if (valid && action != "retireSource"_ctv)
        valid = productionPairWorkloadsReady(record, source, target,
            record.phase < MothershipProductionPairPhase::sourceRetired,
            sourceStatus, targetStatus, failure);
      if (valid && action == "retireSource"_ctv)
      {
        valid = productionClusterHealthy(source, sourceStatus, failure) &&
            productionClusterHealthy(target, targetStatus, failure);
        DeploymentIdentityReport targetReport = {};
        MothershipProductionWorkloadIdentity targetIdentity = {};
        valid = valid && productionWorkloadIdentity(target, record.intent.targetWorkload.deploymentID,
                                                    targetIdentity, targetReport, failure) &&
            productionWorkloadIdentityEqual(targetIdentity, record.intent.targetWorkload);
      }
      if (valid && !topologyMachineOwnsAddress(sourceStatus, record.intent.selectorMachineUUID,
                                               record.intent.selectorAddress))
      {
        failure.assign("production ingress address is not owned by the exact live source machine"_ctv);
        valid = false;
      }

      ProductionPairProviderState state = {}; String output = {}, providerEvidence = {};
      if (valid && action == "query"_ctv)
      {
        valid = runProductionPairProvider(record, source, "query", state, output, providerEvidence, failure);
        MothershipProductionPairPhase selectorPhase = record.phase >= MothershipProductionPairPhase::sourceDrained ?
            MothershipProductionPairPhase::sourceDrained :
            (record.phase >= MothershipProductionPairPhase::targetSelected ?
             MothershipProductionPairPhase::targetSelected : MothershipProductionPairPhase::transitApplied);
        if (valid) valid = productionPairSelectorPhaseMatches(record, selectorPhase, state, failure);
        if (valid) receiptSHA256 = selectorPhase == MothershipProductionPairPhase::sourceDrained ?
            record.sourceDrainReceiptSHA256 :
            (selectorPhase == MothershipProductionPairPhase::targetSelected ?
             record.targetSelectionReceiptSHA256 : record.transitApplyReceiptSHA256);
      }
      else if (valid && action == "selectTarget"_ctv)
      {
        if (record.phase < MothershipProductionPairPhase::targetSelected)
        {
          if (record.phase == MothershipProductionPairPhase::transitApplied)
          {
            valid = productionPairIngressWitness(record, source, "source", receiptSHA256, failure);
            if (valid) { auto registry = openClusterRegistry(); valid = registry.advanceProductionPair(
                operationUUID, MothershipProductionPairPhase::sourceIngressWitnessed, receiptSHA256,
                Time::now<TimeResolution::ms>(), record, resumed, &failure); }
          }
          if (valid && record.phase != MothershipProductionPairPhase::sourceIngressWitnessed)
          { failure.assign("target selection requires a durable distinct-machine source ingress witness"_ctv); valid = false; }
          if (valid) valid = runProductionPairProvider(record, source, "select-target", state, output,
                                                       providerEvidence, failure) &&
              productionPairSelectorPhaseReceipt(record, MothershipProductionPairPhase::targetSelected,
                                                 state, receiptSHA256, failure);
          if (valid)
          {
            auto registry = openClusterRegistry();
            valid = registry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::targetSelected,
                                                   receiptSHA256, Time::now<TimeResolution::ms>(), record, resumed, &failure);
          }
        }
        else
        {
          valid = runProductionPairProvider(record, source, "query", state, output, providerEvidence, failure) &&
              productionPairSelectorPhaseMatches(record, MothershipProductionPairPhase::targetSelected,
                                                 state, failure);
          resumed = valid;
        }
        receiptSHA256 = record.targetSelectionReceiptSHA256;
      }
      else if (valid && action == "drain"_ctv)
      {
        if (record.phase < MothershipProductionPairPhase::sourceDrained)
        {
          if (record.phase == MothershipProductionPairPhase::targetSelected)
          {
            valid = productionPairIngressWitness(record, source, "target", receiptSHA256, failure);
            if (valid) { auto registry = openClusterRegistry(); valid = registry.advanceProductionPair(
                operationUUID, MothershipProductionPairPhase::targetIngressWitnessed, receiptSHA256,
                Time::now<TimeResolution::ms>(), record, resumed, &failure); }
          }
          if (valid && record.phase != MothershipProductionPairPhase::targetIngressWitnessed)
          { failure.assign("source drain requires a durable distinct-machine target ingress witness"_ctv); valid = false; }
          if (valid) valid = runProductionPairProvider(record, source, "drain", state, output,
                                                       providerEvidence, failure) &&
              productionPairSelectorPhaseReceipt(record, MothershipProductionPairPhase::sourceDrained,
                                                 state, receiptSHA256, failure);
          if (valid)
          {
            auto registry = openClusterRegistry();
            valid = registry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::sourceDrained,
                                                   receiptSHA256, Time::now<TimeResolution::ms>(), record, resumed, &failure);
          }
        }
        else
        {
          valid = runProductionPairProvider(record, source, "query", state, output, providerEvidence, failure) &&
              productionPairSelectorPhaseMatches(record, MothershipProductionPairPhase::sourceDrained,
                                                 state, failure);
          resumed = valid;
        }
        receiptSHA256 = record.sourceDrainReceiptSHA256;
      }
      else if (valid && action == "retireSource"_ctv)
      {
        if (record.phase < MothershipProductionPairPhase::sourceRetired)
        {
          if (record.phase != MothershipProductionPairPhase::sourceDrained)
          { failure.assign("source retirement requires the zero-source-flow drain phase"_ctv); valid = false; }
          if (valid) valid = runProductionPairProvider(record, source, "drain", state, output,
                                                       providerEvidence, failure) &&
              productionPairSelectorPhaseMatches(record, MothershipProductionPairPhase::sourceDrained,
                                                 state, failure);
          if (valid) valid = retireProductionPairSource(record, source, target, receiptSHA256, failure);
          if (valid)
          {
            auto registry = openClusterRegistry();
            valid = registry.advanceProductionPair(operationUUID, MothershipProductionPairPhase::sourceRetired,
                                                   receiptSHA256, Time::now<TimeResolution::ms>(), record, resumed, &failure);
          }
        }
        else
        {
          valid = retireProductionPairSource(record, source, target, receiptSHA256, failure) &&
              receiptSHA256 == record.sourceRetirementReceiptSHA256; resumed = valid;
        }
        receiptSHA256 = record.sourceRetirementReceiptSHA256;
      }
    }

    String operation = {}; operation.assignItoh(operationUUID);
    basics_log("productionPair success=%u resumed=%u operationUUID=%s action=%s phase=%u receiptSHA256=%s failure=%s\n",
        unsigned(valid), unsigned(resumed), operation.c_str(), action.c_str(),
        unsigned(valid ? record.phase : MothershipProductionPairPhase::prepared), receiptSHA256.c_str(), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runPrepareTestPairMigration(int argc, char *argv[])
  {
    String failure = {}; TestPairLifecycleLock lock;
    bool valid = (argc == 10 || argc == 11) && lockTestPairLifecycle(lock, failure);
    MothershipTestPairBoundaryRecord requested = {}, recorded = {};
    requested.version = argc == 11 ? 5 : 3;
    MothershipProdigyCluster source = {}, target = {};
    DeploymentPlan plan = {}; String artifactPath = {}; bool returnAfterOkay = false;
    uint128_t op = 0, cousinRouteUUID = 0; uint64_t si = 0, ti = 0, port = 0;
    auto& d = requested.boundary;
    if (valid)
    {
      d.operationID.assign(argv[2]); d.endpointIPv4.assign(argv[6]);
      valid = prodigyParseCanonicalHex128(d.operationID, op) && op != 0 &&
              mothershipParseUnsignedArgument(argv[3], UINT64_MAX, requested.sourceDeploymentID) && requested.sourceDeploymentID != 0 &&
              mothershipParseUnsignedArgument(argv[4], 3, si) && si > 0 &&
              mothershipParseUnsignedArgument(argv[5], 3, ti) && ti > 0 &&
              mothershipParseUnsignedArgument(argv[7], UINT16_MAX, port) && port > 0;
      if (valid && argc == 11)
        valid = prodigyParseCanonicalHex128(String(argv[10]), cousinRouteUUID) && cousinRouteUUID != 0;
      d.sourceMachineIndex = uint32_t(si); d.targetMachineIndex = uint32_t(ti); d.endpointPort = uint16_t(port);
    }
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[0]), source, &failure) &&
              registry.getClusterByIdentity(String(argv[1]), target, &failure);
    }
    valid = valid && bindTestPairRuntimes(source, target, d, failure) &&
                    prepareDeploymentPlan(argv[1], argv[8], argv[9], plan, artifactPath, returnAfterOkay, failure);
    socket.close();
    if (valid && (!prodigyStatelessDeploymentAdmissionPlanEligible(plan) || plan.wormholes[0].externalPort != d.endpointPort))
    {
      failure.assign("paired target requires the supported secret-free stateless TCP profile"_ctv); valid = false;
    }
    DeploymentIdentityReport observed = {};
    valid = valid && testPairDeploymentReady(source, requested.sourceDeploymentID, d.sourceMachineIndex,
                                             d.endpointIPv4, d.endpointPort, observed, failure);
    if (valid)
    {
      requested.sourcePlanSHA256 = observed.canonicalPlanSHA256; requested.sourceBlobSHA256 = observed.containerBlobSHA256;
      requested.targetDeploymentID = plan.config.deploymentID();
      BitseryEngine::serialize(requested.targetRequestPlan, plan);
      valid = prodigyComputeSHA256Hex(requested.targetRequestPlan, requested.targetRequestPlanSHA256, &failure) &&
              mothershipValidateDiscombobulatorContainerBlobContract(artifactPath, &failure) &&
              prodigyComputeFileSHA256Hex(artifactPath, requested.targetBlobSHA256, &requested.targetBlobBytes, &failure);
    }
    DeploymentIdentityReport sourceTransportReport = {}, targetTransportReport = {};
    if (valid && requested.version >= 5)
    {
      valid = bindTestPairCousinTransport(cousinRouteUUID, source, target, requested,
                                          sourceTransportReport, targetTransportReport, failure) &&
              requested.cousinTransport.destinationPermission.localApplicationID != plan.config.applicationID;
      if (!valid && failure.empty())
        failure.assign("stateless successor must be distinct from the bound COUSIN transport workload"_ctv);
    }
    if (valid)
    {
      ClusterStatusReport targetReport = {};
      auto& intent = requested.targetReadinessIntent;
      valid = readManagedClusterStatus(target, targetReport, failure) && targetReport.hasTopology &&
              mothershipBuildTestPairTargetReadinessIntent(
                  targetReport.topology, d.targetMachinePrivate4, intent,
                  requested.version >= 5 ? requested.cousinTransport.destinationPermission.localDeploymentID : 0,
                  requested.version >= 5 ? targetTransportReport.nTarget : 0);
      if (valid && requested.version >= 5)
      {
        const auto& permission = requested.cousinTransport.destinationPermission;
        const uint64_t transportVersionID = permission.localDeploymentID & ((uint64_t(1) << 48) - 1);
        bool foundTransport = false, foundSuccessor = false;
        valid = (targetReport.nApplications == 1 || targetReport.nApplications == 2) &&
                targetReport.applicationReports.size() == targetReport.nApplications;
        for (const ApplicationStatusReport& application : targetReport.applicationReports)
        {
          if (application.applicationID == permission.localApplicationID && application.deploymentReports.size() == 1)
          {
            const auto& deployment = application.deploymentReports[0];
            foundTransport = deployment.versionID == transportVersionID && deployment.state == DeploymentState::running &&
                             deployment.isStateful && deployment.nTarget == targetTransportReport.nTarget &&
                             deployment.nDeployed == deployment.nTarget && deployment.nHealthy == deployment.nTarget;
          }
          else if (application.applicationID == plan.config.applicationID && application.deploymentReports.size() == 1)
          {
            const auto& deployment = application.deploymentReports[0];
            foundSuccessor = deployment.versionID == plan.config.versionID && deployment.state == DeploymentState::running &&
                             !deployment.isStateful && deployment.nTarget == 1 && deployment.nDeployed == 1 && deployment.nHealthy == 1;
          }
          else valid = false;
        }
        valid = valid && foundTransport && (targetReport.nApplications == 1 ? !foundSuccessor : foundSuccessor) &&
                MothershipClusterRegistry::testPairCousinTransportIntentValid(requested) &&
                testPairCousinTransportReady(requested, source, target, failure);
      }
      if (!valid && failure.empty()) failure.assign("paired target commissioned topology is unavailable or unsupported"_ctv);
    }
    if (valid) { auto registry = openClusterRegistry(); valid = registry.admitTestPairBoundary(requested, recorded, &failure); }
    // The immutable pair is durable before any target launch request. A lost
    // response leaves this owner open; admitTestPairTarget queries the same op.
    valid = valid && admitTestPairTarget(recorded, artifactPath, failure);
    basics_log("prepareTestPairMigration success=%u targetAccepted=%u migrationQualified=%u failure=%s\n",
               unsigned(valid), unsigned(valid), unsigned(valid && recorded.version >= 5), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runPrepareTestPairBoundary(int argc, char *argv[])
  {
    String failure = {};
    TestPairLifecycleLock lock;
    if (argc != 9 || !lockTestPairLifecycle(lock, failure))
    {
      basics_log("prepareTestPairBoundary success=0 failure=%s\n", failure.empty() ? "expected source target operationID sourceDeploymentID targetDeploymentID sourceMachineIndex targetMachineIndex IPv4 TCPport" : failure.c_str());
      exit(EXIT_FAILURE);
    }
    MothershipTestPairBoundaryRecord requested = {}, recorded = {};
    auto& d = requested.boundary;
    d.operationID.assign(argv[2]); d.endpointIPv4.assign(argv[7]);
    uint64_t si = 0, ti = 0, port = 0;
    uint128_t op = 0;
    MothershipProdigyCluster source = {}, target = {};
    bool valid = prodigyParseCanonicalHex128(d.operationID, op) && op != 0 &&
                 mothershipParseUnsignedArgument(argv[3], UINT64_MAX, requested.sourceDeploymentID) &&
                 mothershipParseUnsignedArgument(argv[4], UINT64_MAX, requested.targetDeploymentID) &&
                 mothershipParseUnsignedArgument(argv[5], 3, si) && si > 0 &&
                 mothershipParseUnsignedArgument(argv[6], 3, ti) && ti > 0 &&
                 mothershipParseUnsignedArgument(argv[8], UINT16_MAX, port) && port > 0;
    if (valid)
    {
      auto registry = openClusterRegistry();
      valid = registry.getClusterByIdentity(String(argv[0]), source, &failure) &&
              registry.getClusterByIdentity(String(argv[1]), target, &failure) && source.clusterUUID != target.clusterUUID;
    }
    d.sourceMachineIndex = uint32_t(si); d.targetMachineIndex = uint32_t(ti); d.endpointPort = uint16_t(port);
    DeploymentIdentityReport sr = {}, tr = {};
    valid = valid && testPairDeploymentReady(source, requested.sourceDeploymentID, uint32_t(si), d.endpointIPv4, uint16_t(port), sr, failure) &&
                     testPairDeploymentReady(target, requested.targetDeploymentID, uint32_t(ti), d.endpointIPv4, uint16_t(port), tr, failure);
    if (valid)
    {
      valid = bindTestPairRuntimes(source, target, d, failure);
      requested.sourcePlanSHA256 = sr.canonicalPlanSHA256; requested.targetPlanSHA256 = tr.canonicalPlanSHA256;
      requested.sourceBlobSHA256 = sr.containerBlobSHA256; requested.targetBlobSHA256 = tr.containerBlobSHA256;
      if (valid) { auto registry = openClusterRegistry(); valid = registry.admitTestPairBoundary(requested, recorded, &failure); }
    }
    valid = valid && runTestPairProvider(recorded, "prepare", {}, failure);
    basics_log("prepareTestPairBoundary success=%u operationID=%s migrationQualified=0 failure=%s\n", unsigned(valid), d.operationID.c_str(), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runPairBoundary(int argc, char *argv[])
  {
    if (argc != 2) { basics_log("pairBoundary expects operationID prepare|query|selectTarget|drain|remove|crashOwner|armGuestReset\n"); exit(EXIT_FAILURE); }
    const bool prepare = std::strcmp(argv[1], "prepare") == 0;
    const bool select = std::strcmp(argv[1], "selectTarget") == 0;
    const bool remove = std::strcmp(argv[1], "remove") == 0;
    const bool drain = std::strcmp(argv[1], "drain") == 0;
    const bool armReset = std::strcmp(argv[1], "armGuestReset") == 0;
    if (!prepare && !select && !remove && !armReset && std::strcmp(argv[1], "query") != 0 && std::strcmp(argv[1], "drain") != 0 && std::strcmp(argv[1], "crashOwner") != 0) exit(EXIT_FAILURE);
    String failure = {};
    TestPairLifecycleLock lock;
    if (!lockTestPairLifecycle(lock, failure)) { basics_log("pairBoundary success=0 failure=%s\n", failure.c_str()); exit(EXIT_FAILURE); }
    MothershipTestPairBoundaryRecord record = {};
    bool valid = false;
    { auto registry = openClusterRegistry(); valid = registry.loadTestPairBoundary(String(argv[0]), record, &failure); }
    if (valid && record.closed)
    {
      basics_log("pairBoundary success=%u closed=1\n", unsigned(remove));
      if (!remove) exit(EXIT_FAILURE);
      return;
    }
    if (valid && !record.guestResetFence.bootID.empty() && !armReset && !remove)
    {
      failure.assign("test pair awaits guest reset cleanup"_ctv); valid = false;
    }
    if (valid && (prepare || select))
    {
      if (record.version >= 2 && record.targetAdmissionReceipt.empty())
      {
        failure.assign("paired target admission is not durably recorded"_ctv); valid = false;
      }
      MothershipProdigyCluster source = {}, target = {};
      { auto registry = openClusterRegistry(); valid = valid && registry.getClusterByIdentity(record.boundary.sourceClusterUUID, source, &failure) && registry.getClusterByIdentity(record.boundary.targetClusterUUID, target, &failure); }
      if (valid && record.version >= 5) valid = testPairCousinTransportReady(record, source, target, failure);
      DeploymentIdentityReport sr = {}, tr = {};
      valid = valid && testPairDeploymentReady(source, record.sourceDeploymentID, record.boundary.sourceMachineIndex, record.boundary.endpointIPv4, record.boundary.endpointPort, sr, failure) &&
                       testPairDeploymentReady(target, record.targetDeploymentID, record.boundary.targetMachineIndex, record.boundary.endpointIPv4, record.boundary.endpointPort, tr, failure) &&
                       sr.canonicalPlanSHA256 == record.sourcePlanSHA256 && tr.canonicalPlanSHA256 == record.targetPlanSHA256 &&
                       sr.containerBlobSHA256 == record.sourceBlobSHA256 && tr.containerBlobSHA256 == record.targetBlobSHA256;
      // V3 adds the P6 whole-destination fixture intent.  Legacy v2 records
      // retain their original endpoint selection semantics; only retirement
      // is fail-closed to the v3 drain/readiness protocol.
      if (valid && select && record.version >= 3)
        valid = testPairWholeDestinationReady(record, target, failure);
      if (valid && select) { auto registry = openClusterRegistry(); MothershipTestPairBoundaryRecord updated = {}; valid = registry.advanceTestPairBoundary(record, 1, false, updated, &failure); if (valid) record = updated; }
    }
    if (valid && armReset)
    {
      MothershipVirtualDatacenterPairGuestResetFence fence = {};
      valid = (record.version == 3 || record.version == 4 || record.version == 5 || record.version == 6) &&
              runTestPairProvider(record, argv[1], {}, failure, nullptr, &fence);
      if (valid)
      {
        auto registry = openClusterRegistry(); MothershipTestPairBoundaryRecord updated = {};
        valid = registry.recordTestPairGuestResetFence(record, fence, updated, &failure);
        if (valid) record = std::move(updated);
      }
    }
    else if (valid && remove && !record.guestResetFence.bootID.empty())
    {
      MothershipVirtualDatacenterPairGuestResetFence observed = {};
      String completedBootID = {}, expected = {}, actual = {};
      valid = runTestPairProvider(record, argv[1], {}, failure, nullptr, &observed, &completedBootID);
      BitseryEngine::serialize(expected, record.guestResetFence); BitseryEngine::serialize(actual, observed);
      if (valid && expected != actual) { failure.assign("guest reset completion differs from armed operation"_ctv); valid = false; }
      if (valid)
      {
        auto registry = openClusterRegistry(); MothershipTestPairBoundaryRecord updated = {};
        valid = registry.recordTestPairGuestResetCompletion(record, completedBootID, updated, &failure);
        if (valid) record = std::move(updated);
      }
    }
    else if (valid && drain && record.version >= 2) valid = observeAndRecordTestPairSourceDrain(record, failure);
    else valid = valid && runTestPairProvider(record, argv[1], {}, failure);
    if (valid && remove) { auto registry = openClusterRegistry(); MothershipTestPairBoundaryRecord updated = {}; valid = registry.advanceTestPairBoundary(record, record.selectorGeneration, true, updated, &failure); }
    basics_log("pairBoundary success=%u operation=%s migrationQualified=%u failure=%s\n",
               unsigned(valid), argv[1], unsigned(valid && record.version >= 5), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runProbePairBoundary(int argc, char *argv[])
  {
    String failure = {};
    uint64_t deployment = 0, count = 0, interval = 0;
    MothershipTestPairBoundaryRecord record = {};
    bool valid = argc == 4 && mothershipParseUnsignedArgument(argv[1], UINT64_MAX, deployment) && deployment > 0 &&
                 mothershipParseUnsignedArgument(argv[2], 1024, count) && count > 0 &&
                 mothershipParseUnsignedArgument(argv[3], 60000, interval) && (count - 1) * interval <= 50000;
    if (valid) { auto registry = openClusterRegistry(); valid = registry.loadTestPairBoundary(String(argv[0]), record, &failure) && !record.closed && record.guestResetFence.bootID.empty() && (deployment == record.sourceDeploymentID || deployment == record.targetDeploymentID); }
    Vector<String> extra = {};
    if (valid) { for (int index = 1; index != 4; ++index) extra.emplace_back(argv[index]); valid = runTestPairProvider(record, "probe", extra, failure); }
    basics_log("probePairBoundary success=%u failure=%s\n", unsigned(valid), failure.c_str());
    if (!valid) exit(EXIT_FAILURE);
  }

  void runProbeTestCluster(int argc, char *argv[])
  {
    if (argc != 7)
    {
      basics_log("wrong number of arguments. ex: probeTestCluster [name|clusterUUID] [address] [port] [payload] [expected] [timeoutMs] [sourceMachineIndex: 0=datacenter]\n");
      exit(EXIT_FAILURE);
    }

    String identity = {};
    identity.assign(argv[0]);
    String failure = {};
    MothershipProdigyCluster cluster = {};
    if (loadClusterForScopedMutation("probeTestCluster", identity, cluster, failure) == false || cluster.deploymentMode != MothershipClusterDeploymentMode::test)
    {
      basics_log("probeTestCluster success=0 identity=%s failure=%s\n", identity.c_str(), failure.size() ? failure.c_str() : "probeTestCluster requires deploymentMode=test");
      exit(EXIT_FAILURE);
    }

    String address = {};
    String payload = {};
    String expected = {};
    address.assign(argv[1]);
    payload.assign(argv[3]);
    expected.assign(argv[4]);
    uint8_t addressBytes[16] = {};
    bool validAddress = ::inet_pton(AF_INET, address.c_str(), addressBytes) == 1 || ::inet_pton(AF_INET6, address.c_str(), addressBytes) == 1;
    uint64_t port = 0;
    uint64_t timeoutMs = 0;
    uint64_t sourceMachineIndex = 0;
    if (validAddress == false || payload.size() > 4'096 || expected.size() > 4'096 ||
        mothershipParseUnsignedArgument(argv[2], UINT16_MAX, port) == false || port == 0 ||
        mothershipParseUnsignedArgument(argv[5], 60'000, timeoutMs) == false || timeoutMs == 0 ||
        mothershipParseUnsignedArgument(argv[6], cluster.test.machineCount, sourceMachineIndex) == false)
    {
      basics_log("probeTestCluster success=0 identity=%s failure=invalid probe specification\n", identity.c_str());
      exit(EXIT_FAILURE);
    }

    if (mothershipProbeVirtualDatacenterProvider(cluster, address, uint16_t(port), payload, expected, uint32_t(timeoutMs), uint32_t(sourceMachineIndex), &failure) == false)
    {
      basics_log("probeTestCluster success=0 identity=%s failure=%s\n", identity.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }
    basics_log("probeTestCluster success=1 identity=%s address=%s port=%u\n", identity.c_str(), address.c_str(), unsigned(port));
  }

  void runProbeTestClusterTraffic(int argc, char *argv[])
  {
    if (argc != 10)
    {
      basics_log("wrong number of arguments. ex: probeTestClusterTraffic [name|clusterUUID] [address] [port] [payload] [expected] [requestTimeoutMs] [sourceMachineIndex: 0=datacenter] [clients] [requestsPerClient] [intervalMs]\n");
      exit(EXIT_FAILURE);
    }
    String identity = {}; identity.assign(argv[0]);
    String failure = {}, address = {}, payload = {}, expected = {}, output = {};
    MothershipProdigyCluster cluster = {};
    if (loadClusterForScopedMutation("probeTestClusterTraffic", identity, cluster, failure) == false ||
        cluster.deploymentMode != MothershipClusterDeploymentMode::test)
    {
      basics_log("probeTestClusterTraffic success=0 identity=%s failure=%s\n", identity.c_str(), failure.size() ? failure.c_str() : "probeTestClusterTraffic requires deploymentMode=test");
      exit(EXIT_FAILURE);
    }
    address.assign(argv[1]); payload.assign(argv[3]); expected.assign(argv[4]);
    uint8_t addressBytes[16] = {};
    uint64_t port = 0, requestTimeoutMs = 0, sourceMachineIndex = 0, clients = 0, requestsPerClient = 0, intervalMs = 0;
    const bool valid = (::inet_pton(AF_INET, address.c_str(), addressBytes) == 1 || ::inet_pton(AF_INET6, address.c_str(), addressBytes) == 1) &&
        payload.size() <= 4096 && expected.size() <= 4096 &&
        mothershipParseUnsignedArgument(argv[2], UINT16_MAX, port) && port != 0 &&
        mothershipParseUnsignedArgument(argv[5], 5000, requestTimeoutMs) && requestTimeoutMs != 0 &&
        mothershipParseUnsignedArgument(argv[6], cluster.test.machineCount, sourceMachineIndex) &&
        mothershipParseUnsignedArgument(argv[7], 4, clients) && clients == 4 &&
        mothershipParseUnsignedArgument(argv[8], 15000, requestsPerClient) && requestsPerClient != 0 &&
        mothershipParseUnsignedArgument(argv[9], 1000, intervalMs) &&
        clients * requestsPerClient <= 60000 &&
        (intervalMs == 0 ? requestsPerClient * requestTimeoutMs :
         (requestsPerClient - 1) * intervalMs + requestTimeoutMs) + 100 <= 1'201'000;
    if (!valid)
    {
      basics_log("probeTestClusterTraffic success=0 identity=%s failure=invalid bounded traffic specification\n", identity.c_str());
      exit(EXIT_FAILURE);
    }
    const bool succeeded = mothershipProbeTrafficVirtualDatacenterProvider(
        cluster, address, uint16_t(port), payload, expected, uint32_t(requestTimeoutMs), uint32_t(sourceMachineIndex),
        uint32_t(clients), uint32_t(requestsPerClient), uint32_t(intervalMs), output, &failure);
    if (!output.empty()) std::fwrite(output.data(), 1, output.size(), stdout);
    basics_log("probeTestClusterTraffic success=%u identity=%s attempts=%llu clients=%llu requestsPerClient=%llu intervalMs=%llu failure=%s\n",
               unsigned(succeeded), identity.c_str(), (unsigned long long)(clients * requestsPerClient),
               (unsigned long long)clients, (unsigned long long)requestsPerClient, (unsigned long long)intervalMs, failure.c_str());
    if (!succeeded) exit(EXIT_FAILURE);
  }

  bool loadRemoteClusterMutationTarget(const char *operationName, const char *identityArg, MothershipProdigyCluster& controlCluster, String& failure)
  {
    failure.clear();
    controlCluster = {};
    String operation = {};
    operation.assign(operationName);

    String identity = {};
    if (identityArg != nullptr)
    {
      identity.assign(identityArg);
    }

    if (identity.size() == 0)
    {
      failure.snprintf<"{}.identity required"_ctv>(operation);
      return false;
    }

    MothershipClusterRegistry clusterRegistry = openClusterRegistry();
    if (clusterRegistry.getClusterByIdentity(identity, controlCluster, &failure) == false)
    {
      return false;
    }

    if (controlCluster.deploymentMode != MothershipClusterDeploymentMode::remote)
    {
      failure.snprintf<"{} only supports remote clusters"_ctv>(operation);
      return false;
    }

    return true;
  }

  void runUpsertMachineSchemas(int argc, char *argv[])
  {
    if (argc < 2)
    {
      basics_log("too few arguments. ex: upsertMachineSchemas [name|clusterUUID] [json object|array]\n");
      exit(EXIT_FAILURE);
    }

    String failure = {};
    MothershipProdigyCluster controlCluster = {};
    if (loadRemoteClusterMutationTarget("upsertMachineSchemas", argv[0], controlCluster, failure) == false)
    {
      basics_log("upsertMachineSchemas success=0 identity=%s failure=%s\n", argv[0], failure.c_str());
      exit(EXIT_FAILURE);
    }

    String json = {};
    json.append(argv[1]);
    json.need(simdjson::SIMDJSON_PADDING);

    simdjson::dom::parser parser;
    simdjson::dom::element doc;
    if (parser.parse(json.data(), json.size()).get(doc))
    {
      basics_log("invalid json for upsertMachineSchemas\n");
      exit(EXIT_FAILURE);
    }

    Vector<MothershipProdigyClusterMachineSchemaPatch> patches = {};
    if (doc.type() == simdjson::dom::element_type::OBJECT)
    {
      MothershipProdigyClusterMachineSchemaPatch patch = {};
      if (parseClusterMachineSchemaPatchJSON(doc, patch, "upsertMachineSchemas") == false)
      {
        exit(EXIT_FAILURE);
      }
      patches.push_back(patch);
    }
    else if (doc.type() == simdjson::dom::element_type::ARRAY)
    {
      for (auto item : doc.get_array())
      {
        MothershipProdigyClusterMachineSchemaPatch patch = {};
        if (parseClusterMachineSchemaPatchJSON(item, patch, "upsertMachineSchemas[]") == false)
        {
          exit(EXIT_FAILURE);
        }
        patches.push_back(patch);
      }
    }
    else
    {
      basics_log("upsertMachineSchemas requires object or array json\n");
      exit(EXIT_FAILURE);
    }

    if (patches.empty())
    {
      basics_log("upsertMachineSchemas requires at least one schema patch\n");
      exit(EXIT_FAILURE);
    }

    MothershipProdigyCluster desiredCluster = controlCluster;
    uint32_t createdCount = 0;
    for (const MothershipProdigyClusterMachineSchemaPatch& patch : patches)
    {
      bool created = false;
      if (mothershipUpsertClusterMachineSchema(desiredCluster.machineSchemas, patch, &created, &failure) == false)
      {
        basics_log("upsertMachineSchemas success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
        exit(EXIT_FAILURE);
      }

      if (created)
      {
        createdCount += 1;
      }
    }

    MothershipProviderCredential referencedCredential = {};
    if (validateClusterProviderCredentialReference(desiredCluster, failure, &referencedCredential) == false || inferClusterMachineSchemaCpuCapabilities(desiredCluster, &referencedCredential, failure) == false)
    {
      basics_log("upsertMachineSchemas success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    bool changed = mothershipEqualClusterMachineSchemas(controlCluster.machineSchemas, desiredCluster.machineSchemas) == false;

    Vector<ProdigyManagedMachineSchemaPatch> requestPatches = {};
    requestPatches.reserve(patches.size());
    for (const MothershipProdigyClusterMachineSchemaPatch& patch : patches)
    {
      ProdigyManagedMachineSchemaPatch requestPatch = {};
      convertClusterMachineSchemaPatch(patch, requestPatch);
      for (const MothershipProdigyClusterMachineSchema& desiredSchema : desiredCluster.machineSchemas)
      {
        if (desiredSchema.schema == requestPatch.schema)
        {
          requestPatch.hasCpu = true;
          requestPatch.cpu = desiredSchema.cpu;
          break;
        }
      }
      requestPatches.push_back(std::move(requestPatch));
    }

    if (socket.configureCluster(controlCluster, &failure) == false)
    {
      basics_log("upsertMachineSchemas success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    UpsertMachineSchemas request = {};
    request.patches = requestPatches;
    UpsertMachineSchemas response = {};
    if (requestUpsertMachineSchemas(request, response, failure) == false)
    {
      MothershipProdigyCluster refreshCluster = controlCluster;
      persistClusterRefreshFailure(refreshCluster, failure);
      basics_log("upsertMachineSchemas success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    desiredCluster.topology = response.topology;
    desiredCluster.lastRefreshMs = Time::now<TimeResolution::ms>();
    desiredCluster.lastRefreshFailure.clear();

    {
      MothershipClusterRegistry clusterRegistry = openClusterRegistry();
      if (clusterRegistry.upsertCluster(desiredCluster, &desiredCluster, &failure) == false)
      {
        basics_log("upsertMachineSchemas success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
        exit(EXIT_FAILURE);
      }
    }

    basics_log("upsertMachineSchemas success=1 name=%s upserted=%u created=%u changed=%d topologyVersion=%llu topologyMachines=%u\n",
               desiredCluster.name.c_str(),
               unsigned(patches.size()),
               unsigned(createdCount),
               int(changed),
               (unsigned long long)desiredCluster.topology.version,
               unsigned(desiredCluster.topology.machines.size()));
    printManagedCluster(desiredCluster);
  }

  void runDeltaMachineBudget(int argc, char *argv[])
  {
    if (argc < 2)
    {
      basics_log("too few arguments. ex: deltaMachineBudget [name|clusterUUID] [{\"schema\":\"...\",\"delta\":-1}]\n");
      exit(EXIT_FAILURE);
    }

    String failure = {};
    MothershipProdigyCluster controlCluster = {};
    if (loadRemoteClusterMutationTarget("deltaMachineBudget", argv[0], controlCluster, failure) == false)
    {
      basics_log("deltaMachineBudget success=0 identity=%s failure=%s\n", argv[0], failure.c_str());
      exit(EXIT_FAILURE);
    }

    String json = {};
    json.append(argv[1]);
    json.need(simdjson::SIMDJSON_PADDING);

    simdjson::dom::parser parser;
    simdjson::dom::element doc;
    if (parser.parse(json.data(), json.size()).get(doc))
    {
      basics_log("invalid json for deltaMachineBudget\n");
      exit(EXIT_FAILURE);
    }

    if (doc.type() != simdjson::dom::element_type::OBJECT)
    {
      basics_log("deltaMachineBudget requires object json\n");
      exit(EXIT_FAILURE);
    }

    String schema = {};
    int64_t delta = 0;
    bool sawSchema = false;
    bool sawDelta = false;
    for (auto field : doc.get_object())
    {
      String key = {};
      key.setInvariant(field.key.data(), field.key.size());

      if (key.equal("schema"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("deltaMachineBudget.schema requires string\n");
          exit(EXIT_FAILURE);
        }

        schema.assign(field.value.get_c_str());
        sawSchema = true;
      }
      else if (key.equal("delta"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::INT64 || field.value.get(delta) != simdjson::SUCCESS)
        {
          basics_log("deltaMachineBudget.delta invalid\n");
          exit(EXIT_FAILURE);
        }

        sawDelta = true;
      }
      else
      {
        basics_log("deltaMachineBudget invalid field\n");
        exit(EXIT_FAILURE);
      }
    }

    if (sawSchema == false || sawDelta == false)
    {
      basics_log("deltaMachineBudget requires schema and delta\n");
      exit(EXIT_FAILURE);
    }

    MothershipProdigyCluster desiredCluster = controlCluster;
    uint32_t finalBudget = 0;
    if (mothershipDeltaClusterMachineBudget(desiredCluster.machineSchemas, schema, delta, &finalBudget, &failure) == false)
    {
      basics_log("deltaMachineBudget success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    MothershipProviderCredential referencedCredential = {};
    if (validateClusterProviderCredentialReference(desiredCluster, failure, &referencedCredential) == false || inferClusterMachineSchemaCpuCapabilities(desiredCluster, &referencedCredential, failure) == false)
    {
      basics_log("deltaMachineBudget success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    bool changed = mothershipEqualClusterMachineSchemas(controlCluster.machineSchemas, desiredCluster.machineSchemas) == false;

    if (socket.configureCluster(controlCluster, &failure) == false)
    {
      basics_log("deltaMachineBudget success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    DeltaMachineBudget request = {};
    request.schema = schema;
    request.delta = delta;

    DeltaMachineBudget response = {};
    if (requestDeltaMachineBudget(request, response, failure) == false)
    {
      MothershipProdigyCluster refreshCluster = controlCluster;
      persistClusterRefreshFailure(refreshCluster, failure);
      basics_log("deltaMachineBudget success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
      exit(EXIT_FAILURE);
    }

    desiredCluster.topology = response.topology;
    desiredCluster.lastRefreshMs = Time::now<TimeResolution::ms>();
    desiredCluster.lastRefreshFailure.clear();

    {
      MothershipClusterRegistry clusterRegistry = openClusterRegistry();
      if (clusterRegistry.upsertCluster(desiredCluster, &desiredCluster, &failure) == false)
      {
        basics_log("deltaMachineBudget success=0 name=%s failure=%s\n", controlCluster.name.c_str(), failure.c_str());
        exit(EXIT_FAILURE);
      }
    }

    basics_log("deltaMachineBudget success=1 name=%s schema=%s budget=%u changed=%d topologyVersion=%llu topologyMachines=%u\n",
               desiredCluster.name.c_str(),
               schema.c_str(),
               unsigned(finalBudget),
               int(changed),
               (unsigned long long)desiredCluster.topology.version,
               unsigned(desiredCluster.topology.machines.size()));
    printManagedCluster(desiredCluster);
  }

