  void runAuthorizeBGPOriginPrefix(int argc, char *argv[])
  {
    if (argc < 2) { basics_log("usage: authorizeBGPOriginPrefix [cluster] [canonical CIDR]\n"); exit(EXIT_FAILURE); }
    MothershipProdigyCluster cluster = {}; String failure = {};
    MothershipClusterRegistry::BGPOriginPolicyLock policyLock = {};
    IPPrefix prefix = {};
    char canonicalPrefix[INET6_ADDRSTRLEN + 8] = {};
    if (!parseRoutablePrefixLiteral(argv[1], prefix) || std::strchr(argv[1], '/') == nullptr ||
        prefix.cidr > (prefix.network.is6 ? 128 : 32) || !prefix.equals(prefix.canonicalized()) ||
        !mothershipProviderBGPOriginPrefixAllowed(prefix) ||
        !formatCIDRPrefix(prefix, canonicalPrefix, sizeof(canonicalPrefix)) || std::strcmp(argv[1], canonicalPrefix) != 0)
    { basics_log("authorizeBGPOriginPrefix requires a canonical CIDR prefix\n"); exit(EXIT_FAILURE); }
    bool created = false;
    {
      MothershipClusterRegistry registry = openClusterRegistry();
      if (!registry.lockBGPOriginPolicy(policyLock, &failure))
      { basics_log("authorizeBGPOriginPrefix lock failed: %s\n", failure.c_str()); exit(EXIT_FAILURE); }
      if (!registry.getClusterByIdentity(String(argv[0]), cluster, &failure) ||
          !mothershipClusterBGPEnabled(cluster))
      { basics_log("authorizeBGPOriginPrefix requires a registered BGP-enabled cluster\n"); exit(EXIT_FAILURE); }
      bool exists = false;
      for (const IPPrefix& existing : cluster.bgpAuthorizedOriginPrefixes)
        if (existing.equals(prefix)) { exists = true; break; }
      if (!exists)
      {
        if (cluster.bgpAuthorizedOriginPrefixes.size() >= 256) { basics_log("authorizeBGPOriginPrefix registry full\n"); exit(EXIT_FAILURE); }
        cluster.bgpAuthorizedOriginPrefixes.push_back(prefix);
        created = true;
      }
      if (created && !registry.upsertClusterBGPOriginPolicy(cluster, policyLock, nullptr, &failure))
      { basics_log("authorizeBGPOriginPrefix persist failed: %s\n", failure.c_str()); exit(EXIT_FAILURE); }
    }
    basics_log("authorizeBGPOriginPrefix success=1 created=%u\n", unsigned(created));
  }

  void runRevokeBGPOriginPrefix(int argc, char *argv[])
  {
    if (argc < 2) { basics_log("usage: revokeBGPOriginPrefix [cluster] [canonical CIDR]\n"); exit(EXIT_FAILURE); }
    MothershipProdigyCluster cluster = {}; String failure = {};
    MothershipClusterRegistry::BGPOriginPolicyLock policyLock = {};
    IPPrefix prefix = {};
    char canonicalPrefix[INET6_ADDRSTRLEN + 8] = {};
    if (!parseRoutablePrefixLiteral(argv[1], prefix) || std::strchr(argv[1], '/') == nullptr || !prefix.equals(prefix.canonicalized()) ||
        !formatCIDRPrefix(prefix, canonicalPrefix, sizeof(canonicalPrefix)) || std::strcmp(argv[1], canonicalPrefix) != 0)
    { basics_log("revokeBGPOriginPrefix requires canonical CIDR prefix\n"); exit(EXIT_FAILURE); }
    MothershipClusterRegistry registry = openClusterRegistry();
    if (!registry.lockBGPOriginPolicy(policyLock, &failure))
    { basics_log("revokeBGPOriginPrefix lock failed: %s\n", failure.c_str()); exit(EXIT_FAILURE); }
    if (!registry.getClusterByIdentity(String(argv[0]), cluster, &failure) ||
        !mothershipClusterBGPEnabled(cluster))
    { basics_log("revokeBGPOriginPrefix requires a registered BGP-enabled cluster\n"); exit(EXIT_FAILURE); }
    RoutableSubnetRegistryReport active = {};
    if (!readRoutableSubnets(cluster, active, failure)) { basics_log("revokeBGPOriginPrefix cannot verify active prefixes: %s\n", failure.c_str()); exit(EXIT_FAILURE); }
    for (const auto& subnet : active.subnets)
      if (subnet.ingressScope == RoutableIngressScope::switchboardFleet && subnet.subnet.equals(prefix))
      { basics_log("revokeBGPOriginPrefix prefix remains actively registered\n"); exit(EXIT_FAILURE); }
    bool removed = false;
    for (auto it = cluster.bgpAuthorizedOriginPrefixes.begin(); it != cluster.bgpAuthorizedOriginPrefixes.end(); ++it)
      if (it->equals(prefix)) { cluster.bgpAuthorizedOriginPrefixes.erase(it); removed = true; break; }
    if (!removed) { basics_log("revokeBGPOriginPrefix prefix is not authorized\n"); exit(EXIT_FAILURE); }
    if (!registry.upsertClusterBGPOriginPolicy(cluster, policyLock, nullptr, &failure))
    { basics_log("revokeBGPOriginPrefix persist failed: %s\n", failure.c_str()); exit(EXIT_FAILURE); }
    basics_log("revokeBGPOriginPrefix success=1 removed=%d\n", int(removed));
  }

  void runListBGPOriginPrefixes(int argc, char *argv[])
  {
    if (argc < 1) { basics_log("usage: listBGPOriginPrefixes [cluster]\n"); exit(EXIT_FAILURE); }
    MothershipProdigyCluster cluster = {}; String failure = {};
    if (!openClusterRegistry().getClusterByIdentity(String(argv[0]), cluster, &failure)) { basics_log("listBGPOriginPrefixes unknown cluster\n"); exit(EXIT_FAILURE); }
    basics_log("listBGPOriginPrefixes success=1 count=%u\n", unsigned(cluster.bgpAuthorizedOriginPrefixes.size()));
    for (const IPPrefix& prefix : cluster.bgpAuthorizedOriginPrefixes) { char text[INET6_ADDRSTRLEN + 8] = {}; formatCIDRPrefix(prefix, text, sizeof(text)); basics_log("  %s\n", text); }
  }

  void runRegisterRoutableSubnet(int argc, char *argv[])
  {
    if (argc < 2)
    {
      basics_log("too few arguments. ex: registerRoutableSubnet [target: local|clusterName|clusterUUID] [json]\n");
      exit(EXIT_FAILURE);
    }

    RoutableSubnetRegistration request = {};
    bool sawSubnet = false;
    bool sawUsage = false;
    bool sawFamily = false;
    bool sawElasticIntent = false;

    String json;
    json.append(argv[1]);
    json.need(simdjson::SIMDJSON_PADDING);

    simdjson::dom::parser parser;
    simdjson::dom::element doc;
    if (parser.parse(json.data(), json.size()).get(doc))
    {
      basics_log("invalid json for registerRoutableSubnet\n");
      exit(EXIT_FAILURE);
    }

    for (auto field : doc.get_object())
    {
      String key;
      key.setInvariant(field.key.data(), field.key.size());

      if (key.equal("name"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.name requires string\n");
          exit(EXIT_FAILURE);
        }

        request.subnet.name.assign(field.value.get_c_str());
      }
      else if (key.equal("kind"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.kind requires string\n");
          exit(EXIT_FAILURE);
        }

        String kind;
        kind.setInvariant(field.value.get_c_str());
        if (parseRoutablePrefixKind(kind, request.subnet.kind) == false)
        {
          basics_log("registerRoutableSubnet.kind invalid\n");
          exit(EXIT_FAILURE);
        }
      }
      else if (key.equal("subnet"_ctv) || key.equal("prefix"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.prefix requires string\n");
          exit(EXIT_FAILURE);
        }

        if (parseRoutablePrefixLiteral(field.value.get_c_str(), request.subnet.subnet) == false)
        {
          basics_log("registerRoutableSubnet.prefix invalid\n");
          exit(EXIT_FAILURE);
        }

        sawSubnet = true;
      }
      else if (key.equal("uuid"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.uuid requires string\n");
          exit(EXIT_FAILURE);
        }

        String value;
        value.setInvariant(field.value.get_c_str());
        request.subnet.uuid = String::numberFromHexString<uint128_t>(value);
        if (request.subnet.uuid == 0)
        {
          basics_log("registerRoutableSubnet.uuid invalid\n");
          exit(EXIT_FAILURE);
        }
      }
      else if (key.equal("family"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.family requires string\n");
          exit(EXIT_FAILURE);
        }

        String value;
        value.setInvariant(field.value.get_c_str());
        if (parseExternalAddressFamily(value, request.family) == false)
        {
          basics_log("registerRoutableSubnet.family invalid\n");
          exit(EXIT_FAILURE);
        }

        sawFamily = true;
      }
      else if (key.equal("elasticIntent"_ctv) || key.equal("intent"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.elasticIntent requires string\n");
          exit(EXIT_FAILURE);
        }

        String value;
        value.setInvariant(field.value.get_c_str());
        if (parseElasticPrefixIntent(value, request.elasticIntent) == false)
        {
          basics_log("registerRoutableSubnet.elasticIntent invalid\n");
          exit(EXIT_FAILURE);
        }

        sawElasticIntent = true;
      }
      else if (key.equal("routing"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.routing requires string\n");
          exit(EXIT_FAILURE);
        }

        String routing;
        routing.setInvariant(field.value.get_c_str());
        if (parseExternalSubnetRouting(routing, request.subnet.routing) == false)
        {
          basics_log("registerRoutableSubnet.routing invalid\n");
          exit(EXIT_FAILURE);
        }
      }
      else if (key.equal("usage"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.usage requires string\n");
          exit(EXIT_FAILURE);
        }

        String usage;
        usage.setInvariant(field.value.get_c_str());
        if (parseExternalSubnetUsage(usage, request.subnet.usage) == false)
        {
          basics_log("registerRoutableSubnet.usage invalid\n");
          exit(EXIT_FAILURE);
        }

        sawUsage = true;
      }
      else if (key.equal("ingressScope"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.ingressScope requires string\n");
          exit(EXIT_FAILURE);
        }

        String scope;
        scope.setInvariant(field.value.get_c_str());
        if (parseRoutableIngressScope(scope, request.subnet.ingressScope) == false)
        {
          basics_log("registerRoutableSubnet.ingressScope invalid\n");
          exit(EXIT_FAILURE);
        }
      }
      else if (key.equal("machineUUID"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.machineUUID requires string\n");
          exit(EXIT_FAILURE);
        }

        String value;
        value.setInvariant(field.value.get_c_str());
        request.subnet.machineUUID = String::numberFromHexString<uint128_t>(value);
        if (request.subnet.machineUUID == 0)
        {
          basics_log("registerRoutableSubnet.machineUUID invalid\n");
          exit(EXIT_FAILURE);
        }
      }
      else if (key.equal("requestedAddress"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.requestedAddress requires string\n");
          exit(EXIT_FAILURE);
        }

        request.requestedAddress.assign(field.value.get_c_str());
      }
      else if (key.equal("providerPool"_ctv))
      {
        if (field.value.type() != simdjson::dom::element_type::STRING)
        {
          basics_log("registerRoutableSubnet.providerPool requires string\n");
          exit(EXIT_FAILURE);
        }

        request.subnet.providerPool.assign(field.value.get_c_str());
      }
      else
      {
        basics_log("registerRoutableSubnet invalid field\n");
        exit(EXIT_FAILURE);
      }
    }

    if (request.subnet.name.size() == 0)
    {
      basics_log("registerRoutableSubnet.name required\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.routing != ExternalSubnetRouting::switchboardBGP)
    {
      basics_log("registerRoutableSubnet only supports routing=BGP\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::BGP && (request.requestedAddress.size() > 0 || request.subnet.providerPool.size() > 0 || sawFamily || sawElasticIntent))
    {
      basics_log("registerRoutableSubnet BGP prefixes do not accept elastic fields\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.ingressScope == RoutableIngressScope::switchboardFleet && request.subnet.machineUUID != 0)
    {
      basics_log("registerRoutableSubnet switchboardFleet must not set machineUUID\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::BGP && sawSubnet == false)
    {
      basics_log("registerRoutableSubnet.prefix required\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::elastic && sawSubnet)
    {
      basics_log("registerRoutableSubnet elastic prefixes are provider allocated; omit prefix\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::elastic && sawFamily == false)
    {
      basics_log("registerRoutableSubnet elastic prefix requires family\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::elastic && sawElasticIntent == false)
    {
      basics_log("registerRoutableSubnet elastic prefix requires elasticIntent\n");
      exit(EXIT_FAILURE);
    }

    if (sawUsage == false)
    {
      basics_log("registerRoutableSubnet.usage required\n");
      exit(EXIT_FAILURE);
    }

    if (request.subnet.kind == RoutablePrefixKind::BGP && routableExternalSubnetHasSupportedBreadth(request.subnet) == false)
    {
      basics_log("registerRoutableSubnet prefix CIDR is invalid\n");
      exit(EXIT_FAILURE);
    }

    // Fleet BGP origin authorization belongs to Mothership. Keep one
    // process-shared lock from the exact durable policy decision through the
    // Brain response so a concurrent revoke cannot pass its active-prefix
    // check while this registration is in flight. Brain still requires an
    // active authenticated Mothership control stream before accepting fleet
    // registrations; no BrainConfig wire or persisted-state codec changes.
    MothershipClusterRegistry::BGPOriginPolicyLock originPolicyLock = {};
    if (request.subnet.ingressScope == RoutableIngressScope::switchboardFleet)
    {
      String failure = {};
      String clusterIdentity = {};
      const bool localTarget = std::strcmp(argv[0], "local") == 0;
      if (localTarget)
      {
        if (!socket.setLocal(&failure) || socket.configuredClusterUUID() == 0)
        {
          basics_log("registerRoutableSubnet cannot resolve local cluster policy identity: %s\n", failure.c_str());
          exit(EXIT_FAILURE);
        }
        clusterIdentity.assignItoh(socket.configuredClusterUUID());
      }
      else
      {
        clusterIdentity.assign(argv[0]);
      }

      MothershipProdigyCluster cluster = {};
      {
        MothershipClusterRegistry registry = openClusterRegistry();
        if (!registry.lockBGPOriginPolicy(originPolicyLock, &failure))
        {
          basics_log("registerRoutableSubnet BGP origin policy lock failed: %s\n", failure.c_str());
          exit(EXIT_FAILURE);
        }
        if (!registry.getClusterByIdentity(clusterIdentity, cluster, &failure))
        {
          basics_log("registerRoutableSubnet unknown BGP policy cluster: %s\n", failure.c_str());
          exit(EXIT_FAILURE);
        }
        if (!mothershipClusterAuthorizesBGPOriginPrefix(cluster, request.subnet.subnet))
        {
          basics_log("registerRoutableSubnet exact fleet BGP origin prefix is not authorized\n");
          exit(EXIT_FAILURE);
        }
      }

      if (!localTarget && !socket.configureCluster(cluster, &failure))
      {
        basics_log("registerRoutableSubnet cluster has invalid control configuration: %s\n", failure.c_str());
        exit(EXIT_FAILURE);
      }
    }
    else if (configureControlTarget(argv[0]) == false)
    {
      exit(EXIT_FAILURE);
    }

    if (socket.connect() != 0)
    {
      exit(EXIT_FAILURE);
    }

    uint32_t headerOffset = Message::appendHeader(socket.wBuffer, MothershipTopic::registerRoutableSubnet);
    Message::serializeAndAppendObject(socket.wBuffer, request);
    Message::finish(socket.wBuffer, headerOffset);

    if (socket.send() == false)
    {
      exit(EXIT_FAILURE);
    }

    Message *responseMessage = socket.recvExpectedTopic(MothershipTopic::registerRoutableSubnet);
    if (responseMessage == nullptr)
    {
      exit(EXIT_FAILURE);
    }

    String serializedResponse;
    uint8_t *responseArgs = responseMessage->args;
    Message::extractToStringView(responseArgs, serializedResponse);

    RoutableSubnetRegistration response;
    if (BitseryEngine::deserializeSafe(serializedResponse, response) == false)
    {
      basics_log("registerRoutableSubnet response decode failed\n");
      exit(EXIT_FAILURE);
    }

    char prefixBuffer[INET6_ADDRSTRLEN + 8] = {0};
    (void)formatCIDRPrefix(response.subnet.subnet, prefixBuffer, sizeof(prefixBuffer));
    String subnetUUIDText = {};
    subnetUUIDText.assignItoh(response.subnet.uuid);
    String machineUUIDText = {};
    machineUUIDText.assignItoh(response.subnet.machineUUID);

    basics_log("registerRoutableSubnet success=%d created=%d name=%s uuid=%s kind=%s prefix=%s routing=%s usage=%s ingressScope=%s machineUUID=%s elasticIntent=%s family=%s failure=%s\n",
               int(response.success),
               int(response.created),
               response.subnet.name.c_str(),
               subnetUUIDText.c_str(),
               routablePrefixKindName(response.subnet.kind),
               prefixBuffer,
               externalSubnetRoutingName(response.subnet.routing),
               externalSubnetUsageName(response.subnet.usage),
               routableIngressScopeName(response.subnet.ingressScope),
               machineUUIDText.c_str(),
               elasticPrefixIntentName(response.elasticIntent),
               response.family == ExternalAddressFamily::ipv6 ? "ipv6" : "ipv4",
               (response.failure.size() ? response.failure.c_str() : ""));

    if (response.success == false)
    {
      exit(EXIT_FAILURE);
    }
  }

